function handleA11yModalFocusTrap(event) {
  if (event.key !== "Tab" || event.defaultPrevented) {
    return;
  }
  const topModal = getTopOpenModalElement();
  if (!topModal) {
    return;
  }
  const focusables = getFocusableElementsWithin(topModal);
  if (!focusables.length) {
    event.preventDefault();
    if (typeof topModal.focus === "function") {
      topModal.focus({ preventScroll: true });
    }
    return;
  }
  const first = focusables[0];
  const last = focusables[focusables.length - 1];
  const activeElement = document.activeElement;
  if (event.shiftKey) {
    if (activeElement === first || !topModal.contains(activeElement)) {
      event.preventDefault();
      last.focus({ preventScroll: true });
    }
    return;
  }
  if (activeElement === last || !topModal.contains(activeElement)) {
    event.preventDefault();
    first.focus({ preventScroll: true });
  }
}

function handleA11yTablistNavigation(event) {
  const target = event.target;
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const tabButton = target.closest("[role='tab']");
  if (!tabButton) {
    return;
  }
  const tablist = tabButton.closest("[role='tablist']");
  if (!tablist) {
    return;
  }
  const tabs = Array.from(tablist.querySelectorAll("[role='tab']")).filter(
    (entry) => entry instanceof HTMLElement && !entry.hasAttribute("disabled")
  );
  if (!tabs.length) {
    return;
  }
  const currentIndex = tabs.indexOf(tabButton);
  if (currentIndex < 0) {
    return;
  }
  const normalizedKey = String(event.key || "");
  if (!["ArrowLeft", "ArrowRight", "Home", "End", "Enter", " "].includes(normalizedKey)) {
    return;
  }
  event.preventDefault();
  if (normalizedKey === "Enter" || normalizedKey === " ") {
    tabButton.click();
    return;
  }
  let nextIndex = currentIndex;
  if (normalizedKey === "ArrowLeft") {
    nextIndex = currentIndex === 0 ? tabs.length - 1 : currentIndex - 1;
  } else if (normalizedKey === "ArrowRight") {
    nextIndex = currentIndex === tabs.length - 1 ? 0 : currentIndex + 1;
  } else if (normalizedKey === "Home") {
    nextIndex = 0;
  } else if (normalizedKey === "End") {
    nextIndex = tabs.length - 1;
  }
  const nextTab = tabs[nextIndex];
  if (!(nextTab instanceof HTMLElement)) {
    return;
  }
  nextTab.focus({ preventScroll: true });
  nextTab.click();
}

function initializeAccessibilityInfrastructure() {
  initializeModalA11ySemantics();
  initializeTabsA11ySemantics();
  syncModalA11yState();
}

let requiredFieldIndicatorTimer = null;
let requiredFieldIndicatorObserver = null;

function isCurrentlyRequiredFormControl(control) {
  if (!(control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement)) {
    return false;
  }
  return control.required && !control.disabled && control.type !== "hidden";
}

function labelContainsRequiredFormControl(label) {
  if (!(label instanceof HTMLLabelElement)) {
    return false;
  }
  const referencedControl = label.htmlFor ? document.getElementById(label.htmlFor) : null;
  if (isCurrentlyRequiredFormControl(referencedControl)) {
    return true;
  }
  return Array.from(label.querySelectorAll("input, select, textarea")).some(isCurrentlyRequiredFormControl);
}

function findOrCreateRequiredLabelTextElement(label) {
  const existingTextElement = Array.from(label.children).find(
    (child) =>
      child instanceof HTMLElement &&
      child.matches("span") &&
      !child.querySelector("input, select, textarea") &&
      Boolean(String(child.textContent || "").trim())
  );
  if (existingTextElement) {
    return existingTextElement;
  }

  const textNode = Array.from(label.childNodes).find(
    (node) => node.nodeType === Node.TEXT_NODE && Boolean(String(node.textContent || "").trim())
  );
  if (!textNode) {
    return null;
  }
  const textElement = document.createElement("span");
  textElement.className = "field-label-text";
  textNode.parentNode?.insertBefore(textElement, textNode);
  textElement.appendChild(textNode);
  return textElement;
}

function syncRequiredFieldMarker(label, isRequired) {
  const existingMarker = label.querySelector("[data-required-field-marker]");
  label.classList.toggle("field-is-required", isRequired);
  if (!isRequired) {
    existingMarker?.remove();
    return;
  }
  if (existingMarker) {
    return;
  }

  const marker = document.createElement("span");
  marker.className = "field-required-marker";
  marker.dataset.requiredFieldMarker = "true";
  marker.setAttribute("aria-hidden", "true");
  marker.textContent = "*";

  const textElement = findOrCreateRequiredLabelTextElement(label);
  if (textElement) {
    textElement.appendChild(marker);
  }
}

function syncRequiredFieldIndicators() {
  document.querySelectorAll("label").forEach((label) => {
    syncRequiredFieldMarker(label, labelContainsRequiredFormControl(label));
  });

  document.querySelectorAll("form").forEach((form) => {
    const hasRequiredField = Array.from(form.querySelectorAll("input, select, textarea")).some(
      isCurrentlyRequiredFormControl
    );
    const existingHint = form.querySelector(":scope > [data-required-fields-hint]");
    if (!hasRequiredField) {
      existingHint?.remove();
      return;
    }
    if (existingHint) {
      return;
    }
    const hint = document.createElement("p");
    hint.className = "form-required-fields-hint";
    hint.dataset.requiredFieldsHint = "true";
    hint.textContent = "(*Pflichtfeld)";
    form.appendChild(hint);
  });
}

function scheduleRequiredFieldIndicatorSync() {
  if (requiredFieldIndicatorTimer !== null) {
    return;
  }
  requiredFieldIndicatorTimer = window.setTimeout(() => {
    requiredFieldIndicatorTimer = null;
    syncRequiredFieldIndicators();
  }, 40);
}

function initializeRequiredFieldIndicators() {
  syncRequiredFieldIndicators();
  if (requiredFieldIndicatorObserver || !document.body) {
    return;
  }
  requiredFieldIndicatorObserver = new MutationObserver(scheduleRequiredFieldIndicatorSync);
  requiredFieldIndicatorObserver.observe(document.body, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["required", "disabled", "id", "for"],
  });
}

function normalizeUserRole(role) {
  const normalizedRole = String(role || "").trim().toLowerCase();
  if (normalizedRole === ROLE_ADMIN) {
    return normalizedRole;
  }
  if (normalizedRole === ROLE_SUPERADMIN || normalizedRole === ROLE_SUPAADMIN_LEGACY) {
    return ROLE_SUPERADMIN;
  }
  if (
    normalizedRole === ROLE_VERTRIEBSMITARBEITER ||
    normalizedRole === "vertrieb" ||
    normalizedRole === "vertreibmitarbeiter"
  ) {
    return ROLE_VERTRIEBSMITARBEITER;
  }
  return ROLE_MITARBEITER;
}

function isPrivilegedRole(role) {
  return PRIVILEGED_ROLES.has(normalizeUserRole(role));
}

function isSuperAdmin(user = getCurrentUser()) {
  return normalizeUserRole(user?.role) === ROLE_SUPERADMIN;
}

function canCurrentUserExportProviders(currentUser = getCurrentUser()) {
  return isSuperAdmin(currentUser);
}

function canCurrentUserUseProviderListAdvancedFilters(currentUser = getCurrentUser()) {
  return isSuperAdmin(currentUser) || isSalesRepresentative(currentUser);
}

function canCurrentUserUseProviderListSuperAdminFilters(currentUser = getCurrentUser()) {
  return isSuperAdmin(currentUser);
}

function isSalesRepresentative(user = getCurrentUser()) {
  return normalizeUserRole(user?.role) === ROLE_VERTRIEBSMITARBEITER;
}

function canCurrentUserSetProviderDashboardCreated(currentUser = getCurrentUser()) {
  return isRoleAdmin(currentUser) || isSalesRepresentative(currentUser);
}

function shouldOpenSalesDashboardByDefault(roleLike = getCurrentUser()) {
  const normalizedRole = normalizeUserRole(
    typeof roleLike === "object" && roleLike !== null ? roleLike.role : roleLike
  );
  return [ROLE_MITARBEITER, ROLE_VERTRIEBSMITARBEITER, ROLE_ADMIN, ROLE_SUPERADMIN].includes(normalizedRole);
}

function shouldUseFlatSalesNavigation(roleLike = getCurrentUser()?.role || authProfile?.role || "") {
  const normalizedRole = normalizeUserRole(
    typeof roleLike === "object" && roleLike !== null ? roleLike.role : roleLike
  );
  return normalizedRole === ROLE_MITARBEITER || normalizedRole === ROLE_VERTRIEBSMITARBEITER;
}

function getDefaultSectionForRole(roleLike = getCurrentUser()?.role || authProfile?.role || "") {
  return shouldOpenSalesDashboardByDefault(roleLike) ? "sales-dashboard-section" : "dashboard-section";
}

function normalizeMarketingRole(role) {
  return String(role || "")
    .trim()
    .toLowerCase();
}

function hasMarketingRoleValue(role) {
  const normalizedRole = normalizeMarketingRole(role);
  return MARKETING_ACCESS_ROLES.has(normalizedRole);
}

function isMarketingSectionId(sectionId) {
  return false;
}

function canAccessMarketingModule(user = getCurrentUser()) {
  return false;
}

function canApproveMarketingWorkflow(user = getCurrentUser()) {
  return false;
}

function getMarketingRoleLabel(role) {
  const normalizedRole = normalizeMarketingRole(role);
  if (normalizedRole === "marketing_manager") {
    return "Marketing Manager";
  }
  if (normalizedRole === "marketing_editor") {
    return "Marketing Editor";
  }
  if (normalizedRole === "marketing_designer") {
    return "Marketing Designer";
  }
  if (normalizedRole === "marketing") {
    return "Marketing";
  }
  return "";
}

