function setAppLoadingState(isLoading) {
  document.body.classList.toggle("app-loading", Boolean(isLoading));
}

function beginAuthFlow() {
  authFlowVersion += 1;
  return authFlowVersion;
}

function isCurrentAuthFlow(flowId) {
  const normalizedFlowId = Number(flowId);
  if (!Number.isFinite(normalizedFlowId) || normalizedFlowId <= 0) {
    return true;
  }
  return normalizedFlowId === authFlowVersion;
}

function cancelAuthFlow(flowId) {
  if (isCurrentAuthFlow(flowId)) {
    authFlowVersion += 1;
  }
}

function isProviderFormDirtyRelevantTarget(target) {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  const tagName = String(target.tagName || "").toLowerCase();
  if (!["input", "select", "textarea"].includes(tagName)) {
    return false;
  }
  if (target.id === "provider-topic-search") {
    return false;
  }
  if (target.closest("#provider-notes-tab-panel")) {
    return false;
  }
  if (target.matches('input[name="provider-bigplayer-mode"]')) {
    return false;
  }
  if (
    target.id === "provider-bigplayer-category-select" ||
    target.id === "provider-bigplayer-subcategory-category-select" ||
    target.id === "provider-bigplayer-subcategory-select" ||
    target.id === "provider-topic-template"
  ) {
    return false;
  }
  return true;
}

function markProviderFormDirty(target = null) {
  if (target && !isProviderFormDirtyRelevantTarget(target)) {
    return;
  }
  if (providersViewMode !== "form") {
    return;
  }
  providerFormDirty = true;
  providerDraftPendingResume = true;
}

function resolveProviderUnsavedChanges(decision) {
  const resolve = providerUnsavedChangesResolve;
  providerUnsavedChangesResolve = null;
  els.providerUnsavedChangesPanel?.classList.add("hidden");
  syncBodyModalOpenState();
  resolve?.(decision);
}

function openProviderUnsavedChangesDialog() {
  if (!els.providerUnsavedChangesPanel) {
    return Promise.resolve("cancel");
  }
  els.providerUnsavedChangesPanel.classList.remove("hidden");
  syncBodyModalOpenState();
  return new Promise((resolve) => {
    providerUnsavedChangesResolve = resolve;
  });
}

function waitForProviderSaveCompletion() {
  return new Promise((resolve) => {
    providerSaveCompletionResolvers.push(resolve);
  });
}

function resolveProviderSaveCompletion(saved) {
  const resolvers = providerSaveCompletionResolvers;
  providerSaveCompletionResolvers = [];
  resolvers.forEach((resolve) => resolve(Boolean(saved)));
}

function requestProviderFormSave() {
  const form = els.providerForm;
  if (!form) {
    return Promise.resolve(false);
  }
  // Ein Tab-Wechsel kann während eines laufenden Klick-Speicherns erneut ein
  // requestSubmit() auslösen. Die zweite Anfrage darf weder den ersten Save
  // überholen noch dessen Abschluss-Callback ersetzen.
  if (providerSaveInFlight) {
    // Nicht als Fehler behandeln: Der laufende Speichervorgang ist genau der,
    // dessen Ergebnis der anschließende Wechsel zur Übersicht benötigt.
    return waitForProviderSaveCompletion();
  }
  if (!form.checkValidity()) {
    const firstInvalidField = form.querySelector(":invalid");
    firstInvalidField?.focus({ preventScroll: false });
    form.reportValidity();
    showErrorFeedback(
      "Anbieter konnte nicht gespeichert werden. Bitte die markierten Pflichtfelder prüfen.",
      { toast: true, statusPersistMs: 5200, toastDurationMs: 5200 }
    );
    return Promise.resolve(false);
  }
  const completion = waitForProviderSaveCompletion();
  try {
    form.requestSubmit();
  } catch (error) {
    resolveProviderSaveCompletion(false);
    showErrorFeedback(
      "Anbieter konnte nicht gespeichert werden. Bitte Formular prüfen und erneut versuchen.",
      { toast: true, statusPersistMs: 5200, toastDurationMs: 5200 }
    );
    console.warn("Anbieterformular konnte nicht zum Speichern eingereicht werden.", error);
    return Promise.resolve(false);
  }
  return completion;
}

function getEditingProviderRecord() {
  const normalizedProviderId = String(editingProviderId || "").trim();
  if (!normalizedProviderId) {
    return null;
  }
  return (
    state.providers.find((entry) => String(entry?.id || "").trim() === normalizedProviderId) || null
  );
}

function setProviderCompetitorFormValues(isCompetitor, competitorName = "") {
  const toggle = els.providerForm?.elements?.competitor;
  const nameInput = els.providerForm?.elements?.competitorName;
  if (toggle instanceof HTMLInputElement) {
    toggle.checked = Boolean(isCompetitor);
  }
  if (nameInput instanceof HTMLInputElement) {
    nameInput.value = isCompetitor ? String(competitorName || "").trim() : "";
  }
}

function syncProviderCompetitorLockUi(provider = getEditingProviderRecord()) {
  const form = els.providerForm;
  const isExistingCompetitor = Boolean(editingProviderId && isProviderCompetitor(provider));
  const adminCanResolve = isExistingCompetitor && isRoleAdmin(getCurrentUser());
  const controls = [
    ...Array.from(form?.querySelectorAll("input, select, textarea, button") || []),
    ...Array.from(els.providerStatusSlider?.querySelectorAll('input[name="status"]') || []),
    ...Array.from(els.providerDetailTabButtons || []),
  ];

  form?.classList.toggle("is-competitor-locked", isExistingCompetitor);
  controls.forEach((control) => {
    const canResolveCompetitor = adminCanResolve && control.matches?.('input[name="competitor"]');
    const canLeaveForm = control === els.providerResetBtn;
    const shouldDisable = isExistingCompetitor && !canResolveCompetitor && !canLeaveForm;
    if (shouldDisable) {
      if (!Object.prototype.hasOwnProperty.call(control.dataset, "competitorLockPreviousDisabled")) {
        control.dataset.competitorLockPreviousDisabled = control.disabled ? "true" : "false";
      }
      control.disabled = true;
      return;
    }
    if (Object.prototype.hasOwnProperty.call(control.dataset, "competitorLockPreviousDisabled")) {
      control.disabled = control.dataset.competitorLockPreviousDisabled === "true";
      delete control.dataset.competitorLockPreviousDisabled;
    }
  });
}

function setProviderCompetitorSyncState(isSyncing) {
  const toggle = els.providerForm?.elements?.competitor;
  if (!(toggle instanceof HTMLInputElement)) {
    return;
  }
  const toggleContainer = toggle.closest(".provider-meta-competitor-toggle");
  const provider = getEditingProviderRecord();
  const lockedForAdminClarification = Boolean(
    editingProviderId && isProviderCompetitor(provider) && !isRoleAdmin(getCurrentUser())
  );
  toggle.disabled = Boolean(isSyncing) || lockedForAdminClarification;
  toggleContainer?.classList.toggle("is-syncing", Boolean(isSyncing));
}

async function requestProviderCompetitorName(providerName = "", initialName = "") {
  const titleName = String(providerName || "diesen Anbieter").trim() || "diesen Anbieter";
  if (
    !els.providerCompetitorPanel ||
    !els.providerCompetitorText ||
    !els.providerCompetitorForm ||
    !els.providerCompetitorName ||
    !els.providerCompetitorClose ||
    !els.providerCompetitorCancel
  ) {
    return String(window.prompt(`Name des Mitbewerbs für „${titleName}“ eingeben:`, initialName) || "").trim();
  }

  els.providerCompetitorText.textContent = `Bei welchem Mitbewerb ist „${titleName}“ bereits angelegt?`;
  els.providerCompetitorName.value = String(initialName || "").trim();
  els.providerCompetitorPanel.classList.remove("hidden");
  syncBodyModalOpenState();
  window.setTimeout(() => {
    els.providerCompetitorName?.focus();
    els.providerCompetitorName?.select();
  }, 0);

  return new Promise((resolve) => {
    let settled = false;
    const finish = (value = "") => {
      if (settled) {
        return;
      }
      settled = true;
      els.providerCompetitorPanel.classList.add("hidden");
      syncBodyModalOpenState();
      els.providerCompetitorForm.removeEventListener("submit", onSubmit);
      els.providerCompetitorCancel.removeEventListener("click", onCancel);
      els.providerCompetitorClose.removeEventListener("click", onCancel);
      document.removeEventListener("keydown", onKeyDown);
      resolve(String(value || "").trim());
    };
    const onSubmit = (event) => {
      event.preventDefault();
      const competitorName = String(els.providerCompetitorName.value || "").trim();
      if (!competitorName) {
        showWarningFeedback("Bitte den Namen des Mitbewerbs eingeben.");
        els.providerCompetitorName.focus();
        return;
      }
      finish(competitorName);
    };
    const onCancel = () => finish("");
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        finish("");
      }
    };

    els.providerCompetitorForm.addEventListener("submit", onSubmit);
    els.providerCompetitorCancel.addEventListener("click", onCancel);
    els.providerCompetitorClose.addEventListener("click", onCancel);
    document.addEventListener("keydown", onKeyDown);
  });
}

async function syncProviderCompetitorToggle(nextValue) {
  const toggle = els.providerForm?.elements?.competitor;
  if (!(toggle instanceof HTMLInputElement) || providerCompetitorSyncInFlight) {
    return false;
  }

  const shouldMarkCompetitor = Boolean(nextValue);
  let provider = getEditingProviderRecord();
  const currentCompetitor = provider ? isProviderCompetitor(provider) : false;
  const currentCompetitorName = provider ? getProviderCompetitorName(provider) : "";
  let competitorName = currentCompetitorName;

  if (shouldMarkCompetitor) {
    competitorName = await requestProviderCompetitorName(
      provider?.name || els.providerNameInput?.value || "",
      currentCompetitorName
    );
    if (!competitorName) {
      setProviderCompetitorFormValues(currentCompetitor, currentCompetitorName);
      return false;
    }
  } else {
    competitorName = "";
  }

  // Neue Anbieter werden mit dem regulären Speichern angelegt. Bei bestehenden
  // Datensätzen wird die Kennzeichnung sofort und vollständig synchronisiert.
  if (!editingProviderId) {
    setProviderCompetitorFormValues(shouldMarkCompetitor, competitorName);
    const dashboardToggle = els.providerForm?.elements?.dashboardCreated;
    if (dashboardToggle instanceof HTMLInputElement) {
      if (shouldMarkCompetitor) {
        if (!Object.prototype.hasOwnProperty.call(dashboardToggle.dataset, "competitorLockPreviousDisabled")) {
          dashboardToggle.dataset.competitorLockPreviousDisabled = dashboardToggle.disabled ? "true" : "false";
        }
        dashboardToggle.checked = false;
        dashboardToggle.disabled = true;
      } else if (Object.prototype.hasOwnProperty.call(dashboardToggle.dataset, "competitorLockPreviousDisabled")) {
        dashboardToggle.disabled = dashboardToggle.dataset.competitorLockPreviousDisabled === "true";
        delete dashboardToggle.dataset.competitorLockPreviousDisabled;
      }
    }
    markProviderFormDirty(toggle);
    return true;
  }

  // Ein laufender Hintergrund-Pull kann sonst den gerade gewählten Wert mit
  // einem älteren Stand überschreiben. Der Schalter bleibt bis zum Abschluss
  // gesperrt, danach wird der aktuelle Datensatz erst gelesen und gespeichert.
  if (remoteStatePullInFlight) {
    providerCompetitorSyncInFlight = true;
    setProviderCompetitorSyncState(true);
    try {
      const pullWaitDeadline = Date.now() + 5000;
      while (remoteStatePullInFlight && Date.now() < pullWaitDeadline) {
        await new Promise((resolve) => window.setTimeout(resolve, 40));
      }
      if (remoteStatePullInFlight) {
        setProviderCompetitorFormValues(currentCompetitor, currentCompetitorName);
        showActionFeedback("Die Hintergrundsynchronisierung läuft noch. Bitte erneut versuchen.", {
          tone: "error",
          toast: true,
          statusPersistMs: 4000,
        });
        return false;
      }
    } finally {
      providerCompetitorSyncInFlight = false;
      setProviderCompetitorSyncState(false);
    }
  }

  provider = getEditingProviderRecord();
  if (!provider) {
    setProviderCompetitorFormValues(false, "");
    return false;
  }
  if (!canCurrentUserOpenProvider(provider, getCurrentUser()) || isProviderInProgressLockedForCurrentUser(provider)) {
    setProviderCompetitorFormValues(isProviderCompetitor(provider), getProviderCompetitorName(provider));
    showProviderLockedFeedback(provider);
    return false;
  }

  const previousCompetitor = isProviderCompetitor(provider);
  const previousCompetitorName = getProviderCompetitorName(provider);
  if (shouldMarkCompetitor === previousCompetitor && competitorName === previousCompetitorName) {
    setProviderCompetitorFormValues(previousCompetitor, previousCompetitorName);
    return true;
  }

  const previousProviderSnapshot = JSON.parse(JSON.stringify(provider));
  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  const dashboardCreated = shouldMarkCompetitor ? false : isProviderDashboardCreated(provider);
  const hadPendingRemoteChanges = localChangesPendingRemoteSync;
  providerCompetitorSyncInFlight = true;
  setProviderCompetitorSyncState(true);
  if (!hadPendingRemoteChanges) {
    localChangesPendingRemoteSync = true;
  }

  Object.assign(provider, {
    competitor: shouldMarkCompetitor,
    isCompetitor: shouldMarkCompetitor,
    competitorName,
    competitor_name: competitorName,
    dashboardCreated,
    dashboard_created: dashboardCreated,
    updatedAt: nowIso,
    updatedByName: actor.name,
    updatedByRole: actor.role,
    updatedByUserId: actor.userId,
  });
  Object.assign(provider, normalizeProviderRecord(provider) || provider);
  setProviderCompetitorFormValues(shouldMarkCompetitor, competitorName);
  renderProvidersTable();

  try {
    const persistence = await persistCriticalStateSnapshot({
      retries: 3,
      providersSync: { upsertProviderIds: [provider.id] },
    });
    if (!persistence?.ok) {
      throw persistence?.error || new Error(String(persistence?.reason || "sync_failed"));
    }
    if (els.providerUpdatedMeta) {
      els.providerUpdatedMeta.textContent = formatAuditStamp(
        provider.updatedAt,
        provider.updatedByRole,
        provider.updatedByName
      );
    }
    fillProviderForm(provider);
    showSuccessFeedback("Mitbewerb-Markierung synchronisiert.", { toast: false, statusPersistMs: 1400 });
    return true;
  } catch (error) {
    Object.keys(provider).forEach((key) => {
      delete provider[key];
    });
    Object.assign(provider, previousProviderSnapshot);
    setProviderCompetitorFormValues(previousCompetitor, previousCompetitorName);
    if (!hadPendingRemoteChanges) {
      localChangesPendingRemoteSync = false;
    }
    persistLocalBackup();
    renderProvidersTable();
    console.warn("Mitbewerb-Markierung konnte nicht synchronisiert werden.", error);
    showActionFeedback(
      "Mitbewerb-Markierung konnte nicht synchronisiert werden. Der bisherige Wert wurde wiederhergestellt.",
      { tone: "error", toast: true, statusPersistMs: 5000, toastDurationMs: 5000 }
    );
    return false;
  } finally {
    providerCompetitorSyncInFlight = false;
    setProviderCompetitorSyncState(false);
  }
}

function setProviderDashboardCreatedSyncState(isSyncing) {
  const toggle = els.providerForm?.elements?.dashboardCreated;
  if (!(toggle instanceof HTMLInputElement)) {
    return;
  }
  const toggleContainer = toggle.closest(".provider-meta-dashboard-toggle");
  const provider = getEditingProviderRecord();
  toggle.disabled = Boolean(isSyncing) || Boolean(editingProviderId && isProviderCompetitor(provider));
  toggleContainer?.classList.toggle("is-syncing", Boolean(isSyncing));
}

async function syncProviderDashboardCreatedToggle(nextValue) {
  let provider = getEditingProviderRecord();
  const toggle = els.providerForm?.elements?.dashboardCreated;
  if (!(toggle instanceof HTMLInputElement) || !provider || providerDashboardCreatedSyncInFlight) {
    return false;
  }
  if (!canCurrentUserSetProviderDashboardCreated(getCurrentUser())) {
    toggle.checked = isProviderDashboardCreated(provider);
    return false;
  }
  if (isProviderCompetitor(provider)) {
    toggle.checked = false;
    showWarningFeedback(
      `Dieser Anbieter ist bereits bei „${getProviderCompetitorName(provider) || "einem Mitbewerb"}“ platziert und bis zur Klärung durch den Admin gesperrt.`
    );
    return false;
  }
  if (isProviderInProgressLockedForCurrentUser(provider)) {
    toggle.checked = isProviderDashboardCreated(provider);
    showProviderLockedFeedback(provider);
    return false;
  }

  // Ein bereits laufender Pull könnte sonst noch den alten Tabellenstand über
  // den gerade bearbeiteten Datensatz legen. Erst dessen Abschluss abwarten,
  // danach wird der neue Wert exklusiv gespeichert.
  if (remoteStatePullInFlight) {
    providerDashboardCreatedSyncInFlight = true;
    setProviderDashboardCreatedSyncState(true);
    try {
      const pullWaitDeadline = Date.now() + 5000;
      while (remoteStatePullInFlight && Date.now() < pullWaitDeadline) {
        await new Promise((resolve) => window.setTimeout(resolve, 40));
      }
      if (remoteStatePullInFlight) {
        toggle.checked = isProviderDashboardCreated(provider);
        showActionFeedback("Die Hintergrundsynchronisierung läuft noch. Bitte erneut versuchen.", {
          tone: "error",
          toast: true,
          statusPersistMs: 4000,
        });
        return false;
      }
      provider = getEditingProviderRecord();
      if (!provider) {
        return false;
      }
      if (isProviderCompetitor(provider)) {
        toggle.checked = false;
        showWarningFeedback(
          `Dieser Anbieter ist bereits bei „${getProviderCompetitorName(provider) || "einem Mitbewerb"}“ platziert und bis zur Klärung durch den Admin gesperrt.`
        );
        return false;
      }
      if (isProviderInProgressLockedForCurrentUser(provider)) {
        toggle.checked = isProviderDashboardCreated(provider);
        showProviderLockedFeedback(provider);
        return false;
      }
    } finally {
      providerDashboardCreatedSyncInFlight = false;
      setProviderDashboardCreatedSyncState(false);
    }
  }

  const dashboardCreated = Boolean(nextValue);
  const previousDashboardCreated = isProviderDashboardCreated(provider);
  if (dashboardCreated === previousDashboardCreated) {
    return true;
  }

  if (dashboardCreated && isProviderCompetitor(provider)) {
    const competitorName = getProviderCompetitorName(provider) || "einem Mitbewerb";
    const confirmed = await confirmAction(
      `Dieser Anbieter ist bereits bei „${competitorName}“ angelegt. Trotzdem als im Dashboard angelegt markieren?`,
      {
        title: "Mitbewerb-Hinweis",
        confirmLabel: "Trotzdem aktivieren",
        danger: true,
      }
    );
    if (!confirmed) {
      toggle.checked = previousDashboardCreated;
      return false;
    }
    provider = getEditingProviderRecord() || provider;
  }

  const previousProviderSnapshot = JSON.parse(JSON.stringify(provider));
  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  const hadPendingRemoteChanges = localChangesPendingRemoteSync;
  providerDashboardCreatedSyncInFlight = true;
  setProviderDashboardCreatedSyncState(true);

  // Ab hier darf kein Hintergrund-Pull den optimistisch gesetzten Wert mit
  // einem älteren Snapshot überschreiben. Der Flag wird nach dem bestätigten
  // Vollspeichern wieder von persistStateToSupabase zurückgesetzt.
  if (!hadPendingRemoteChanges) {
    localChangesPendingRemoteSync = true;
  }

  Object.assign(provider, {
    dashboardCreated,
    dashboard_created: dashboardCreated,
    updatedAt: nowIso,
    updatedByName: actor.name,
    updatedByRole: actor.role,
    updatedByUserId: actor.userId,
  });
  Object.assign(provider, normalizeProviderRecord(provider) || provider);
  renderProvidersTable();

  try {
    const persistence = await persistCriticalStateSnapshot({
      retries: 3,
      providersSync: { upsertProviderIds: [provider.id] },
    });
    if (!persistence?.ok) {
      throw persistence?.error || new Error(String(persistence?.reason || "sync_failed"));
    }
    if (els.providerUpdatedMeta) {
      els.providerUpdatedMeta.textContent = formatAuditStamp(
        provider.updatedAt,
        provider.updatedByRole,
        provider.updatedByName
      );
    }
    showSuccessFeedback("Dashboard-Status synchronisiert.", { toast: false, statusPersistMs: 1400 });
    return true;
  } catch (error) {
    Object.keys(provider).forEach((key) => {
      delete provider[key];
    });
    Object.assign(provider, previousProviderSnapshot);
    toggle.checked = previousDashboardCreated;
    if (!hadPendingRemoteChanges) {
      localChangesPendingRemoteSync = false;
    }
    persistLocalBackup();
    renderProvidersTable();
    console.warn("Dashboard-Status konnte nicht synchronisiert werden.", error);
    showActionFeedback(
      "Dashboard-Status konnte nicht synchronisiert werden. Der bisherige Wert wurde wiederhergestellt.",
      { tone: "error", toast: true, statusPersistMs: 5000, toastDurationMs: 5000 }
    );
    return false;
  } finally {
    providerDashboardCreatedSyncInFlight = false;
    setProviderDashboardCreatedSyncState(false);
  }
}

function isProviderStatusDirtyInForm() {
  if (providersViewMode !== "form" || !editingProviderId || !els.providerForm) {
    return false;
  }
  const provider = getEditingProviderRecord();
  if (!provider) {
    return false;
  }
  const formStatus = normalizeProviderStatusValue(getProviderStatusFromForm());
  const savedStatus = normalizeProviderStatusValue(provider.status || "offen");
  const formComparable = getProviderStatusFormComparableValue(formStatus);
  const savedComparable = getProviderStatusFormComparableValue(savedStatus);
  if (formComparable !== savedComparable) {
    return true;
  }
  return providerStatusTouchedInForm && formStatus !== savedStatus;
}

function hasUnsavedProviderFormChanges() {
  return providerFormDirty || isProviderStatusDirtyInForm();
}

async function leaveProviderForm({ nextTab = "", close = false } = {}) {
  const normalizedNextTab = nextTab ? normalizeProviderDetailTab(nextTab) : "";
  const fallbackTab = normalizedNextTab || providerDetailTab;
  const activeProvider = getEditingProviderRecord();
  // Die Mitbewerb-Kennzeichnung wurde bereits sofort gespeichert. Sie darf den
  // Rückweg zur Übersicht niemals über einen alten Entwurfszustand blockieren.
  if (close && isProviderCompetitor(activeProvider)) {
    providerFormDirty = false;
    providerDraftPendingResume = false;
    clearProviderForm();
    setProvidersView("list");
    restoreProviderAnalyticsAfterEditor();
    return;
  }
  if (!hasUnsavedProviderFormChanges()) {
    if (close) {
      clearProviderForm();
      setProvidersView("list");
      restoreProviderAnalyticsAfterEditor();
    } else if (normalizedNextTab) {
      setProviderDetailTab(normalizedNextTab);
    }
    return;
  }

  const decision = await openProviderUnsavedChangesDialog();
  if (decision === "cancel") {
    return;
  }
  if (decision === "discard") {
    providerFormDirty = false;
    providerDraftPendingResume = false;
    if (close) {
      clearProviderForm();
      setProvidersView("list");
      restoreProviderAnalyticsAfterEditor();
    } else if (normalizedNextTab) {
      const provider = getEditingProviderRecord();
      if (provider) {
        fillProviderForm(provider);
        if (els.providerSaveBtn) {
          els.providerSaveBtn.textContent = "Aktualisieren";
        }
      } else {
        clearProviderForm();
      }
      providerFormDirty = false;
      providerDraftPendingResume = false;
      setProviderDetailTab(fallbackTab);
    }
    return;
  }

  providerPendingTabAfterSave = normalizedNextTab;
  providerPendingCloseAfterSave = close;
  const saved = await requestProviderFormSave();
  if (saved) {
    // Falls der ursprüngliche Klick bereits kurz vor dem Abschluss war,
    // konnte er den eben gesetzten Wechselwunsch noch nicht sehen. Den
    // gewünschten Zielzustand nach dem bestätigten Save deshalb nochmals
    // atomar herstellen.
    providerPendingTabAfterSave = "";
    providerPendingCloseAfterSave = false;
    providerFormDirty = false;
    providerDraftPendingResume = false;
    providerStatusTouchedInForm = false;
    if (close && providersViewMode === "form") {
      clearProviderForm();
      setProvidersView("list");
      restoreProviderAnalyticsAfterEditor();
    } else if (normalizedNextTab && providersViewMode === "form") {
      setProviderDetailTab(normalizedNextTab);
    }
    return;
  }
  providerPendingTabAfterSave = "";
  providerPendingCloseAfterSave = false;
  providerFormDirty = true;
  providerDraftPendingResume = true;
}

function inferFeedbackTone(message, fallbackTone = "info") {
  const normalized = String(message || "").trim().toLowerCase();
  if (!normalized) {
    return fallbackTone;
  }
  if (
    normalized.includes("konnte nicht") ||
    normalized.includes("fehlgeschlagen") ||
    normalized.includes("fehler") ||
    normalized.includes("ungultig") ||
    normalized.includes("ungültig") ||
    normalized.includes("blockiert") ||
    normalized.includes("nicht erlaubt") ||
    normalized.includes("nicht moglich") ||
    normalized.includes("nicht möglich") ||
    normalized.includes("sql fehlt")
  ) {
    return "error";
  }
  if (
    normalized.includes("gespeichert") ||
    normalized.includes("aktualisiert") ||
    normalized.includes("geloscht") ||
    normalized.includes("gelöscht") ||
    normalized.includes("entfernt") ||
    normalized.includes("freigeschaltet") ||
    normalized.includes("erstellt")
  ) {
    return "success";
  }
  if (normalized.startsWith("bitte ")) {
    return "warning";
  }
  return fallbackTone;
}

function renderActionFeedbackStatus(message, tone = "info", persistMs = 2600) {
  if (!els.actionFeedbackStatus) {
    return;
  }
  const text = String(message || "").trim();
  if (!text) {
    els.actionFeedbackStatus.textContent = "";
    els.actionFeedbackStatus.classList.add("hidden");
    return;
  }

  const sequence = actionFeedbackSequence + 1;
  actionFeedbackSequence = sequence;
  if (actionFeedbackStatusTimeoutId) {
    window.clearTimeout(actionFeedbackStatusTimeoutId);
    actionFeedbackStatusTimeoutId = 0;
  }

  els.actionFeedbackStatus.textContent = text;
  els.actionFeedbackStatus.classList.remove("hidden", "is-success", "is-error", "is-warning", "is-info");
  els.actionFeedbackStatus.classList.add(
    tone === "error" ? "is-error" : tone === "success" ? "is-success" : tone === "warning" ? "is-warning" : "is-info"
  );

  if (persistMs > 0) {
    actionFeedbackStatusTimeoutId = window.setTimeout(() => {
      if (sequence !== actionFeedbackSequence || !els.actionFeedbackStatus) {
        return;
      }
      els.actionFeedbackStatus.classList.add("hidden");
      els.actionFeedbackStatus.textContent = "";
    }, persistMs);
  }
}

function renderActionToast(message, tone = "info", durationMs = 3600) {
  if (!els.actionToastStack) {
    return;
  }
  const text = String(message || "").trim();
  if (!text) {
    return;
  }

  const toast = document.createElement("div");
  toast.className = `action-toast is-${tone}`;
  toast.textContent = text;
  toast.dataset.toastId = String(++actionToastSequence);
  els.actionToastStack.prepend(toast);

  const lifetimeMs = Number.isFinite(durationMs) ? Math.max(1100, durationMs) : 3600;
  window.setTimeout(() => {
    toast.remove();
  }, lifetimeMs);
}

function showActionFeedback(message, options = {}) {
  const text = String(message || "").trim();
  if (!text) {
    return;
  }
  const tone = options?.tone || inferFeedbackTone(text, "info");
  // Kurzfristige Status- und technische Browserhinweise gehören nicht in die
  // Glocke. Dort stehen ausschließlich fachliche Benachrichtigungen.
  if (options?.notification === true) {
    appendAdminSystemNotification(text, tone);
  }
  const statusPersistMs = Number.isFinite(options?.statusPersistMs) ? options.statusPersistMs : 2600;
  const withToast = options?.toast === true;
  const toastDurationMs = Number.isFinite(options?.toastDurationMs) ? options.toastDurationMs : 3600;
  renderActionFeedbackStatus(text, tone, statusPersistMs);
  if (withToast) {
    renderActionToast(text, tone, toastDurationMs);
  }
}

function showSuccessFeedback(message, options = {}) {
  showActionFeedback(message, { ...options, tone: "success" });
}

function showInfoFeedback(message, options = {}) {
  showActionFeedback(message, { ...options, tone: "info" });
}

function showWarningFeedback(message, options = {}) {
  showActionFeedback(message, { ...options, tone: "warning" });
}

function showErrorFeedback(message, options = {}) {
  showActionFeedback(message, { ...options, tone: "error" });
}

function announceAutoSaveFeedback() {
  const now = Date.now();
  if (now - lastAutoSaveFeedbackAt < 1400) {
    return;
  }
  lastAutoSaveFeedbackAt = now;
  showSuccessFeedback("Änderungen gespeichert.", { toast: false, statusPersistMs: 1700 });
}

function showProviderSaveConfirmation(wasEditingProvider, isLivePendingRequest = false) {
  const message = isLivePendingRequest ? "Live-Anfrage gespeichert." : wasEditingProvider ? "Gespeichert." : "Anbieter gespeichert.";
  showSuccessFeedback(message, { toast: false, statusPersistMs: 1400 });
}

function setActionButtonBusy(button, busy, busyLabel = "Speichert...") {
  if (!(button instanceof HTMLElement)) {
    return;
  }
  if (busy) {
    button.dataset.busyOriginalLabel = button.textContent || "";
    button.textContent = busyLabel;
    button.classList.add("is-busy");
    button.setAttribute("disabled", "disabled");
    return;
  }
  const originalLabel = String(button.dataset.busyOriginalLabel || "").trim();
  if (originalLabel) {
    button.textContent = originalLabel;
  }
  delete button.dataset.busyOriginalLabel;
  button.classList.remove("is-busy");
  button.removeAttribute("disabled");
}

function installAlertBridge() {
  if (typeof window === "undefined" || typeof window.alert !== "function") {
    return;
  }
  if (window.__vertriebsmanagerAlertBridgeInstalled) {
    return;
  }
  nativeWindowAlert = window.alert.bind(window);
  window.alert = (message) => {
    const text = String(message || "").trim();
    if (!text) {
      return;
    }
    showActionFeedback(text, {
      tone: inferFeedbackTone(text, "warning"),
      toast: true,
      statusPersistMs: 5400,
      toastDurationMs: 5400,
    });
  };
  window.__vertriebsmanagerAlertBridgeInstalled = true;
}

function normalizeAuthMode(mode) {
  return mode === "signup" ? "signup" : "signin";
}

function setAuthFieldRequired(field, required) {
  if (!field) {
    return;
  }
  field.required = Boolean(required);
}

function getAuthSignUpPasswordValidation(password = "", confirmPassword = "") {
  const value = String(password || "");
  const confirmValue = String(confirmPassword || "");
  const checks = Object.fromEntries(
    Object.entries(AUTH_SIGNUP_PASSWORD_RULES).map(([rule, validator]) => [rule, Boolean(validator(value))])
  );
  checks.match = confirmValue.length > 0 && value === confirmValue;
  checks.validPassword = checks.length && checks.lower && checks.upper && checks.number && checks.special;
  checks.allValid = checks.validPassword && checks.match;
  return checks;
}

function refreshAuthSignUpPasswordRules() {
  const rulesRoot = els.authSignUpPasswordRules;
  if (!rulesRoot) {
    return;
  }
  const password = String(els.authSignUpPassword?.value || "");
  const confirmPassword = String(els.authSignUpPasswordConfirm?.value || "");
  const checks = getAuthSignUpPasswordValidation(password, confirmPassword);
  rulesRoot.querySelectorAll("[data-rule]").forEach((ruleElement) => {
    const rule = String(ruleElement.dataset.rule || "").trim();
    const met = Boolean(checks[rule]);
    ruleElement.classList.toggle("is-met", met);
  });
}

function refreshPasswordRules(rulesRoot, password = "", confirmPassword = "") {
  if (!rulesRoot) {
    return;
  }
  const checks = getAuthSignUpPasswordValidation(password, confirmPassword);
  rulesRoot.querySelectorAll("[data-rule]").forEach((ruleElement) => {
    const rule = String(ruleElement.dataset.rule || "").trim();
    ruleElement.classList.toggle("is-met", Boolean(checks[rule]));
  });
}

function refreshMyAccountPasswordRules() {
  const form = els.myAccountPasswordForm;
  refreshPasswordRules(
    els.myAccountPasswordRules,
    String(form?.elements?.newPassword?.value || ""),
    String(form?.elements?.confirmPassword?.value || "")
  );
}

function refreshPasswordRecoveryRules() {
  refreshPasswordRules(
    els.authPasswordRecoveryRules,
    String(els.authPasswordRecoveryNew?.value || ""),
    String(els.authPasswordRecoveryConfirm?.value || "")
  );
}

function setMyAccountPasswordFeedback(message = "", tone = "") {
  if (!els.myAccountPasswordFeedback) {
    return;
  }
  els.myAccountPasswordFeedback.textContent = String(message || "").trim();
  els.myAccountPasswordFeedback.classList.toggle("is-success", tone === "success");
  els.myAccountPasswordFeedback.classList.toggle("is-error", tone === "error");
}

function renderMyAccountSection() {
  const currentUser = getCurrentUser();
  const userName = String(currentUser?.name || authProfile?.full_name || "Benutzer").trim() || "Benutzer";
  const email = String(authSession?.user?.email || authProfile?.email || currentUser?.email || "").trim();
  const role = currentUser ? getRoleLabel(currentUser.role) : "–";

  if (els.myAccountName) {
    els.myAccountName.textContent = userName;
  }
  if (els.myAccountEmail) {
    els.myAccountEmail.textContent = email || "Keine E-Mail-Adresse hinterlegt";
  }
  if (els.myAccountRole) {
    els.myAccountRole.textContent = role;
  }
  refreshMyAccountPasswordRules();
  renderMyInventorySection();
}

function getMyAccountPasswordErrorMessage(error) {
  const message = String(error?.message || "").trim();
  const normalizedMessage = normalizeText(message);
  if (normalizedMessage.includes("invalid login credentials") || normalizedMessage.includes("invalid password")) {
    return "Das aktuelle Passwort ist nicht korrekt.";
  }
  if (normalizedMessage.includes("same password")) {
    return "Das neue Passwort muss sich vom bisherigen Passwort unterscheiden.";
  }
  if (
    normalizedMessage.includes("password should") ||
    normalizedMessage.includes("weak password") ||
    normalizedMessage.includes("password is too weak")
  ) {
    return "Das neue Passwort erfüllt die Sicherheitsanforderungen nicht.";
  }
  if (normalizedMessage.includes("rate limit")) {
    return "Zu viele Versuche. Bitte warte kurz und versuche es erneut.";
  }
  return message || "Das Passwort konnte nicht geändert werden. Bitte versuche es erneut.";
}

async function handleMyAccountPasswordChange() {
  const form = els.myAccountPasswordForm;
  const currentUser = getCurrentUser();
  const client = getSupabaseClient();
  const email = String(authSession?.user?.email || authProfile?.email || currentUser?.email || "").trim();
  if (!form || !currentUser || !client || !email) {
    setMyAccountPasswordFeedback("Dein Konto ist gerade nicht verfügbar. Bitte melde dich erneut an.", "error");
    return;
  }

  const formData = new FormData(form);
  const currentPassword = String(formData.get("currentPassword") || "");
  const newPassword = String(formData.get("newPassword") || "");
  const confirmPassword = String(formData.get("confirmPassword") || "");
  const validation = getAuthSignUpPasswordValidation(newPassword, confirmPassword);
  refreshMyAccountPasswordRules();

  if (!currentPassword) {
    setMyAccountPasswordFeedback("Bitte gib dein aktuelles Passwort ein.", "error");
    return;
  }
  if (!validation.validPassword) {
    setMyAccountPasswordFeedback("Das neue Passwort erfüllt die Sicherheitsanforderungen nicht.", "error");
    return;
  }
  if (!validation.match) {
    setMyAccountPasswordFeedback("Die beiden neuen Passwörter stimmen nicht überein.", "error");
    return;
  }
  if (currentPassword === newPassword) {
    setMyAccountPasswordFeedback("Das neue Passwort muss sich vom bisherigen Passwort unterscheiden.", "error");
    return;
  }

  setMyAccountPasswordFeedback("");
  setActionButtonBusy(els.myAccountPasswordSubmit, true, "Passwort wird geändert...");
  try {
    // Die erneute Anmeldung verifiziert das aktuelle Passwort unabhängig von
    // optionalen Supabase-Projekteinstellungen. Es wird nur für den bereits
    // angemeldeten Benutzer durchgeführt und erzeugt keine fremde Berechtigung.
    const { data: verificationData, error: verificationError } = await withAsyncTimeout(
      client.auth.signInWithPassword({ email, password: currentPassword }),
      AUTH_REQUEST_TIMEOUT_MS,
      "Die Prüfung des aktuellen Passworts dauert zu lange."
    );
    if (verificationError || !verificationData?.session) {
      setMyAccountPasswordFeedback(getMyAccountPasswordErrorMessage(verificationError), "error");
      return;
    }
    authSession = verificationData.session;

    const { data, error } = await withAsyncTimeout(
      client.auth.updateUser({ password: newPassword, current_password: currentPassword }),
      AUTH_REQUEST_TIMEOUT_MS,
      "Die Passwortänderung dauert zu lange."
    );
    if (error) {
      setMyAccountPasswordFeedback(getMyAccountPasswordErrorMessage(error), "error");
      return;
    }

    authSession = data?.session || authSession;
    form.reset();
    refreshMyAccountPasswordRules();
    setMyAccountPasswordFeedback("Dein Passwort wurde sicher geändert.", "success");
    showSuccessFeedback("Passwort geändert.", { toast: true, statusPersistMs: 2600 });
  } catch (error) {
    setMyAccountPasswordFeedback(getMyAccountPasswordErrorMessage(error), "error");
  } finally {
    setActionButtonBusy(els.myAccountPasswordSubmit, false);
  }
}

function setAuthMode(mode, { preserveMessage = false } = {}) {
  authMode = normalizeAuthMode(mode);
  const signInMode = authMode === "signin";

  if (els.authModeSignInBtn) {
    els.authModeSignInBtn.classList.toggle("active", signInMode);
  }
  if (els.authModeSignUpBtn) {
    els.authModeSignUpBtn.classList.toggle("active", !signInMode);
  }
  if (els.authSignInFields) {
    els.authSignInFields.classList.toggle("hidden", !signInMode);
  }
  if (els.authSignUpFields) {
    els.authSignUpFields.classList.toggle("hidden", signInMode);
  }
  if (els.authSubmitBtn) {
    els.authSubmitBtn.textContent = signInMode ? "Anmelden" : "Registrieren";
  }

  if (signInMode) {
    if (els.authSignInEmail && !els.authSignInEmail.value && els.authSignUpEmail?.value) {
      els.authSignInEmail.value = els.authSignUpEmail.value;
    }
  } else if (els.authSignUpEmail && !els.authSignUpEmail.value && els.authSignInEmail?.value) {
    els.authSignUpEmail.value = els.authSignInEmail.value;
  }

  setAuthFieldRequired(els.authSignInEmail, signInMode);
  setAuthFieldRequired(els.authSignInPassword, signInMode);
  setAuthFieldRequired(els.authSignUpFullName, !signInMode);
  setAuthFieldRequired(els.authSignUpEmail, !signInMode);
  setAuthFieldRequired(els.authSignUpPassword, !signInMode);
  setAuthFieldRequired(els.authSignUpPasswordConfirm, !signInMode);

  refreshAuthSignUpPasswordRules();

  if (!preserveMessage && els.authMessage) {
    els.authMessage.textContent = "";
  }
}

function isPasswordRecoveryRequest() {
  try {
    return new URL(window.location.href).searchParams.get("auth") === "recovery";
  } catch (_error) {
    return false;
  }
}

function getPasswordRecoveryRedirectUrl() {
  const url = new URL(window.location.href);
  ["code", "error", "error_code", "error_description"].forEach((parameter) => url.searchParams.delete(parameter));
  url.searchParams.set("auth", "recovery");
  url.hash = "";
  return url.toString();
}

function clearPasswordRecoveryUrl() {
  const url = new URL(window.location.href);
  if (!url.searchParams.has("auth") && !url.searchParams.has("code") && !url.hash) {
    return;
  }
  url.searchParams.delete("auth");
  url.searchParams.delete("code");
  url.searchParams.delete("error");
  url.searchParams.delete("error_code");
  url.searchParams.delete("error_description");
  url.hash = "";
  window.history.replaceState({}, "", `${url.pathname}${url.search}`);
}

function setPasswordRecoveryMode(active, options = {}) {
  passwordRecoveryMode = Boolean(active);
  const available = options.available !== false;
  if (els.authModeSwitch) {
    els.authModeSwitch.classList.toggle("hidden", passwordRecoveryMode);
  }
  if (els.authForm) {
    els.authForm.classList.toggle("hidden", passwordRecoveryMode);
  }
  if (els.authPasswordRecoveryForm) {
    els.authPasswordRecoveryForm.classList.toggle("hidden", !passwordRecoveryMode);
  }
  if (els.authPasswordRecoverySubmit) {
    els.authPasswordRecoverySubmit.disabled = !available;
  }
  if (passwordRecoveryMode) {
    refreshPasswordRecoveryRules();
  }
  if (options.message) {
    showAuthGate(options.message);
  }
}

async function handlePasswordResetRequest() {
  const client = getSupabaseClient();
  const email = String(els.authSignInEmail?.value || "").trim().toLowerCase();
  if (!client) {
    showAuthGate("Supabase ist nicht erreichbar. Konfiguration prüfen.");
    return;
  }
  if (!email || !email.includes("@")) {
    showAuthGate("Bitte gib zuerst deine E-Mail-Adresse ein.");
    els.authSignInEmail?.focus();
    return;
  }

  setActionButtonBusy(els.authForgotPasswordBtn, true, "Link wird angefordert...");
  try {
    const { error } = await withAsyncTimeout(
      client.auth.resetPasswordForEmail(email, { redirectTo: getPasswordRecoveryRedirectUrl() }),
      AUTH_REQUEST_TIMEOUT_MS,
      "Die Anfrage dauert zu lange. Bitte versuche es erneut."
    );
    if (error) {
      throw error;
    }
    showAuthGate("Falls zu dieser E-Mail ein Konto besteht, wurde ein Link zum Zurücksetzen versendet.");
  } catch (error) {
    showAuthGate(getMyAccountPasswordErrorMessage(error));
  } finally {
    setActionButtonBusy(els.authForgotPasswordBtn, false);
  }
}

async function leavePasswordRecoveryMode(message = "Bitte melde dich an.") {
  const client = getSupabaseClient();
  passwordRecoveryMode = false;
  clearPasswordRecoveryUrl();
  els.authPasswordRecoveryForm?.reset();
  refreshPasswordRecoveryRules();
  if (client) {
    suppressNextSignedOutAuthMessage = true;
    try {
      await client.auth.signOut();
    } catch (error) {
      console.warn("Recovery-Session konnte nicht beendet werden.", error);
    }
  }
  authSession = null;
  authProfile = null;
  setPasswordRecoveryMode(false);
  setAuthMode("signin", { preserveMessage: true });
  showAuthGate(message);
  setAppLoadingState(false);
  els.authSignInPassword?.focus();
}

async function handlePasswordRecoverySubmit() {
  const client = getSupabaseClient();
  const newPassword = String(els.authPasswordRecoveryNew?.value || "");
  const confirmPassword = String(els.authPasswordRecoveryConfirm?.value || "");
  const validation = getAuthSignUpPasswordValidation(newPassword, confirmPassword);
  refreshPasswordRecoveryRules();
  if (!client || !authSession) {
    showAuthGate("Dieser Rücksetzlink ist nicht mehr gültig. Bitte fordere einen neuen Link an.");
    return;
  }
  if (!validation.validPassword) {
    showAuthGate("Bitte erfülle alle Passwort-Kriterien.");
    return;
  }
  if (!validation.match) {
    showAuthGate("Die beiden Passwörter stimmen nicht überein.");
    return;
  }

  setActionButtonBusy(els.authPasswordRecoverySubmit, true, "Passwort wird gespeichert...");
  try {
    const { error } = await withAsyncTimeout(
      client.auth.updateUser({ password: newPassword }),
      AUTH_REQUEST_TIMEOUT_MS,
      "Die Passwortänderung dauert zu lange. Bitte versuche es erneut."
    );
    if (error) {
      throw error;
    }
    await leavePasswordRecoveryMode("Dein Passwort wurde geändert. Bitte melde dich mit dem neuen Passwort an.");
  } catch (error) {
    showAuthGate(getMyAccountPasswordErrorMessage(error));
  } finally {
    setActionButtonBusy(els.authPasswordRecoverySubmit, false);
  }
}

async function initialize() {
  setAppLoadingState(true);
  setAuthMode("signin", { preserveMessage: true });
  bindEvents();
  initializeRequiredFieldIndicators();
  window.addEventListener("pagehide", () => {
    if (localBackupQueuedHandle !== null) {
      flushQueuedLocalBackup();
    }
  });
  showAuthGate("Bitte melde dich an.");
  clearLegacyAuthErrorParams();
  void restoreStartupSessionInBackground();
}

async function restoreStartupSessionInBackground() {
  const flowId = beginAuthFlow();
  try {
    const authReady = await withAsyncTimeout(
      initializeAuth(flowId),
      6000,
      "Initiale Session-Prüfung hat zu lange gedauert."
    );
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    if (passwordRecoveryMode || isPasswordRecoveryRequest()) {
      const recoveryAvailable = Boolean(authReady && authSession);
      clearPasswordRecoveryUrl();
      setPasswordRecoveryMode(true, {
        available: recoveryAvailable,
        message: recoveryAvailable
          ? "Bestätige dein neues Passwort."
          : "Dieser Rücksetzlink ist nicht mehr gültig. Bitte fordere einen neuen Link an.",
      });
      setAppLoadingState(false);
      return;
    }
    if (!authReady) {
      if (!String(els.authMessage?.textContent || "").trim()) {
        showAuthGate("Bitte melde dich an.");
      }
      setAppLoadingState(false);
      return;
    }
    showAuthGate("Sitzung gefunden. Dashboard wird geladen...");
    await withAsyncTimeout(
      finishBootstrapAfterLogin(flowId),
      APP_STARTUP_TIMEOUT_MS,
      "Dashboard-Start hat zu lange gedauert."
    );
  } catch (error) {
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    cancelAuthFlow(flowId);
    console.error("Session-Start im Hintergrund fehlgeschlagen:", error);
    const startupMessage = String(error?.message || "").trim();
    showAuthGate(startupMessage || "Bitte melde dich an.");
    setAppLoadingState(false);
  }
}

async function withAsyncTimeout(promiseLike, timeoutMs, message) {
  const timeout = Math.max(1000, Number(timeoutMs) || 0);
  let timeoutId = 0;
  try {
    return await Promise.race([
      Promise.resolve(promiseLike),
      new Promise((_, reject) => {
        timeoutId = window.setTimeout(() => {
          reject(new Error(message || "Vorgang hat zu lange gedauert."));
        }, timeout);
      }),
    ]);
  } finally {
    if (timeoutId) {
      window.clearTimeout(timeoutId);
    }
  }
}

function createTimeoutError(message) {
  const error = new Error(message || "Vorgang hat zu lange gedauert.");
  error.name = "TimeoutError";
  return error;
}

function normalizeAuthApiError(payload, fallbackMessage = "Anmeldung fehlgeschlagen.") {
  const message =
    payload?.msg ||
    payload?.message ||
    payload?.error_description ||
    payload?.error ||
    fallbackMessage;
  return {
    message: String(message || fallbackMessage),
    code: payload?.code || payload?.error_code || "",
  };
}

async function fetchJsonWithTimeout(url, options = {}, timeoutMs = AUTH_REQUEST_TIMEOUT_MS, timeoutMessage = "") {
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => {
    controller.abort(createTimeoutError(timeoutMessage));
  }, Math.max(1000, Number(timeoutMs) || AUTH_REQUEST_TIMEOUT_MS));

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });
    const payload = await response.json().catch(() => null);
    return { response, payload };
  } catch (error) {
    if (error?.name === "AbortError" || error?.name === "TimeoutError") {
      throw createTimeoutError(timeoutMessage);
    }
    throw error;
  } finally {
    window.clearTimeout(timeoutId);
  }
}

// Supabase erhält diese Fetch-Implementierung beim Erzeugen des Clients. Damit
// sind auch PostgREST-Abfragen (Anbieter, Claims, Sync) wirklich abbrechbar;
// ein Promise-Rennen allein würde einen hängenden Netzwerkrequest im Hintergrund
// weiterlaufen lassen.
async function fetchSupabaseWithTimeout(input, init = {}) {
  const externalSignal = init?.signal;
  if (externalSignal?.aborted) {
    throw externalSignal.reason || createTimeoutError("Supabase-Anfrage wurde abgebrochen.");
  }

  const controller = new AbortController();
  let timedOut = false;
  const abortFromExternalSignal = () => {
    controller.abort(externalSignal?.reason);
  };
  if (externalSignal) {
    externalSignal.addEventListener("abort", abortFromExternalSignal, { once: true });
  }
  const timeoutId = window.setTimeout(() => {
    timedOut = true;
    controller.abort(createTimeoutError("Die Verbindung zum CRM antwortet nicht rechtzeitig."));
  }, SUPABASE_REQUEST_TIMEOUT_MS);

  try {
    const { signal: _ignoredSignal, ...requestOptions } = init || {};
    return await window.fetch(input, {
      ...requestOptions,
      signal: controller.signal,
    });
  } catch (error) {
    if (timedOut) {
      throw createTimeoutError("Die Verbindung zum CRM antwortet nicht rechtzeitig. Bitte erneut versuchen.");
    }
    throw error;
  } finally {
    window.clearTimeout(timeoutId);
    if (externalSignal) {
      externalSignal.removeEventListener("abort", abortFromExternalSignal);
    }
  }
}

function waitForMs(delayMs) {
  return new Promise((resolve) => window.setTimeout(resolve, Math.max(0, Number(delayMs) || 0)));
}

function createSupabaseAuthStorage() {
  return {
    getItem(key) {
      try {
        return window.localStorage?.getItem(key) || null;
      } catch (_error) {
        return null;
      }
    },
    setItem(key, value) {
      try {
        window.localStorage?.setItem(key, value);
      } catch (error) {
        console.warn("Login-Session konnte nicht dauerhaft im Browser gespeichert werden.", error);
      }
    },
    removeItem(key) {
      try {
        window.localStorage?.removeItem(key);
      } catch (_error) {
        // bewusst still
      }
    },
  };
}

function isAuthSessionExpiringSoon(session, thresholdMs = 2 * 60 * 1000) {
  const expiresAt = Number(session?.expires_at || 0);
  if (!Number.isFinite(expiresAt) || expiresAt <= 0) {
    return false;
  }
  return expiresAt * 1000 <= Date.now() + Math.max(0, Number(thresholdMs) || 0);
}

async function getStoredAuthSessionWithRetry(client, options = {}) {
  const attempts = Math.max(1, Number(options?.attempts || AUTH_STARTUP_SESSION_RETRY_COUNT));
  const delayMs = Math.max(0, Number(options?.delayMs || AUTH_STARTUP_SESSION_RETRY_DELAY_MS));
  let lastError = null;

  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      const { data, error } = await client.auth.getSession();
      if (error) {
        lastError = error;
      } else if (data?.session) {
        return { session: data.session, error: null };
      }
    } catch (error) {
      lastError = error;
    }

    if (attempt < attempts) {
      await waitForMs(delayMs);
    }
  }

  return { session: null, error: lastError };
}

async function restoreStoredAuthSession(client) {
  const { session, error } = await getStoredAuthSessionWithRetry(client);
  if (error && !session) {
    console.warn("Gespeicherte Login-Session konnte nicht gelesen werden.", error);
  }
  if (!session) {
    return null;
  }

  if (!isAuthSessionExpiringSoon(session)) {
    return session;
  }

  try {
    const { data, error: refreshError } = await client.auth.refreshSession();
    if (refreshError) {
      console.warn("Gespeicherte Login-Session konnte nicht erneuert werden.", refreshError);
      return session;
    }
    return data?.session || session;
  } catch (refreshError) {
    console.warn("Gespeicherte Login-Session konnte nicht erneuert werden.", refreshError);
    return session;
  }
}

async function signInWithPasswordViaAuthApi(client, email, password) {
  const supabaseUrl = String(window.APP_CONFIG?.SUPABASE_URL || "").replace(/\/+$/, "");
  const supabaseAnonKey = String(window.APP_CONFIG?.SUPABASE_ANON_KEY || "").trim();
  if (!supabaseUrl || !supabaseAnonKey) {
    return {
      data: null,
      error: { message: "Supabase ist nicht erreichbar. Konfiguration prüfen." },
    };
  }

  try {
    const { response, payload } = await fetchJsonWithTimeout(
      `${supabaseUrl}/auth/v1/token?grant_type=password`,
      {
        method: "POST",
        headers: {
          apikey: supabaseAnonKey,
          authorization: `Bearer ${supabaseAnonKey}`,
          "content-type": "application/json",
          "x-client-info": "vertriebsmanager-auth-direct",
        },
        body: JSON.stringify({ email, password }),
      },
      AUTH_DIRECT_REQUEST_TIMEOUT_MS,
      "Direkte Anmeldung antwortet nicht rechtzeitig."
    );

    if (!response.ok) {
      return {
        data: null,
        error: normalizeAuthApiError(payload, `Anmeldung fehlgeschlagen (HTTP ${response.status}).`),
      };
    }

    return completePasswordSignIn(client, payload);
  } catch (directError) {
    console.warn("Direkte Supabase-Anmeldung fehlgeschlagen. Server-Fallback wird verwendet.", directError);
    showAuthGate("Verbindung wird über einen sicheren Ersatzweg hergestellt...");
    return signInWithPasswordViaAuthProxy(client, email, password, supabaseUrl, supabaseAnonKey);
  }
}

async function signInWithPasswordViaAuthProxy(client, email, password, supabaseUrl, supabaseAnonKey) {
  try {
    const { response, payload } = await fetchJsonWithTimeout(
      AUTH_SIGNIN_PROXY_ENDPOINT,
      {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-supabase-url": supabaseUrl,
          "x-supabase-anon-key": supabaseAnonKey,
        },
        body: JSON.stringify({ email, password }),
      },
      AUTH_PROXY_REQUEST_TIMEOUT_MS,
      "Anmeldung ist aktuell nicht erreichbar. Bitte in einem Moment erneut versuchen."
    );

    if (!response.ok) {
      return {
        data: null,
        error: normalizeAuthApiError(payload, `Anmeldung fehlgeschlagen (HTTP ${response.status}).`),
      };
    }

    return completePasswordSignIn(client, payload);
  } catch (error) {
    return { data: null, error };
  }
}

async function completePasswordSignIn(client, payload) {
  const accessToken = String(payload?.access_token || "").trim();
  const refreshToken = String(payload?.refresh_token || "").trim();
  if (!accessToken || !refreshToken) {
    return {
      data: null,
      error: { message: "Anmeldung erfolgreich, aber Session-Token fehlt." },
    };
  }

  const sessionResult = await withAsyncTimeout(
    client.auth.setSession({
      access_token: accessToken,
      refresh_token: refreshToken,
    }),
    5000,
    "Session konnte nach Anmeldung nicht gespeichert werden."
  );
  if (sessionResult?.error) {
    return { data: null, error: sessionResult.error };
  }

  return {
    data: {
      session: sessionResult?.data?.session || {
        access_token: accessToken,
        refresh_token: refreshToken,
        user: payload?.user || null,
      },
      user: sessionResult?.data?.user || payload?.user || null,
    },
    error: null,
  };
}

async function finishBootstrapAfterLogin(flowId = 0) {
  try {
    await bootstrapAfterAuth(flowId);
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    hideAuthGate();
    void recordCurrentUserLogin();
    scheduleOnboardingPrompt();
    scheduleDailySalesProgressPrompt();
    scheduleAdminNotificationLoginBriefing();
  } catch (error) {
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    console.error("Bootstrap nach Login fehlgeschlagen:", error);
    try {
      await hydrateState();
      if (purgeKnownTestProvisionLedgerEntries()) {
        saveState({ showFeedback: false });
      }
      await syncUsersFromSupabase();
      if (runProvisionLedgerOneTimePurgeTasks()) {
        await persistCriticalStateSnapshot({ retries: 3 });
      }
      ensureSessionUser();
      await hydratePartnerRequestsFromSupabase({ force: true });
      ensureManagementSelection();
      startRemoteStateSync();
      startPartnerRequestSync();
      renderAll();
      if (!openHelpCenterFromLocation() && shouldOpenSalesDashboardByDefault()) {
        setActiveSection("sales-dashboard-section");
      }
      if (!isCurrentAuthFlow(flowId)) {
        return;
      }
      hideAuthGate();
      void recordCurrentUserLogin();
      scheduleOnboardingPrompt();
      scheduleDailySalesProgressPrompt();
      scheduleAdminNotificationLoginBriefing();
      showActionFeedback("Anmeldung erfolgreich, aber einige Daten konnten nicht geladen werden.", {
        tone: "warning",
        toast: true,
        statusPersistMs: 5200,
        toastDurationMs: 5200,
      });
    } catch (fallbackError) {
      if (!isCurrentAuthFlow(flowId)) {
        return;
      }
      console.error("Fallback-Bootstrap fehlgeschlagen:", fallbackError);
      showAuthGate("Anmeldung erfolgreich, Dashboard konnte aber nicht geladen werden. Bitte neu laden.");
    } finally {
      setAppLoadingState(false);
    }
  }
}

function isActiveAuthenticatedProfileForBackgroundLoad(userId, flowId = 0) {
  return (
    isCurrentAuthFlow(flowId) &&
    Boolean(authSession) &&
    String(authProfile?.user_id || "").trim() === String(userId || "").trim() &&
    isUserStatusActive(authProfile?.status)
  );
}

function hydrateLocalDashboardCache() {
  state = loadLocalStateFromStorage();
  const offerFallback = getIncomingOffersLocalFallback();
  applyIncomingOffersCache(offerFallback.offers, offerFallback.files, { persistBackup: false });
  applyContractManagerCache(getContractManagerLocalFallback(), { persistBackup: false });
  ensureSessionUser();
  ensureManagementSelection();
}

async function hydrateInitialDashboardData(flowId = 0) {
  const userId = String(authProfile?.user_id || "").trim();
  if (!userId) {
    return false;
  }

  try {
    // Der zentrale CRM-Stand enthält die Anbieter. Nutzer- und Partnerdaten
    // können danach im Hintergrund ergänzt werden und blockieren die Liste nicht.
    await hydrateState();
    if (!isActiveAuthenticatedProfileForBackgroundLoad(userId, flowId)) {
      return false;
    }

    if (purgeKnownTestProvisionLedgerEntries()) {
      saveState({ showFeedback: false });
    }
    const offerFallback = getIncomingOffersLocalFallback();
    applyIncomingOffersCache(offerFallback.offers, offerFallback.files, { persistBackup: false });
    applyContractManagerCache(getContractManagerLocalFallback(), { persistBackup: false });
    ensureSessionUser();
    ensureManagementSelection();

    ensureSessionUser();
    ensureManagementSelection();
    return true;
  } catch (error) {
    console.warn("Initiale Vertriebs-Dashboard-Daten konnten nicht vollständig geladen werden.", error);
    return false;
  }
}

async function waitForInitialDashboardData(initialDataPromise) {
  try {
    return await withAsyncTimeout(
      initialDataPromise,
      INITIAL_DASHBOARD_DATA_TIMEOUT_MS,
      "Initiale Dashboard-Daten brauchen länger als erwartet."
    );
  } catch (error) {
    console.warn("Initialer Dashboard-Abgleich wird im Hintergrund fortgesetzt.", error);
    return false;
  }
}

function queuePostLoginDataHydration(flowId = 0, initialDataPromise = Promise.resolve(false), initialDataReady = false) {
  const userId = String(authProfile?.user_id || "").trim();
  if (!userId) {
    return;
  }

  void (async () => {
    try {
      // Falls die 6,5-Sekunden-Grenze überschritten wurde, warten wir hier auf
      // denselben Abgleich und rendern danach einmal mit dem vollständigen Stand.
      await initialDataPromise;
      if (!isActiveAuthenticatedProfileForBackgroundLoad(userId, flowId)) {
        return;
      }

      ensureSessionUser();
      ensureManagementSelection();
      startRemoteStateSync();
      startPartnerRequestSync({ refreshImmediately: false });
      if (!initialDataReady) {
        renderAll();
      }

      await Promise.allSettled([
        syncUsersFromSupabase(),
        hydratePartnerRequestsFromSupabase({ force: true }),
        hydrateTopicRequestsFromSupabase(),
        hydrateTopicSubtopicsFromSupabase(),
        hydrateContentReadReceipts({ force: true }),
        canUseAdminFeatures() ? hydrateIncomingInvoicesFromSupabase({ force: true }) : Promise.resolve(),
        repairOrphanProviderRegistryEntries(),
      ]);
      if (!isActiveAuthenticatedProfileForBackgroundLoad(userId, flowId)) {
        return;
      }
      if (runProvisionLedgerOneTimePurgeTasks()) {
        await persistCriticalStateSnapshot({ retries: 3 });
      }
    } catch (error) {
      console.warn("Zusätzliche Dashboard-Daten konnten nach Anmeldung nicht vollständig geladen werden.", error);
    } finally {
      if (!isActiveAuthenticatedProfileForBackgroundLoad(userId, flowId)) {
        return;
      }
      ensureSessionUser();
      ensureManagementSelection();
      startRemoteStateSync();
      startPartnerRequestSync({ refreshImmediately: false });
      renderAll();
    }
  })();
}

async function bootstrapAfterAuth(flowId = 0) {
  onboardingPromptShownForSession = false;
  automaticLoginPopupShownForSession = false;
  if (dailySalesProgressPromptTimerId) {
    window.clearTimeout(dailySalesProgressPromptTimerId);
    dailySalesProgressPromptTimerId = 0;
  }
  dailySalesProgressPromptDeferred = false;
  if (adminNotificationLoginBriefingTimerId) {
    window.clearTimeout(adminNotificationLoginBriefingTimerId);
    adminNotificationLoginBriefingTimerId = 0;
  }
  adminNotificationLoginBriefingShownForSession = false;
  adminNotificationLoginBriefingEntries = [];
  providerRegistryRepairChecked = false;
  conversationThreadsLoadingRemote = false;
  conversationThreadsLoadedRemote = false;
  conversationThreadsRemoteUnavailable = false;
  conversationThreadsRemoteWarningShown = false;
  conversationThreadsBackfillAttempted = false;
  ceoSecretaryEntries = [];
  ceoSecretaryLinks = [];
  ceoSecretaryCrmEntities = [];
  ceoSecretaryLoadingRemote = false;
  ceoSecretaryLoadedRemote = false;
  ceoSecretaryRemoteUnavailable = false;
  ceoSecretaryLastError = "";
  ceoSecretarySearchTerm = "";
  ceoSecretaryFilter = "all";
  ceoSecretaryActiveView = "secretary";
  ceoSecretaryAssistantWorking = false;
  ceoSecretaryPreferencesLoaded = false;
  ceoSecretaryPreferences = { assistantName: "", memory: [], updatedAt: "" };
  ceoSecretaryChatMessages = [];
  ceoSecretaryLastReferencedEntryIds = [];
  resetCeoSecretaryComposer();
  incomingInvoicesLoadedRemote = false;
  incomingInvoicesLoadingRemote = false;
  incomingInvoicesRemoteUnavailable = false;
  incomingInvoicesRemoteWarningShown = false;
  partnerRequests = [];
  partnerRequestsLoadedRemote = false;
  partnerRequestsLoadingRemote = false;
  partnerRequestsRemoteUnavailable = false;
  partnerRequestsRemoteWarningShown = false;
  providerNotesPrefetchedProviderIds = new Set();
  incomingInvoices = [];
  incomingInvoiceFiles = [];
  incomingInvoiceEvents = [];
  incomingOffers = [];
  incomingOfferFiles = [];
  contractManagerEntries = [];
  hydrateLocalDashboardCache();
  setUsersView("list");
  setProvidersView("list");
  setupRolesRightsAutoRefresh();
  showAuthGate("Dashboard-Daten werden geladen...");
  const initialDataPromise = hydrateInitialDashboardData(flowId);
  const initialDataReady = await waitForInitialDashboardData(initialDataPromise);
  if (!isCurrentAuthFlow(flowId)) {
    return;
  }
  renderInitialDashboardShell();
  queuePostLoginDataHydration(flowId, initialDataPromise, initialDataReady);
}

// Der frühere Start hat vor dem ersten sichtbaren Bildschirm jede einzelne
// CRM-Seite aufgebaut. Bei größeren Datenbeständen blockiert das den Login
// unnötig. Hier wird nur die Shell samt Startseite gerendert; die vollständige
// Synchronisierung und die restlichen Ansichten folgen im Hintergrund.
function renderInitialDashboardShell() {
  ensureManagementSelection();
  syncPlatformCountryFilterFromSettings();
  syncDashboardStatusFilterFromSettings();
  renderUserSwitch();
  renderHeaderBranding();
  renderRoleState();
  renderAdminNotifications();
  if (!openHelpCenterFromLocation()) {
    setActiveSection(getDefaultSectionForRole());
  }
}

