  document.addEventListener("change", (event) => {
    if (!canAccessMarketingModule()) {
      return;
    }

    const campaignInlineField = event.target.closest("[data-marketing-campaign-inline-field]");
    if (campaignInlineField) {
      const campaignId = String(campaignInlineField.dataset.id || "").trim();
      const field = String(campaignInlineField.dataset.marketingCampaignInlineField || "").trim();
      if (!campaignId || !field) {
        return;
      }
      if (field === "status") {
        void updateMarketingCampaignFields(campaignId, { status: campaignInlineField.value }, { successMessage: "Kampagnenstatus aktualisiert." });
      }
      return;
    }

    const contentInlineField = event.target.closest("[data-marketing-content-inline-field]");
    if (contentInlineField) {
      const contentId = String(contentInlineField.dataset.id || "").trim();
      const field = String(contentInlineField.dataset.marketingContentInlineField || "").trim();
      if (!contentId || !field) {
        return;
      }
      if (field === "status") {
        void updateMarketingContentFields(contentId, { status: contentInlineField.value }, { successMessage: "Content-Status aktualisiert." });
      }
      return;
    }

    const taskInlineField = event.target.closest("[data-marketing-task-inline-field]");
    if (!taskInlineField) {
      return;
    }
    const taskId = String(taskInlineField.dataset.id || "").trim();
    const field = String(taskInlineField.dataset.marketingTaskInlineField || "").trim();
    if (!taskId || !field) {
      return;
    }

    if (field === "status") {
      void updateMarketingTaskFields(taskId, { status: taskInlineField.value }, { successMessage: "Status aktualisiert." });
      return;
    }
    if (field === "priority") {
      void updateMarketingTaskFields(taskId, { priority: taskInlineField.value }, { successMessage: "Priorität aktualisiert." });
      return;
    }
    if (field === "dueDate") {
      void updateMarketingTaskFields(taskId, { dueDate: taskInlineField.value }, { successMessage: "Fälligkeit aktualisiert." });
    }
  });

  document.addEventListener("dragstart", (event) => {
    const campaignCard = event.target.closest("[data-marketing-campaign-card-id]");
    if (campaignCard) {
      marketingDraggingContentId = "";
      marketingDraggingTaskId = "";
      marketingDraggingCampaignId = String(campaignCard.dataset.marketingCampaignCardId || "").trim();
      if (!marketingDraggingCampaignId) {
        return;
      }
      campaignCard.classList.add("is-dragging");
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", marketingDraggingCampaignId);
      }
      return;
    }

    const contentCard = event.target.closest("[data-marketing-content-card-id]");
    if (contentCard) {
      marketingDraggingCampaignId = "";
      marketingDraggingTaskId = "";
      marketingDraggingContentId = String(contentCard.dataset.marketingContentCardId || "").trim();
      if (!marketingDraggingContentId) {
        return;
      }
      contentCard.classList.add("is-dragging");
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", marketingDraggingContentId);
      }
      return;
    }

    const taskCard = event.target.closest("[data-marketing-task-card-id]");
    if (!taskCard) {
      return;
    }
    marketingDraggingCampaignId = "";
    marketingDraggingContentId = "";
    marketingDraggingTaskId = String(taskCard.dataset.marketingTaskCardId || "").trim();
    if (!marketingDraggingTaskId) {
      return;
    }
    taskCard.classList.add("is-dragging");
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", marketingDraggingTaskId);
    }
  });

  document.addEventListener("dragend", (event) => {
    const campaignCard = event.target.closest("[data-marketing-campaign-card-id]");
    if (campaignCard) {
      campaignCard.classList.remove("is-dragging");
    }
    const contentCard = event.target.closest("[data-marketing-content-card-id]");
    if (contentCard) {
      contentCard.classList.remove("is-dragging");
    }
    const taskCard = event.target.closest("[data-marketing-task-card-id]");
    if (taskCard) {
      taskCard.classList.remove("is-dragging");
    }
    marketingDraggingCampaignId = "";
    marketingDraggingContentId = "";
    marketingDraggingTaskId = "";
    document.querySelectorAll(".is-drop-target").forEach((entry) => {
      entry.classList.remove("is-drop-target");
    });
  });

  document.addEventListener("dragover", (event) => {
    const campaignDropZone = event.target.closest("[data-marketing-campaign-drop-status]");
    if (campaignDropZone && marketingDraggingCampaignId) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = "move";
      }
      campaignDropZone.classList.add("is-drop-target");
      return;
    }

    const contentDropZone = event.target.closest("[data-marketing-content-drop-status]");
    if (contentDropZone && marketingDraggingContentId) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = "move";
      }
      contentDropZone.classList.add("is-drop-target");
      return;
    }

    const dropZone = event.target.closest("[data-marketing-drop-status]");
    if (!dropZone || !marketingDraggingTaskId) {
      return;
    }
    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = "move";
    }
    dropZone.classList.add("is-drop-target");
  });

  document.addEventListener("dragleave", (event) => {
    const dropZone =
      event.target.closest("[data-marketing-drop-status]") ||
      event.target.closest("[data-marketing-campaign-drop-status]") ||
      event.target.closest("[data-marketing-content-drop-status]");
    if (!dropZone) {
      return;
    }
    dropZone.classList.remove("is-drop-target");
  });

  document.addEventListener("drop", (event) => {
    const campaignDropZone = event.target.closest("[data-marketing-campaign-drop-status]");
    if (campaignDropZone && marketingDraggingCampaignId) {
      event.preventDefault();
      campaignDropZone.classList.remove("is-drop-target");
      const nextStatus = String(campaignDropZone.dataset.marketingCampaignDropStatus || "").trim().toLowerCase();
      if (!nextStatus) {
        return;
      }
      void updateMarketingCampaignFields(marketingDraggingCampaignId, { status: nextStatus }, { successMessage: "Kampagne verschoben." });
      return;
    }

    const contentDropZone = event.target.closest("[data-marketing-content-drop-status]");
    if (contentDropZone && marketingDraggingContentId) {
      event.preventDefault();
      contentDropZone.classList.remove("is-drop-target");
      const nextStatus = String(contentDropZone.dataset.marketingContentDropStatus || "").trim().toLowerCase();
      if (!nextStatus) {
        return;
      }
      void updateMarketingContentFields(marketingDraggingContentId, { status: nextStatus }, { successMessage: "Inhalt verschoben." });
      return;
    }

    const dropZone = event.target.closest("[data-marketing-drop-status]");
    if (!dropZone || !marketingDraggingTaskId) {
      return;
    }
    event.preventDefault();
    dropZone.classList.remove("is-drop-target");
    const nextStatus = String(dropZone.dataset.marketingDropStatus || "").trim().toLowerCase();
    if (!nextStatus) {
      return;
    }
    void updateMarketingTaskFields(marketingDraggingTaskId, { status: nextStatus }, { successMessage: "Aufgabe verschoben." });
  });

