  let lastSuggestionActivationKey = "";
  let lastSuggestionActivationAt = 0;
  const shouldSkipDuplicateSuggestionActivation = (key) => {
    const now = Date.now();
    if (lastSuggestionActivationKey === key && now - lastSuggestionActivationAt < 320) {
      return true;
    }
    lastSuggestionActivationKey = key;
    lastSuggestionActivationAt = now;
    return false;
  };
  const findClosestTargetFromEvent = (event, selector) => {
    const target = event.target;
    if (target instanceof Element) {
      return target.closest(selector);
    }
    if (target && target.parentElement instanceof Element) {
      return target.parentElement.closest(selector);
    }
    return null;
  };
