  // Der Zeilenwechsel passiert bei der Maus bereits beim Drücken. Dadurch
  // bleibt die Aktion zuverlässig, selbst wenn ein asynchroner Hintergrundjob
  // zwischen mouseup und click gerade andere Teile der Oberfläche aktualisiert.
  // Touch bleibt bewusst ausgenommen, damit Scrollen in der Tabelle niemals
  // versehentlich den Anbieter öffnet.
  els.providersTableBody.addEventListener("pointerdown", (event) => {
    if (event.pointerType !== "mouse" || event.button !== 0) {
      return;
    }
    const targetElement =
      event.target instanceof Element
        ? event.target
        : event.target instanceof Node
          ? event.target.parentElement
          : null;
    if (!targetElement) {
      return;
    }
    const interactiveTarget = targetElement.closest(
      "button, a, input, select, textarea, label, details, summary, .provider-name-info, .provider-dashboard-created-info, .provider-competitor-info, [role=\"button\"]"
    );
    if (interactiveTarget || targetElement.closest(".provider-actions-cell")) {
      return;
    }
    const providerRow = targetElement.closest("tr[data-provider-row]");
    const providerId = String(providerRow?.dataset.providerRow || "").trim();
    const provider = findProviderRecordById(providerId, state.providers);
    const currentUser = getCurrentUser();
    if (!provider || !currentUser || (!isAdmin() && !providerVisibleForCurrentUser(provider, currentUser))) {
      return;
    }
    if (isProviderAccessLockedForCurrentUser(provider, currentUser)) {
      openProviderOverviewLockedModal(provider);
      event.preventDefault();
      return;
    }
    if (openProviderEditor(provider.id)) {
      // Unterdrückt den nachfolgenden synthetischen click. Ohne das würde der
      // gerade geöffnete Editor unnötig ein zweites Mal initialisiert.
      event.preventDefault();
    }
  });

  els.providersTableBody.addEventListener("click", (event) => {
    const targetElement =
      event.target instanceof Element
        ? event.target
        : event.target instanceof Node
          ? event.target.parentElement
          : null;
    if (!targetElement) {
      return;
    }
    const interactiveTarget = targetElement.closest(
      "button, a, input, select, textarea, label, details, summary, .provider-name-info, .provider-dashboard-created-info, .provider-competitor-info, [role=\"button\"]"
    );
    const openNotesButton = targetElement.closest("button[data-provider-open-notes]");
    if (openNotesButton) {
      const providerId = String(openNotesButton.dataset.providerOpenNotes || "").trim();
      if (!providerId) {
        return;
      }
      void openProviderOpenNotesModal(providerId);
      return;
    }

    const invitationResetButton = targetElement.closest("button[data-provider-invitation-reset]");
    if (invitationResetButton) {
      openProviderInvitationResetModal(invitationResetButton.dataset.providerInvitationReset || "");
      return;
    }

    const invitationToggleButton = targetElement.closest("button[data-provider-invitation-toggle]");
    if (invitationToggleButton) {
      const provider = findProviderRecordById(invitationToggleButton.dataset.providerInvitationToggle || "", state.providers);
      if (provider && isProviderInvitationLockedByAnotherUser(provider, getCurrentUser())) {
        openProviderInvitationLockedModal(provider);
        return;
      }
      if (invitationToggleButton.dataset.providerInvitationStatusBlocked === "true") {
        openProviderInvitationStatusHintModal();
        return;
      }
      void toggleProviderInvitationRequest(
        invitationToggleButton.dataset.providerInvitationToggle || "",
        invitationToggleButton
      );
      return;
    }

    // Die Aktionsspalte gehört ausschließlich ihren eigenen Steuerelementen.
    // Besonders bei deaktivierten Buttons kann der Browser den Klick an das
    // umgebende Element weiterreichen; er darf dann niemals den Datensatz öffnen.
    if (targetElement.closest(".provider-actions-cell")) {
      return;
    }

    if (!interactiveTarget) {
      const providerRow = targetElement.closest("tr[data-provider-row]");
      const providerId = String(providerRow?.dataset.providerRow || "").trim();
      const provider = findProviderRecordById(providerId, state.providers);
      if (!provider) {
        return;
      }
      const currentUser = getCurrentUser();
      if (!currentUser) {
        return;
      }
      if (!isAdmin() && !providerVisibleForCurrentUser(provider, currentUser)) {
        return;
      }
      if (isProviderAccessLockedForCurrentUser(provider, currentUser)) {
        openProviderOverviewLockedModal(provider);
        return;
      }
      openProviderEditor(provider.id);
      return;
    }

    const viewButton = event.target.closest("button[data-view-provider]");
    if (viewButton) {
      const providerId = viewButton.dataset.viewProvider;
      const provider = findProviderRecordById(providerId, state.providers);
      if (!provider) {
        return;
      }
      openProviderEditor(provider.id, { tab: "master" });
      return;
    }

  });
