function formatAdminNotificationTime(value) {
  const parsedDate = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsedDate.getTime())) {
    return "";
  }
  try {
    return new Intl.DateTimeFormat("de-AT", {
      dateStyle: "short",
      timeStyle: "short",
    }).format(parsedDate);
  } catch (_error) {
    return parsedDate.toLocaleString();
  }
}

function getAdminNotificationDismissedById() {
  return normalizeAdminNotificationDismissedById(state.settings?.adminNotificationDismissedById || {});
}

function getAdminNotificationSeenById() {
  return normalizeAdminNotificationSeenById(state.settings?.adminNotificationSeenById || {});
}

function buildNotificationDismissKey(notificationId, userId = "") {
  const normalizedId = String(notificationId || "").trim();
  const normalizedUserId = normalizeUserId(userId || "");
  if (!normalizedId || !normalizedUserId) {
    return normalizedId;
  }
  return `${normalizedUserId}::${normalizedId}`;
}

function buildNotificationSeenKey(notificationId, userId = "") {
  const normalizedId = String(notificationId || "").trim();
  const normalizedUserId = normalizeUserId(userId || "");
  if (!normalizedId || !normalizedUserId) {
    return normalizedId;
  }
  return `${normalizedUserId}::${normalizedId}`;
}

function isNotificationDismissedByCurrentUser(notificationId) {
  const normalizedId = String(notificationId || "").trim();
  if (!normalizedId) {
    return false;
  }
  const dismissedById = getAdminNotificationDismissedById();
  const actorUserId = normalizeUserId(getCurrentActorInfo().userId || "");
  const scopedKey = buildNotificationDismissKey(normalizedId, actorUserId);
  return Boolean(dismissedById[scopedKey] || dismissedById[normalizedId]);
}

function setAdminNotificationDismissedById(notificationId, dismissed = true, userId = "") {
  const normalizedId = String(notificationId || "").trim();
  if (!normalizedId) {
    return;
  }
  const actorUserId = normalizeUserId(userId || getCurrentActorInfo().userId || "");
  const dismissKey = buildNotificationDismissKey(normalizedId, actorUserId);
  const dismissedById = getAdminNotificationDismissedById();
  const nextDismissedById = { ...dismissedById };
  if (dismissed) {
    nextDismissedById[dismissKey] = true;
  } else {
    delete nextDismissedById[dismissKey];
    delete nextDismissedById[normalizedId];
  }
  state.settings = normalizeSettings({
    ...state.settings,
    adminNotificationDismissedById: nextDismissedById,
  });
  saveState({ showFeedback: false });
}

function isNotificationSeenByCurrentUser(notificationId) {
  const normalizedId = String(notificationId || "").trim();
  if (!normalizedId) {
    return false;
  }
  const seenById = getAdminNotificationSeenById();
  const actorUserId = normalizeUserId(getCurrentActorInfo().userId || "");
  const scopedKey = buildNotificationSeenKey(normalizedId, actorUserId);
  return Boolean(seenById[scopedKey] || seenById[normalizedId]);
}

function markAdminNotificationsSeen(notificationIds = []) {
  const ids = Array.from(new Set((notificationIds || []).map((id) => String(id || "").trim()).filter(Boolean)));
  if (!ids.length) {
    return;
  }
  const actorUserId = normalizeUserId(getCurrentActorInfo().userId || "");
  const nextSeenById = { ...getAdminNotificationSeenById() };
  ids.forEach((notificationId) => {
    nextSeenById[buildNotificationSeenKey(notificationId, actorUserId)] = true;
  });
  state.settings = normalizeSettings({
    ...state.settings,
    adminNotificationSeenById: nextSeenById,
  });
  saveState({ showFeedback: false });
}

function appendAdminSystemNotification(message, tone = "info") {
  const text = String(message || "").trim();
  if (!text || text === "Änderungen gespeichert.") {
    return;
  }
  const actor = getCurrentActorInfo();
  const now = new Date().toISOString();
  adminSystemNotifications.unshift({
    id: `system_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    kind: "system",
    tone: String(tone || "info").trim().toLowerCase(),
    title: "Systemmeldung",
    text,
    createdAt: now,
    createdAtMs: Date.parse(now),
    createdByUserId: normalizeUserId(actor?.userId || ""),
    createdByRole: normalizeUserRole(actor?.role || ""),
    persistent: false,
    targetSection: "",
  });
  if (adminSystemNotifications.length > ADMIN_NOTIFICATION_MAX_SYSTEM_ITEMS) {
    adminSystemNotifications = adminSystemNotifications.slice(0, ADMIN_NOTIFICATION_MAX_SYSTEM_ITEMS);
  }
}

function getAdminNotificationDisplayTimeLabel(entry) {
  const explicitLabel = String(entry?.timeLabel || "").trim();
  if (explicitLabel) {
    return explicitLabel;
  }
  return formatAdminNotificationTime(entry?.createdAt || "");
}

function getProviderTaskReminderNotifications(actorUserId = "") {
  const normalizedActorUserId = normalizeUserId(actorUserId);
  if (!normalizedActorUserId) {
    return [];
  }
  const todayStart = getDateStart(new Date());
  const todayKey = getTodayDateInputValue();
  return collectProviderTaskRowsForCurrentUser(getVisibleProvidersForCurrentUser("all"))
    .map((entry) => {
      const dueDate = sanitizeEmployeeAdminDate(entry?.dueDate || "");
      const dueStart = parseDateInputStart(dueDate);
      if (!dueDate || !(dueStart instanceof Date)) {
        return null;
      }
      const dayDiff = Math.round((dueStart.getTime() - todayStart.getTime()) / 86400000);
      if (dayDiff > PROVIDER_TASK_REMINDER_LEAD_DAYS) {
        return null;
      }
      const dueLabel = formatEmployeeAdminDate(dueDate);
      const overdue = dayDiff < 0;
      const notePreview = truncateSelectLabel(entry?.noteText || "Aufgabe", 72);
      const providerId = String(entry?.providerId || "").trim();
      const noteId = String(entry?.noteId || "").trim();
      if (!providerId || !noteId) {
        return null;
      }
      return {
        id: `provider_task_reminder_${normalizedActorUserId}_${providerId}_${noteId}_${dueDate}_${todayKey}`,
        kind: "provider_task_reminder",
        tone: overdue ? "danger" : "warning",
        title: "Aufgaben-Reminder",
        text: overdue
          ? `${String(entry?.providerName || "Anbieter").trim() || "Anbieter"}: ${notePreview} ist seit ${dueLabel} überfällig.`
          : dayDiff === 0
            ? `${String(entry?.providerName || "Anbieter").trim() || "Anbieter"}: ${notePreview} ist heute fällig.`
            : `${String(entry?.providerName || "Anbieter").trim() || "Anbieter"}: ${notePreview} ist am ${dueLabel} fällig.`,
        createdAt: dueDate,
        createdAtMs: dueStart.getTime(),
        timeLabel: overdue ? `Überfällig seit ${dueLabel}` : `Fällig ${dueLabel}`,
        persistent: true,
        dismissible: true,
        targetSection: "providers-section",
        providerId,
        noteId,
        sortPriority: overdue ? -10 : dayDiff,
      };
    })
    .filter(Boolean)
    .sort((left, right) => {
      const leftPriority = Number.isFinite(left?.sortPriority) ? left.sortPriority : 999;
      const rightPriority = Number.isFinite(right?.sortPriority) ? right.sortPriority : 999;
      if (leftPriority !== rightPriority) {
        return leftPriority - rightPriority;
      }
      if ((left?.createdAtMs || 0) !== (right?.createdAtMs || 0)) {
        return (left?.createdAtMs || 0) - (right?.createdAtMs || 0);
      }
      return String(left?.text || "").localeCompare(String(right?.text || ""), "de", {
        sensitivity: "base",
      });
    });
}

function getAdminPendingSignupNotifications() {
  const pendingSignups = state.users
    .filter((entry) => entry?.source === "profile" && isUserStatusPending(entry?.status))
    .map((entry) => {
      const createdAt = String(entry.createdAt || "").trim();
      const createdAtMs = Date.parse(createdAt);
      return {
        id: `signup_pending_${String(entry.sourceId || "").trim()}`,
        kind: "signup",
        tone: "warning",
        title: "Neue Anmeldung",
        text: `${String(entry.name || entry.email || "Benutzer").trim()} wartet auf Freigabe.`,
        createdAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        targetSection: "users-section",
      };
    })
    .filter((entry) => !!entry.id && !!entry.text)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);

  return pendingSignups;
}

function getSupabasePartnerRequestsTable() {
  return window.APP_CONFIG?.SUPABASE_PARTNER_REQUESTS_TABLE || "partner_requests";
}

function canUsePartnerRequestsSection(user = getCurrentUser()) {
  return Boolean(user);
}

function canManagePartnerRequestActions(user = getCurrentUser()) {
  return Boolean(user);
}

function canDeletePartnerRequests(user = getCurrentUser()) {
  return isRoleAdmin(user);
}

function pickPartnerRequestField(row, names, fallback = "") {
  if (!row || typeof row !== "object") {
    return fallback;
  }
  const candidates = Array.isArray(names) ? names : [names];
  for (const name of candidates) {
    if (Object.prototype.hasOwnProperty.call(row, name)) {
      const value = row[name];
      if (value !== null && value !== undefined && String(value).trim()) {
        return String(value).trim();
      }
    }
  }
  return fallback;
}

function getPartnerRequestId(row, index = 0) {
  const explicitId = pickPartnerRequestField(row, ["id", "uuid", "request_id", "requestId"]);
  if (explicitId) {
    return explicitId;
  }
  const createdAt = pickPartnerRequestCreatedAt(row);
  const email = pickPartnerRequestField(row, ["email", "contact_email", "partner_email"]);
  return `${createdAt || "unknown"}_${email || index}`;
}

function pickPartnerRequestCreatedAt(row) {
  return pickPartnerRequestField(row, [
    "created_at",
    "createdAt",
    "inserted_at",
    "submitted_at",
    "requested_at",
    "date",
  ]);
}

function getPartnerRequestDisplayName(row) {
  const company = pickPartnerRequestField(row, [
    "company_name",
    "company",
    "firm_name",
    "business_name",
    "business",
    "provider_name",
    "partner_name",
    "name",
  ]);
  if (company) {
    return company;
  }
  const firstName = pickPartnerRequestField(row, ["first_name", "firstname", "vorname"]);
  const lastName = pickPartnerRequestField(row, ["last_name", "lastname", "nachname"]);
  const fullName = [firstName, lastName].filter(Boolean).join(" ").trim();
  return fullName || pickPartnerRequestField(row, ["contact_name", "full_name", "contact", "person"], "Neue Anfrage");
}

function getPartnerRequestContactLabel(row) {
  const contact = pickPartnerRequestField(row, ["contact_name", "full_name", "contact", "person"]);
  const firstName = pickPartnerRequestField(row, ["first_name", "firstname", "vorname"]);
  const lastName = pickPartnerRequestField(row, ["last_name", "lastname", "nachname"]);
  const fullName = contact || [firstName, lastName].filter(Boolean).join(" ").trim();
  const email = pickPartnerRequestField(row, ["email", "contact_email", "partner_email"]);
  const phone = pickPartnerRequestField(row, ["phone", "phone_number", "telephone", "tel", "contact_phone"]);
  return [fullName, email, phone].filter(Boolean).join(" · ");
}

function getPartnerRequestSummary(row) {
  return pickPartnerRequestField(row, [
    "message",
    "notes",
    "note",
    "comment",
    "request_text",
    "description",
    "category",
    "interest",
  ]);
}

function getPartnerRequestRedemptionMethod(row) {
  return pickPartnerRequestField(row, [
    "redemption_method",
    "redemptionMethod",
    "redeem_method",
    "redeemMethod",
    "voucher_redemption_method",
    "voucherRedemptionMethod",
    "einloesungsmethode",
    "einlösungsmethode",
    "einloesung",
    "einlösung",
    "redemption",
  ]);
}

function getPartnerRequestContactName(row) {
  const explicitName = pickPartnerRequestField(row, ["contact_name", "full_name", "contact", "person"]);
  if (explicitName) {
    return explicitName;
  }
  const firstName = pickPartnerRequestField(row, ["first_name", "firstname", "vorname"]);
  const lastName = pickPartnerRequestField(row, ["last_name", "lastname", "nachname"]);
  return [firstName, lastName].filter(Boolean).join(" ").trim();
}

function getPartnerRequestEmail(row) {
  return normalizeUserEmail(pickPartnerRequestField(row, ["email", "contact_email", "partner_email"]));
}

function getPartnerRequestPhone(row) {
  return pickPartnerRequestField(row, ["phone", "phone_number", "telephone", "tel", "contact_phone"]);
}

function getPartnerRequestWebsite(row) {
  return pickPartnerRequestField(row, ["website", "url", "homepage", "web", "site"]);
}

function getPartnerRequestStatus(row) {
  return normalizePartnerRequestStatusValue(
    pickPartnerRequestField(row, ["status", "state", "request_status", "lead_status", "processing_status"])
  );
}

function normalizePartnerRequestStatusValue(value = "") {
  const normalized = normalizeText(value).replaceAll("-", "_").replace(/\s+/g, "_");
  if (!normalized) {
    return "";
  }
  if (["offen", "open", "neu", "new"].includes(normalized)) {
    return "offen";
  }
  if (["in_bearbeitung", "bearbeitung", "in_progress", "progress"].includes(normalized)) {
    return "in_bearbeitung";
  }
  if (["live", "geschlossen", "closed", "erledigt", "done", "processed", "bearbeitet"].includes(normalized)) {
    return "live";
  }
  return normalized;
}

function mapProviderStatusToPartnerRequestStatus(status = "") {
  const normalizedStatus = normalizeProviderStatusValue(status || "");
  if (normalizedStatus === "live") {
    return "live";
  }
  if (
    [
      "in Bearbeitung",
      PROVIDER_STATUS_LIVE_PENDING,
      PROVIDER_STATUS_TELEFONAKQUISE,
      PROVIDER_STATUS_NOT_REACHED,
      PROVIDER_STATUS_CALLBACK,
      PROVIDER_STATUS_REACHED,
      PROVIDER_STATUS_TOUR_PLANNED,
    ].includes(normalizedStatus)
  ) {
    return "in_bearbeitung";
  }
  return "offen";
}

function mapPartnerRequestStatusToProviderStatus(status = "") {
  const normalizedStatus = normalizePartnerRequestStatusValue(status || "");
  if (normalizedStatus === "live") {
    return "live";
  }
  if (normalizedStatus === "in_bearbeitung") {
    return "in Bearbeitung";
  }
  return "offen";
}

function getPartnerRequestPersistedId(row) {
  return pickPartnerRequestField(row, ["id", "uuid", "request_id", "requestId"]);
}

function isPartnerRequestOpen(row) {
  const status = getPartnerRequestStatus(row);
  if (!status) {
    return true;
  }
  const closedStatuses = new Set([
    "live",
    "done",
    "erledigt",
    "closed",
    "geschlossen",
    "archived",
    "archiviert",
    "processed",
    "bearbeitet",
    "rejected",
    "abgelehnt",
    "cancelled",
    "canceled",
    "storniert",
  ]);
  return !closedStatuses.has(status);
}

function normalizePartnerRequestRows(rows) {
  const seenIds = new Set();
  return (Array.isArray(rows) ? rows : [])
    .map((row, index) => {
      const id = getPartnerRequestId(row, index);
      if (!id || seenIds.has(id)) {
        return null;
      }
      seenIds.add(id);
      const createdAt = pickPartnerRequestCreatedAt(row);
      const createdAtMs = Date.parse(createdAt);
      const notificationId = `partner_request_${id}`;
      return {
        id,
        notificationId,
        raw: row,
        title: getPartnerRequestDisplayName(row),
        contactLabel: getPartnerRequestContactLabel(row),
        summary: getPartnerRequestSummary(row),
        status: getPartnerRequestStatus(row),
        createdAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        isOpen: isPartnerRequestOpen(row),
      };
    })
    .filter(Boolean)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getPartnerRequestLinkedProvider(entry) {
  if (!entry) {
    return null;
  }
  return getPartnerRequestResponsibleInfo(entry)?.provider || findProviderCreatedFromPartnerRequest(entry) || null;
}

function getPartnerRequestEffectiveStatus(entry) {
  const provider = getPartnerRequestLinkedProvider(entry);
  return provider ? mapProviderStatusToPartnerRequestStatus(provider.status) : normalizePartnerRequestStatusValue(entry?.status || "");
}

function getOpenPartnerRequestEntries() {
  return partnerRequests.filter((entry) => getPartnerRequestEffectiveStatus(entry) !== "live");
}

function getPartnerRequestResponsibleInfo(entry) {
  const raw = entry?.raw && typeof entry.raw === "object" ? entry.raw : {};
  const explicitUserId = normalizeUserId(
    pickPartnerRequestField(raw, ["responsible_user_id", "responsibleUserId", "assigned_user_id", "owner_user_id"])
  );
  const explicitName = pickPartnerRequestField(raw, [
    "responsible_name",
    "responsibleName",
    "assigned_user_name",
    "owner_name",
  ]);
  const explicitRole = normalizeUserRole(
    pickPartnerRequestField(raw, ["responsible_role", "responsibleRole", "assigned_user_role", "owner_role"])
  );
  const explicitSource = pickPartnerRequestField(raw, [
    "responsibility_source",
    "responsibilitySource",
    "responsible_source",
  ]);
  const explicitAt = pickPartnerRequestField(raw, ["responsibility_updated_at", "responsibilityUpdatedAt"]);
  const linkedProviderId = pickPartnerRequestField(raw, ["linked_provider_id", "linkedProviderId", "provider_id", "providerId"]);
  const provider =
    (linkedProviderId &&
      state.providers.find((item) => String(item?.id || "").trim() === String(linkedProviderId || "").trim())) ||
    findProviderCreatedFromPartnerRequest(entry);

  if (provider && resolveProviderManualResponsibleUserId(provider)) {
    return getProviderEffectiveResponsibleInfo(provider);
  }

  if (explicitUserId || explicitName) {
    return {
      userId: explicitUserId,
      name: explicitName || getUserDisplayNameByUserId(explicitUserId) || "",
      role: explicitRole || getUserRoleByUserId(explicitUserId) || "",
      source: explicitSource || "",
      updatedAt: explicitAt,
      provider,
    };
  }

  if (provider) {
    return getProviderEffectiveResponsibleInfo(provider);
  }

  return {
    userId: "",
    name: "",
    role: "",
    source: "",
    updatedAt: "",
    provider: null,
  };
}

function getPartnerRequestResponsibilitySourceLabel(source = "") {
  const normalized = String(source || "").trim().toLowerCase();
  if (normalized === "in_progress") {
    return "In Bearbeitung";
  }
  if (normalized === "created_by") {
    return "Angelegt";
  }
  if (normalized === "manual") {
    return "Manuell";
  }
  return "";
}

function renderPartnerRequestResponsibleCell(row) {
  const responsible = row.responsible || {};
  const providerName = String(responsible.provider?.name || "").trim();
  const responsibleName = String(responsible.name || "").trim();
  if (!providerName) {
    if (!responsibleName) {
      return `
        <div class="partner-request-responsible">
          <span class="partner-requests-muted">Nicht zugeordnet</span>
        </div>
      `;
    }
    const sourceLabel = getPartnerRequestResponsibilitySourceLabel(responsible.source || "");
    return `
      <div class="partner-request-responsible">
        <strong>${escapeHtml(responsibleName)}</strong>
        ${sourceLabel ? `<span>${escapeHtml(sourceLabel)}</span>` : ""}
      </div>
    `;
  }
  return `
    <div class="partner-request-responsible">
      <strong>${escapeHtml(providerName)}</strong>
      ${responsibleName ? `<span>${escapeHtml(responsibleName)}</span>` : ""}
    </div>
  `;
}

function getPartnerRequestNotifications() {
  return getOpenPartnerRequestEntries()
    .map((entry) => ({
      id: entry.notificationId,
      kind: "partner_request",
      tone: "warning",
      title: "Neue Partner-Anfrage",
      text: `Neue Partner-Anfrage: ${entry.title || "Unbekannt"}${
        entry.contactLabel ? ` · ${entry.contactLabel}` : ""
      }`,
      createdAt: entry.createdAt,
      createdAtMs: entry.createdAtMs,
      persistent: true,
      targetSection: "partner-requests-section",
    }))
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getAdminNotificationKindLabel(kind, entry = {}) {
  if (kind === "signup") {
    return "Anmeldung";
  }
  if (kind === "partner_request") {
    return "Partner-Anfrage";
  }
  if (kind === "live_pending") {
    return "Live-Anfrage";
  }
  if (kind === "live_approved") {
    return "Live-Freigabe";
  }
  if (kind === "provider_invitation_request") {
    return "Einladung";
  }
  if (kind === "provider_invitation_completed") {
    return "Einladung";
  }
  if (kind === "topic_request") {
    return "Kategorie";
  }
  if (kind === "provider_task_reminder") {
    return "Aufgabe";
  }
  if (kind === "provider_responsibility_transfer") {
    return "Übergabe";
  }
  if (kind === "provider_responsibility_rejected") {
    return "Abgelehnt";
  }
  if (kind === "employee_message") {
    const senderName = String(entry?.senderName || entry?.sentByName || "Superadmin").trim() || "Superadmin";
    return `Nachricht von ${senderName}`;
  }
  return "Meldung";
}

function getLivePendingApprovalNotifications() {
  return (state.providers || [])
    .filter((provider) => isProviderAwaitingLiveApproval(provider))
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const requestedAt = getProviderLiveRequestTimestamp(provider);
      const requestedByName = resolveProviderLiveRequestorName(provider);
      const createdAtMs = Date.parse(requestedAt);
      return {
        id: `live_pending_admin_${providerId}_${requestedAt || "pending"}`,
        kind: "live_pending",
        tone: "warning",
        title: "Live-Anfrage",
        text: `LIVE beantragt von ${requestedByName}: ${providerName}.`,
        createdAt: requestedAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        targetSection: "providers-section",
      };
    })
    .filter((entry) => !!entry.id)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getProviderInvitationRequestNotifications() {
  return (state.providers || [])
    .filter((provider) => isProviderInvitationRequestOpen(provider))
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const requestedAt = String(provider?.invitationRequestedAt || provider?.invitation_requested_at || "").trim();
      const requestedByName = String(
        provider?.invitationRequestedByName || provider?.invitation_requested_by_name || "Mitarbeiter"
      ).trim();
      const createdAtMs = Date.parse(requestedAt);
      return {
        id: `provider_invitation_request_${providerId}_${requestedAt || "open"}`,
        kind: "provider_invitation_request",
        tone: "warning",
        title: "Einladung senden",
        text: `${providerName}: Einladung angefordert von ${requestedByName}.`,
        createdAt: requestedAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        targetSection: "sales-dashboard-section",
        providerId,
      };
    })
    .filter((entry) => !!entry.providerId)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getOpenTopicRequestEntries() {
  return (Array.isArray(state.settings?.topicRequests) ? state.settings.topicRequests : [])
    .filter((entry) => String(entry?.status || "open").trim().toLowerCase() === "open")
    .map((entry) => {
      const createdAt = String(entry?.createdAt || "").trim();
      const createdAtMs = Date.parse(createdAt);
      return {
        id: String(entry?.id || "").trim(),
        topic: String(entry?.topic || "").trim(),
        note: String(entry?.note || "").trim(),
        providerName: String(entry?.providerName || "").trim(),
        requestedByName: String(entry?.requestedByName || "Mitarbeiter").trim() || "Mitarbeiter",
        requestedByUserId: normalizeUserId(entry?.requestedByUserId || ""),
        createdAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
      };
    })
    .filter((entry) => entry.id && entry.topic)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function normalizeTopicRequestTableRows(rows = []) {
  return (Array.isArray(rows) ? rows : []).map((row) => ({
    id: String(row?.id || "").trim(), topic: String(row?.topic || "").trim(), note: String(row?.note || "").trim(),
    providerName: String(row?.provider_name || "").trim(), requestedByName: String(row?.requested_by_name || "Mitarbeiter").trim() || "Mitarbeiter",
    requestedByUserId: normalizeUserId(row?.requested_by_user_id || ""), createdAt: String(row?.requested_at || row?.created_at || "").trim(), status: String(row?.status || "open").trim(), resolvedTopicName: String(row?.resolved_topic_name || "").trim(),
  })).filter((entry) => entry.id && entry.topic);
}

async function hydrateTopicRequestsFromSupabase() {
  const client = getSupabaseClient();
  if (!client) return false;
  const { data, error } = await client.from(TOPIC_REQUESTS_TABLE).select("*").order("requested_at", { ascending: false });
  if (error) { console.warn("Kategorieanfragen konnten nicht aus Supabase geladen werden.", error); return false; }
  state.settings = normalizeSettings({ ...state.settings, topicRequests: normalizeTopicRequestTableRows(data) });
  renderAdminNotifications();
  renderSalesDashboardSection();
  return true;
}

function normalizeTopicSubtopicRows(rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => ({
      id: String(row?.id || "").trim(),
      topicId: String(row?.topic_id || row?.topicId || "").trim(),
      name: String(row?.name || "").trim(),
      normalizedName: normalizeText(row?.normalized_name || row?.name || ""),
    }))
    .filter((entry) => entry.id && entry.topicId && entry.name);
}

function getTopicSubtopics(topicId) {
  const normalizedTopicId = String(topicId || "").trim();
  return topicSubtopics
    .filter((entry) => entry.topicId === normalizedTopicId)
    .slice()
    .sort((left, right) => left.name.localeCompare(right.name, "de"));
}

async function hydrateTopicSubtopicsFromSupabase() {
  const client = getSupabaseClient();
  if (!client) {
    return false;
  }
  const { data, error } = await client
    .from(TOPIC_SUBTOPICS_TABLE)
    .select("id, topic_id, name, normalized_name")
    .order("name", { ascending: true });
  if (error) {
    console.warn("Sub-Themen konnten nicht aus Supabase geladen werden.", error);
    return false;
  }
  topicSubtopics = normalizeTopicSubtopicRows(data);
  renderManagementSection();
  renderProviderTopicPicker();
  return true;
}

async function deleteTopicSubtopicsOnServer(topicIds) {
  const normalizedTopicIds = Array.from(
    new Set((Array.isArray(topicIds) ? topicIds : []).map((id) => String(id || "").trim()).filter(Boolean))
  );
  if (!normalizedTopicIds.length) {
    return true;
  }
  const client = getSupabaseClient();
  if (storageMode === "supabase") {
    if (!client) {
      showErrorFeedback("Keine Verbindung zu Supabase. Das Hauptthema bleibt unverändert.", { toast: true });
      return false;
    }
    const { error } = await client.from(TOPIC_SUBTOPICS_TABLE).delete().in("topic_id", normalizedTopicIds);
    if (error) {
      showErrorFeedback("Die zugehörigen Sub-Themen konnten nicht gelöscht werden. Das Hauptthema bleibt unverändert.", {
        toast: true,
      });
      return false;
    }
  }
  const topicIdSet = new Set(normalizedTopicIds);
  topicSubtopics = topicSubtopics.filter((entry) => !topicIdSet.has(entry.topicId));
  return true;
}

async function openTopicSubtopicsModal(topicId) {
  if (!isAdmin()) {
    return;
  }
  const topic = findTopicLocation(topicId)?.topic;
  if (!topic) {
    showWarningFeedback("Das Thema ist nicht mehr verfügbar.");
    return;
  }
  const normalizedTopicId = String(topic.id || "").trim();
  const modal = document.createElement("div");
  modal.className = "topic-subtopics-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.setAttribute("aria-label", `Sub-Themen für ${topic.name}`);

  const renderModal = () => {
    const entries = getTopicSubtopics(normalizedTopicId);
    modal.innerHTML = `<section class="topic-subtopics-dialog"><header><div><p>SUB-THEMEN</p><h3>${escapeHtml(topic.name)}</h3><span>Sub-Themen verbessern die Suche bei der Anbieter-Zuordnung. Anbieter bleiben dem Hauptthema zugeordnet.</span></div><button type="button" class="mini-btn" data-close-subtopics aria-label="Popup schließen">✕</button></header><form data-subtopic-form><label>Neues Sub-Thema<input name="name" maxlength="120" autocomplete="off" placeholder="z. B. Fitnesstraining" required /></label><button type="submit" class="btn btn-success">Hinzufügen</button></form><div class="topic-subtopics-list">${entries.length ? entries.map((entry) => `<div><span>${escapeHtml(entry.name)}</span><button type="button" class="mini-btn danger" data-delete-subtopic="${escapeHtml(entry.id)}" aria-label="${escapeHtml(`${entry.name} löschen`)}" title="Sub-Thema löschen">✕</button></div>`).join("") : "<p>Noch keine Sub-Themen erfasst.</p>"}</div></section>`;
  };
  const close = () => {
    document.removeEventListener("keydown", onKeyDown);
    modal.remove();
  };
  const onKeyDown = (event) => {
    if (event.key === "Escape") {
      close();
    }
  };
  modal.addEventListener("click", async (event) => {
    if (event.target === modal || event.target.closest("[data-close-subtopics]")) {
      close();
      return;
    }
    const deleteButton = event.target.closest("[data-delete-subtopic]");
    if (!deleteButton) {
      return;
    }
    const subtopicId = String(deleteButton.dataset.deleteSubtopic || "").trim();
    const subtopic = topicSubtopics.find((entry) => entry.id === subtopicId);
    if (!subtopic || !(await confirmDeleteAction(`Sub-Thema „${subtopic.name}“ wirklich löschen?`))) {
      return;
    }
    const client = getSupabaseClient();
    if (storageMode === "supabase") {
      if (!client) {
        showErrorFeedback("Keine Verbindung zu Supabase. Sub-Thema wurde nicht gelöscht.", { toast: true });
        return;
      }
      const { error } = await client.from(TOPIC_SUBTOPICS_TABLE).delete().eq("id", subtopicId);
      if (error) {
        showErrorFeedback("Sub-Thema konnte nicht gelöscht werden.", { toast: true });
        return;
      }
    }
    topicSubtopics = topicSubtopics.filter((entry) => entry.id !== subtopicId);
    renderModal();
    renderManagementSection();
    renderProviderTopicPicker();
  });
  modal.addEventListener("submit", async (event) => {
    const form = event.target.closest("form[data-subtopic-form]");
    if (!form) {
      return;
    }
    event.preventDefault();
    const name = String(new FormData(form).get("name") || "").trim().slice(0, 120);
    const normalizedName = normalizeText(name);
    if (!normalizedName) {
      return;
    }
    if (getTopicSubtopics(normalizedTopicId).some((entry) => entry.normalizedName === normalizedName)) {
      showWarningFeedback("Dieses Sub-Thema ist für dieses Hauptthema bereits vorhanden.", { toast: true });
      form.elements.name?.focus();
      form.elements.name?.select();
      return;
    }
    const client = getSupabaseClient();
    let inserted = { id: createId("topic_subtopic"), topicId: normalizedTopicId, name, normalizedName };
    if (storageMode === "supabase") {
      if (!client) {
        showErrorFeedback("Keine Verbindung zu Supabase. Sub-Thema wurde nicht gespeichert.", { toast: true });
        return;
      }
      const { data, error } = await client
        .from(TOPIC_SUBTOPICS_TABLE)
        .insert({ topic_id: normalizedTopicId, name, normalized_name: normalizedName })
        .select("id, topic_id, name, normalized_name")
        .single();
      if (error) {
        showErrorFeedback(
          error.code === "23505"
            ? "Dieses Sub-Thema ist für dieses Hauptthema bereits vorhanden."
            : "Sub-Thema konnte nicht in Supabase gespeichert werden.",
          { toast: true }
        );
        return;
      }
      inserted = normalizeTopicSubtopicRows([data])[0] || inserted;
    }
    topicSubtopics.push(inserted);
    renderModal();
    renderManagementSection();
    renderProviderTopicPicker();
  });
  document.body.appendChild(modal);
  document.addEventListener("keydown", onKeyDown);
  renderModal();
  modal.querySelector("input[name='name']")?.focus();
}

function getTopicRequestNotifications() {
  return getOpenTopicRequestEntries().map((entry) => ({
    id: `topic_request_${entry.id}`,
    kind: "topic_request",
    tone: "warning",
    title: "Kategorieanfrage",
    text: `${entry.requestedByName} wünscht „${entry.topic}“.${entry.providerName ? ` Anbieter: ${entry.providerName}.` : ""}`,
    createdAt: entry.createdAt,
    createdAtMs: entry.createdAtMs,
    persistent: true,
    targetSection: "sales-dashboard-section",
  }));
}

function getTopicRequestResolutionNotificationsForActor(actorUserId = "") {
  const userId = normalizeUserId(actorUserId);
  if (!userId) return [];
  return (Array.isArray(state.settings?.topicRequests) ? state.settings.topicRequests : [])
    .filter((entry) => normalizeUserId(entry?.requestedByUserId || "") === userId)
    .filter((entry) => ["resolved", "rejected"].includes(String(entry?.status || "").trim()))
    .map((entry) => {
      const createdAt = String(entry?.createdAt || "").trim();
      const createdAtMs = Date.parse(createdAt);
      const existing = String(entry?.status || "") === "rejected";
      return {
        id: `topic_request_resolution_${entry.id}`,
        kind: "topic_request_resolution",
        tone: existing ? "info" : "success",
        title: existing ? "Thema zugeordnet" : "Thema angelegt",
        text: existing
          ? `Für „${entry.topic}“ wurde das bestehende Thema „${entry.resolvedTopicName || "Thema"}“ zugeordnet.`
          : `„${entry.resolvedTopicName || entry.topic}“ wurde angelegt und dem Anbieter zugeordnet.`,
        createdAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        dismissible: true,
        targetSection: "providers-section",
      };
    });
}

function getProviderInvitationCompletedNotificationsForActor(actorUserId = "") {
  const normalizedActorUserId = normalizeUserId(actorUserId);
  if (!normalizedActorUserId) {
    return [];
  }
  const nowMs = Date.now();
  const windowMs = 45 * 24 * 60 * 60 * 1000;
  return (state.providers || [])
    .filter((provider) => getProviderInvitationRequestStatus(provider) === "completed")
    .filter(
      (provider) =>
        normalizeUserId(provider?.invitationRequestedByUserId || provider?.invitation_requested_by_user_id || "") ===
        normalizedActorUserId
    )
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const completedAt = String(provider?.invitationCompletedAt || provider?.invitation_completed_at || "").trim();
      const completedAtMs = Date.parse(completedAt);
      if (!providerId || !Number.isFinite(completedAtMs) || nowMs - completedAtMs > windowMs) {
        return null;
      }
      const completedByName = String(
        provider?.invitationCompletedByName || provider?.invitation_completed_by_name || "Admin"
      ).trim();
      return {
        id: `provider_invitation_completed_${providerId}_${normalizedActorUserId}_${completedAt}`,
        kind: "provider_invitation_completed",
        tone: "success",
        title: "Einladung versendet",
        text: `${providerName}: Die Dashboard-Einladung wurde von ${completedByName} versendet.`,
        createdAt: completedAt,
        createdAtMs: completedAtMs,
        persistent: true,
        dismissible: true,
        targetSection: "providers-section",
        providerId,
      };
    })
    .filter(Boolean)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getLiveSelfPendingNotifications(actorUserId = "") {
  if (!actorUserId) {
    return [];
  }
  return (state.providers || [])
    .filter((provider) => isProviderAwaitingLiveApproval(provider))
    .filter((provider) => resolveProviderLiveRequestorUserId(provider) === actorUserId)
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const requestedAt = getProviderLiveRequestTimestamp(provider);
      const createdAtMs = Date.parse(requestedAt);
      return {
        id: `live_pending_self_${providerId}_${actorUserId}_${requestedAt || "pending"}`,
        kind: "live_pending",
        tone: "info",
        title: "Live-Anfrage",
        text: `${providerName}: Anfrage gesendet, wartet auf Superadmin-Freigabe.`,
        createdAt: requestedAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        targetSection: "providers-section",
      };
    })
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getLiveApprovedNotificationsForActor(actorUserId = "") {
  if (!actorUserId) {
    return [];
  }
  const nowMs = Date.now();
  const windowMs = 45 * 24 * 60 * 60 * 1000;
  return (state.providers || [])
    .filter((provider) => normalizeProviderStatusValue(provider?.status) === "live")
    .filter((provider) => normalizeUserId(getProviderLiveEvent(provider).provisionUserId || "") === actorUserId)
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const history = normalizeProviderStatusHistory(provider?.statusHistory || provider?.status_history || []);
      const approvalEntry = history
        .slice()
        .reverse()
        .find((entry) => entry.toStatus === "live" && entry.fromStatus === PROVIDER_STATUS_LIVE_PENDING);
      const liveEvent = getProviderLiveEvent(provider);
      const provisionEntry = getLatestOpenProvisionCreditEntryForProvider(providerId);
      const provisionUserId = normalizeUserId(provisionEntry?.userId || liveEvent.provisionUserId || "");
      if (provisionUserId !== actorUserId) {
        return null;
      }
      const provisionAmount = provisionEntry
        ? Math.abs(Number(provisionEntry.amountEur || 0) || 0)
        : getProvisionAmountForUserId(provisionUserId);
      const provisionUserName = String(
        provisionEntry?.userName || liveEvent.provisionUserName || getUserDisplayNameByUserId(provisionUserId) || "Mitarbeiter"
      ).trim();
      const createdAt = String(approvalEntry?.at || liveEvent.liveAt || provider?.updatedAt || "").trim();
      const createdAtMs = Date.parse(createdAt);
      if (!Number.isFinite(createdAtMs) || nowMs - createdAtMs > windowMs) {
        return null;
      }
      return {
        id: `live_approved_${providerId}_${createdAt}`,
        kind: "live_approved",
        tone: "success",
        title: "Live-Freigabe",
        text: `${providerName} wurde live geschaltet. Provision zugeordnet: ${provisionUserName} · ${formatEuroAmount(provisionAmount)}.`,
        createdAt,
        createdAtMs,
        persistent: true,
        targetSection: "providers-section",
      };
    })
    .filter(Boolean)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getProviderResponsibilityAcceptanceStatus(provider) {
  return String(provider?.responsibilityAcceptanceStatus || provider?.responsibility_acceptance_status || "").trim();
}

function getProviderResponsibilityTransferRequestId(provider) {
  return String(provider?.responsibilityTransferRequestId || provider?.responsibility_transfer_request_id || "").trim();
}

function getProviderResponsibilityTransferNotificationsForActor(actorUserId = "") {
  const normalizedActorUserId = normalizeUserId(actorUserId);
  if (!normalizedActorUserId) {
    return [];
  }
  return (state.providers || [])
    .filter((provider) => resolveProviderManualResponsibleUserId(provider) === normalizedActorUserId)
    .filter((provider) => getProviderResponsibilityAcceptanceStatus(provider) === "pending")
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const transferredAt = String(provider?.responsibilityUpdatedAt || provider?.responsibility_updated_at || provider?.updatedAt || "").trim();
      const createdAtMs = Date.parse(transferredAt);
      const adminName = String(provider?.responsibilityTransferredByName || provider?.responsibility_transferred_by_name || "Admin").trim();
      const requestId = getProviderResponsibilityTransferRequestId(provider);
      return {
        id: `provider_responsibility_transfer_${providerId}_${normalizedActorUserId}_${transferredAt || "pending"}`,
        kind: "provider_responsibility_transfer",
        tone: "warning",
        title: "Übergabe",
        text: `${providerName} wurde dir von ${adminName} übertragen.`,
        createdAt: transferredAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        targetSection: requestId ? "partner-requests-section" : "providers-section",
        providerId,
        requestId,
        actions: [
          { id: "accept_provider_transfer", label: "Annehmen", tone: "success" },
          { id: "reject_provider_transfer", label: "Ablehnen", tone: "danger" },
        ],
      };
    })
    .filter((entry) => !!entry.providerId)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getProviderResponsibilityRejectedNotifications() {
  return (state.providers || [])
    .filter((provider) => getProviderResponsibilityAcceptanceStatus(provider) === "rejected")
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const rejectedAt = String(provider?.responsibilityRejectedAt || provider?.responsibility_rejected_at || provider?.updatedAt || "").trim();
      const createdAtMs = Date.parse(rejectedAt);
      const responsibleName =
        String(provider?.responsibilityRejectedByName || provider?.responsibility_rejected_by_name || "").trim() ||
        "Mitarbeiter";
      const reason = String(provider?.responsibilityRejectionReason || provider?.responsibility_rejection_reason || "").trim();
      const requestId = getProviderResponsibilityTransferRequestId(provider);
      return {
        id: `provider_responsibility_rejected_${providerId}_${rejectedAt || "rejected"}`,
        kind: "provider_responsibility_rejected",
        tone: "danger",
        title: "Übergabe abgelehnt",
        text: `${responsibleName} hat ${providerName} abgelehnt.${reason ? ` Grund: ${reason}` : ""}`,
        createdAt: rejectedAt,
        createdAtMs: Number.isFinite(createdAtMs) ? createdAtMs : 0,
        persistent: true,
        dismissible: true,
        targetSection: requestId ? "partner-requests-section" : "providers-section",
        providerId,
        requestId,
      };
    })
    .filter((entry) => !!entry.providerId)
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
}

function getSystemNotificationsForRole(role = "", actorUserId = "") {
  const systemEntries = adminSystemNotifications
    .slice()
    .sort((left, right) => right.createdAtMs - left.createdAtMs);
  if (role === ROLE_ADMIN || role === ROLE_SUPERADMIN) {
    return systemEntries;
  }
  if (!actorUserId) {
    return [];
  }
  return systemEntries.filter((entry) => {
    const createdByUserId = normalizeUserId(entry?.createdByUserId || "");
    const targetUserId = normalizeUserId(entry?.targetUserId || "");
    if (createdByUserId && createdByUserId === actorUserId) {
      return true;
    }
    if (targetUserId && targetUserId === actorUserId) {
      return true;
    }
    return false;
  });
}

function getSecretaryEmployeeMessageNotifications(actorUserId = "") {
  const normalizedActorUserId = normalizeUserId(actorUserId || "");
  if (!normalizedActorUserId) {
    return [];
  }
  return normalizeSecretaryEmployeeMessages(state.settings?.secretaryEmployeeMessages || [])
    .filter((entry) => entry.recipientUserIds.includes(normalizedActorUserId))
    .map((entry) => {
      const sentAtMs = Date.parse(entry.sentAt);
      return {
        id: `employee_message_${entry.id}`,
        kind: "employee_message",
        tone: "info",
        senderName: entry.sentByName,
        text: entry.body,
        createdAt: entry.sentAt,
        createdAtMs: Number.isFinite(sentAtMs) ? sentAtMs : 0,
        persistent: true,
        dismissible: true,
        targetSection: "",
      };
    });
}

function getVisibleAdminNotifications() {
  const currentUser = getCurrentUser();
  if (!currentUser) {
    return [];
  }
  const role = normalizeUserRole(currentUser.role);
  const actorUserId = normalizeUserId(getCurrentActorInfo().userId || "");
  const canReviewSignups = role === ROLE_ADMIN || role === ROLE_SUPERADMIN;
  const canReviewLiveRequests = role === ROLE_ADMIN || role === ROLE_SUPERADMIN;
  const canReviewPartnerRequests = canUsePartnerRequestsSection(currentUser);

  const signupEntries = canReviewSignups ? getAdminPendingSignupNotifications() : [];
  const partnerRequestEntries = canReviewPartnerRequests ? getPartnerRequestNotifications() : [];
  const livePendingEntries = canReviewLiveRequests ? getLivePendingApprovalNotifications() : [];
  const invitationRequestEntries = canReviewLiveRequests ? getProviderInvitationRequestNotifications() : [];
  const topicRequestEntries = role === ROLE_SUPERADMIN ? getTopicRequestNotifications() : [];
  const topicResolutionEntries = getTopicRequestResolutionNotificationsForActor(actorUserId);
  const invitationCompletedEntries = getProviderInvitationCompletedNotificationsForActor(actorUserId);
  const providerTaskReminderEntries = getProviderTaskReminderNotifications(actorUserId);
  const responsibilityTransferEntries = getProviderResponsibilityTransferNotificationsForActor(actorUserId);
  const responsibilityRejectedEntries =
    role === ROLE_ADMIN || role === ROLE_SUPERADMIN ? getProviderResponsibilityRejectedNotifications() : [];
  const ownPendingEntries =
    role !== ROLE_ADMIN && role !== ROLE_SUPERADMIN ? getLiveSelfPendingNotifications(actorUserId) : [];
  const ownApprovedEntries =
    role !== ROLE_ADMIN && role !== ROLE_SUPERADMIN
      ? getLiveApprovedNotificationsForActor(actorUserId)
      : [];
  const systemEntries = getSystemNotificationsForRole(role, actorUserId);
  const employeeMessageEntries = getSecretaryEmployeeMessageNotifications(actorUserId);
  const visible = [
    ...signupEntries,
    ...partnerRequestEntries,
    ...livePendingEntries,
    ...invitationRequestEntries,
    ...topicRequestEntries,
    ...topicResolutionEntries,
    ...invitationCompletedEntries,
    ...ownPendingEntries,
    ...ownApprovedEntries,
    ...responsibilityTransferEntries,
    ...responsibilityRejectedEntries,
    ...employeeMessageEntries,
    ...systemEntries,
  ];
  return visible
    .filter((entry) => !isNotificationDismissedByCurrentUser(entry.id))
    .filter((entry) => entry?.kind !== "employee_message" || !isEmployeeMessageNotificationReadByCurrentUser(entry.id))
    .sort((left, right) => {
      const leftPriority = Number.isFinite(left?.sortPriority) ? left.sortPriority : 100;
      const rightPriority = Number.isFinite(right?.sortPriority) ? right.sortPriority : 100;
      if (leftPriority !== rightPriority) {
        return leftPriority - rightPriority;
      }
      const leftMs = Number.isFinite(left?.createdAtMs) ? left.createdAtMs : 0;
      const rightMs = Number.isFinite(right?.createdAtMs) ? right.createdAtMs : 0;
      return rightMs - leftMs;
    });
}

function isEmployeeMessageNotificationReadByCurrentUser(notificationId) {
  const prefix = "employee_message_";
  const normalizedId = String(notificationId || "").trim();
  const readerUserId = getContentReadReceiptReaderUserId();
  if (!normalizedId.startsWith(prefix) || !readerUserId) {
    return false;
  }
  const messageId = normalizedId.slice(prefix.length);
  return contentReadReceipts.some(
    (entry) =>
      entry?.contentType === "employee_message" &&
      String(entry?.contentId || "") === messageId &&
      normalizeUserId(entry?.readerUserId || "") === readerUserId
  );
}

function getLiveRequestDashboardEntriesForUser(user = getCurrentUser()) {
  if (!user) {
    return [];
  }
  const normalizedRole = normalizeUserRole(user.role);
  const actorUserId = normalizeUserId(getCurrentActorInfo().userId || "");
  const canSeeAll = normalizedRole === ROLE_ADMIN || normalizedRole === ROLE_SUPERADMIN;
  // Dashboard-Karte bleibt bewusst unabhängig vom Glocken-Lesestatus.
  return (state.providers || [])
    .filter((provider) => isProviderAwaitingLiveApproval(provider))
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const providerName = String(provider?.name || "Anbieter").trim() || "Anbieter";
      const requestedByUserId = resolveProviderLiveRequestorUserId(provider);
      const requestedByName = resolveProviderLiveRequestorName(provider);
      const requestedByRole = normalizeUserRole(
        provider?.liveRequestedByRole || provider?.live_requested_by_role || getUserRoleByUserId(requestedByUserId)
      );
      const requestedAt = getProviderLiveRequestTimestamp(provider);
      const requestedAtMs = Date.parse(requestedAt);
      return {
        id: `live_request_board_${providerId}`,
        providerId,
        providerName,
        requestedByUserId,
        requestedByName,
        requestedByRole,
        requestedAt,
        requestedAtMs: Number.isFinite(requestedAtMs) ? requestedAtMs : 0,
        isOwnRequest: Boolean(actorUserId && requestedByUserId && requestedByUserId === actorUserId),
      };
    })
    .filter((entry) => (canSeeAll ? true : entry.isOwnRequest))
    .filter((entry) => !!entry.providerId)
    .sort((left, right) => right.requestedAtMs - left.requestedAtMs);
}

function renderLiveRequestBoard(container, entries, options = {}) {
  if (!container) {
    return;
  }
  const heading = String(options.heading || "").trim() || "Live-Beantragungen";
  const showRequester = options.showRequester !== false;
  const emptyLabel = String(options.emptyLabel || "").trim() || "Keine offenen Live-Beantragungen.";
  const rows = Array.isArray(entries) ? entries : [];

  container.innerHTML = `
    <div class="live-request-board-head">
      <h3>${escapeHtml(heading)}</h3>
      <span class="live-request-board-count">${escapeHtml(String(rows.length))}</span>
    </div>
    ${
      rows.length
        ? `<div class="live-request-board-list">
            ${rows
              .map((entry) => {
                const requestorLabel = showRequester
                  ? `${entry.requestedByName || "Mitarbeiter"}${
                      entry.requestedByRole ? ` (${getRoleLabel(entry.requestedByRole)})` : ""
                    }`
                  : "";
                const timeLabel = formatAdminNotificationTime(entry.requestedAt || "");
                return `
                  <article class="live-request-board-item">
                    <div class="live-request-board-item-head">
                      <strong>${escapeHtml(entry.providerName)}</strong>
                      <span>${escapeHtml(timeLabel || "")}</span>
                    </div>
                    ${
                      requestorLabel
                        ? `<p class="live-request-board-item-meta">Beantragt von: ${escapeHtml(requestorLabel)}</p>`
                        : '<p class="live-request-board-item-meta">Anfrage wurde an Superadmin/Admin gesendet.</p>'
                    }
                    <button
                      type="button"
                      class="table-btn"
                      data-live-request-open-provider="${escapeHtml(entry.providerId)}"
                    >Anbieter öffnen</button>
                  </article>
                `;
              })
              .join("")}
          </div>`
        : `<p class="live-request-board-empty">${escapeHtml(emptyLabel)}</p>`
    }
  `;
}

function getProviderInvitationRequestDashboardEntries(options = {}) {
  const includeCompleted = options?.includeCompleted === true;
  const keepUntilLiveRequested = options?.keepUntilLiveRequested === true;
  const requestedByUserId = normalizeUserId(options?.requestedByUserId || "");
  return (state.providers || [])
    .filter((provider) => {
      const status = getProviderInvitationRequestStatus(provider);
      const providerRequestedByUserId = normalizeUserId(
        provider?.invitationRequestedByUserId || provider?.invitation_requested_by_user_id || ""
      );
      const belongsToRequester = !requestedByUserId || providerRequestedByUserId === requestedByUserId;
      const invitationIsRelevant =
        isProviderInvitationRequestOpen(provider) || (includeCompleted && status === "completed");
      const liveRequestStarted = isProviderAwaitingLiveApproval(provider) || isLiveStatus(provider?.status);
      return belongsToRequester && invitationIsRelevant && (!keepUntilLiveRequested || !liveRequestStarted);
    })
    .map((provider) => {
      const providerId = String(provider?.id || "").trim();
      const requestedAt = String(provider?.invitationRequestedAt || provider?.invitation_requested_at || "").trim();
      const requestedByUserId = normalizeUserId(
        provider?.invitationRequestedByUserId || provider?.invitation_requested_by_user_id || ""
      );
      const requestedByName = String(
        provider?.invitationRequestedByName ||
          provider?.invitation_requested_by_name ||
          getUserDisplayNameByUserId(requestedByUserId) ||
          "Mitarbeiter"
      ).trim();
      const requestedByRole = normalizeUserRole(
        provider?.invitationRequestedByRole ||
          provider?.invitation_requested_by_role ||
          getUserRoleByUserId(requestedByUserId)
      );
      const status = getProviderInvitationRequestStatus(provider);
      const completedAt = String(provider?.invitationCompletedAt || provider?.invitation_completed_at || "").trim();
      const completedByUserId = normalizeUserId(
        provider?.invitationCompletedByUserId || provider?.invitation_completed_by_user_id || ""
      );
      const completedByName = String(
        provider?.invitationCompletedByName ||
          provider?.invitation_completed_by_name ||
          getUserDisplayNameByUserId(completedByUserId) ||
          ""
      ).trim();
      const completedByRole = normalizeUserRole(
        provider?.invitationCompletedByRole ||
          provider?.invitation_completed_by_role ||
          getUserRoleByUserId(completedByUserId)
      );
      const contactName = buildProviderContactPersonName(provider);
      const contactValues = [contactName, provider?.email, provider?.phone].filter(Boolean).map((value) => String(value).trim());
      return {
        providerId,
        providerName: String(provider?.name || "Anbieter").trim() || "Anbieter",
        locationLabel: [provider?.city, provider?.country].filter(Boolean).join(", "),
        contactLabel: contactValues.join(" · "),
        requestedAt,
        requestedAtMs: Number.isFinite(Date.parse(requestedAt)) ? Date.parse(requestedAt) : 0,
        requestedByUserId,
        requestedByName,
        requestedByRole,
        status,
        completedAt,
        completedAtMs: Number.isFinite(Date.parse(completedAt)) ? Date.parse(completedAt) : 0,
        completedByName,
        completedByRole,
      };
    })
    .filter((entry) => !!entry.providerId)
    .sort((left, right) => {
      const leftCompleted = left.status === "completed" ? 1 : 0;
      const rightCompleted = right.status === "completed" ? 1 : 0;
      if (leftCompleted !== rightCompleted) {
        return leftCompleted - rightCompleted;
      }
      return (right.completedAtMs || right.requestedAtMs) - (left.completedAtMs || left.requestedAtMs);
    });
}

function getProviderInvitationRequestCompletedCount() {
  return (state.providers || []).filter(
    (provider) => getProviderInvitationRequestStatus(provider) === "completed"
  ).length;
}

function handleProviderInvitationRequestBoardClick(event) {
  const completedVisibilityButton = event.target.closest("button[data-provider-invitation-show-completed]");
  if (completedVisibilityButton) {
    invitationRequestBoardShowCompleted = !invitationRequestBoardShowCompleted;
    renderLiveRequestBoards();
    return;
  }
  const actionButton = event.target.closest("button[data-provider-invitation-request-action]");
  if (actionButton) {
    const providerId = String(actionButton.dataset.providerInvitationRequestProviderId || "").trim();
    const action = String(actionButton.dataset.providerInvitationRequestAction || "").trim();
    if (action === "complete") {
      setActionButtonBusy(actionButton, true, "Speichert...");
      void completeProviderInvitationRequest(providerId).finally(() => {
        setActionButtonBusy(actionButton, false);
      });
      return;
    }
    if (action === "request-live") {
      void requestProviderLiveFromInvitationBoard(providerId);
    }
    return;
  }

  const target = event.target instanceof Element ? event.target : null;
  const providerRow = target?.closest("tr[data-provider-invitation-open-provider]");
  if (!providerRow || !isRoleAdmin()) {
    return;
  }
  if (target?.closest("button, a, input, select, textarea, label")) {
    return;
  }
  openProviderEditor(String(providerRow.dataset.providerInvitationOpenProvider || "").trim());
}

function handleProviderInvitationRequestBoardKeydown(event) {
  if ((event.key !== "Enter" && event.key !== " ") || !isRoleAdmin()) {
    return;
  }
  const target = event.target instanceof Element ? event.target : null;
  const providerRow = target?.closest("tr[data-provider-invitation-open-provider]");
  if (!providerRow || target?.closest("button, a, input, select, textarea, label")) {
    return;
  }
  event.preventDefault();
  openProviderEditor(String(providerRow.dataset.providerInvitationOpenProvider || "").trim());
}

function renderProviderInvitationRequestBoard(container) {
  if (!container) {
    return;
  }
  const rows = getProviderInvitationRequestDashboardEntries({
    includeCompleted: invitationRequestBoardShowCompleted,
  });
  const completedCount = getProviderInvitationRequestCompletedCount();
  container.innerHTML = `
    <div class="invitation-request-board-head">
      <div>
        <h3>Einladungen versenden</h3>
        <p>Extern kontaktieren und anschließend als erledigt markieren.</p>
      </div>
      <div class="invitation-request-board-head-actions">
        ${
          completedCount
            ? `<button
                 type="button"
                 class="mini-btn invitation-request-history-btn"
                 data-provider-invitation-show-completed="true"
                 aria-pressed="${invitationRequestBoardShowCompleted ? "true" : "false"}"
               >${
                 invitationRequestBoardShowCompleted
                   ? "Erledigte ausblenden"
                   : `Erledigte anzeigen (${completedCount})`
               }</button>`
            : ""
        }
        <span class="invitation-request-board-count">${escapeHtml(String(rows.length))}</span>
      </div>
    </div>
    ${
      rows.length
        ? `<div class="invitation-request-table-wrap">
            <table class="invitation-request-table">
              <thead>
                <tr>
                  <th>Anbieter</th>
                  <th>Kontakt</th>
                  <th>Angefordert von</th>
                  <th>Status</th>
                  <th>Aktion</th>
                </tr>
              </thead>
              <tbody>
                ${rows
                  .map((entry) => {
                    const requesterLabel = `${entry.requestedByName}${
                      entry.requestedByRole ? ` (${getRoleLabel(entry.requestedByRole)})` : ""
                    }`;
                    const completedLabel = entry.completedByName
                      ? `Erledigt: ${entry.completedByName}${
                          entry.completedByRole ? ` (${getRoleLabel(entry.completedByRole)})` : ""
                        }`
                      : "Erledigt";
                    const statusLabel = entry.status === "completed" ? completedLabel : "Offen";
                    return `
                      <tr
                        class="invitation-request-provider-row"
                        data-provider-invitation-request-row="${escapeHtml(entry.providerId)}"
                        data-provider-invitation-open-provider="${escapeHtml(entry.providerId)}"
                        tabindex="0"
                        role="button"
                        aria-label="${escapeHtml(entry.providerName)} bearbeiten"
                        title="Anbieter bearbeiten"
                      >
                        <td>
                          <strong>${escapeHtml(entry.providerName)}</strong>
                          <small>${escapeHtml(entry.locationLabel || "")}</small>
                        </td>
                        <td>${escapeHtml(entry.contactLabel || "Keine Kontaktdaten hinterlegt")}</td>
                        <td>
                          <span>${escapeHtml(requesterLabel)}</span>
                          <small>${escapeHtml(formatAdminNotificationTime(entry.requestedAt) || "")}</small>
                        </td>
                        <td>
                          <span class="invitation-request-status ${entry.status === "completed" ? "is-completed" : "is-open"}">${escapeHtml(statusLabel)}</span>
                          ${
                            entry.status === "completed" && entry.completedAt
                              ? `<small>${escapeHtml(formatAdminNotificationTime(entry.completedAt) || "")}</small>`
                              : ""
                          }
                        </td>
                        <td>
                          ${
                            entry.status === "completed"
                              ? '<span class="invitation-request-done">–</span>'
                              : `<div class="invitation-request-actions">
                                   <button
                                     type="button"
                                     class="mini-btn task-action-btn is-success"
                                     data-provider-invitation-request-action="complete"
                                     data-provider-invitation-request-provider-id="${escapeHtml(entry.providerId)}"
                                     title="Einladung als erledigt markieren"
                                   >Erledigt</button>
                                 </div>`
                          }
                        </td>
                      </tr>
                    `;
                  })
                  .join("")}
              </tbody>
            </table>
          </div>`
        : '<p class="invitation-request-board-empty">Keine offenen Einladungen. Mit „Erledigte anzeigen“ kannst du die abgeschlossenen Aufträge einblenden.</p>'
    }
  `;
}

