function focusProviderInvitationRequestBoard(providerId = "") {
  const board = els.salesDashboardInvitationRequests;
  if (!board || board.classList.contains("hidden")) {
    return;
  }
  board.scrollIntoView({ behavior: "smooth", block: "start" });
  const normalizedProviderId = String(providerId || "").trim();
  if (!normalizedProviderId) {
    return;
  }
  const row = Array.from(board.querySelectorAll("tr[data-provider-invitation-request-row]")).find(
    (entry) => String(entry.dataset.providerInvitationRequestRow || "").trim() === normalizedProviderId
  );
  if (!(row instanceof HTMLElement)) {
    return;
  }
  if (providerInvitationBoardHighlightTimerId) {
    window.clearTimeout(providerInvitationBoardHighlightTimerId);
  }
  row.classList.remove("is-highlighted");
  window.requestAnimationFrame(() => row.classList.add("is-highlighted"));
  providerInvitationBoardHighlightTimerId = window.setTimeout(() => {
    row.classList.remove("is-highlighted");
    providerInvitationBoardHighlightTimerId = 0;
  }, 3600);
}

