function confirmResponsibilityTransferDialog(options = {}) {
  const subjectLabel = String(options.subjectLabel || "Anbieter").trim();
  const subjectName = String(options.subjectName || subjectLabel).trim();
  const targetName = String(options.targetName || "Mitarbeiter").trim();
  const message = String(options.message || `Soll "${subjectName}" wirklich an ${targetName} übergeben werden?`).trim();
  if (!els.providerTransferConfirmPanel) {
    return confirmAction(message, {
      title: String(options.title || "Übergabe bestätigen").trim(),
      confirmLabel: "Übertragen",
    });
  }
  if (els.providerTransferConfirmTitle) {
    els.providerTransferConfirmTitle.textContent = String(options.title || "Übergabe bestätigen").trim();
  }
  if (els.providerTransferConfirmText) {
    els.providerTransferConfirmText.textContent = message;
  }
  if (els.providerTransferConfirmSubjectLabel) {
    els.providerTransferConfirmSubjectLabel.textContent = subjectLabel;
  }
  if (els.providerTransferConfirmProvider) {
    els.providerTransferConfirmProvider.textContent = subjectName;
  }
  if (els.providerTransferConfirmUser) {
    els.providerTransferConfirmUser.textContent = targetName;
  }
  els.providerTransferConfirmPanel.classList.remove("hidden");
  syncBodyModalOpenState();
  window.setTimeout(() => {
    els.providerTransferConfirmYes?.focus({ preventScroll: true });
  }, 0);
  return new Promise((resolve) => {
    providerTransferConfirmResolve = resolve;
  });
}

