  return `<span class="help-start-topic-icon is-${iconKind}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" focusable="false">${iconPaths[iconKind] || iconPaths.book}</svg></span>`;
