function getHelpStartViewMarkup(topics, videos, user = getCurrentUser()) {
  const startVideo = videos.find((video) => video.primary) || null;
  const additionalVideos = videos.filter((video) => !video.primary).slice(0, 2);
  const featuredVideos = [startVideo, ...additionalVideos].filter(Boolean);
  return `
    <section class="help-start-section help-start-section-plain">
      <div class="help-start-section-head">
        <div>
          <p class="help-center-eyebrow">Schneller Einstieg</p>
          <h3>Alle Themen</h3>
        </div>
        <button type="button" class="help-inline-link" data-help-center-view="topics">Listenansicht öffnen</button>
      </div>
      <div class="help-start-topic-grid">
        ${
          topics.length
            ? topics
                .map(
                  (topic) => `<button type="button" class="help-start-topic-card" data-help-topic-id="${escapeHtml(topic.id)}">
                    ${getHelpStartTopicIconMarkup(topic)}
                    <strong>${escapeHtml(topic.title)}</strong>
                    <span>${escapeHtml(topic.summary)}</span>
                  </button>`
                )
                .join("")
            : '<p class="help-topic-detail-empty">Keine passenden Themen gefunden.</p>'
        }
      </div>
    </section>
    ${
      featuredVideos.length
        ? `<section class="help-start-section">
            <div class="help-start-section-head">
              <div><p class="help-center-eyebrow">Start &amp; Weiterlernen</p><h3>Video-Anleitungen</h3></div>
              <button type="button" class="help-inline-link" data-help-center-view="videos">Videothek öffnen</button>
            </div>
            <div class="help-start-video-grid">${featuredVideos.map((video) => getOnboardingVideoMarkup(video, "page")).join("")}</div>
          </section>`
        : ""
    }
  `;
}

function renderHelpMarkupIfChanged(element, markup, previousKey) {
  if (!element || previousKey === markup) {
    return previousKey;
  }
  element.innerHTML = markup;
  return markup;
}

function renderHelpCenterSection() {
  if (!els.helpCenterSection || !els.helpTopicList || !els.helpTopicDetail) {
    return;
  }
  const currentUser = getCurrentUser();
  if (!currentUser) {
    helpTopicDetailRenderKey = "";
    helpStartContentRenderKey = "";
    helpVideoLibraryRenderKey = "";
    els.helpTopicList.innerHTML = "";
    els.helpTopicDetail.innerHTML = '<p class="help-topic-detail-empty">Bitte melde dich an.</p>';
    return;
  }

  const allTopics = getVisibleHelpTopics(currentUser);
  const canManageHelpCenter = isRoleAdmin(currentUser);
  if (helpCenterActiveView === "manage" && !canManageHelpCenter) {
    helpCenterActiveView = "start";
  }
  const allVideos = getOnboardingVideos();
  const topics = getFilteredHelpTopics(allTopics);
  const videos = getFilteredHelpVideos(allVideos);
  if (!topics.some((topic) => topic.id === helpCenterSelectedTopicId)) {
    helpCenterSelectedTopicId = allTopics[0]?.id || "";
  }
  const selectedTopic = topics.find((topic) => topic.id === helpCenterSelectedTopicId) || null;
  if (helpCenterActiveView === "topics" && selectedTopic) {
    markHelpTopicViewed(selectedTopic.id);
  }
  const progress = getHelpProgressSummary(currentUser);

  if (els.helpCenterProgress) {
    els.helpCenterProgress.textContent = progress.total
      ? `${progress.completed} von ${progress.total} Hilfeinhalten angesehen`
      : "Keine Hilfeinhalte";
  }
  if (els.helpTopicCount) {
    els.helpTopicCount.textContent = `${topics.length} ${topics.length === 1 ? "Thema" : "Themen"}`;
  }
  els.helpTopicList.innerHTML = topics.length
    ? topics
        .map((topic) => {
          const viewed = isOnboardingItemViewed(topic);
          return `
            <button type="button" class="help-topic-row ${topic.id === helpCenterSelectedTopicId ? "is-selected" : ""} ${
              viewed ? "is-viewed" : ""
            }" data-help-topic-id="${escapeHtml(topic.id)}">
              <span class="help-topic-row-title"><span>${escapeHtml(topic.title)}</span><span class="help-topic-status-dot" aria-hidden="true"></span></span>
              <span class="help-topic-row-summary">${escapeHtml(topic.summary)}</span>
            </button>
          `;
        })
        .join("")
    : '<p class="help-topic-detail-empty">Für diese Rolle sind derzeit keine Hilfe-Themen veröffentlicht.</p>';
  const policyMarkup = getHelpPolicyMarkup();
  const topicDetailMarkup = `${getHelpTopicDetailMarkup(selectedTopic)}${policyMarkup}`;
  helpTopicDetailRenderKey = renderHelpMarkupIfChanged(
    els.helpTopicDetail,
    topicDetailMarkup,
    helpTopicDetailRenderKey
  );
  window.setTimeout(() => resizeHelpTopicWebDocumentFrames(els.helpTopicDetail), 0);
  if (els.helpCenterSearchInput && els.helpCenterSearchInput.value !== helpCenterSearchTerm) {
    els.helpCenterSearchInput.value = helpCenterSearchTerm;
  }
  els.helpCenterViewButtons?.forEach((button) => {
    const isActive = button.dataset.helpCenterView === helpCenterActiveView;
    const isManageTab = button.dataset.helpCenterView === "manage";
    button.classList.toggle("hidden", isManageTab && !canManageHelpCenter);
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  els.helpCenterViewPanels?.forEach((panel) => {
    const isManagePanel = panel.dataset.helpCenterPanel === "manage";
    const isActive = panel.dataset.helpCenterPanel === helpCenterActiveView && (!isManagePanel || canManageHelpCenter);
    panel.classList.toggle("hidden", !isActive);
  });
  if (els.helpCenterStartContent) {
    const startMarkup = `${getHelpStartViewMarkup(topics, videos, currentUser)}${policyMarkup}`;
    helpStartContentRenderKey = renderHelpMarkupIfChanged(
      els.helpCenterStartContent,
      startMarkup,
      helpStartContentRenderKey
    );
  }
  if (els.helpCenterVideoLibrary) {
    const videoLibraryMarkup = `${getHelpVideoLibraryMarkup(videos)}${policyMarkup}`;
    helpVideoLibraryRenderKey = renderHelpMarkupIfChanged(
      els.helpCenterVideoLibrary,
      videoLibraryMarkup,
      helpVideoLibraryRenderKey
    );
  }
  renderHelpAdminWorkspace();
}

function getHelpSupportMailtoUrl() {
  return `mailto:${HELP_DEFAULT_SUPPORT_EMAIL}`;
}

function getHelpPolicyMarkup() {
  const helpCenter = getHelpCenterSettings();
  const links = [];
  if (helpCenter.privacyNoticeUrl) {
    links.push(
      `<a href="${escapeHtml(helpCenter.privacyNoticeUrl)}" target="_blank" rel="noopener noreferrer">Datenschutzhinweis</a>`
    );
  }
  links.push(
    `<a href="${escapeHtml(getHelpSupportMailtoUrl())}" target="_blank" rel="noopener noreferrer" data-help-support-contact="true">Support kontaktieren</a>`
  );
  return links.length ? `<div class="help-policy-note">${links.join("")}</div>` : "";
}

function normalizeHelpAdminTabId(tabId = "") {
  const normalized = String(tabId || "").trim();
  return HELP_ADMIN_TAB_IDS.includes(normalized) ? normalized : "overview";
}

function setHelpAdminTab(tabId = "overview") {
  helpAdminActiveTab = normalizeHelpAdminTabId(tabId);
  syncHelpAdminTabs();
}

function syncHelpAdminTabs() {
  const activeTab = normalizeHelpAdminTabId(helpAdminActiveTab);
  helpAdminActiveTab = activeTab;
  els.helpAdminTabButtons?.forEach((button) => {
    const isActive = button.dataset.helpAdminTab === activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  els.helpAdminTabPanels?.forEach((panel) => {
    const isActive = panel.dataset.helpAdminPanel === activeTab;
    panel.classList.toggle("hidden", !isActive);
    panel.hidden = !isActive;
  });
}

function renderHelpAdminWorkspace() {
  if (!els.helpAdminWorkspace) {
    return;
  }
  const canManage = isRoleAdmin();
  els.helpAdminWorkspace.classList.toggle("hidden", !canManage);
  if (!canManage) {
    return;
  }
  const helpCenter = getHelpCenterSettings();
  const topics = helpCenter.topics;
  const activeCount = topics.filter((topic) => topic.status === "active").length;
  const requiredCount = topics.filter((topic) => topic.status === "active" && topic.required).length;
  const draftCount = topics.filter((topic) => topic.status === "draft").length;
  const videoCount = getOnboardingVideos().length;
  syncHelpAdminTabs();
  if (els.helpAdminMeta) {
    els.helpAdminMeta.textContent = `${topics.length} Themen gesamt`;
  }
  if (els.helpAdminStatVideos) {
    els.helpAdminStatVideos.textContent = String(videoCount);
  }
  if (els.helpAdminStatActive) {
    els.helpAdminStatActive.textContent = String(activeCount);
  }
  if (els.helpAdminStatRequired) {
    els.helpAdminStatRequired.textContent = String(requiredCount);
  }
  if (els.helpAdminStatDraft) {
    els.helpAdminStatDraft.textContent = String(draftCount);
  }
  if (els.helpCenterSettingsForm) {
    const form = els.helpCenterSettingsForm.elements;
    form.startVideoTitle.value = helpCenter.startVideo.title;
    form.startVideoUrl.value = helpCenter.startVideo.url;
    form.privacyNoticeUrl.value = helpCenter.privacyNoticeUrl;
    form.supportEmail.value = helpCenter.supportEmail;
    form.renewStartVideo.checked = false;
  }
  renderHelpAdminVideoList();
  renderHelpOnboardingVideoForm();
  renderHelpAdminTopicList();
  renderHelpTopicForm();
}

function renderHelpAdminVideoList() {
  if (!els.helpOnboardingVideoList) {
    return;
  }
  const videos = getHelpCenterSettings().onboardingVideos;
  els.helpOnboardingVideoList.innerHTML = videos.length
    ? videos
        .map(
          (video, index) => `
            <div class="help-admin-video-row ${video.id === helpOnboardingVideoEditingId ? "is-editing" : ""}">
              <span class="help-admin-row-index">${String(index + 2).padStart(2, "0")}</span>
              <div>
                <strong>${escapeHtml(video.title)}</strong>
                <small>${escapeHtml(getHelpVideoSourceLabel(video.url))} · Version ${video.version}</small>
              </div>
              <div class="help-admin-topic-actions">
                <button type="button" class="mini-btn" title="Nach oben" aria-label="Nach oben" data-help-onboarding-video-move="up" data-help-onboarding-video-id="${escapeHtml(
                  video.id
                )}" ${index === 0 ? "disabled" : ""}>↑</button>
                <button type="button" class="mini-btn" title="Nach unten" aria-label="Nach unten" data-help-onboarding-video-move="down" data-help-onboarding-video-id="${escapeHtml(
                  video.id
                )}" ${index === videos.length - 1 ? "disabled" : ""}>↓</button>
                <button type="button" class="mini-btn" title="Bearbeiten" aria-label="Bearbeiten" data-help-onboarding-video-edit="${escapeHtml(
                  video.id
                )}">✎</button>
                <button type="button" class="mini-btn danger" title="Video entfernen" aria-label="Video entfernen" data-help-onboarding-video-delete="${escapeHtml(
                  video.id
                )}">×</button>
              </div>
            </div>
          `
        )
        .join("")
    : '<p class="help-topic-detail-empty">Noch keine weiteren Videos angelegt.</p>';
}

function renderHelpOnboardingVideoForm() {
  if (!els.helpOnboardingVideoForm) {
    return;
  }
  const video = getHelpCenterSettings().onboardingVideos.find((entry) => entry.id === helpOnboardingVideoEditingId) || null;
  const form = els.helpOnboardingVideoForm.elements;
  form.videoId.value = video?.id || "";
  form.title.value = video?.title || "";
  form.videoUrl.value = video?.url || "";
  form.renewOnboarding.checked = false;
  if (els.helpOnboardingVideoFormTitle) {
    els.helpOnboardingVideoFormTitle.textContent = video ? "Weiteres Video bearbeiten" : "Weiteres Video anlegen";
  }
}

function setHelpOnboardingVideoEditor(videoId = "") {
  helpOnboardingVideoEditingId = String(videoId || "").trim();
  renderHelpCenterSection();
  if (els.helpOnboardingVideoForm && helpOnboardingVideoEditingId) {
    window.setTimeout(() => els.helpOnboardingVideoForm.elements.title?.focus({ preventScroll: true }), 0);
  }
}

async function handleHelpOnboardingVideoSubmit(formElement) {
  if (!isRoleAdmin()) {
    return;
  }
  const formData = new FormData(formElement);
  const current = getHelpCenterSettings();
  const videoId = String(formData.get("videoId") || "").trim();
  const existing = current.onboardingVideos.find((entry) => entry.id === videoId) || null;
  const rawUrl = String(formData.get("videoUrl") || "").trim();
  const normalizedUrl = sanitizeHelpHttpsUrl(rawUrl);
  if (!normalizedUrl) {
    showWarningFeedback("Bitte eine gueltige HTTPS-Video-URL verwenden.");
    return;
  }
  let url = normalizedUrl;
  try {
    url = await resolveHelpVideoUrl(normalizedUrl);
  } catch (error) {
    showWarningFeedback(error?.message || "Der Vimeo-Link konnte nicht aufgeloest werden.");
    return;
  }
  const video = normalizeHelpOnboardingVideo(
    {
      id: existing?.id || createId("help_video"),
      title: formData.get("title"),
      url,
      version: existing && formData.get("renewOnboarding") === "on" ? existing.version + 1 : existing?.version || 1,
      sortOrder: existing?.sortOrder || current.onboardingVideos.length + 1,
    },
    current.onboardingVideos.length
  );
  if (!video) {
    showWarningFeedback("Bitte Titel und Video-URL vollstaendig ausfuellen.");
    return;
  }
  const onboardingVideos = existing
    ? current.onboardingVideos.map((entry) => (entry.id === existing.id ? video : entry))
    : current.onboardingVideos.concat(video);
  helpOnboardingVideoEditingId = video.id;
  saveHelpCenterConfiguration({ ...current, onboardingVideos });
  showSuccessFeedback(existing ? "Onboarding-Video aktualisiert." : "Onboarding-Video hinzugefuegt.");
}

function moveHelpOnboardingVideo(videoId, direction) {
  if (!isRoleAdmin()) {
    return;
  }
  const current = getHelpCenterSettings();
  const videos = current.onboardingVideos.slice();
  const index = videos.findIndex((video) => video.id === String(videoId || "").trim());
  const targetIndex = direction === "up" ? index - 1 : index + 1;
  if (index < 0 || targetIndex < 0 || targetIndex >= videos.length) {
    return;
  }
  const [video] = videos.splice(index, 1);
  videos.splice(targetIndex, 0, video);
  saveHelpCenterConfiguration({
    ...current,
    onboardingVideos: videos.map((entry, videoIndex) => ({ ...entry, sortOrder: videoIndex + 1 })),
  });
}

async function deleteHelpOnboardingVideo(videoId) {
  if (!isRoleAdmin()) {
    return;
  }
  const current = getHelpCenterSettings();
  const video = current.onboardingVideos.find((entry) => entry.id === String(videoId || "").trim());
  if (!video || !(await confirmAction(`Onboarding-Video „${video.title}“ entfernen?`, {
    title: "Video entfernen",
    confirmLabel: "Entfernen",
    danger: true,
  }))) {
    return;
  }
  if (helpOnboardingVideoEditingId === video.id) {
    helpOnboardingVideoEditingId = "";
  }
  saveHelpCenterConfiguration({
    ...current,
    onboardingVideos: current.onboardingVideos.filter((entry) => entry.id !== video.id),
  });
  showSuccessFeedback("Onboarding-Video entfernt.");
}

function renderHelpAdminTopicList() {
  if (!els.helpAdminTopicList) {
    return;
  }
  const topics = getAllHelpTopics();
  els.helpAdminTopicList.innerHTML = topics.length
    ? topics
        .map(
          (topic, index) => `
            <div class="help-admin-topic-row ${topic.id === helpTopicEditingId ? "is-editing" : ""}">
              <span class="help-admin-row-index">${String(index + 1).padStart(2, "0")}</span>
              <div>
                <div class="help-admin-row-title-line">
                  <strong>${escapeHtml(topic.title)}</strong>
                  <span class="help-admin-status ${getHelpAdminStatusClass(topic.status)}">${escapeHtml(
                    getHelpTopicStatusLabel(topic.status)
                  )}</span>
                </div>
                <small>${escapeHtml(getHelpAudienceLabel(topic))} · Version ${topic.version}${topic.required ? " · Pflicht" : ""}</small>
              </div>
              <div class="help-admin-topic-actions">
                <button type="button" class="mini-btn" title="Nach oben" aria-label="Nach oben" data-help-topic-move="up" data-help-topic-id="${escapeHtml(
                  topic.id
                )}" ${index === 0 ? "disabled" : ""}>↑</button>
                <button type="button" class="mini-btn" title="Nach unten" aria-label="Nach unten" data-help-topic-move="down" data-help-topic-id="${escapeHtml(
                  topic.id
                )}" ${index === topics.length - 1 ? "disabled" : ""}>↓</button>
                <button type="button" class="mini-btn" title="Bearbeiten" aria-label="Bearbeiten" data-help-topic-edit="${escapeHtml(
                  topic.id
                )}">✎</button>
                <button type="button" class="mini-btn" title="Archivieren" aria-label="Archivieren" data-help-topic-archive="${escapeHtml(
                  topic.id
                )}" ${topic.status === "archived" ? "disabled" : ""}>⌁</button>
                <button type="button" class="mini-btn danger" title="Löschen" aria-label="Löschen" data-help-topic-delete="${escapeHtml(
                  topic.id
                )}">×</button>
              </div>
            </div>
          `
        )
        .join("")
    : '<p class="help-topic-detail-empty">Noch keine Themen angelegt.</p>';
}

function renderHelpTopicForm() {
  if (!els.helpTopicForm) {
    return;
  }
  if (helpTopicEditorDirty) {
    syncHelpTopicImageControls();
    return;
  }
  const topic = getAllHelpTopics().find((entry) => entry.id === helpTopicEditingId) || null;
  const form = els.helpTopicForm.elements;
  form.topicId.value = topic?.id || "";
  form.title.value = topic?.title || "";
  form.summary.value = topic?.summary || "";
  setHelpTopicVisualEditorContent(topic?.content || "");
  syncHelpTopicTextSizeControl();
  setHelpTopicSelectedImage(null);
  form.videoUrl.value = topic?.videoUrl || "";
  form.hasVideo.checked = Boolean(topic?.videoUrl);
  syncHelpTopicVideoField();
  form.targetSection.value = topic?.targetSection || "";
  form.countries.value = topic && !topic.countries.includes("all") ? topic.countries.join(", ") : "";
  form.status.value = topic?.status || "active";
  form.required.checked = Boolean(topic?.required);
  form.renewOnboarding.checked = false;
  Array.from(els.helpTopicForm.querySelectorAll('input[name="roles"]')).forEach((input) => {
    input.checked = topic ? topic.roles.includes(input.value) : true;
  });
  if (els.helpTopicFormTitle) {
    els.helpTopicFormTitle.textContent = topic ? "Hilfe-Thema bearbeiten" : "Hilfe-Thema anlegen";
  }
  if (els.helpTopicFormMode) {
    els.helpTopicFormMode.textContent = topic ? `Version ${topic.version}` : "Neu";
  }
  if (els.helpTopicShareLinkBtn) {
    els.helpTopicShareLinkBtn.disabled = !topic;
  }
}

function syncHelpTopicVideoField() {
  if (!els.helpTopicForm) {
    return;
  }
  const form = els.helpTopicForm.elements;
  const showVideo = Boolean(form.hasVideo?.checked);
  const field = els.helpTopicForm.querySelector("[data-help-topic-video-field]");
  field?.classList.toggle("hidden", !showVideo);
  if (form.videoUrl) {
    form.videoUrl.disabled = !showVideo;
    if (!showVideo) {
      form.videoUrl.value = "";
    }
  }
}

function setHelpTopicEditor(topicId = "") {
  helpTopicEditingId = String(topicId || "").trim();
  helpTopicEditorDirty = false;
  setHelpTopicHtmlSourceMode(false, { applySource: false });
  renderHelpCenterSection();
  if (els.helpTopicForm && helpTopicEditingId) {
    window.setTimeout(() => els.helpTopicForm.elements.title?.focus({ preventScroll: true }), 0);
  }
}

function isHelpListGapElement(element) {
  return element instanceof HTMLElement && element.getAttribute("data-help-list-gap") === "true";
}

function isHelpListItemEmpty(listItem) {
  if (!(listItem instanceof HTMLElement)) {
    return false;
  }
  if (listItem.querySelector("img, video, iframe, table, hr")) {
    return false;
  }
  const text = String(listItem.textContent || "").replace(/\u00a0/g, " ").trim();
  return !text;
}

function ensureHelpListGapPlaceholder(listItem) {
  if (!(listItem instanceof HTMLElement)) {
    return;
  }
  if (!listItem.childNodes.length) {
    listItem.appendChild(document.createElement("br"));
  }
}

function normalizeHelpTopicListGaps(root, options = {}) {
  if (!(root instanceof HTMLElement || root instanceof DocumentFragment)) {
    return false;
  }
  const markEmptyItemsAsGaps = options?.markEmptyItemsAsGaps !== false;
  let changed = false;
  const listItems = Array.from(root.querySelectorAll("li"));
  listItems.forEach((listItem) => {
    if (!(listItem instanceof HTMLElement)) {
      return;
    }
    if (isHelpListItemEmpty(listItem)) {
      if (markEmptyItemsAsGaps && !isHelpListGapElement(listItem)) {
        listItem.setAttribute("data-help-list-gap", "true");
        changed = true;
      }
      if (isHelpListGapElement(listItem)) {
        ensureHelpListGapPlaceholder(listItem);
        listItem.removeAttribute("value");
      }
      return;
    }
    if (isHelpListGapElement(listItem)) {
      listItem.removeAttribute("data-help-list-gap");
      changed = true;
    }
  });

  Array.from(root.querySelectorAll("ol")).forEach((list) => {
    let visibleIndex = 1;
    Array.from(list.children).forEach((child) => {
      if (!(child instanceof HTMLElement) || child.tagName.toLowerCase() !== "li") {
        return;
      }
      if (isHelpListGapElement(child)) {
        child.removeAttribute("value");
        return;
      }
      const nextValue = String(visibleIndex);
      if (child.getAttribute("value") !== nextValue) {
        child.setAttribute("value", nextValue);
        changed = true;
      }
      visibleIndex += 1;
    });
  });
  return changed;
}

function normalizeHelpTopicEditorStructure() {
  const editor = els.helpTopicContentEditor;
  if (!(editor instanceof HTMLElement) || editor.dataset.helpWebDocument) {
    return false;
  }
  return normalizeHelpTopicListGaps(editor, { markEmptyItemsAsGaps: false });
}

function getHelpTopicEditorActiveListItem() {
  const editor = els.helpTopicContentEditor;
  const selection = window.getSelection?.();
  if (!(editor instanceof HTMLElement) || !selection?.rangeCount) {
    return null;
  }
  const range = selection.getRangeAt(0);
  const container =
    range.startContainer instanceof Element ? range.startContainer : range.startContainer?.parentElement;
  const listItem = container?.closest?.("li") || null;
  return listItem instanceof HTMLElement && editor.contains(listItem) ? listItem : null;
}

function placeHelpTopicCaretInElement(element) {
  if (!(element instanceof HTMLElement)) {
    return;
  }
  const range = document.createRange();
  range.setStart(element, 0);
  range.collapse(true);
  const selection = window.getSelection?.();
  selection?.removeAllRanges();
  selection?.addRange(range);
  helpTopicEditorSavedRange = range.cloneRange();
}

function createHelpTopicEmptyListItem() {
  const listItem = document.createElement("li");
  listItem.appendChild(document.createElement("br"));
  return listItem;
}

function getHelpTopicRangeFragmentText(range) {
  if (!(range instanceof Range)) {
    return "";
  }
  const container = document.createElement("div");
  container.appendChild(range.cloneContents());
  return String(container.textContent || "").replace(/\u00a0/g, " ").trim();
}

function helpTopicRangeFragmentHasMedia(range) {
  if (!(range instanceof Range)) {
    return false;
  }
  const container = document.createElement("div");
  container.appendChild(range.cloneContents());
  return Boolean(container.querySelector("img, video, iframe, table, hr"));
}

function isHelpTopicRangeAtListItemStart(range, listItem) {
  if (!(range instanceof Range) || !(listItem instanceof HTMLElement)) {
    return false;
  }
  const startElement =
    range.startContainer instanceof Element ? range.startContainer : range.startContainer?.parentElement;
  if (!startElement || !listItem.contains(startElement)) {
    return false;
  }
  const beforeRange = range.cloneRange();
  beforeRange.selectNodeContents(listItem);
  try {
    beforeRange.setEnd(range.startContainer, range.startOffset);
  } catch (_error) {
    return false;
  }
  return !getHelpTopicRangeFragmentText(beforeRange) && !helpTopicRangeFragmentHasMedia(beforeRange);
}

function getPreviousHelpTopicContentListItem(listItem) {
  let previousItem = listItem?.previousElementSibling;
  while (previousItem instanceof HTMLElement && previousItem.tagName.toLowerCase() === "li") {
    if (!isHelpListGapElement(previousItem) && !isHelpListItemEmpty(previousItem)) {
      return previousItem;
    }
    previousItem = previousItem.previousElementSibling;
  }
  return null;
}

function removeHelpTopicEmptyListItem(listItem) {
  if (!(listItem instanceof HTMLElement) || (!isHelpListGapElement(listItem) && !isHelpListItemEmpty(listItem))) {
    return;
  }
  listItem.remove();
}

function appendHelpTopicImageToListItem(listItem, image) {
  if (!(listItem instanceof HTMLElement) || !(image instanceof HTMLImageElement)) {
    return false;
  }
  listItem.removeAttribute("data-help-list-gap");
  listItem.removeAttribute("value");
  if (isHelpListItemEmpty(listItem)) {
    listItem.innerHTML = "";
  }
  listItem.appendChild(image);
  return true;
}

function placeHelpTopicCaretAfterNode(node) {
  if (!(node instanceof Node)) {
    return;
  }
  const range = document.createRange();
  range.setStartAfter(node);
  range.collapse(true);
  const selection = window.getSelection?.();
  selection?.removeAllRanges();
  selection?.addRange(range);
  helpTopicEditorSavedRange = range.cloneRange();
}

function getHelpTopicListContinuationItem(listItem) {
  let nextItem = listItem?.nextElementSibling;
  while (nextItem instanceof HTMLElement && nextItem.tagName.toLowerCase() === "li") {
    if (!isHelpListGapElement(nextItem)) {
      return nextItem;
    }
    nextItem = nextItem.nextElementSibling;
  }
  return null;
}

function getHelpTopicListContinuationAnchor(listItem) {
  let anchor = listItem;
  let nextItem = listItem?.nextElementSibling;
  while (nextItem instanceof HTMLElement && nextItem.tagName.toLowerCase() === "li" && isHelpListGapElement(nextItem)) {
    anchor = nextItem;
    nextItem = nextItem.nextElementSibling;
  }
  return anchor instanceof HTMLElement ? anchor : listItem;
}

function insertHelpTopicListGapFromItem(listItem) {
  if (!(listItem instanceof HTMLElement) || !isHelpListItemEmpty(listItem)) {
    return false;
  }
  listItem.setAttribute("data-help-list-gap", "true");
  ensureHelpListGapPlaceholder(listItem);

  let nextItem = getHelpTopicListContinuationItem(listItem);
  if (!nextItem) {
    nextItem = createHelpTopicEmptyListItem();
    getHelpTopicListContinuationAnchor(listItem)?.insertAdjacentElement("afterend", nextItem);
  }
  normalizeHelpTopicEditorStructure();
  placeHelpTopicCaretInElement(nextItem);
  syncHelpTopicImageControls();
  return true;
}

function insertHelpTopicListGapAfterItem(listItem) {
  if (!(listItem instanceof HTMLElement)) {
    return false;
  }
  if (isHelpListItemEmpty(listItem)) {
    insertHelpTopicListGapFromItem(listItem);
    return true;
  }
  const gapItem = document.createElement("li");
  gapItem.setAttribute("data-help-list-gap", "true");
  gapItem.appendChild(document.createElement("br"));

  let nextItem = getHelpTopicListContinuationItem(listItem);
  listItem.insertAdjacentElement("afterend", gapItem);
  nextItem = getHelpTopicListContinuationItem(gapItem) || nextItem;
  if (!nextItem) {
    nextItem = createHelpTopicEmptyListItem();
    getHelpTopicListContinuationAnchor(gapItem)?.insertAdjacentElement("afterend", nextItem);
  }
  normalizeHelpTopicEditorStructure();
  placeHelpTopicCaretInElement(nextItem);
  syncHelpTopicImageControls();
  return true;
}

function removeHelpTopicListGap(listItem) {
  if (!isHelpListGapElement(listItem)) {
    return false;
  }
  const nextItem = listItem.nextElementSibling instanceof HTMLElement ? listItem.nextElementSibling : null;
  const previousItem = listItem.previousElementSibling instanceof HTMLElement ? listItem.previousElementSibling : null;
  listItem.remove();
  normalizeHelpTopicEditorStructure();
  placeHelpTopicCaretInElement(nextItem || previousItem || els.helpTopicContentEditor);
  syncHelpTopicImageControls();
  return true;
}

function handleHelpTopicEditorKeydown(event) {
  if (event.defaultPrevented || event.isComposing) {
    return;
  }
  const isListGapKey = event.key === "Enter" && !event.shiftKey;
  const isDeleteEmptyMarkerKey = event.key === "Backspace" || event.key === "Delete";
  if (!isListGapKey && !isDeleteEmptyMarkerKey) {
    return;
  }
  const listItem = getHelpTopicEditorActiveListItem();
  if (!listItem) {
    return;
  }
  if (isHelpListGapElement(listItem)) {
    if (isDeleteEmptyMarkerKey) {
      event.preventDefault();
      removeHelpTopicListGap(listItem);
    }
    return;
  }
  if (!isHelpListItemEmpty(listItem)) {
    return;
  }
  event.preventDefault();
  insertHelpTopicListGapFromItem(listItem);
}

function isHelpTopicImageFile(file) {
  return file instanceof File && HELP_TOPIC_IMAGE_MIME_TYPES.has(String(file.type || "").toLowerCase());
}

function rememberHelpTopicEditorSelection() {
  const editor = els.helpTopicContentEditor;
  const selection = window.getSelection?.();
  if (!(editor instanceof HTMLElement) || !selection?.rangeCount) {
    return;
  }
  const range = selection.getRangeAt(0);
  if (editor.contains(range.commonAncestorContainer)) {
    helpTopicEditorSavedRange = range.cloneRange();
    syncHelpTopicTextSizeControl();
  }
}

function restoreHelpTopicEditorSelection() {
  const editor = els.helpTopicContentEditor;
  const selection = window.getSelection?.();
  if (!(editor instanceof HTMLElement) || !selection || !helpTopicEditorSavedRange) {
    return false;
  }
  if (!editor.contains(helpTopicEditorSavedRange.commonAncestorContainer)) {
    return false;
  }
  selection.removeAllRanges();
  selection.addRange(helpTopicEditorSavedRange);
  return true;
}

function getValidHelpTopicSelectedImage() {
  const editor = els.helpTopicContentEditor;
  if (!(editor instanceof HTMLElement) || !(helpTopicSelectedImage instanceof HTMLImageElement)) {
    return null;
  }
  return editor.contains(helpTopicSelectedImage) ? helpTopicSelectedImage : null;
}

function syncHelpTopicImageControls() {
  const image = getValidHelpTopicSelectedImage();
  if (!image) {
    helpTopicSelectedImage = null;
  }
  const size = normalizeHelpImageSize(image?.getAttribute("data-help-image-size"));
  const align = normalizeHelpImageAlign(image?.getAttribute("data-help-image-align"));
  els.helpTopicImageSizeButtons?.forEach((button) => {
    const isActive = Boolean(image) && button.dataset.helpImageSize === size;
    button.classList.toggle("is-active", isActive);
    button.disabled = !image;
  });
  els.helpTopicImageAlignButtons?.forEach((button) => {
    const isActive = Boolean(image) && button.dataset.helpImageAlign === align;
    button.classList.toggle("is-active", isActive);
    button.disabled = !image;
  });
}

function setHelpTopicSelectedImage(image) {
  const editor = els.helpTopicContentEditor;
  const nextImage = image instanceof HTMLImageElement && editor?.contains(image) ? image : null;
  if (helpTopicSelectedImage && helpTopicSelectedImage !== nextImage) {
    helpTopicSelectedImage.classList.remove("is-selected");
  }
  helpTopicSelectedImage = nextImage;
  helpTopicSelectedImage?.classList.add("is-selected");
  syncHelpTopicImageControls();
}

function applyHelpTopicImageSize(sizeLike) {
  const image = getValidHelpTopicSelectedImage();
  if (!image) {
    showWarningFeedback("Bitte zuerst ein Bild im Inhalt anklicken.");
    syncHelpTopicImageControls();
    return;
  }
  image.setAttribute("data-help-image-size", normalizeHelpImageSize(sizeLike));
  helpTopicEditorDirty = true;
  syncHelpTopicImageControls();
}

function applyHelpTopicImageAlign(alignLike) {
  const image = getValidHelpTopicSelectedImage();
  if (!image) {
    showWarningFeedback("Bitte zuerst ein Bild im Inhalt anklicken.");
    syncHelpTopicImageControls();
    return;
  }
  image.setAttribute("data-help-image-align", normalizeHelpImageAlign(alignLike));
  helpTopicEditorDirty = true;
  syncHelpTopicImageControls();
}

function normalizeHelpTopicTextSize(value) {
  const normalized = String(value || "").trim().toLowerCase();
  return HELP_TOPIC_TEXT_SIZES.has(normalized) ? normalized : "";
}

function getHelpTopicTextBlockAncestor(node, editor) {
  let element = node instanceof Element ? node : node?.parentElement;
  while (element instanceof HTMLElement && element !== editor) {
    if (element.matches("p, h3, h4, li, blockquote, div")) {
      return element;
    }
    element = element.parentElement;
  }
  return null;
}

function getHelpTopicTextBlocks(range, editor) {
  if (!(range instanceof Range) || !(editor instanceof HTMLElement)) {
    return [];
  }
  const startBlock = getHelpTopicTextBlockAncestor(range.startContainer, editor);
  if (range.collapsed) {
    if (startBlock) {
      return [startBlock];
    }
    if (!String(editor.textContent || "").trim() || editor.querySelector("img, video, iframe, table")) {
      return [];
    }
    const paragraph = document.createElement("p");
    while (editor.firstChild) {
      paragraph.appendChild(editor.firstChild);
    }
    editor.appendChild(paragraph);
    return [paragraph];
  }

  const blocks = Array.from(editor.querySelectorAll("p, h3, h4, li, blockquote, div"))
    .filter((element) => {
      try {
        return range.intersectsNode(element);
      } catch (_error) {
        return false;
      }
    })
    .filter((element, _index, allBlocks) => !allBlocks.some((other) => other !== element && element.contains(other)));
  return blocks.length ? blocks : startBlock ? [startBlock] : [];
}

function unwrapHelpTopicTextSizeSpans(element) {
  if (!(element instanceof HTMLElement)) {
    return;
  }
  element.querySelectorAll("span[data-help-text-size]").forEach((span) => {
    while (span.firstChild) {
      span.parentNode?.insertBefore(span.firstChild, span);
    }
    span.remove();
  });
}

function syncHelpTopicTextSizeControl() {
  const editor = els.helpTopicContentEditor;
  const selection = window.getSelection?.();
  if (!(editor instanceof HTMLElement)) {
    return;
  }
  const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
  const blocks = range && editor.contains(range.commonAncestorContainer) ? getHelpTopicTextBlocks(range, editor) : [];
  const textSize = normalizeHelpTopicTextSize(blocks[0]?.getAttribute("data-help-text-size"));
  const activeSize = textSize || "normal";
  els.helpTopicTextSizeButtons?.forEach((button) => {
    const isActive = button.dataset.helpTextSize === activeSize;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });
}

function applyHelpTopicTextSize(sizeLike) {
  const editor = els.helpTopicContentEditor;
  const requestedSize = String(sizeLike || "").trim().toLowerCase();
  const textSize = normalizeHelpTopicTextSize(requestedSize);
  if (!(editor instanceof HTMLElement) || (requestedSize !== "normal" && !textSize)) {
    return;
  }
  editor.focus({ preventScroll: true });
  restoreHelpTopicEditorSelection();
  const selection = window.getSelection?.();
  const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
  if (!range || !editor.contains(range.commonAncestorContainer)) {
    showInfoFeedback("Bitte den Cursor in den Absatz setzen, dessen Schriftgröße du ändern möchtest.");
    return;
  }
  const blocks = getHelpTopicTextBlocks(range, editor);
  if (!blocks.length) {
    showInfoFeedback("Bitte den Cursor in einen Textabsatz setzen.");
    return;
  }
  blocks.forEach((block) => {
    unwrapHelpTopicTextSizeSpans(block);
    if (textSize) {
      block.setAttribute("data-help-text-size", textSize);
    } else {
      block.removeAttribute("data-help-text-size");
    }
  });
  normalizeHelpTopicEditorStructure();
  rememberHelpTopicEditorSelection();
  syncHelpTopicTextSizeControl();
  helpTopicEditorDirty = true;
}

function syncHelpTopicHtmlSourceUi() {
  const editor = els.helpTopicContentEditor;
  const htmlEditor = els.helpTopicHtmlEditor;
  const toggleButton = els.helpTopicHtmlToggleBtn;
  editor?.classList.toggle("hidden", helpTopicHtmlSourceMode);
  htmlEditor?.classList.toggle("hidden", !helpTopicHtmlSourceMode);
  els.helpTopicHtmlHint?.classList.toggle("hidden", !helpTopicHtmlSourceMode);
  if (htmlEditor instanceof HTMLTextAreaElement) {
    htmlEditor.disabled = !helpTopicHtmlSourceMode;
  }
  if (toggleButton instanceof HTMLButtonElement) {
    toggleButton.classList.toggle("is-active", helpTopicHtmlSourceMode);
    toggleButton.textContent = helpTopicHtmlSourceMode ? "Vorschau" : "HTML-Code";
    toggleButton.title = helpTopicHtmlSourceMode ? "HTML prüfen und Vorschau anzeigen" : "HTML-Code bearbeiten";
    toggleButton.setAttribute("aria-label", toggleButton.title);
    toggleButton.setAttribute("aria-pressed", String(helpTopicHtmlSourceMode));
  }
  els.helpTopicRichCommandButtons?.forEach((button) => {
    if (button !== toggleButton) {
      // Bilder können auch direkt im HTML-Code eingefügt werden. Alle übrigen
      // visuellen Formatierungswerkzeuge arbeiten erst wieder in der Vorschau.
      button.disabled = helpTopicHtmlSourceMode && button.dataset.helpRichCommand !== "insertImage";
    }
  });
}

function commitHelpTopicHtmlSource() {
  if (!helpTopicHtmlSourceMode) {
    return false;
  }
  const editor = els.helpTopicContentEditor;
  const htmlEditor = els.helpTopicHtmlEditor;
  if (!(editor instanceof HTMLElement) || !(htmlEditor instanceof HTMLTextAreaElement)) {
    return false;
  }
  const content = normalizeHelpTopicContent(htmlEditor.value);
  setHelpTopicVisualEditorContent(content);
  setHelpTopicSelectedImage(null);
  helpTopicEditorDirty = true;
  return true;
}

function setHelpTopicHtmlSourceMode(enabled, options = {}) {
  const nextMode = Boolean(enabled);
  const applySource = options.applySource !== false;
  const focus = options.focus === true;
  const editor = els.helpTopicContentEditor;
  const htmlEditor = els.helpTopicHtmlEditor;
  if (!(editor instanceof HTMLElement) || !(htmlEditor instanceof HTMLTextAreaElement)) {
    return;
  }
  if (nextMode === helpTopicHtmlSourceMode) {
    syncHelpTopicHtmlSourceUi();
    return;
  }
  if (nextMode) {
    htmlEditor.value = String(editor.dataset.helpWebDocument || editor.innerHTML).trim() || getHelpTopicHtmlStarterTemplate();
    helpTopicHtmlSourceMode = true;
  } else {
    if (applySource) {
      commitHelpTopicHtmlSource();
    }
    helpTopicHtmlSourceMode = false;
  }
  syncHelpTopicHtmlSourceUi();
  if (focus) {
    window.setTimeout(() => {
      (nextMode ? htmlEditor : editor).focus({ preventScroll: true });
    }, 0);
  }
}

function getHelpTopicHtmlStarterTemplate() {
  return `<section class="help-web-hero">
  <p class="help-web-eyebrow">SCHRITT 1</p>
  <h2 class="help-web-title">Deine Überschrift</h2>
  <p class="help-web-lead">Ein klarer Einstieg in dieses Hilfe-Thema.</p>
</section>

<div class="help-web-grid help-web-grid-2">
  <section class="help-web-card">
    <h3>Erster Punkt</h3>
    <p style="font-size: 18px">Diese Zeile kann eine eigene Schriftgröße erhalten.</p>
  </section>
  <section class="help-web-callout help-web-callout-info">
    <strong>Hinweis</strong>
    <p>Hier stehen wichtige Informationen.</p>
  </section>
</div>`;
}

function setHelpTopicVisualEditorContent(contentLike) {
  const editor = els.helpTopicContentEditor;
  if (!(editor instanceof HTMLElement)) {
    return;
  }
  const content = normalizeHelpTopicContent(contentLike);
  if (isHelpTopicWebDocument(content)) {
    editor.dataset.helpWebDocument = content;
    editor.contentEditable = "false";
    editor.innerHTML = getHelpTopicWebDocumentMarkup(content, { title: "Webseiten-Vorschau des Hilfe-Themas" });
    window.setTimeout(() => resizeHelpTopicWebDocumentFrames(editor), 0);
    return;
  }
  delete editor.dataset.helpWebDocument;
  editor.contentEditable = "true";
  editor.innerHTML = content;
  normalizeHelpTopicEditorStructure();
}

function getHelpTopicEditorContent() {
  const editor = els.helpTopicContentEditor;
  if (!(editor instanceof HTMLElement)) {
    return "";
  }
  return normalizeHelpTopicContent(editor.dataset.helpWebDocument || editor.innerHTML || "");
}

function toggleHelpTopicHtmlSourceMode() {
  setHelpTopicHtmlSourceMode(!helpTopicHtmlSourceMode, { applySource: true, focus: true });
}

function loadHelpTopicImage(dataUrl) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Bild konnte nicht verarbeitet werden."));
    image.src = dataUrl;
  });
}

async function createHelpTopicImageDataUrl(file) {
  if (!isHelpTopicImageFile(file)) {
    throw new Error("Bitte ein Bild im Format JPG, PNG oder WebP verwenden.");
  }
  if (file.size > HELP_TOPIC_IMAGE_MAX_UPLOAD_BYTES) {
    throw new Error("Bild ist zu groß. Bitte maximal 5 MB verwenden.");
  }
  const sourceDataUrl = await readFileAsDataUrl(file);
  const image = await loadHelpTopicImage(sourceDataUrl);
  const sourceWidth = Math.max(1, image.naturalWidth || image.width || 1);
  const sourceHeight = Math.max(1, image.naturalHeight || image.height || 1);
  const sourceMaxSide = Math.max(sourceWidth, sourceHeight);
  let scale = Math.min(1, HELP_TOPIC_IMAGE_MAX_DIMENSION / sourceMaxSide);
  let quality = HELP_TOPIC_IMAGE_OUTPUT_QUALITY;
  let dataUrl = "";

  for (let attempt = 0; attempt < 8; attempt += 1) {
    const width = Math.max(1, Math.round(sourceWidth * scale));
    const height = Math.max(1, Math.round(sourceHeight * scale));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext("2d");
    if (!context) {
      throw new Error("Bild konnte nicht verarbeitet werden.");
    }
    context.drawImage(image, 0, 0, width, height);
    dataUrl = canvas.toDataURL("image/webp", quality);
    if (!dataUrl.startsWith("data:image/webp")) {
      dataUrl = canvas.toDataURL("image/jpeg", quality);
    }
    if (dataUrl.length <= HELP_TOPIC_IMAGE_MAX_DATA_URL_LENGTH) {
      return dataUrl;
    }
    if (quality > 0.58) {
      quality = Math.max(0.58, quality - 0.08);
    } else {
      scale *= 0.82;
    }
  }

  throw new Error("Bild ist nach der Optimierung noch zu groß. Bitte ein kleineres Bild verwenden.");
}

function insertHelpTopicImageIntoListItem(image, listItem, range) {
  if (!(image instanceof HTMLImageElement) || !(listItem instanceof HTMLElement)) {
    return false;
  }

  const previousContentItem = getPreviousHelpTopicContentListItem(listItem);
  const shouldUsePreviousItem =
    Boolean(previousContentItem) &&
    (isHelpListGapElement(listItem) || isHelpListItemEmpty(listItem) || isHelpTopicRangeAtListItemStart(range, listItem));
  const targetItem = shouldUsePreviousItem ? previousContentItem : listItem;
  const caretItem = shouldUsePreviousItem && !isHelpListGapElement(listItem) && !isHelpListItemEmpty(listItem) ? listItem : null;

  if (!appendHelpTopicImageToListItem(targetItem, image)) {
    return false;
  }
  if (targetItem !== listItem && (isHelpListGapElement(listItem) || isHelpListItemEmpty(listItem))) {
    removeHelpTopicEmptyListItem(listItem);
  }
  normalizeHelpTopicEditorStructure();
  if (caretItem) {
    placeHelpTopicCaretInElement(caretItem);
  } else {
    placeHelpTopicCaretAfterNode(image);
  }
  syncHelpTopicImageControls();
  return true;
}

function insertHelpTopicImageIntoEditor(dataUrl, altText = "Hilfe-Bild") {
  const editor = els.helpTopicContentEditor;
  if (!(editor instanceof HTMLElement)) {
    return;
  }
  const image = document.createElement("img");
  image.src = dataUrl;
  image.alt = String(altText || "Hilfe-Bild").trim().slice(0, 120) || "Hilfe-Bild";
  image.setAttribute("data-help-image-size", "full");
  image.setAttribute("data-help-image-align", "center");
  image.loading = "lazy";
  image.decoding = "async";

  const imageBlock = document.createElement("p");
  imageBlock.appendChild(image);
  const nextBlock = document.createElement("p");
  nextBlock.appendChild(document.createElement("br"));
  const fragment = document.createDocumentFragment();
  fragment.appendChild(imageBlock);
  fragment.appendChild(nextBlock);

  editor.focus({ preventScroll: true });
  restoreHelpTopicEditorSelection();
  const selection = window.getSelection?.();
  const range =
    selection?.rangeCount && editor.contains(selection.getRangeAt(0).commonAncestorContainer)
      ? selection.getRangeAt(0)
      : null;
  const listItem = getHelpTopicEditorActiveListItem();
  if (listItem) {
    if (insertHelpTopicImageIntoListItem(image, listItem, range)) {
      setHelpTopicSelectedImage(image);
      return;
    }
  }
  if (range) {
    range.deleteContents();
    range.insertNode(fragment);
  } else {
    editor.appendChild(imageBlock);
    editor.appendChild(nextBlock);
  }

  const nextRange = document.createRange();
  nextRange.setStart(nextBlock, 0);
  nextRange.collapse(true);
  selection?.removeAllRanges();
  selection?.addRange(nextRange);
  helpTopicEditorSavedRange = nextRange.cloneRange();
  setHelpTopicSelectedImage(image);
}

async function insertHelpTopicImage(file) {
  if (!isRoleAdmin()) {
    return;
  }
  try {
    const dataUrl = await createHelpTopicImageDataUrl(file);
    const altText = String(file.name || "Hilfe-Bild").replace(/\.[^.]+$/, "").trim() || "Hilfe-Bild";
    if (helpTopicHtmlSourceMode) {
      insertHelpTopicImageIntoHtmlSource(dataUrl, altText);
      helpTopicEditorDirty = true;
      showSuccessFeedback("Bild-Code in das Hilfe-Thema eingefügt.");
      return;
    }
    insertHelpTopicImageIntoEditor(dataUrl, altText);
    helpTopicEditorDirty = true;
    showSuccessFeedback("Bild in Hilfe-Thema eingefügt.");
  } catch (error) {
    showWarningFeedback(error?.message || "Bild konnte nicht eingefügt werden.");
  }
}

function insertHelpTopicImageIntoHtmlSource(dataUrl, altText) {
  const htmlEditor = els.helpTopicHtmlEditor;
  if (!(htmlEditor instanceof HTMLTextAreaElement)) {
    return false;
  }
  const source = String(dataUrl || "").trim();
  if (!sanitizeHelpImageSrc(source)) {
    return false;
  }
  const imageMarkup = `<img src="${escapeHtml(source)}" alt="${escapeHtml(altText || "Hilfe-Bild")}" style="max-width: 100%; height: auto;" />`;
  const selectionStart = Number.isInteger(htmlEditor.selectionStart) ? htmlEditor.selectionStart : htmlEditor.value.length;
  const selectionEnd = Number.isInteger(htmlEditor.selectionEnd) ? htmlEditor.selectionEnd : selectionStart;
  htmlEditor.setRangeText(imageMarkup, selectionStart, selectionEnd, "end");
  htmlEditor.focus({ preventScroll: true });
  return true;
}

function executeHelpRichEditorCommand(commandLike) {
  const editor = els.helpTopicContentEditor;
  if (!(editor instanceof HTMLElement)) {
    return;
  }
  const command = String(commandLike || "").trim();
  if (!command) {
    return;
  }
  if (command === "toggleHtml") {
    toggleHelpTopicHtmlSourceMode();
    return;
  }
  if (command === "insertImage" && helpTopicHtmlSourceMode) {
    els.helpTopicImageUpload?.click();
    return;
  }
  if (helpTopicHtmlSourceMode) {
    showInfoFeedback("Bitte HTML zuerst mit „Übernehmen“ in die Vorschau übernehmen.");
    return;
  }
  if (command === "insertImage") {
    rememberHelpTopicEditorSelection();
    editor.focus({ preventScroll: true });
    els.helpTopicImageUpload?.click();
    return;
  }
  if (command.startsWith("textSize:")) {
    applyHelpTopicTextSize(command.split(":")[1]);
    return;
  }
  if (command === "insertListGap") {
    editor.focus({ preventScroll: true });
    restoreHelpTopicEditorSelection();
    const listItem = getHelpTopicEditorActiveListItem();
    if (!insertHelpTopicListGapAfterItem(listItem)) {
      showInfoFeedback("Leerzeilen können direkt innerhalb einer Liste eingefügt werden.");
    } else {
      helpTopicEditorDirty = true;
    }
    return;
  }
  editor.focus({ preventScroll: true });
  if (command === "createLink") {
    const rawUrl = window.prompt("Link-URL eingeben (https://...)", "");
    const url = sanitizeHelpHttpsUrl(rawUrl);
    if (rawUrl && !url) {
      showWarningFeedback("Bitte eine gueltige HTTPS-Link-URL verwenden.");
      return;
    }
    if (url) {
      document.execCommand("createLink", false, url);
      helpTopicEditorDirty = true;
    }
    return;
  }
  if (command.startsWith("formatBlock:")) {
    const block = command.split(":")[1];
    if (["h3", "p"].includes(block)) {
      document.execCommand("formatBlock", false, block);
      helpTopicEditorDirty = true;
    }
    return;
  }
  if (["bold", "italic", "underline", "insertUnorderedList", "insertOrderedList", "removeFormat"].includes(command)) {
    document.execCommand(command, false);
    normalizeHelpTopicEditorStructure();
    rememberHelpTopicEditorSelection();
    helpTopicEditorDirty = true;
  }
}

function saveHelpCenterConfiguration(helpCenter) {
  state.settings = normalizeSettings({
    ...state.settings,
    helpCenter,
  });
  saveState({ showFeedback: false });
  renderHelpCenterSection();
  if (isOnboardingModalOpen()) {
    renderOnboardingModal();
  }
}

async function handleHelpCenterSettingsSubmit(formElement) {
  if (!isRoleAdmin()) {
    return;
  }
  const formData = new FormData(formElement);
  const rawVideoUrl = String(formData.get("startVideoUrl") || "").trim();
  const normalizedVideoUrl = sanitizeHelpHttpsUrl(rawVideoUrl);
  if (rawVideoUrl && !normalizedVideoUrl) {
    showWarningFeedback("Bitte für das Startvideo eine gültige HTTPS-URL verwenden.");
    return;
  }
  let videoUrl = normalizedVideoUrl;
  if (normalizedVideoUrl) {
    try {
      videoUrl = await resolveHelpVideoUrl(normalizedVideoUrl);
    } catch (error) {
      showWarningFeedback(error?.message || "Der Vimeo-Link konnte nicht aufgeloest werden.");
      return;
    }
  }
  const rawPrivacyUrl = String(formData.get("privacyNoticeUrl") || "").trim();
  const privacyNoticeUrl = sanitizeHelpHttpsUrl(rawPrivacyUrl);
  if (rawPrivacyUrl && !privacyNoticeUrl) {
    showWarningFeedback("Bitte für den Datenschutzhinweis eine gültige HTTPS-URL verwenden.");
    return;
  }
  const current = getHelpCenterSettings();
  const renew = formData.get("renewStartVideo") === "on";
  saveHelpCenterConfiguration({
    ...current,
    startVideo: {
      title: String(formData.get("startVideoTitle") || "").trim() || "Willkommen bei MyWayControl",
      url: videoUrl,
      required: Boolean(videoUrl),
      version: renew ? current.startVideo.version + 1 : current.startVideo.version,
    },
    privacyNoticeUrl,
    supportEmail: String(formData.get("supportEmail") || "").trim(),
  });
  showSuccessFeedback("Hilfe-Einstellungen gespeichert.");
}

async function handleHelpTopicSubmit(formElement) {
  if (!isRoleAdmin()) {
    return;
  }
  commitHelpTopicHtmlSource();
  const formData = new FormData(formElement);
  const topicId = String(formData.get("topicId") || "").trim();
  const current = getHelpCenterSettings();
  const existing = current.topics.find((topic) => topic.id === topicId) || null;
  const roles = formData.getAll("roles");
  if (!roles.length) {
    showWarningFeedback("Bitte mindestens eine Rolle auswählen.");
    return;
  }
  const hasVideo = formData.get("hasVideo") === "on";
  const rawVideoUrl = hasVideo ? String(formData.get("videoUrl") || "").trim() : "";
  const normalizedVideoUrl = sanitizeHelpHttpsUrl(rawVideoUrl);
  if (hasVideo && !normalizedVideoUrl) {
    showWarningFeedback("Bitte für das Themenvideo eine gültige HTTPS-URL verwenden.");
    return;
  }
  let videoUrl = normalizedVideoUrl;
  if (normalizedVideoUrl) {
    try {
      videoUrl = await resolveHelpVideoUrl(normalizedVideoUrl);
    } catch (error) {
      showWarningFeedback(error?.message || "Der Vimeo-Link konnte nicht aufgeloest werden.");
      return;
    }
  }
  const content = getHelpTopicEditorContent();
  const topic = normalizeHelpTopic(
    {
      id: existing?.id || createId("help"),
      title: formData.get("title"),
      summary: formData.get("summary"),
      content,
      videoUrl,
      targetSection: formData.get("targetSection"),
      roles,
      countries: formData.get("countries"),
      status: formData.get("status"),
      required: formData.get("required") === "on",
      version:
        existing && formData.get("renewOnboarding") === "on" ? existing.version + 1 : existing?.version || 1,
      sortOrder: existing?.sortOrder || current.topics.length + 1,
    },
    current.topics.length
  );
  if (!topic) {
    showWarningFeedback("Bitte Titel, Kurzbeschreibung und Inhalt vollständig ausfüllen.");
    return;
  }
  const topics = existing
    ? current.topics.map((entry) => (entry.id === existing.id ? topic : entry))
    : current.topics.concat(topic);
  helpTopicEditingId = topic.id;
  helpTopicEditorDirty = false;
  setHelpTopicHtmlSourceMode(false, { applySource: false });
  saveHelpCenterConfiguration({ ...current, topics });
  showSuccessFeedback(existing ? "Hilfe-Thema aktualisiert." : "Hilfe-Thema veröffentlicht.");
}

function moveHelpTopic(topicId, direction) {
  if (!isRoleAdmin()) {
    return;
  }
  const current = getHelpCenterSettings();
  const topics = current.topics.slice();
  const index = topics.findIndex((topic) => topic.id === String(topicId || "").trim());
  const targetIndex = direction === "up" ? index - 1 : index + 1;
  if (index < 0 || targetIndex < 0 || targetIndex >= topics.length) {
    return;
  }
  const [topic] = topics.splice(index, 1);
  topics.splice(targetIndex, 0, topic);
  saveHelpCenterConfiguration({
    ...current,
    topics: topics.map((entry, topicIndex) => ({ ...entry, sortOrder: topicIndex + 1 })),
  });
}

async function archiveHelpTopic(topicId) {
  if (!isRoleAdmin()) {
    return;
  }
  const current = getHelpCenterSettings();
  const topic = current.topics.find((entry) => entry.id === String(topicId || "").trim());
  if (!topic || topic.status === "archived") {
    return;
  }
  if (!(await confirmAction(`Hilfe-Thema „${topic.title}“ archivieren?`, {
    title: "Thema archivieren",
    confirmLabel: "Archivieren",
  }))) {
    return;
  }
  if (helpTopicEditingId === topic.id) {
    helpTopicEditingId = "";
  }
  saveHelpCenterConfiguration({
    ...current,
    topics: current.topics.map((entry) => (entry.id === topic.id ? { ...entry, status: "archived" } : entry)),
  });
  showSuccessFeedback("Hilfe-Thema archiviert.");
}

async function deleteHelpTopic(topicId) {
  if (!isRoleAdmin()) {
    return;
  }
  const current = getHelpCenterSettings();
  const topic = current.topics.find((entry) => entry.id === String(topicId || "").trim());
  if (!topic) {
    return;
  }
  if (!(await confirmDeleteAction(`Hilfe-Thema „${topic.title}“ endgültig löschen?`))) {
    return;
  }
  if (helpTopicEditingId === topic.id) {
    helpTopicEditingId = "";
  }
  if (helpCenterSelectedTopicId === topic.id) {
    helpCenterSelectedTopicId = "";
  }
  if (onboardingSelectedItemId === topic.id) {
    onboardingSelectedItemId = "";
  }
  saveHelpCenterConfiguration({
    ...current,
    topics: current.topics
      .filter((entry) => entry.id !== topic.id)
      .map((entry, topicIndex) => ({ ...entry, sortOrder: topicIndex + 1 })),
  });
  showSuccessFeedback("Hilfe-Thema gelöscht.");
}

function isHelpImageZoomOpen() {
  return Boolean(els.helpImageZoomModal && !els.helpImageZoomModal.classList.contains("hidden"));
}

function openHelpImageZoom(image) {
  if (!els.helpImageZoomModal || !els.helpImageZoomImg || !(image instanceof HTMLImageElement)) {
    return;
  }
  const src = sanitizeHelpImageSrc(image.currentSrc || image.src || "");
  if (!src) {
    return;
  }
  const altText = String(image.alt || "Hilfe-Bild").trim();
  els.helpImageZoomImg.src = src;
  els.helpImageZoomImg.alt = altText || "Hilfe-Bild";
  if (els.helpImageZoomCaption) {
    els.helpImageZoomCaption.textContent = altText;
    els.helpImageZoomCaption.classList.toggle("hidden", !altText);
  }
  els.helpImageZoomModal.classList.remove("hidden");
  syncBodyModalOpenState();
  window.setTimeout(() => els.helpImageZoomClose?.focus({ preventScroll: true }), 0);
}

function closeHelpImageZoom() {
  if (!els.helpImageZoomModal) {
    return;
  }
  els.helpImageZoomModal.classList.add("hidden");
  if (els.helpImageZoomImg) {
    els.helpImageZoomImg.removeAttribute("src");
    els.helpImageZoomImg.alt = "";
  }
  syncBodyModalOpenState();
}

function isOnboardingModalOpen() {
  return Boolean(els.onboardingModal && !els.onboardingModal.classList.contains("hidden"));
}

function scheduleOnboardingPrompt() {
  if (onboardingPromptShownForSession) {
    return;
  }
  onboardingPromptShownForSession = true;
  window.setTimeout(() => {
    const currentUser = getCurrentUser();
    if (!currentUser || isRoleAdmin(currentUser)) {
      return;
    }
    if (automaticLoginPopupShownForSession) {
      return;
    }
    if (isOnboardingPromptHiddenForUser()) {
      return;
    }
    const summary = getOnboardingSummary();
    if (summary.total && !summary.complete) {
      automaticLoginPopupShownForSession = true;
      openOnboardingModal();
    }
  }, 320);
}

function openOnboardingModal() {
  if (!els.onboardingModal) {
    return;
  }
  const summary = getOnboardingSummary();
  if (!summary.total || summary.complete || isOnboardingPromptHiddenForUser()) {
    return;
  }
  const videoItems = summary.items.filter((item) => item.kind === "video");
  const topicItems = summary.items.filter((item) => item.kind === "topic");
  if (!videoItems.some((item) => item.id === onboardingSelectedVideoId)) {
    onboardingSelectedVideoId = videoItems[0]?.id || "";
  }
  if (!topicItems.some((item) => item.id === onboardingSelectedItemId)) {
    onboardingSelectedItemId = topicItems[0]?.id || "";
  }
  renderOnboardingModal();
  els.onboardingModal.classList.remove("hidden");
  syncBodyModalOpenState();
}

function closeOnboardingModal() {
  if (!els.onboardingModal) {
    return;
  }
  els.onboardingModal.classList.add("hidden");
  syncBodyModalOpenState();
  dailySalesProgressPromptDeferred = false;
}

function renderOnboardingModal() {
  if (!els.onboardingModal || !els.onboardingVideoArea || !els.onboardingVideoList || !els.onboardingTopicList || !els.onboardingTopicDetail) {
    return;
  }
  const summary = getOnboardingSummary();
  if (!summary.total) {
    if (isOnboardingModalOpen()) {
      closeOnboardingModal();
    }
    return;
  }
  const videoItems = summary.items.filter((item) => item.kind === "video");
  const topicItems = summary.items.filter((item) => item.kind === "topic");
  if (!videoItems.some((item) => item.id === onboardingSelectedVideoId)) {
    onboardingSelectedVideoId = videoItems[0]?.id || "";
  }
  if (!topicItems.some((item) => item.id === onboardingSelectedItemId)) {
    onboardingSelectedItemId = topicItems[0]?.id || "";
  }
  const progressPercent = summary.total ? Math.round((summary.completed / summary.total) * 100) : 0;
  if (els.onboardingModalProgress) {
    els.onboardingModalProgress.textContent = `${summary.completed} von ${summary.total} erledigt`;
  }
  if (els.onboardingProgressBar) {
    els.onboardingProgressBar.style.width = `${progressPercent}%`;
  }
  if (els.onboardingVideoArea) {
    const selectedVideo = getOnboardingVideos().find((video) => video.id === onboardingSelectedVideoId) || null;
    els.onboardingVideoArea.innerHTML = selectedVideo ? getOnboardingVideoMarkup(selectedVideo, "onboarding") : "";
  }
  els.onboardingVideoList.classList.toggle("hidden", videoItems.length < 2);
  els.onboardingVideoList.parentElement?.classList.toggle("is-single", videoItems.length < 2);
  els.onboardingVideoList.innerHTML = videoItems
    .map((item, index) => {
      const viewed = isOnboardingItemViewed(item);
      return `
        <button type="button" class="onboarding-video-choice ${item.id === onboardingSelectedVideoId ? "is-selected" : ""} ${
          viewed ? "is-viewed" : ""
        }" data-onboarding-video-id="${escapeHtml(item.id)}">
          <span class="onboarding-video-choice-index">${String(index + 1).padStart(2, "0")}</span>
          <span class="onboarding-video-choice-title">${escapeHtml(item.title)}</span>
        </button>
      `;
    })
    .join("");
  els.onboardingTopicList.innerHTML = topicItems
    .map((item) => {
      const viewed = isOnboardingItemViewed(item);
      return `
        <button type="button" class="onboarding-topic-row ${item.id === onboardingSelectedItemId ? "is-selected" : ""} ${
          viewed ? "is-viewed" : ""
        }" data-onboarding-item-id="${escapeHtml(item.id)}">
          <span class="onboarding-topic-row-title"><span>${escapeHtml(item.title)}</span><span class="help-topic-status-dot" aria-hidden="true"></span></span>
          <span class="onboarding-topic-row-summary">${escapeHtml(item.summary)}</span>
        </button>
      `;
    })
    .join("");
  const selected = topicItems.find((item) => item.id === onboardingSelectedItemId) || null;
  const selectedTopic = selected?.kind === "topic" ? getVisibleHelpTopics().find((topic) => topic.id === selected.id) : null;
  els.onboardingTopicDetail.innerHTML = summary.complete
    ? '<h4>Alles erledigt</h4><p>Die Einfuehrung ist abgeschlossen. Alle Inhalte bleiben jederzeit unter Hilfe &amp; Start erreichbar.</p>'
    : selectedTopic
    ? `<h4>${escapeHtml(selectedTopic.title)}</h4><div class="onboarding-topic-content">${formatHelpText(
        selectedTopic.content
      )}</div>${
        selectedTopic.videoUrl
          ? getHelpVideoMarkup({
              url: selectedTopic.videoUrl,
              title: selectedTopic.title,
              variant: "onboarding",
              onboardingItemId: selectedTopic.id,
              onboardingVersion: selectedTopic.version,
            })
          : ""
      }`
    : '<p class="onboarding-topic-detail-empty">Sieh dir die Videos an und oeffne anschliessend die Themen.</p>';
  if (els.onboardingCompleteBtn) {
    els.onboardingCompleteBtn.disabled = !summary.complete;
  }
}

function selectOnboardingVideo(videoId) {
  const video = getOnboardingVideos().find((entry) => entry.id === String(videoId || "").trim());
  if (!video) {
    return;
  }
  onboardingSelectedVideoId = video.id;
  renderOnboardingModal();
}

function selectOnboardingItem(itemId) {
  const item = getRequiredOnboardingItems().find((entry) => entry.id === String(itemId || "").trim());
  if (!item) {
    return;
  }
  onboardingSelectedItemId = item.id;
  saveOnboardingItemViewed(item.id, item.version);
  if (item.kind === "topic") {
    helpCenterSelectedTopicId = item.id;
  }
  renderOnboardingModal();
  renderHelpCenterSection();
}

function syncHelpProgressIndicators() {
  const currentUser = getCurrentUser();
  const helpProgress = getHelpProgressSummary(currentUser);
  if (els.helpCenterProgress) {
    els.helpCenterProgress.textContent = helpProgress.total
      ? `${helpProgress.completed} von ${helpProgress.total} Hilfeinhalten angesehen`
      : "Keine Hilfeinhalte";
  }
  els.helpCenterStartContent?.querySelectorAll("[data-help-start-progress-value]").forEach((progressValue) => {
    progressValue.textContent = `${helpProgress.completed} / ${helpProgress.total}`;
  });
  const helpProgressPercent = helpProgress.total ? Math.round((helpProgress.completed / helpProgress.total) * 100) : 0;
  els.helpCenterStartContent?.querySelectorAll("[data-help-start-progress-percent]").forEach((progressValue) => {
    progressValue.textContent = `${helpProgressPercent}%`;
  });
  els.helpCenterStartContent?.querySelectorAll("[data-help-start-progress-bar]").forEach((progressBar) => {
    progressBar.style.width = `${helpProgressPercent}%`;
  });

  els.helpTopicList?.querySelectorAll("button[data-help-topic-id]").forEach((button) => {
    const topic = getVisibleHelpTopics(currentUser).find((entry) => entry.id === button.dataset.helpTopicId);
    button.classList.toggle("is-viewed", Boolean(topic && isOnboardingItemViewed(topic)));
  });

  if (!isOnboardingModalOpen()) {
    return;
  }
  const onboardingSummary = getOnboardingSummary(currentUser);
  const progressPercent = onboardingSummary.total
    ? Math.round((onboardingSummary.completed / onboardingSummary.total) * 100)
    : 0;
  if (els.onboardingModalProgress) {
    els.onboardingModalProgress.textContent = `${onboardingSummary.completed} von ${onboardingSummary.total} erledigt`;
  }
  if (els.onboardingProgressBar) {
    els.onboardingProgressBar.style.width = `${progressPercent}%`;
  }
  els.onboardingVideoList?.querySelectorAll("button[data-onboarding-video-id]").forEach((button) => {
    const item = onboardingSummary.items.find((entry) => entry.id === button.dataset.onboardingVideoId);
    button.classList.toggle("is-viewed", Boolean(item && isOnboardingItemViewed(item)));
  });
  els.onboardingTopicList?.querySelectorAll("button[data-onboarding-item-id]").forEach((button) => {
    const item = onboardingSummary.items.find((entry) => entry.id === button.dataset.onboardingItemId);
    button.classList.toggle("is-viewed", Boolean(item && isOnboardingItemViewed(item)));
  });
  if (els.onboardingCompleteBtn) {
    els.onboardingCompleteBtn.disabled = !onboardingSummary.complete;
  }
}

function handleHelpVideoViewed(mediaElement, options = {}) {
  if (!(mediaElement instanceof HTMLElement)) {
    return false;
  }
  const itemId = String(mediaElement.dataset.helpVideoItemId || "").trim();
  if (!itemId) {
    return false;
  }
  const progressItem = getHelpProgressItems().find((item) => item.id === itemId);
  if (!progressItem) {
    return false;
  }
  const version = normalizeHelpVersion(mediaElement.dataset.helpVideoVersion || progressItem.version);
  const changed = saveOnboardingItemViewed(itemId, version);
  void recordContentReadReceipt("help_video", itemId, version);
  if (!changed) {
    return false;
  }
  if (options?.renderOnChange) {
    renderHelpCenterSection();
    if (isOnboardingModalOpen()) {
      renderOnboardingModal();
    }
  } else {
    syncHelpProgressIndicators();
  }
  return true;
}

function initializeHelpExternalVideoTracking(iframe) {
  const provider = String(iframe.dataset.helpVideoProvider || "").trim().toLowerCase();
  const itemId = String(iframe.dataset.helpVideoItemId || "").trim();
  if (!provider || !itemId || !iframe.contentWindow) {
    return;
  }
  handleHelpVideoViewed(iframe, { renderOnChange: false });
  try {
    const origin = new URL(iframe.src).origin;
    if (provider === "youtube") {
      iframe.contentWindow.postMessage(JSON.stringify({ event: "listening", id: Date.now() }), origin);
      iframe.contentWindow.postMessage(
        JSON.stringify({ event: "command", func: "addEventListener", args: "onStateChange" }),
        origin
      );
    } else if (provider === "vimeo") {
      iframe.contentWindow.postMessage({ method: "addEventListener", value: "finish" }, origin);
    }
  } catch (_error) {
    // The regular iframe player remains usable even when completion tracking is unavailable.
  }
}

function handleHelpExternalVideoMessage(event) {
  const matchingFrame = Array.from(document.querySelectorAll("iframe[data-help-video-item-id]")).find(
    (iframe) => iframe.contentWindow === event.source
  );
  if (!(matchingFrame instanceof HTMLIFrameElement)) {
    return;
  }
  let expectedOrigin = "";
  try {
    expectedOrigin = new URL(matchingFrame.src).origin;
  } catch (_error) {
    return;
  }
  if (event.origin !== expectedOrigin) {
    return;
  }
  const provider = String(matchingFrame.dataset.helpVideoProvider || "").trim().toLowerCase();
  let payload = event.data;
  if (typeof payload === "string") {
    try {
      payload = JSON.parse(payload);
    } catch (_error) {
      return;
    }
  }
  const isYoutubeComplete = provider === "youtube" && payload?.event === "onStateChange" && Number(payload?.info) === 0;
  const isVimeoComplete = provider === "vimeo" && payload?.event === "finish";
  if (isYoutubeComplete || isVimeoComplete) {
    handleHelpVideoViewed(matchingFrame, { renderOnChange: true });
  }
}

function completeOnboarding() {
  const summary = getOnboardingSummary();
  if (!summary.complete) {
    return;
  }
  closeOnboardingModal();
  showSuccessFeedback("Onboarding abgeschlossen. Die Inhalte bleiben unter Hilfe & Start verfügbar.");
}

