function markDeleteActionButton(button) {
  if (!button) {
    return;
  }
  button.classList.add("danger");
  if (button.classList.contains("btn")) {
    button.classList.add("btn-danger");
  }
  if (button.classList.contains("table-btn")) {
    button.classList.add("danger");
  }
}

function renderManagementSection() {
  ensureManagementSelection();
  renderManagementSummary();
  renderCategoryCsvExportControls();
  renderCategoryList();
  renderSubcategoriesList();
  renderTopicsList();
  applyActionButtonIcons();
}

function iconifyDetailActionButton(button, role) {
  if (!button || !role) {
    return;
  }
  const currentLabel = String(button.dataset.iconLabel || button.textContent || "").trim();
  const fallbackLabel = role === "delete" ? "Löschen" : "Speichern";
  const label = currentLabel || fallbackLabel;
  button.dataset.iconLabel = label;
  button.dataset.iconRole = role;
  button.setAttribute("title", label);
  button.setAttribute("aria-label", label);
  button.classList.add("btn-icon-compact");
  if (role === "delete") {
    markDeleteActionButton(button);
    button.textContent = "✕";
    return;
  }
  button.classList.remove("btn-success");
  if (!button.classList.contains("btn-danger")) {
    button.classList.add("btn-primary");
  }
  button.textContent = "✓";
}

function applyActionButtonIcons() {
  const keepTextDeleteIds = new Set(["delete-confirm-yes"]);
  const detailSaveIconIds = new Set([
    "user-save-btn",
    "conversation-meta-save-btn",
    "company-save-btn",
    "tour-detail-save-btn",
    "sales-phone-detail-save-btn",
  ]);
  const detailDeleteIconIds = new Set([
    "conversation-delete-btn",
    "tour-delete-btn",
    "sales-phone-delete-btn",
  ]);
  document.querySelectorAll("button").forEach((button) => {
    if (button.dataset.noIconify === "true") {
      return;
    }
    const buttonId = String(button.id || "").trim();
    if (detailSaveIconIds.has(buttonId)) {
      iconifyDetailActionButton(button, "save");
      return;
    }
    if (detailDeleteIconIds.has(buttonId)) {
      iconifyDetailActionButton(button, "delete");
      return;
    }
    if (button.closest("#conversation-notes-section")) {
      return;
    }
    const text = String(button.textContent || button.dataset.iconLabel || "").trim();
    if (!text) {
      return;
    }
    const normalizedText = normalizeText(text);
    const isDeleteLabel = normalizedText.includes("losch");
    const isEditLabel = normalizedText.includes("bearbeit");
    const hasDeleteDataAttr = button
      .getAttributeNames()
      .some((name) => name.startsWith("data-") && (name.includes("delete") || name.includes("remove")));

    if (isDeleteLabel || hasDeleteDataAttr) {
      markDeleteActionButton(button);
    }

    if (isDeleteLabel && !keepTextDeleteIds.has(buttonId)) {
      if (!button.getAttribute("title")) {
        button.setAttribute("title", text);
      }
      if (!button.getAttribute("aria-label")) {
        button.setAttribute("aria-label", text);
      }
      button.textContent = "✕";
      return;
    }

    if (isEditLabel) {
      if (!button.getAttribute("title")) {
        button.setAttribute("title", text);
      }
      if (!button.getAttribute("aria-label")) {
        button.setAttribute("aria-label", text);
      }
      button.textContent = "✎";
    }
  });
}

function renderUserSwitch() {
  const activeUser = getCurrentUser();
  if (!activeUser) {
    els.currentUserLabel.textContent = "Nicht angemeldet";
    return;
  }

  els.currentUserLabel.textContent = String(activeUser.name || "Benutzer").trim();
}

function isAllowedSalesNavigationTarget(targetId, roleLike = getCurrentUser()?.role || authProfile?.role || "") {
  const allSalesTargets = [
    "dashboard-section",
    "help-center-section",
    "my-account-section",
    "providers-section",
    "provider-coverage-section",
    "sales-dashboard-section",
    "sales-provision-section",
    "tour-planner-section",
    "sales-leads-section",
    "partner-requests-section",
    "sales-phone-section",
  ];
  // Vertriebsmitarbeiter arbeiten ausschließlich im Vertriebs-Dashboard,
  // bei Anbietern, Leads und Formularen. Die Planungsseiten bleiben für die
  // übrigen Rollen verfügbar, sind für Vertrieb aber weder per Menü noch
  // per internem Direktaufruf erreichbar.
  const salesRepresentativeTargets = allSalesTargets.filter(
    (sectionId) => sectionId !== "sales-phone-section" && sectionId !== "tour-planner-section"
  );
  const allowedTargets =
    normalizeUserRole(roleLike) === ROLE_VERTRIEBSMITARBEITER ? salesRepresentativeTargets : allSalesTargets;
  return allowedTargets.includes(String(targetId || "").trim());
}

function isAllowedSalesNavigationButton(button, roleLike = getCurrentUser()?.role || authProfile?.role || "") {
  if (!button) {
    return false;
  }
  const targetId = String(button.dataset.target || "").trim();
  const inSalesSubmenu = Boolean(button.closest("#sales-nav-submenu"));
  if (inSalesSubmenu && targetId === "sales-dashboard-section") {
    return false;
  }
  const navToggle = String(button.dataset.navToggle || "").trim();
  if (navToggle === "sales-submenu") {
    return true;
  }
  return isAllowedSalesNavigationTarget(targetId, roleLike);
}

function updateSidebarNavigationVisibilityForRole(user = getCurrentUser()) {
  const normalizedRole = normalizeUserRole(user?.role || "");
  const roleAdmin = isRoleAdmin(user);
  const roleSuperAdmin = isSuperAdmin(user);
  const salesRepresentative = isSalesRepresentative(user);
  const hasUser = Boolean(user);
  const useFlatSalesNavigation = shouldUseFlatSalesNavigation(normalizedRole);

  const navTargetButtons = Array.from(document.querySelectorAll(".sidebar .nav-btn[data-target]"));
  const navButtonsByTarget = new Map();
  navTargetButtons.forEach((button) => {
    const targetId = String(button.dataset.target || "").trim();
    if (targetId) {
      navButtonsByTarget.set(targetId, button);
    }
  });

  const isRoleClassAllowed = (button) => {
    if (button.classList.contains("superadmin-only")) {
      return roleSuperAdmin;
    }
    if (button.classList.contains("role-admin-only") || button.classList.contains("admin-only")) {
      return roleAdmin;
    }
    if (button.classList.contains("non-admin-only")) {
      return !roleAdmin;
    }
    return true;
  };

  navTargetButtons.forEach((button) => {
    const targetId = String(button.dataset.target || "").trim();
    const roleAccessible = hasUser && resolveAccessibleSectionForRole(targetId, normalizedRole) === targetId;
    const salesAccessible = !salesRepresentative || isAllowedSalesNavigationButton(button, normalizedRole);
    const visible = hasUser && roleAccessible && salesAccessible && isRoleClassAllowed(button);
    button.classList.toggle("hidden", !visible);
  });

  const navParentButtons = Array.from(document.querySelectorAll(".sidebar .nav-parent-btn[data-child-targets]"));
  navParentButtons.forEach((button) => {
    const navToggle = String(button.dataset.navToggle || "").trim();
    const isSalesParent = navToggle === "sales-submenu";
    const childTargets = String(button.dataset.childTargets || "")
      .split(",")
      .map((entry) => entry.trim())
      .filter(Boolean);
    const hasVisibleChild = childTargets.some((targetId) => {
      const childButton = navButtonsByTarget.get(targetId);
      return Boolean(childButton && !childButton.classList.contains("hidden"));
    });
    const forcedFlatSubmenuVisible = isSalesParent && useFlatSalesNavigation && hasUser && hasVisibleChild;
    const parentVisible = !forcedFlatSubmenuVisible && hasUser && hasVisibleChild && isRoleClassAllowed(button);
    button.classList.toggle("hidden", !parentVisible);
    const submenuId = String(button.getAttribute("aria-controls") || "").trim();
    const submenu = submenuId ? document.getElementById(submenuId) : null;
    submenu?.classList.toggle("nav-submenu-flat", forcedFlatSubmenuVisible);
    if (forcedFlatSubmenuVisible) {
      button.setAttribute("aria-expanded", "true");
      submenu?.classList.remove("hidden");
      return;
    }
    if (!parentVisible) {
      button.setAttribute("aria-expanded", "false");
      submenu?.classList.add("hidden");
    }
  });

  document.querySelectorAll(".sidebar .nav-group").forEach((group) => {
    const visibleButton = group.querySelector(".nav-btn:not(.hidden)");
    group.classList.toggle("hidden", !visibleButton);
  });
}

function resolveAccessibleSectionForRole(targetId, roleLike) {
  let sectionId = String(targetId || "").trim();
  const normalizedRole = normalizeUserRole(roleLike);
  const fallbackSectionId = getDefaultSectionForRole(normalizedRole);
  if (sectionId === "org-chart-section") {
    sectionId = "departments-section";
  }
  const targetPanelExists = Array.from(els.panels || []).some((panel) => panel.id === sectionId);
  if (!targetPanelExists) {
    sectionId = fallbackSectionId;
  }
  const roleAdmin = isPrivilegedRole(normalizedRole);
  const roleSuperAdmin = normalizedRole === ROLE_SUPERADMIN;
  const roleSales = normalizedRole === ROLE_VERTRIEBSMITARBEITER;

  if (sectionId === "dashboard-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if ((sectionId === "parameters-section" || sectionId === "management-section") && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "companies-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "incoming-invoices-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "incoming-offers-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "contract-manager-section" && !roleSuperAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "provider-coverage-section" && !roleSuperAdmin && !roleSales) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "ceo-secretary-section" && !roleSuperAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "users-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "inventory-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "employee-admin-section" && !roleSuperAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "departments-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "conversation-notes-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "team-meeting-protocol-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "roles-rights-section" && !roleAdmin) {
    sectionId = fallbackSectionId;
  }
  if (sectionId === "partner-requests-section" && !getCurrentUser()) {
    sectionId = fallbackSectionId;
  }
  if (roleSales && !isAllowedSalesNavigationTarget(sectionId, normalizedRole)) {
    sectionId = "sales-dashboard-section";
  }
  return sectionId;
}

function getRolesRightsCandidateSectionIds() {
  const existingSectionIds = new Set(Array.from(els.panels || []).map((panel) => String(panel.id || "").trim()).filter(Boolean));
  const sectionIds = [];
  const seen = new Set();

  Array.from(document.querySelectorAll(".nav-btn[data-target]")).forEach((button) => {
    const targetId = String(button.dataset.target || "").trim();
    if (!targetId || seen.has(targetId) || !existingSectionIds.has(targetId)) {
      return;
    }
    seen.add(targetId);
    sectionIds.push(targetId);
  });

  Array.from(els.panels || []).forEach((panel) => {
    const sectionId = String(panel.id || "").trim();
    if (!sectionId || seen.has(sectionId)) {
      return;
    }
    seen.add(sectionId);
    sectionIds.push(sectionId);
  });

  return sectionIds;
}

function getRolesRightsSectionLabel(sectionId) {
  const panel = document.getElementById(sectionId);
  const heading = panel?.querySelector("h2");
  if (heading) {
    return String(heading.textContent || "").trim();
  }
  const navButton = document.querySelector(`.nav-btn[data-target="${sectionId}"]`);
  if (navButton) {
    return String(navButton.textContent || "").trim();
  }
  return sectionId;
}

function describeRolesRightsPattern(allowedByRole) {
  const mitarbeiter = Boolean(allowedByRole[ROLE_MITARBEITER]);
  const vertrieb = Boolean(allowedByRole[ROLE_VERTRIEBSMITARBEITER]);
  const admin = Boolean(allowedByRole[ROLE_ADMIN]);
  const superadmin = Boolean(allowedByRole[ROLE_SUPERADMIN]);

  if (mitarbeiter && vertrieb && admin && superadmin) {
    return "Alle Rollen";
  }
  if (!mitarbeiter && !vertrieb && admin && superadmin) {
    return "Nur Admin/Superadmin";
  }
  if (!mitarbeiter && !vertrieb && !admin && superadmin) {
    return "Nur Superadmin";
  }
  if (mitarbeiter && !vertrieb && admin && superadmin) {
    return "Alle außer Vertrieb";
  }
  return "Spezialregel";
}

function getRolesRightsRuleSource(sectionId, panel, allowedByRole) {
  const sources = [];
  if (panel?.classList?.contains("superadmin-only-view")) {
    sources.push("UI: superadmin-only-view");
  } else if (panel?.classList?.contains("role-admin-only-view")) {
    sources.push("UI: role-admin-only-view");
  } else if (panel?.classList?.contains("admin-only-view")) {
    sources.push("UI: admin-only-view");
  }
  if (sectionId === "roles-rights-section") {
    sources.push("Logik: resolveAccessibleSectionForRole");
  }
  if (!sources.length) {
    sources.push(`Logik: ${describeRolesRightsPattern(allowedByRole)}`);
  }
  return sources.join(" + ");
}

function formatRolesRightsTimestamp(date = new Date()) {
  try {
    return new Intl.DateTimeFormat("de-AT", {
      dateStyle: "medium",
      timeStyle: "medium",
    }).format(date);
  } catch (_error) {
    return new Date(date).toLocaleString();
  }
}

function hasRolesRightsDifferences(allowedByRole) {
  const values = ROLES_RIGHTS_MATRIX_ROLES.map((entry) => Boolean(allowedByRole[entry.id]));
  if (!values.length) {
    return false;
  }
  return values.some((value) => value !== values[0]);
}

function renderRolesRightsSection() {
  if (!els.rolesRightsBody || !els.rolesRightsMeta || !els.rolesRightsEmpty) {
    return;
  }
  if (els.rolesRightsDiffOnly) {
    els.rolesRightsDiffOnly.checked = rolesRightsShowDifferencesOnly;
  }

  const sectionIds = getRolesRightsCandidateSectionIds();
  if (!sectionIds.length) {
    els.rolesRightsBody.innerHTML = "";
    els.rolesRightsEmpty.textContent = "Keine Bereiche gefunden.";
    els.rolesRightsEmpty.classList.remove("hidden");
    els.rolesRightsMeta.textContent = "Keine Daten vorhanden.";
    return;
  }

  const rows = sectionIds
    .map((sectionId) => {
      const panel = document.getElementById(sectionId);
      const allowedByRole = {};
      ROLES_RIGHTS_MATRIX_ROLES.forEach((entry) => {
        allowedByRole[entry.id] = resolveAccessibleSectionForRole(sectionId, entry.id) === sectionId;
      });
      const area = getRolesRightsSectionLabel(sectionId);
      const ruleSource = getRolesRightsRuleSource(sectionId, panel, allowedByRole);
      return {
        sectionId,
        area,
        ruleSource,
        allowedByRole,
        hasDifferences: hasRolesRightsDifferences(allowedByRole),
      };
    })
    .sort((left, right) => left.area.localeCompare(right.area, "de"));

  const visibleRows = rolesRightsShowDifferencesOnly ? rows.filter((row) => row.hasDifferences) : rows;

  if (!visibleRows.length) {
    els.rolesRightsBody.innerHTML = "";
    els.rolesRightsEmpty.textContent = rolesRightsShowDifferencesOnly
      ? "Keine Unterschiede zwischen Rollen gefunden."
      : "Keine Bereiche gefunden.";
    els.rolesRightsEmpty.classList.remove("hidden");
    els.rolesRightsMeta.textContent = `${rows.length} Bereiche · Filter aktiv: nur Unterschiede`;
    return;
  }

  els.rolesRightsBody.innerHTML = visibleRows
    .map((row) => {
      const cells = ROLES_RIGHTS_MATRIX_ROLES.map((roleEntry) => {
        const allowed = Boolean(row.allowedByRole[roleEntry.id]);
        const cellClass = allowed ? "is-allowed" : "is-denied";
        const label = allowed ? "✓" : "✕";
        return `
          <td class="roles-rights-cell ${cellClass}" title="${escapeHtml(roleEntry.label)}">
            <span class="roles-rights-badge ${cellClass}">${label}</span>
          </td>
        `;
      }).join("");
      return `
        <tr>
          <td class="roles-rights-area">${escapeHtml(row.area)}</td>
          <td><code>${escapeHtml(row.sectionId)}</code></td>
          <td>${escapeHtml(row.ruleSource)}</td>
          ${cells}
        </tr>
      `;
    })
    .join("");

  els.rolesRightsEmpty.classList.add("hidden");
  const filterInfo = rolesRightsShowDifferencesOnly
    ? ` · angezeigt: ${visibleRows.length}/${rows.length} (nur Unterschiede)`
    : "";
  els.rolesRightsMeta.textContent =
    `${rows.length} Bereiche${filterInfo} · zuletzt aktualisiert: ${formatRolesRightsTimestamp(new Date())}`;
}

function queueRolesRightsRender() {
  if (rolesRightsRenderQueued) {
    return;
  }
  rolesRightsRenderQueued = true;
  window.requestAnimationFrame(() => {
    rolesRightsRenderQueued = false;
    renderRolesRightsSection();
  });
}

function setupRolesRightsAutoRefresh() {
  if (rolesRightsObserver || typeof MutationObserver !== "function") {
    return;
  }
  const observerRoot = document.body;
  if (!observerRoot) {
    return;
  }
  rolesRightsObserver = new MutationObserver((mutations) => {
    const rolesRightsSection = document.getElementById("roles-rights-section");
    const changedOutsideRolesRights = mutations.some((mutation) => {
      const targetNode = mutation.target;
      if (rolesRightsSection && targetNode instanceof Node && rolesRightsSection.contains(targetNode)) {
        return false;
      }
      return mutation.type === "childList" || mutation.type === "attributes";
    });
    if (changedOutsideRolesRights) {
      queueRolesRightsRender();
    }
  });
  rolesRightsObserver.observe(observerRoot, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ["class", "id", "data-target"],
  });
}

