function getFilteredMarketingCampaigns() {
  return marketingData.campaigns
    .slice()
    .sort((left, right) => String(right.startDate || "").localeCompare(String(left.startDate || "")))
    .filter((entry) => {
      const searchTerm = normalizeText(marketingUiState.campaigns.search || "");
      const statusFilter = String(marketingUiState.campaigns.status || "all");
      if (statusFilter !== "all" && entry.status !== statusFilter) {
        return false;
      }
      if (!searchTerm) {
        return true;
      }
      return normalizeText(`${entry.name} ${entry.goal}`).includes(searchTerm);
    });
}

function buildMarketingCampaignStatusSelect(campaignEntry) {
  const status = String(campaignEntry?.status || "draft").trim().toLowerCase();
  const options = [
    { value: "draft", label: "Entwurf" },
    { value: "in_review", label: "In Review" },
    { value: "approved", label: "Freigegeben" },
    { value: "scheduled", label: "Geplant" },
    { value: "published", label: "Veröffentlicht" },
    { value: "rejected", label: "Abgelehnt" },
  ];
  return `<select class="marketing-inline-select" data-marketing-campaign-inline-field="status" data-id="${escapeHtml(
    campaignEntry.id
  )}">${options
    .map(
      (option) =>
        `<option value="${escapeHtml(option.value)}" ${option.value === status ? "selected" : ""}>${escapeHtml(option.label)}</option>`
    )
    .join("")}</select>`;
}

function renderMarketingCampaignsBoard(filteredRows, channelsByCampaign, latestActivityByCampaignId) {
  if (!els.marketingCampaignBoardGrid) {
    return;
  }
  const columns = [
    { key: "draft", label: "Entwurf" },
    { key: "in_review", label: "In Review" },
    { key: "approved", label: "Freigegeben" },
    { key: "scheduled", label: "Geplant" },
    { key: "published", label: "Veröffentlicht" },
    { key: "rejected", label: "Abgelehnt" },
  ];

  els.marketingCampaignBoardGrid.innerHTML = columns
    .map((column) => {
      const rows = filteredRows.filter((entry) => entry.status === column.key);
      const cardsHtml = rows
        .map((entry) => {
          const channels = Array.from(new Set(channelsByCampaign.get(entry.id) || []))
            .filter(Boolean)
            .join(", ");
          const latestActivity = latestActivityByCampaignId.get(entry.id) || null;
          const updatedStamp = `${formatDateTime(latestActivity?.createdAt || entry.updatedAt || entry.createdAt)} · ${getMarketingActivityActorName(
            latestActivity
          )}`;
          return `
            <article class="marketing-entity-card" draggable="true" data-marketing-campaign-card-id="${escapeHtml(entry.id)}">
              <header class="marketing-entity-card-head">
                <strong>${escapeHtml(entry.name || "Ohne Namen")}</strong>
                ${buildMarketingStatusBadge(entry.status)}
              </header>
              <p class="marketing-entity-card-meta">${escapeHtml(entry.goal || "Kein Ziel gesetzt")}</p>
              <div class="marketing-task-card-chips">
                <span class="marketing-task-chip">${escapeHtml(
                  new Intl.NumberFormat("de-AT", { style: "currency", currency: "EUR" }).format(entry.budget || 0)
                )}</span>
                <span class="marketing-task-chip">${escapeHtml(formatMarketingDate(entry.startDate))} – ${escapeHtml(
                  formatMarketingDate(entry.endDate)
                )}</span>
                <span class="marketing-task-chip">${escapeHtml(channels || "Kein Kanal")}</span>
              </div>
              <p class="marketing-entity-updated">Zuletzt: ${escapeHtml(updatedStamp)}</p>
              <div class="marketing-task-card-actions">
                <button type="button" class="table-btn" data-marketing-campaign-action="edit" data-id="${escapeHtml(entry.id)}">Bearbeiten</button>
              </div>
            </article>
          `;
        })
        .join("");
      return `
        <section class="marketing-entity-column" data-marketing-campaign-drop-status="${escapeHtml(column.key)}">
          <header class="marketing-entity-column-head">
            <h3>${escapeHtml(column.label)}</h3>
            <span>${escapeHtml(String(rows.length))}</span>
          </header>
          <div class="marketing-entity-column-body" data-marketing-campaign-drop-status="${escapeHtml(column.key)}">
            ${cardsHtml || '<p class="marketing-task-column-empty">Keine Kampagnen</p>'}
          </div>
        </section>
      `;
    })
    .join("");
}

function renderMarketingCampaignsTable() {
  if (!els.marketingCampaignsTableBody) {
    return;
  }
  const channelsByCampaign = new Map();
  marketingData.campaignChannels.forEach((entry) => {
    const campaignId = String(entry.campaignId || "");
    if (!campaignId) {
      return;
    }
    if (!channelsByCampaign.has(campaignId)) {
      channelsByCampaign.set(campaignId, []);
    }
    channelsByCampaign.get(campaignId).push(formatMarketingChannelLabel(entry.channel));
  });

  const filteredRows = getFilteredMarketingCampaigns();
  const latestActivityByCampaignId = getLatestMarketingActivityMapByEntityType("campaign");
  const campaignView = normalizeMarketingCampaignView(marketingUiState.campaigns.view);
  const pageMeta = paginateRows(filteredRows, "campaigns");

  if (els.marketingCampaignTableWrap) {
    els.marketingCampaignTableWrap.classList.toggle("hidden", campaignView !== "table");
  }
  if (els.marketingCampaignBoardWrap) {
    els.marketingCampaignBoardWrap.classList.toggle("hidden", campaignView !== "board");
  }
  if (els.marketingCampaignsPagination) {
    els.marketingCampaignsPagination.classList.toggle("hidden", campaignView !== "table");
  }

  els.marketingCampaignsTableBody.innerHTML = pageMeta.pageRows
    .map((entry) => {
      const channels = Array.from(new Set(channelsByCampaign.get(entry.id) || []))
        .filter(Boolean)
        .join(", ");
      const approval = getLatestApprovalByEntity("campaign", entry.id);
      const latestActivity = latestActivityByCampaignId.get(entry.id) || null;
      const updatedStamp = `${formatDateTime(latestActivity?.createdAt || entry.updatedAt || entry.createdAt)} · ${getMarketingActivityActorName(
        latestActivity
      )}`;
      return `
        <tr>
          <td data-label="Name">
            <div class="marketing-cell-main">
              <strong>${escapeHtml(entry.name || "–")}</strong>
              <small>${escapeHtml(updatedStamp)}</small>
            </div>
          </td>
          <td data-label="Ziel">${escapeHtml(entry.goal || "–")}</td>
          <td data-label="Budget">${escapeHtml(new Intl.NumberFormat("de-AT", { style: "currency", currency: "EUR" }).format(entry.budget || 0))}</td>
          <td data-label="Zeitraum">${escapeHtml(formatMarketingDate(entry.startDate))} – ${escapeHtml(formatMarketingDate(entry.endDate))}</td>
          <td data-label="Status">${buildMarketingCampaignStatusSelect(entry)}</td>
          <td data-label="Kanal">${escapeHtml(channels || "–")}</td>
          <td data-label="Aktion">
            <div class="table-icon-actions">
              <button type="button" class="table-btn" data-marketing-campaign-action="edit" data-id="${escapeHtml(
                entry.id
              )}">Bearbeiten</button>
              <button type="button" class="table-btn" data-marketing-campaign-action="review" data-id="${escapeHtml(
                entry.id
              )}">${approval ? "Review erneut" : "Review"}</button>
              <button type="button" class="table-btn danger" data-marketing-campaign-action="delete" data-id="${escapeHtml(
                entry.id
              )}">Löschen</button>
            </div>
          </td>
        </tr>
      `;
    })
    .join("");
  renderMarketingCampaignsBoard(filteredRows, channelsByCampaign, latestActivityByCampaignId);
  renderMarketingPagination(els.marketingCampaignsPagination, "campaigns", pageMeta);
  if (els.marketingCampaignsEmpty) {
    els.marketingCampaignsEmpty.classList.toggle("hidden", filteredRows.length > 0);
    els.marketingCampaignsEmpty.textContent = getMarketingEmptyMessage(MARKETING_COPY.emptyCampaigns);
  }
}

