async function handleMarketingAssetCreate(event) {
  if (!canAccessMarketingModule()) {
    return;
  }
  const client = getSupabaseClient();
  if (!client || !getAuthUid()) {
    showMarketingError("Supabase Verbindung fehlt.");
    return;
  }

  const formData = new FormData(event.currentTarget);
  const campaignId = String(formData.get("campaignId") || "").trim();
  const contentItemId = String(formData.get("contentItemId") || "").trim();
  const fileNameRaw = String(formData.get("fileName") || "").trim();
  const storageBucket = String(formData.get("storageBucket") || "").trim();
  const storagePathRaw = String(formData.get("storagePath") || "").trim();
  const mimeTypeRaw = String(formData.get("mimeType") || "").trim();
  const selectedFile = els.marketingAssetFileInput?.files?.[0] || null;
  const fileName = fileNameRaw || selectedFile?.name || "";
  const mimeType = mimeTypeRaw || selectedFile?.type || "";
  const generatedPath = `uploads/${new Date().toISOString().slice(0, 10)}/${Date.now()}_${String(fileName || "asset")
    .replace(/\s+/g, "_")
    .replace(/[^a-zA-Z0-9._/-]/g, "")}`;
  const storagePath = storagePathRaw || generatedPath;

  if (!fileName || !storageBucket || !storagePath) {
    showMarketingWarning("Bitte Dateiname, Bucket und Pfad ausfüllen.");
    return;
  }

  const isEditing = Boolean(marketingEditState.assetId);
  setActionButtonBusy(els.marketingAssetSaveBtn, true, isEditing ? "Aktualisiert..." : "Speichert...");
  try {
    let uploadPath = storagePath;
    if (selectedFile) {
      const uploadResult = await client.storage.from(storageBucket).upload(storagePath, selectedFile, {
        cacheControl: "3600",
        upsert: false,
      });
      if (uploadResult.error) {
        const fallbackPath = `${generatedPath}_${Math.floor(Math.random() * 10000)}`;
        const retryUpload = await client.storage.from(storageBucket).upload(fallbackPath, selectedFile, {
          cacheControl: "3600",
          upsert: false,
        });
        if (retryUpload.error) {
          showMarketingError(`Datei-Upload fehlgeschlagen: ${getSupabaseErrorSummary(retryUpload.error)}`);
          return;
        }
        uploadPath = fallbackPath;
      }
    }

    const payload = {
      campaign_id: campaignId || null,
      content_item_id: contentItemId || null,
      storage_bucket: storageBucket,
      storage_path: uploadPath,
      file_name: fileName,
      mime_type: mimeType || null,
      size_bytes: selectedFile?.size || null,
      uploaded_by: getAuthUid(),
    };
    const { data, error } = isEditing
      ? await client.from(getMarketingAssetsTable()).update(payload).eq("id", marketingEditState.assetId).select("id").single()
      : await client.from(getMarketingAssetsTable()).insert(payload).select("id").single();
    if (error) {
      if (isSupabaseMissingRelationError(error, getMarketingAssetsTable())) {
        showMarketingError(getMarketingMissingTableMessage(getMarketingAssetsTable()));
      } else {
        showMarketingError(`Asset konnte nicht gespeichert werden: ${getSupabaseErrorSummary(error)}`);
      }
      return;
    }

    await logMarketingActivity(isEditing ? "asset_updated" : "asset_created", "asset", data?.id || "", {
      fileName,
      storageBucket,
      storagePath: uploadPath,
    });
    clearMarketingAssetForm();
    await hydrateMarketingData({ force: true });
    renderMarketingModule();
    showMarketingSuccess(isEditing ? "Asset aktualisiert." : "Asset gespeichert.");
  } finally {
    setActionButtonBusy(els.marketingAssetSaveBtn, false);
  }
}

