function renderEmployeeSalesActivityAnalytics(range, countryFilter = "all") {
  if (!canCurrentUserViewEmployeeDashboardPanel()) {
    return;
  }
  const analytics = buildEmployeeSalesActivityAnalytics(range, countryFilter);
  if (els.employeeSalesActivityMeta) {
    const countryLabel = countryFilter === "all" ? "Alle Länder" : countryFilter;
    els.employeeSalesActivityMeta.textContent = `${analytics.totals.totalActions} Aktionen · ${analytics.totals.activeEmployees} aktive Mitarbeiter · ${countryLabel}`;
  }
  renderEmployeeSalesActivityKpis(analytics);
  renderEmployeeSalesActivityTable(analytics);
  renderEmployeeSalesActivityFeed(analytics);
}

function getProviderStatusBucket(status) {
  const normalized = normalizeProviderStatusValue(status || "");
  if (normalized === "live") {
    return "live";
  }
  if (
    normalized === "live_pending" ||
    normalized === "live pending" ||
    normalized === "live beantragt" ||
    normalized === "live beantragung" ||
    normalized === "live-beantragung" ||
    normalized === "freigabe ausstehend"
  ) {
    return "livePending";
  }
  if (normalized === "in Bearbeitung") {
    return "inProgress";
  }
  if (
    [
      PROVIDER_STATUS_TELEFONAKQUISE,
      PROVIDER_STATUS_NOT_REACHED,
      PROVIDER_STATUS_CALLBACK,
      PROVIDER_STATUS_REACHED,
      PROVIDER_STATUS_TOUR_PLANNED,
    ].includes(normalized)
  ) {
    return "inProgress";
  }
  if (normalized === PROVIDER_STATUS_NO_INTEREST || normalized === PROVIDER_STATUS_ARCHIVED) {
    return "closed";
  }
  return "open";
}

function normalizeProviderStatusValue(status) {
  const normalized = normalizeText(status || "");
  if (normalized === "live") {
    return "live";
  }
  if (["angelegt", "erstellt", "created"].includes(normalized)) {
    return PROVIDER_STATUS_CREATED;
  }
  if (
    normalized === "live_pending" ||
    normalized === "live pending" ||
    normalized === "live beantragt" ||
    normalized === "live beantragung" ||
    normalized === "live-beantragung" ||
    normalized === "freigabe ausstehend"
  ) {
    return PROVIDER_STATUS_LIVE_PENDING;
  }
  if (["erfasst", "in bearbeitung", "in_bearbeitung", "bearbeitung", "in_progress", "progress", "claimed"].includes(normalized)) {
    return "in Bearbeitung";
  }
  if (["telefonakquise", "telefon akquise", "phone acquisition", "telefon"].includes(normalized)) {
    return PROVIDER_STATUS_TELEFONAKQUISE;
  }
  if (["nicht_erreicht", "nicht erreicht", "mailbox"].includes(normalized)) {
    return PROVIDER_STATUS_NOT_REACHED;
  }
  if (["rueckruf", "ruckruf", "rückruf", "callback"].includes(normalized)) {
    return PROVIDER_STATUS_CALLBACK;
  }
  if (["erreicht", "kontakt erreicht"].includes(normalized)) {
    return PROVIDER_STATUS_REACHED;
  }
  if (["kein_interesse", "kein interesse", "no interest"].includes(normalized)) {
    return PROVIDER_STATUS_NO_INTEREST;
  }
  if (["tour_geplant", "tour geplant", "tour"].includes(normalized)) {
    return PROVIDER_STATUS_TOUR_PLANNED;
  }
  if (["archiviert", "archived", "archive"].includes(normalized)) {
    return PROVIDER_STATUS_ARCHIVED;
  }
  return "offen";
}

function normalizeProviderStatusHistoryEntry(entry, index = 0) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const toStatusRaw = String(entry.toStatus || entry.to_status || entry.status || "").trim();
  if (!toStatusRaw) {
    return null;
  }
  const fromStatusRaw = String(entry.fromStatus || entry.from_status || "").trim();
  const timestampRaw = String(entry.at || entry.changedAt || entry.changed_at || entry.timestamp || "").trim();
  if (!timestampRaw) {
    return null;
  }
  const byRoleRaw = String(entry.byRole || entry.by_role || entry.role || "").trim();
  const sourceRaw = String(entry.source || "").trim();
  return {
    id: String(entry.id || `pst_${index}_${timestampRaw}`).trim(),
    fromStatus: fromStatusRaw ? normalizeProviderStatusValue(fromStatusRaw) : "",
    toStatus: normalizeProviderStatusValue(toStatusRaw),
    at: timestampRaw,
    byUserId: normalizeUserId(entry.byUserId || entry.by_user_id || entry.userId || ""),
    byName: String(entry.byName || entry.by_name || entry.userName || entry.name || "").trim(),
    byRole: byRoleRaw ? normalizeUserRole(byRoleRaw) : "",
    source: sourceRaw || "manual",
  };
}

function normalizeProviderStatusHistory(historyLike) {
  if (!Array.isArray(historyLike)) {
    return [];
  }
  return historyLike
    .map((entry, index) => normalizeProviderStatusHistoryEntry(entry, index))
    .filter(Boolean)
    .sort((left, right) => {
      const leftAt = String(left.at || "").trim();
      const rightAt = String(right.at || "").trim();
      if (leftAt !== rightAt) {
        return leftAt.localeCompare(rightAt);
      }
      return String(left.id || "").localeCompare(String(right.id || ""));
    });
}

function appendProviderStatusHistory(
  provider,
  fromStatusRaw,
  toStatusRaw,
  actor = getCurrentActorInfo(),
  timestampIso = "",
  source = "manual"
) {
  if (!provider || typeof provider !== "object") {
    return;
  }
  const toStatus = normalizeProviderStatusValue(toStatusRaw);
  const fromStatusNormalized = String(fromStatusRaw || "").trim()
    ? normalizeProviderStatusValue(fromStatusRaw)
    : "";
  if (!toStatus || (fromStatusNormalized && fromStatusNormalized === toStatus)) {
    return;
  }
  const at = String(timestampIso || "").trim() || new Date().toISOString();
  const entry = {
    id: createId("pst"),
    fromStatus: fromStatusNormalized,
    toStatus,
    at,
    byUserId: normalizeUserId(actor?.userId || ""),
    byName: String(actor?.name || "").trim(),
    byRole: normalizeUserRole(actor?.role || ""),
    source: String(source || "").trim() || "manual",
  };
  const history = normalizeProviderStatusHistory(provider.statusHistory || provider.status_history || []);
  const isDuplicate = history.some(
    (existing) =>
      existing.at === entry.at &&
      existing.fromStatus === entry.fromStatus &&
      existing.toStatus === entry.toStatus &&
      existing.byUserId === entry.byUserId &&
      existing.source === entry.source
  );
  if (!isDuplicate) {
    history.push(entry);
  }
  provider.statusHistory = normalizeProviderStatusHistory(history);
  provider.status_history = provider.statusHistory;
}

function getProviderStatusSliderClass(status) {
  const bucket = getProviderStatusBucket(status);
  if (bucket === "live") {
    return "status-live";
  }
  if (bucket === "livePending") {
    return "status-live-pending";
  }
  if (bucket === "inProgress" || bucket === "livePending") {
    return "status-in-progress";
  }
  if (bucket === "closed") {
    return "status-closed";
  }
  return "status-offen";
}

function getProviderStatusFlowIndex(status, flow = PROVIDER_STATUS_FLOW, options = {}) {
  const useFormComparable = options?.formComparable === true;
  const normalizeForFlow = useFormComparable
    ? getProviderStatusFormComparableValue
    : normalizeProviderStatusValue;
  const normalizedValue = normalizeForFlow(status);
  const index = flow.findIndex((entry) => normalizeForFlow(entry.id) === normalizedValue);
  return index >= 0 ? index : 0;
}

function getProviderStatusFromForm() {
  const statusField = els.providerForm?.elements?.status;
  const rawValue = typeof statusField?.value === "string" ? statusField.value : "";
  return normalizeProviderStatusValue(rawValue);
}

function getProviderStatusFormComparableValue(status) {
  const normalizedValue = normalizeProviderStatusValue(status);
  if (["offen", "in Bearbeitung", PROVIDER_STATUS_LIVE_PENDING, "live"].includes(normalizedValue)) {
    return normalizedValue;
  }
  const bucket = getProviderStatusBucket(normalizedValue);
  if (bucket === "inProgress") {
    return "in Bearbeitung";
  }
  return "offen";
}

function setProviderStatusInForm(status) {
  if (!els.providerForm) {
    return;
  }
  const normalizedValue = getProviderStatusFormComparableValue(status);
  const radios = Array.from(els.providerStatusSlider?.querySelectorAll('input[name="status"]') || []);
  if (!radios.length) {
    if (typeof els.providerForm.elements?.status?.value === "string") {
      els.providerForm.elements.status.value = normalizedValue;
    }
    return;
  }
  radios.forEach((radio) => {
    radio.checked = getProviderStatusFormComparableValue(radio.value) === normalizedValue;
  });
}

function syncProviderHeaderLiveLight() {
  if (!els.providerHeaderLiveLight) {
    return;
  }
  const showLive = providersViewMode === "form" && normalizeText(getProviderStatusFromForm()) === "live";
  els.providerHeaderLiveLight.classList.toggle("hidden", !showLive);
  els.providerHeaderLiveLight.classList.toggle("is-live", showLive);
}

function syncProviderStatusSliderUi() {
  const slider = els.providerStatusSlider;
  if (!slider) {
    providerStatusLastFormValue = normalizeProviderStatusValue(getProviderStatusFromForm());
    if (providerStatusLastFormValue !== "live") {
      providerLiveStatusConfirmedInForm = false;
      providerLiveProvisionAssigneeInForm = "";
    }
    syncProviderHeaderLiveLight();
    return;
  }
  const normalizedValue = getProviderStatusFromForm();
  providerStatusLastFormValue = normalizedValue;
  if (normalizedValue !== "live") {
    providerLiveStatusConfirmedInForm = false;
    providerLiveProvisionAssigneeInForm = "";
  }
  const options = Array.from(slider.querySelectorAll(".provider-status-option"));
  const editingProvider = getEditingProviderRecord();
  const statusPermissionSource = editingProvider?.status || "offen";
  const allowedStatusValues = getAllowedProviderStatusValuesForCurrentUser(statusPermissionSource);
  const lockedForCompetitorClarification = Boolean(editingProviderId && isProviderCompetitor(editingProvider));
  const activeIndex = getProviderStatusFlowIndex(normalizedValue, PROVIDER_STATUS_FLOW, { formComparable: true });
  slider.style.setProperty("--status-index", String(activeIndex));
  slider.style.setProperty("--provider-status-index", String(activeIndex));
  slider.style.setProperty("--provider-status-count", String(Math.max(options.length, 1)));
  slider.classList.remove(
    "status-offen",
    "status-in-progress",
    "status-live",
    "status-live-pending",
    "status-closed"
  );
  slider.classList.add(getProviderStatusSliderClass(normalizedValue));

  options.forEach((option) => {
    const radio = option.querySelector('input[name="status"]');
    const optionValue = getProviderStatusFormComparableValue(radio?.value || "");
    const isActive = optionValue === getProviderStatusFormComparableValue(normalizedValue);
    const isAllowed = !lockedForCompetitorClarification && allowedStatusValues.has(optionValue);
    option.classList.toggle("active", isActive);
    option.classList.toggle("is-disabled", !isAllowed);
    if (radio instanceof HTMLInputElement) {
      radio.disabled = !isAllowed;
    }
  });

  syncProviderHeaderLiveLight();
}

function appendProviderToEmployeeRow(row, provider) {
  if (!row || !provider) {
    return;
  }
  const providerId = String(provider.id || "").trim();
  if (!providerId) {
    row.providers.push(provider);
    return;
  }
  const alreadyIncluded = row.providers.some(
    (entry) => String(entry?.id || "").trim() === providerId
  );
  if (!alreadyIncluded) {
    row.providers.push(provider);
  }
}

function getOrCreateUnknownEmployeeRow(employeeById, unknownId) {
  if (employeeById.has(unknownId)) {
    return employeeById.get(unknownId);
  }
  const unknownEntry = {
    id: unknownId,
    name: "Unbekannt",
    role: ROLE_MITARBEITER,
    openCount: 0,
    inProgressCount: 0,
    liveCount: 0,
    totalCount: 0,
    ratePerLive: 0,
    honorariumEnabled: false,
    liveActivatedCount: 0,
    earningsEur: 0,
    providers: [],
  };
  employeeById.set(unknownId, unknownEntry);
  return unknownEntry;
}

function providerBelongsToUser(provider, user) {
  const userId = normalizeUserId(user?.sourceId || user?.id || "");
  const responsible = getProviderEffectiveResponsibleInfo(provider);
  const responsibleUserId = normalizeUserId(responsible?.userId || "");
  if (userId && responsibleUserId) {
    if (responsibleUserId === userId) {
      return true;
    }
  }

  const normalizedUserName = normalizeText(user?.name || "");
  const normalizedUserEmail = normalizeText(user?.email || "");
  const normalizedProviderResponsibleName = normalizeText(responsible?.name || provider?.createdByName || "");

  if (normalizedUserName && normalizedProviderResponsibleName) {
    return normalizedProviderResponsibleName === normalizedUserName;
  }
  if (normalizedUserEmail && normalizedProviderResponsibleName) {
    return normalizedProviderResponsibleName === normalizedUserEmail;
  }
  return false;
}

function providerInvitationWasRequestedByUser(provider, user = getCurrentUser()) {
  if (!provider || !user || !getProviderInvitationRequestStatus(provider)) {
    return false;
  }
  const userId = normalizeUserId(user?.sourceId || user?.id || getCurrentUserId() || "");
  const requestedByUserId = normalizeUserId(
    provider?.invitationRequestedByUserId || provider?.invitation_requested_by_user_id || ""
  );
  if (userId && requestedByUserId) {
    return userId === requestedByUserId;
  }

  const requestedByName = normalizeText(
    provider?.invitationRequestedByName || provider?.invitation_requested_by_name || ""
  );
  if (!requestedByName) {
    return false;
  }
  const userName = normalizeText(user?.name || "");
  const userEmail = normalizeText(user?.email || "");
  return Boolean((userName && requestedByName === userName) || (userEmail && requestedByName === userEmail));
}

function providerCreatedByUser(provider, user = getCurrentUser()) {
  if (!provider || !user) {
    return false;
  }
  const userId = normalizeUserId(user?.sourceId || user?.id || "");
  const createdByUserId = normalizeUserId(provider?.createdByUserId || provider?.created_by_user_id || "");
  if (userId && createdByUserId) {
    return userId === createdByUserId;
  }

  const normalizedUserName = normalizeText(user?.name || "");
  const normalizedUserEmail = normalizeText(user?.email || "");
  const normalizedCreatedByName = normalizeText(provider?.createdByName || provider?.created_by_name || "");
  if (normalizedUserName && normalizedCreatedByName) {
    return normalizedUserName === normalizedCreatedByName;
  }
  if (normalizedUserEmail && normalizedCreatedByName) {
    return normalizedUserEmail === normalizedCreatedByName;
  }
  return false;
}

function getProviderCreatedAtMs(provider) {
  const createdAt = String(
    provider?.createdAt || provider?.sourceCreatedAt || provider?.source_created_at || provider?.created_at || ""
  ).trim();
  const timestamp = createdAt ? new Date(createdAt).getTime() : Number.NaN;
  return Number.isFinite(timestamp) ? timestamp : Number.NaN;
}

function isProviderCreatedWithinDeleteWindow(provider, nowMs = Date.now()) {
  const createdAtMs = getProviderCreatedAtMs(provider);
  const referenceMs = Number(nowMs);
  return Boolean(
    Number.isFinite(createdAtMs) &&
      Number.isFinite(referenceMs) &&
      createdAtMs <= referenceMs &&
      referenceMs - createdAtMs <= PROVIDER_CREATOR_DELETE_WINDOW_MS
  );
}

function hasProviderStatusEverChanged(provider) {
  const currentStatus = normalizeProviderStatusValue(provider?.status || "offen");
  if (currentStatus !== "offen") {
    return true;
  }
  return normalizeProviderStatusHistory(provider?.statusHistory || provider?.status_history || []).some(
    (entry) => normalizeProviderStatusValue(entry?.toStatus || "offen") !== "offen"
  );
}

function isProviderEligibleForPermanentDeletion(provider) {
  return Boolean(provider) && !hasProviderStatusEverChanged(provider);
}

function getProviderDeletionBlockReason(provider) {
  if (!provider) {
    return "Der Anbieter wurde nicht gefunden.";
  }
  if (!isProviderEligibleForPermanentDeletion(provider)) {
    return "Nach einer Statusänderung kann ein Anbieter nicht mehr gelöscht, sondern nur archiviert werden.";
  }
  if (getProviderInvitationRequestStatus(provider)) {
    return "Anbieter mit einer Einladungsanfrage können nicht gelöscht werden.";
  }
  const providerNotes = normalizeProviderNotes([
    ...(Array.isArray(provider?.notes) ? provider.notes : []),
    ...getProviderNotesSource(provider),
  ]);
  if (providerNotes.length) {
    return "Anbieter mit Notizen oder Aufgaben können nicht gelöscht werden.";
  }
  const providerId = String(provider?.id || "").trim();
  if (!providerId) {
    return "Der Anbieter hat keine gültige Kennung.";
  }
  const hasTourAssignment = (Array.isArray(state.tours) ? state.tours : []).some((tour) =>
    (Array.isArray(tour?.stops) ? tour.stops : []).some(
      (stop) => String(stop?.providerId || "").trim() === providerId
    )
  );
  if (hasTourAssignment) {
    return "Anbieter mit einer Tourenplanung können nicht gelöscht werden.";
  }
  if (getSalesPhoneCalls().some((entry) => String(entry?.providerId || "").trim() === providerId)) {
    return "Anbieter mit Telefonakquise-Einträgen können nicht gelöscht werden.";
  }
  const hasLinkedPartnerRequest = [
    ...getProviderLinkedPartnerRequestIds(provider),
    ...getProviderLinkedPartnerRequestPersistedIds(provider),
    ...getProviderLinkedPartnerRequestNotificationIds(provider),
  ].length > 0;
  if (hasLinkedPartnerRequest) {
    return "Anbieter mit verknüpften Partneranfragen können nicht gelöscht werden.";
  }
  return "";
}

function canCurrentUserArchiveProvider(provider, user = getCurrentUser()) {
  return Boolean(provider) && isRoleAdmin(user) && normalizeProviderStatusValue(provider.status) !== PROVIDER_STATUS_ARCHIVED;
}

function canCurrentUserDeleteProvider(provider, user = getCurrentUser()) {
  if (!provider || !user) {
    return false;
  }
  if (getProviderDeletionBlockReason(provider)) {
    return false;
  }
  if (!isProviderCreatedWithinDeleteWindow(provider)) {
    return false;
  }
  if (isSuperAdmin(user)) {
    return true;
  }
  if (!isSalesRepresentative(user)) {
    return false;
  }
  if (!providerVisibleForCurrentUser(provider, user) || !providerCreatedByUser(provider, user)) {
    return false;
  }
  return isProviderCreatedWithinDeleteWindow(provider);
}

function getProviderDeletePermissionHint(provider, user = getCurrentUser()) {
  const blockReason = getProviderDeletionBlockReason(provider);
  if (blockReason) {
    return blockReason;
  }
  if (!isProviderCreatedWithinDeleteWindow(provider)) {
    return "Die 24-Stunden-Frist für das endgültige Löschen ist abgelaufen. Ein Admin kann den Anbieter archivieren.";
  }
  if (isSuperAdmin(user)) {
    return "";
  }
  if (!isSalesRepresentative(user)) {
    return "Nur Superadmins können diesen Anbieter endgültig löschen.";
  }
  if (!providerCreatedByUser(provider, user)) {
    return "Vertriebsmitarbeiter können nur eigene Anbieter löschen.";
  }
  return "Dieser Anbieter kann nicht gelöscht werden.";
}

