async function confirmProviderLiveActivation(providerName = "", options = {}) {
  const nameLabel = String(providerName || "").trim();
  const pendingRequest = options?.pendingRequest === true;
  const requestedByName = String(options?.requestedByName || "").trim();
  const requestedByRole = normalizeUserRole(options?.requestedByRole || "");
  const requestedByRoleLabel = requestedByRole ? getRoleLabel(requestedByRole) : "";
  const requestedByUserId = normalizeUserId(options?.requestedByUserId || "");
  const requestorLabel = requestedByName
    ? `${requestedByName}${requestedByRoleLabel ? ` (${requestedByRoleLabel})` : ""}`
    : "";
  const requestorHint = requestorLabel
    ? ` Antragsteller: ${requestorLabel}.`
    : pendingRequest
      ? " Antragsteller: Unbekannt."
      : "";
  const question = nameLabel
    ? `Wurde "${nameLabel}" wirklich auf der my-waycard.com Website angemeldet?${requestorHint}`
    : `Wurde der Anbieter wirklich auf der my-waycard.com Website angemeldet?${requestorHint}`;
  const actor = getCurrentActorInfo();
  const assignableUsers = getProvisionAssignableUsers();
  const fallbackActorId = normalizeUserId(actor?.userId || "");
  const fallbackDefaultUserId = pendingRequest ? "" : fallbackActorId;
  let selectedProvisionUserId = normalizeUserId(
    options?.preselectedUserId || requestedByUserId || fallbackDefaultUserId || ""
  );
  if (!selectedProvisionUserId && assignableUsers.length && !pendingRequest) {
    selectedProvisionUserId = assignableUsers[0].userId;
  }
  const selectedUserExists = assignableUsers.some((entry) => entry.userId === selectedProvisionUserId);
  if (selectedProvisionUserId && !selectedUserExists) {
    const selectedUser = state.users.find(
      (entry) => entry.source === "profile" && normalizeUserId(entry.sourceId || entry.id) === selectedProvisionUserId
    );
    assignableUsers.unshift({
      userId: selectedProvisionUserId,
      name:
        requestedByUserId && selectedProvisionUserId === requestedByUserId
          ? requestedByName || getUserDisplayNameByUserId(selectedProvisionUserId) || "Mitarbeiter"
          : getUserDisplayNameByUserId(selectedProvisionUserId) || actor?.name || "Mitarbeiter",
      role:
        requestedByUserId && selectedProvisionUserId === requestedByUserId
          ? requestedByRole || normalizeUserRole(selectedUser?.role || actor?.role)
          : normalizeUserRole(selectedUser?.role || actor?.role),
    });
  }
  if (!assignableUsers.length && fallbackActorId && !pendingRequest) {
    assignableUsers.push({
      userId: fallbackActorId,
      name: actor?.name || "Mitarbeiter",
      role: normalizeUserRole(actor?.role),
    });
    selectedProvisionUserId = fallbackActorId;
  }

  if (!els.liveConfirmPanel || !els.liveConfirmText || !els.liveConfirmYes || !els.liveConfirmNo || !els.liveConfirmClose) {
    const confirmed = await confirmAction(`${question}\n\nNur dann bestätigen, wenn die Anmeldung erfolgt ist.`, {
      title: "Live-Freigabe bestätigen",
      confirmLabel: "Bestätigen",
    });
    return {
      confirmed,
      provisionUserId: confirmed ? normalizeUserId(selectedProvisionUserId || fallbackActorId || "") : "",
    };
  }

  els.liveConfirmText.textContent = question;
  if (els.liveConfirmProvisionUser) {
    const optionsMarkup = assignableUsers.length
      ? [
          pendingRequest ? '<option value="">Bitte wählen</option>' : "",
          ...assignableUsers
          .map((entry) => {
            const roleLabel = getRoleLabel(entry.role || "");
            const optionLabel = roleLabel ? `${entry.name} · ${roleLabel}` : entry.name;
            return `<option value="${escapeHtml(entry.userId)}">${escapeHtml(optionLabel)}</option>`;
          })
          .filter(Boolean),
        ].join("")
      : '<option value="">Keine Mitarbeiter verfügbar</option>';
    els.liveConfirmProvisionUser.innerHTML = optionsMarkup;
    if (selectedProvisionUserId) {
      els.liveConfirmProvisionUser.value = selectedProvisionUserId;
    } else if (els.liveConfirmProvisionUser.options.length) {
      els.liveConfirmProvisionUser.selectedIndex = 0;
    }
  }
  if (els.liveConfirmProvisionUserField) {
    els.liveConfirmProvisionUserField.classList.toggle("hidden", !els.liveConfirmProvisionUser);
  }
  els.liveConfirmPanel.classList.remove("hidden");
  syncBodyModalOpenState();

  return new Promise((resolve) => {
    let settled = false;
    const finish = (result) => {
      if (settled) {
        return;
      }
      settled = true;
      els.liveConfirmPanel.classList.add("hidden");
      syncBodyModalOpenState();
      els.liveConfirmYes.removeEventListener("click", onYes);
      els.liveConfirmNo.removeEventListener("click", onNo);
      els.liveConfirmClose.removeEventListener("click", onNo);
      document.removeEventListener("keydown", onKeyDown);
      resolve(result);
    };
    const onYes = () => {
      const selectedUserId = normalizeUserId(els.liveConfirmProvisionUser?.value || selectedProvisionUserId || "");
      if (!selectedUserId) {
        showWarningFeedback("Bitte Mitarbeiter für die Provision auswählen.");
        els.liveConfirmProvisionUser?.focus();
        return;
      }
      finish({
        confirmed: true,
        provisionUserId: selectedUserId,
      });
    };
    const onNo = () => {
      finish({
        confirmed: false,
        provisionUserId: "",
      });
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        finish({
          confirmed: false,
          provisionUserId: "",
        });
      }
    };

    els.liveConfirmYes.addEventListener("click", onYes);
    els.liveConfirmNo.addEventListener("click", onNo);
    els.liveConfirmClose.addEventListener("click", onNo);
    document.addEventListener("keydown", onKeyDown);
  });
}

async function confirmAction(message, options = {}) {
  const question = String(message || "").trim() || "Wirklich löschen?";
  const title = String(options?.title || "Bestätigung erforderlich").trim() || "Bestätigung erforderlich";
  const confirmLabel = String(options?.confirmLabel || "Bestätigen").trim() || "Bestätigen";
  const danger = options?.danger === true;

  if (
    !els.deleteConfirmPanel ||
    !els.deleteConfirmText ||
    !els.deleteConfirmYes ||
    !els.deleteConfirmNo ||
    !els.deleteConfirmClose
  ) {
    return window.confirm(question);
  }

  const titleElement = document.getElementById("delete-confirm-title");
  if (titleElement) {
    titleElement.textContent = title;
  }
  els.deleteConfirmText.textContent = question;
  els.deleteConfirmYes.textContent = confirmLabel;
  els.deleteConfirmPanel.dataset.confirmTone = danger ? "danger" : "default";
  els.deleteConfirmYes.classList.toggle("btn-danger", danger);
  els.deleteConfirmYes.classList.toggle("btn-success", !danger);
  els.deleteConfirmPanel.classList.remove("hidden");
  syncBodyModalOpenState();

  return new Promise((resolve) => {
    let settled = false;
    const finish = (result) => {
      if (settled) {
        return;
      }
      settled = true;
      els.deleteConfirmPanel.classList.add("hidden");
      syncBodyModalOpenState();
      els.deleteConfirmYes.removeEventListener("click", onYes);
      els.deleteConfirmNo.removeEventListener("click", onNo);
      els.deleteConfirmClose.removeEventListener("click", onNo);
      document.removeEventListener("keydown", onKeyDown);
      resolve(result);
    };
    const onYes = () => {
      finish(true);
    };
    const onNo = () => {
      finish(false);
    };
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        finish(false);
      }
    };

    els.deleteConfirmYes.addEventListener("click", onYes);
    els.deleteConfirmNo.addEventListener("click", onNo);
    els.deleteConfirmClose.addEventListener("click", onNo);
    document.addEventListener("keydown", onKeyDown);
  });
}

async function confirmDeleteAction(message, confirmLabel = "Ja, löschen") {
  return confirmAction(message, {
    title: "Löschen bestätigen",
    confirmLabel,
    danger: true,
  });
}

