function formatSignedEuroAmount(value) {
  const numeric = sanitizeEmployeeRateValue(Math.abs(Number(value) || 0));
  const prefix = Number(value) < 0 ? "- " : "+ ";
  return `${prefix}${formatEuroAmount(numeric)}`;
}

function sanitizeSignedEuroAmount(value) {
  const parsed = parseOptionalNumber(value);
  if (typeof parsed !== "number" || !Number.isFinite(parsed)) {
    return 0;
  }
  return Math.round(parsed * 100) / 100;
}

function getEffectiveProvisionEntryAmountEur(entry) {
  if (!entry || typeof entry !== "object") {
    return 0;
  }
  const rawAmount = sanitizeSignedEuroAmount(entry.amountEur);
  if (entry.amountIsFixed === true || Math.abs(rawAmount) > 0) {
    return rawAmount;
  }
  const entryType = normalizeProvisionLedgerEntryType(entry.type || "");
  if (entryType === "reversal") {
    const reversedCredit = findProvisionLedgerEntryById(entry.reversalOfEntryId);
    const reversedCreditAmount = sanitizeSignedEuroAmount(reversedCredit?.amountEur || 0);
    if (reversedCreditAmount > 0) {
      return -Math.abs(reversedCreditAmount);
    }
  }
  const userId = normalizeUserId(entry.userId || "");
  if (!userId) {
    return 0;
  }
  const fallbackRate = sanitizeEmployeeRateValue(getEmployeeRateByUserId(userId));
  if (fallbackRate <= 0) {
    return 0;
  }
  return entryType === "reversal" ? -fallbackRate : fallbackRate;
}

function getProvisionLedgerEntriesForUserInScope(userId, range, countryFilter = "all") {
  const normalizedUserId = normalizeUserId(userId || "");
  if (!normalizedUserId) {
    return [];
  }
  return getProvisionLedgerEntriesScoped(range, countryFilter, getCurrentUser())
    .filter((entry) => normalizeUserId(entry.userId || "") === normalizedUserId)
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")));
}

function renderProvisionLogForUser(
  userId,
  metaElement,
  listElement,
  options = {}
) {
  if (!metaElement || !listElement) {
    return;
  }
  const normalizedUserId = normalizeUserId(userId || "");
  if (!normalizedUserId) {
    metaElement.textContent = "";
    listElement.innerHTML = "";
    return;
  }
  const entries = Array.isArray(options?.entries)
    ? options.entries
    : getProvisionLedgerEntries()
        .filter((entry) => normalizeUserId(entry.userId || "") === normalizedUserId)
        .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")));
  const provisionNetTotal = sanitizeSignedEuroAmount(
    entries.reduce((sum, entry) => sum + getEffectiveProvisionEntryAmountEur(entry), 0)
  );
  const creditCount = entries.filter((entry) => entry.type === "credit").length;
  const reversalCount = entries.filter((entry) => entry.type === "reversal").length;
  metaElement.textContent =
    `${entries.length} Einträge · Gutschriften ${creditCount} · Stornos ${reversalCount} · Saldo ${formatNetEuroAmount(
      provisionNetTotal
    )}`;
  listElement.innerHTML = entries.length
    ? entries
        .map((entry) => {
          const isReversal = entry.type === "reversal";
          const providerLabel = String(entry.providerName || "Anbieter").trim() || "Anbieter";
          const actorLabel = String(entry.createdByName || "System").trim();
          const reason = String(entry.reason || "").trim() || "ohne Zusatz";
          return `
            <article class="employee-detail-provision-log-item">
              <div class="employee-detail-provision-log-item-head">
                <span class="employee-detail-provision-log-item-title">${escapeHtml(
                  `${isReversal ? "Storno" : "Gutschrift"} · ${providerLabel}`
                )}</span>
                <span class="employee-detail-provision-log-item-amount ${isReversal ? "reversal" : "credit"}">${escapeHtml(
                  formatSignedEuroAmount(getEffectiveProvisionEntryAmountEur(entry))
                )}</span>
              </div>
              <div class="employee-detail-provision-log-item-meta">${escapeHtml(
                `${formatDateTime(entry.createdAt)} · ${actorLabel} (${getRoleLabel(entry.createdByRole)})`
              )}</div>
              <div class="employee-detail-provision-log-item-meta">${escapeHtml(reason)}</div>
            </article>
          `;
        })
        .join("")
    : '<p class="empty">Keine Provisionsbuchungen vorhanden.</p>';
}

function renderEmployeeDetails(employeeRows, range, countryFilter = "all") {
  if (!els.employeeDetailPanel || !els.employeeDetailTitle || !els.employeeDetailBody) {
    return;
  }

  const selectedEntry = employeeRows.find((entry) => entry.id === selectedEmployeeActivityUserId) || null;
  if (!selectedEntry) {
    closeEmployeeDetailsModal();
    els.employeeDetailTitle.textContent = "";
    els.employeeDetailBody.innerHTML = "";
    if (els.employeeDetailProvisionLogMeta) {
      els.employeeDetailProvisionLogMeta.textContent = "";
    }
    if (els.employeeDetailProvisionLogList) {
      els.employeeDetailProvisionLogList.innerHTML = "";
    }
    return;
  }
  if (!isAdminDashboardMode()) {
    const ownUserId = normalizeUserId(authProfile?.user_id || getCurrentUser()?.sourceId || getCurrentUser()?.id || "");
    const selectedId = normalizeUserId(selectedEntry.id || "");
    if (selectedId && selectedId !== ownUserId && selectedId !== "__me__") {
      closeEmployeeDetailsModal();
      els.employeeDetailTitle.textContent = "";
      els.employeeDetailBody.innerHTML = "";
      if (els.employeeDetailProvisionLogMeta) {
        els.employeeDetailProvisionLogMeta.textContent = "";
      }
      if (els.employeeDetailProvisionLogList) {
        els.employeeDetailProvisionLogList.innerHTML = "";
      }
      return;
    }
  }

  const selectedUserId = normalizeUserId(selectedEntry.id || "");
  const provisionLogEntries = getProvisionLedgerEntriesForUserInScope(selectedUserId, range, countryFilter);
  const provisionAmountByProviderId = new Map();
  provisionLogEntries.forEach((entry) => {
    const providerId = String(entry.providerId || "").trim();
    if (!providerId) {
      return;
    }
    provisionAmountByProviderId.set(
      providerId,
      sanitizeSignedEuroAmount(
        (provisionAmountByProviderId.get(providerId) || 0) + getEffectiveProvisionEntryAmountEur(entry)
      )
    );
  });

  const detailProviders = selectedEntry.providers
    .filter((provider) => {
      if (!providerMatchesDashboardStatusFilter(provider)) {
        return false;
      }
      if (!providerMatchesCountry(provider, countryFilter)) {
        return false;
      }
      const createdAt = new Date(provider.createdAt || "");
      const createdInRange =
        !Number.isNaN(createdAt.getTime()) && createdAt >= range.start && createdAt < range.end;
      if (createdInRange) {
        return true;
      }
      if (!isLiveStatus(provider?.status)) {
        return false;
      }
      const liveEvent = getProviderLiveEvent(provider);
      return (
        String(liveEvent.provisionUserId || "").trim() === String(selectedEntry.id || "").trim() &&
        isIsoInRange(liveEvent.liveAt, range)
      );
    })
    .sort((a, b) => String(b.createdAt || "").localeCompare(String(a.createdAt || "")));

  const earningsLabel = formatNetEuroAmount(selectedEntry.earningsEur || 0);
  els.employeeDetailTitle.textContent = `${selectedEntry.name} · ${getRoleLabel(
    selectedEntry.role
  )} · ${detailProviders.length} Anlagen · Verdienst ${earningsLabel}`;
  els.employeeDetailBody.innerHTML = detailProviders.length
    ? detailProviders
        .map(
          (provider) => {
            const liveEvent = getProviderLiveEvent(provider);
            const providerCurrentlyLive = isLiveStatus(provider?.status);
            const statusLabel = getProviderStatusLabel(provider.status);
            const providerProvisionNet = sanitizeSignedEuroAmount(
              provisionAmountByProviderId.get(String(provider.id || "").trim()) || 0
            );
            const statusCell = `
              <div class="provider-status-inline">
                <span class="provider-status-pill ${providerCurrentlyLive ? "live" : ""}">
                  <span class="provider-status-light ${providerCurrentlyLive ? "live" : ""}"></span>
                  ${escapeHtml(statusLabel)}
                </span>
                <label class="live-toggle-switch">
                  <input
                    type="checkbox"
                    data-live-toggle-provider="${escapeHtml(provider.id)}"
                    ${providerCurrentlyLive ? "checked" : ""}
                  />
                  <span class="live-toggle-track"><span class="live-toggle-thumb"></span></span>
                  <span class="live-toggle-text">Live</span>
                </label>
              </div>
            `;
            return `
            <tr>
              <td>${escapeHtml(formatDateTime(provider.createdAt))}</td>
              <td>${escapeHtml(provider.name || "")}</td>
              <td>${statusCell}</td>
              <td>${escapeHtml(providerCurrentlyLive ? formatDateTime(liveEvent.liveAt) : "–")}</td>
              <td>${escapeHtml(providerProvisionNet ? formatNetEuroAmount(providerProvisionNet) : "–")}</td>
              <td>${escapeHtml([provider.city, provider.country].filter(Boolean).join(", "))}</td>
            </tr>
          `;
          }
        )
        .join("")
    : '<tr><td colspan="6" class="empty">Keine Anlagen im gewählten Zeitraum.</td></tr>';

  renderProvisionLogForUser(selectedUserId, els.employeeDetailProvisionLogMeta, els.employeeDetailProvisionLogList, {
    entries: provisionLogEntries,
  });
  openEmployeeDetailsModal();
}

