function buildOrgChartEntries() {
  const users = getOrgChartManagedUsers();
  const userIdSet = new Set(users.map((entry) => entry.userId));
  const departments = getDepartments();
  const entries = users.map((entry) => {
    const profile = getEmployeeProfileByUserId(entry.userId);
    const managerCandidate = normalizeUserId(profile.managerUserId || "");
    const managerUserId = managerCandidate && userIdSet.has(managerCandidate) && managerCandidate !== entry.userId ? managerCandidate : "";
    const departmentId = sanitizeEmployeeDepartmentValue(profile.department, departments);
    return {
      userId: entry.userId,
      name: entry.name,
      email: entry.email,
      role: entry.role,
      statusLabel: entry.statusLabel || "Aktiv",
      position: String(profile.position || "").trim(),
      location: String(profile.location || "").trim(),
      responsibility: String(profile.responsibility || "").trim(),
      departmentId,
      departmentLabel: getDepartmentLabelByValue(departmentId, departments),
      managerUserId,
    };
  });
  const entryMap = new Map(entries.map((entry) => [entry.userId, entry]));
  return { entries, entryMap };
}

function computeOrgChartLevels(entries) {
  const childMap = new Map();
  const managerMap = new Map();
  entries.forEach((entry) => {
    const managerId = String(entry.managerUserId || "").trim();
    managerMap.set(entry.userId, managerId);
    if (!childMap.has(managerId)) {
      childMap.set(managerId, []);
    }
    childMap.get(managerId).push(entry.userId);
  });
  childMap.forEach((userIds) => {
    userIds.sort((leftId, rightId) => {
      const left = entries.find((entry) => entry.userId === leftId);
      const right = entries.find((entry) => entry.userId === rightId);
      return String(left?.name || "").localeCompare(String(right?.name || ""), "de");
    });
  });

  const roots = entries
    .filter((entry) => {
      const managerId = managerMap.get(entry.userId) || "";
      return !managerId;
    })
    .map((entry) => entry.userId)
    .sort((leftId, rightId) => {
      const left = entries.find((entry) => entry.userId === leftId);
      const right = entries.find((entry) => entry.userId === rightId);
      return String(left?.name || "").localeCompare(String(right?.name || ""), "de");
    });

  const visited = new Set();
  const levels = [];
  let queue = roots.slice();
  while (queue.length) {
    const level = [];
    const nextQueue = [];
    queue.forEach((userId) => {
      if (visited.has(userId)) {
        return;
      }
      visited.add(userId);
      level.push(userId);
      const children = childMap.get(userId) || [];
      children.forEach((childId) => {
        if (!visited.has(childId)) {
          nextQueue.push(childId);
        }
      });
    });
    if (level.length) {
      levels.push(level);
    }
    queue = nextQueue;
  }

  const remaining = entries
    .map((entry) => entry.userId)
    .filter((userId) => !visited.has(userId))
    .sort((leftId, rightId) => {
      const left = entries.find((entry) => entry.userId === leftId);
      const right = entries.find((entry) => entry.userId === rightId);
      return String(left?.name || "").localeCompare(String(right?.name || ""), "de");
    });
  if (remaining.length) {
    levels.push(remaining);
  }
  return levels;
}

const ORG_CHART_DEPARTMENT_COLORS = [
  "#1f63a8",
  "#4f8b3d",
  "#db8d00",
  "#7a49aa",
  "#0f766e",
  "#8b5e3c",
  "#b91c1c",
  "#374151",
];

function getOrgChartDepartmentColor(departmentId, fallbackLabel = "") {
  const seed = String(departmentId || "").trim() || normalizeText(fallbackLabel || "") || "team";
  const paletteIndex = hashStringToPositiveInt(seed) % ORG_CHART_DEPARTMENT_COLORS.length;
  return ORG_CHART_DEPARTMENT_COLORS[paletteIndex];
}

function isOrgChartManagementDepartmentName(name = "") {
  const normalizedName = normalizeText(name || "");
  return normalizedName === "geschaftsleitung" || normalizedName === "geschaeftsleitung";
}

function getOrgChartManagementDepartment() {
  return getDepartments().find((entry) => isOrgChartManagementDepartmentName(entry?.name || "")) || null;
}

function renderOrgChartTopDepartmentPlaceholder(department, options = {}) {
  if (!department) {
    return "";
  }
  const isStandalone = Boolean(options?.standalone);
  const color = getOrgChartDepartmentColor(department.id, department.name || "Geschäftsleitung");
  return `
    <div class="orgchart-top-placeholder ${isStandalone ? "is-standalone" : ""}">
      <article class="orgchart-graph-node orgchart-graph-node-department-placeholder" style="--org-node-color:${escapeHtml(color)}">
        <div class="orgchart-graph-head">
          <strong>${escapeHtml(department.name || "Geschäftsleitung")}</strong>
        </div>
        <p class="orgchart-top-placeholder-note">Keine Mitarbeiter zugeordnet</p>
        <div class="orgchart-graph-meta">
          <span class="orgchart-graph-chip">Abteilung</span>
        </div>
      </article>
    </div>
  `;
}

function buildOrgChartTreeMap(entries) {
  const childMap = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const managerId = String(entry?.managerUserId || "").trim();
    if (!childMap.has(managerId)) {
      childMap.set(managerId, []);
    }
    childMap.get(managerId).push(entry);
  });
  childMap.forEach((list) => {
    list.sort((left, right) => String(left?.name || "").localeCompare(String(right?.name || ""), "de"));
  });
  return childMap;
}

function groupOrgChartChildrenByDepartment(children = []) {
  const groups = new Map();
  (Array.isArray(children) ? children : []).forEach((child) => {
    const departmentId = String(child?.departmentId || "").trim();
    const departmentLabel = String(child?.departmentLabel || "Ohne Abteilung").trim() || "Ohne Abteilung";
    const groupKey = departmentId || `none_${normalizeText(departmentLabel) || "none"}`;
    if (!groups.has(groupKey)) {
      groups.set(groupKey, {
        id: groupKey,
        departmentId,
        departmentLabel,
        color: getOrgChartDepartmentColor(departmentId, departmentLabel),
        members: [],
      });
    }
    groups.get(groupKey).members.push(child);
  });
  return Array.from(groups.values())
    .map((group) => ({
      ...group,
      members: group.members
        .slice()
        .sort((left, right) => String(left?.name || "").localeCompare(String(right?.name || ""), "de")),
    }))
    .sort((left, right) => String(left?.departmentLabel || "").localeCompare(String(right?.departmentLabel || ""), "de"));
}

function renderOrgChartDepartmentGroupNode(group, childMap, lineage = new Set(), renderedSet = new Set()) {
  if (!group || !Array.isArray(group.members) || !group.members.length) {
    return "";
  }
  const childrenMarkup = group.members
    .map((member) => renderOrgChartTreeNode(member, childMap, lineage, renderedSet))
    .filter(Boolean)
    .join("");
  if (!childrenMarkup) {
    return "";
  }
  const memberCount = group.members.length;
  const childListClass = memberCount <= 1 ? "orgchart-children is-single-child" : "orgchart-children";
  return `
    <li class="has-children orgchart-dept-group">
      <article class="orgchart-dept-group-node" style="--org-node-color:${escapeHtml(group.color)}">
        <strong>${escapeHtml(group.departmentLabel)}</strong>
        <small>${escapeHtml(`${memberCount} ${memberCount === 1 ? "Mitarbeiter" : "Mitarbeiter"}`)}</small>
      </article>
      <ul class="${childListClass}">${childrenMarkup}</ul>
    </li>
  `;
}

function renderOrgChartTreeNode(entry, childMap, lineage = new Set(), renderedSet = new Set()) {
  if (!entry || !entry.userId) {
    return "";
  }
  const userId = String(entry.userId).trim();
  if (!userId || lineage.has(userId) || renderedSet.has(userId)) {
    return "";
  }
  renderedSet.add(userId);
  const departmentLabel = String(entry.departmentLabel || "Ohne Abteilung").trim() || "Ohne Abteilung";
  const color = getOrgChartDepartmentColor(entry.departmentId, departmentLabel);
  const position = String(entry.position || "").trim() || "Keine Position";
  const roleLabel = getRoleLabel(entry.role);
  const children = childMap.get(userId) || [];
  const nextLineage = new Set(lineage);
  nextLineage.add(userId);
  const childGroups = children.length ? groupOrgChartChildrenByDepartment(children) : [];
  const shouldRenderGroupedChildren = childGroups.length > 0;
  const childrenMarkup = shouldRenderGroupedChildren
    ? childGroups
        .map((group) => renderOrgChartDepartmentGroupNode(group, childMap, nextLineage, renderedSet))
        .filter(Boolean)
        .join("")
    : children
        .map((child) => renderOrgChartTreeNode(child, childMap, nextLineage, renderedSet))
        .filter(Boolean)
        .join("");
  const hasChildren = Boolean(childrenMarkup);
  const isRootNode = lineage.size === 0;
  const directChildCount = shouldRenderGroupedChildren ? childGroups.length : children.length;
  const childListClass = [
    "orgchart-children",
    isRootNode ? "orgchart-root-children" : "",
    directChildCount <= 1 ? "is-single-child" : "",
  ]
    .filter(Boolean)
    .join(" ");
  const listClassNames = [hasChildren ? "has-children" : "", isRootNode ? "orgchart-root-node" : ""]
    .filter(Boolean)
    .join(" ");
  return `
    <li class="${listClassNames}">
      <article class="orgchart-graph-node orgchart-employee-node" style="--org-node-color:${escapeHtml(color)}">
        <div class="orgchart-graph-head">
          <strong>${escapeHtml(entry.name)}</strong>
          <div class="orgchart-node-actions">
            <button
              type="button"
              class="mini-btn orgchart-info-btn"
              title="Zuständigkeit anzeigen"
              aria-label="Zuständigkeit anzeigen"
              data-orgchart-info="${escapeHtml(userId)}"
            >i</button>
            <button
              type="button"
              class="mini-btn"
              title="Organigramm bearbeiten"
              aria-label="Organigramm bearbeiten"
              data-orgchart-edit="${escapeHtml(userId)}"
            >✎</button>
          </div>
        </div>
        <p>${escapeHtml(position)}</p>
        <div class="orgchart-graph-meta">
          <span class="orgchart-graph-chip">${escapeHtml(departmentLabel)}</span>
          <span class="orgchart-graph-chip">${escapeHtml(roleLabel)}</span>
        </div>
      </article>
      ${childrenMarkup ? `<ul class="${childListClass}">${childrenMarkup}</ul>` : ""}
    </li>
  `;
}

function alignOrgChartRootNode() {
  if (!els.orgChartBoard) {
    return;
  }
  const rootLi = els.orgChartBoard.querySelector(".orgchart-tree > li.orgchart-root-node");
  if (!rootLi) {
    return;
  }
  rootLi.style.setProperty("--orgchart-root-node-shift", "0px");
  rootLi.style.setProperty("--orgchart-root-branch-shift", "0px");
  const rootNode = rootLi.querySelector(":scope > .orgchart-graph-node, :scope > .orgchart-dept-group-node");
  const directChildNodes = rootLi.querySelectorAll(
    ":scope > ul > li > .orgchart-graph-node, :scope > ul > li > .orgchart-dept-group-node"
  );
  if (!rootNode || !directChildNodes.length) {
    return;
  }
  const rootRect = rootNode.getBoundingClientRect();
  const firstRect = directChildNodes[0].getBoundingClientRect();
  const lastRect = directChildNodes[directChildNodes.length - 1].getBoundingClientRect();
  const currentCenter = rootRect.left + rootRect.width / 2;
  const desiredCenter = (firstRect.left + firstRect.width / 2 + (lastRect.left + lastRect.width / 2)) / 2;
  const delta = Math.round((desiredCenter - currentCenter) * 100) / 100;
  if (Math.abs(delta) < 0.25) {
    return;
  }
  rootLi.style.setProperty("--orgchart-root-node-shift", `${delta}px`);
  rootLi.style.setProperty("--orgchart-root-branch-shift", `${delta}px`);
}

function getOrgChartDirectNodeElement(listItem) {
  if (!listItem || !listItem.children) {
    return null;
  }
  const directChildren = Array.from(listItem.children);
  return directChildren.find(
    (child) => child && child.matches && child.matches(".orgchart-graph-node, .orgchart-dept-group-node")
  ) || null;
}

function createOrgChartSvgLine(x1, y1, x2, y2, stroke, strokeWidth) {
  const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
  line.setAttribute("x1", String(x1));
  line.setAttribute("y1", String(y1));
  line.setAttribute("x2", String(x2));
  line.setAttribute("y2", String(y2));
  line.setAttribute("stroke", stroke);
  line.setAttribute("stroke-width", String(strokeWidth));
  line.setAttribute("stroke-linecap", "round");
  line.setAttribute("fill", "none");
  return line;
}

function drawOrgChartConnectors() {
  if (!els.orgChartBoard || !els.orgChartBoard.offsetParent) {
    return;
  }
  const wrap = els.orgChartBoard.querySelector(".orgchart-graph-wrap");
  const tree = wrap?.querySelector(".orgchart-tree.orgchart-tree--svg");
  if (!wrap || !tree) {
    return;
  }

  wrap.querySelectorAll(".orgchart-connectors-svg").forEach((svg) => svg.remove());

  const width = Math.max(1, Math.ceil(wrap.scrollWidth));
  const height = Math.max(1, Math.ceil(wrap.scrollHeight));
  const wrapRect = wrap.getBoundingClientRect();
  const treeRect = tree.getBoundingClientRect();
  const computed = window.getComputedStyle(tree);
  const stroke = computed.getPropertyValue("--orgchart-line-color").trim() || "#a8bfd9";
  const strokeWidth = Number.parseFloat(computed.getPropertyValue("--orgchart-line-size")) || 2;

  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("class", "orgchart-connectors-svg");
  svg.setAttribute("width", String(width));
  svg.setAttribute("height", String(height));
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);

  const liWithChildren = tree.querySelectorAll("li.has-children");
  liWithChildren.forEach((parentLi) => {
    const parentNode = getOrgChartDirectNodeElement(parentLi);
    const childList = Array.from(parentLi.children).find((child) => child && child.tagName === "UL");
    if (!parentNode || !childList) {
      return;
    }
    const childItems = Array.from(childList.children).filter((child) => child && child.tagName === "LI");
    if (!childItems.length) {
      return;
    }
    const childNodes = childItems
      .map((childLi) => getOrgChartDirectNodeElement(childLi))
      .filter(Boolean);
    if (!childNodes.length) {
      return;
    }

    const parentRect = parentNode.getBoundingClientRect();
    const parentX = parentRect.left - wrapRect.left + wrap.scrollLeft + parentRect.width / 2;
    const parentY = parentRect.bottom - wrapRect.top + wrap.scrollTop;

    const childAnchors = childNodes.map((childNode) => {
      const rect = childNode.getBoundingClientRect();
      return {
        x: rect.left - wrapRect.left + wrap.scrollLeft + rect.width / 2,
        y: rect.top - wrapRect.top + wrap.scrollTop,
      };
    });

    if (childAnchors.length === 1) {
      const only = childAnchors[0];
      svg.appendChild(createOrgChartSvgLine(parentX, parentY, only.x, only.y, stroke, strokeWidth));
      return;
    }

    const minChildX = Math.min(...childAnchors.map((entry) => entry.x));
    const maxChildX = Math.max(...childAnchors.map((entry) => entry.x));
    const minChildY = Math.min(...childAnchors.map((entry) => entry.y));
    const branchY = Math.max(parentY + 14, minChildY - 16);

    svg.appendChild(createOrgChartSvgLine(parentX, parentY, parentX, branchY, stroke, strokeWidth));
    svg.appendChild(createOrgChartSvgLine(minChildX, branchY, maxChildX, branchY, stroke, strokeWidth));
    childAnchors.forEach((anchor) => {
      svg.appendChild(createOrgChartSvgLine(anchor.x, branchY, anchor.x, anchor.y, stroke, strokeWidth));
    });
  });

  wrap.appendChild(svg);
}

function renderOrgChartDepartmentFilterOptions(selectedValue = orgChartDepartmentFilter) {
  if (!els.orgChartDepartmentFilter) {
    return;
  }
  const departments = getDepartments();
  const options = ['<option value="all">Alle Abteilungen</option>'].concat(
    departments.map((entry) => `<option value="${escapeHtml(entry.id)}">${escapeHtml(entry.name)}</option>`)
  );
  els.orgChartDepartmentFilter.innerHTML = options.join("");
  const normalizedValue = normalizeOrgChartDepartmentFilter(selectedValue);
  const exists = normalizedValue === "all" || departments.some((entry) => entry.id === normalizedValue);
  els.orgChartDepartmentFilter.value = exists ? normalizedValue : "all";
}

function openOrgChartEditModal(userId) {
  if (!isRoleAdmin()) {
    return;
  }
  const normalizedUserId = normalizeUserId(userId);
  if (!normalizedUserId) {
    return;
  }
  const users = getOrgChartManagedUsers();
  const selectedUser = users.find((entry) => entry.userId === normalizedUserId) || null;
  if (!selectedUser) {
    return;
  }
  const profile = getEmployeeProfileByUserId(normalizedUserId);
  const departments = getDepartments();
  orgChartEditUserId = normalizedUserId;
  orgChartEditModalOpen = true;

  if (els.orgChartEditTitle) {
    els.orgChartEditTitle.textContent = `Organigramm: ${selectedUser.name}`;
  }
  if (els.orgChartEditName) {
    els.orgChartEditName.value = selectedUser.name;
  }
  if (els.orgChartEditDepartment) {
    const options = ['<option value="">Keine Zuordnung</option>'].concat(
      departments.map((entry) => `<option value="${escapeHtml(entry.id)}">${escapeHtml(entry.name)}</option>`)
    );
    els.orgChartEditDepartment.innerHTML = options.join("");
    const departmentId = sanitizeEmployeeDepartmentValue(profile.department, departments);
    const exists = !departmentId || departments.some((entry) => entry.id === departmentId);
    if (departmentId && !exists) {
      els.orgChartEditDepartment.insertAdjacentHTML(
        "beforeend",
        `<option value="${escapeHtml(departmentId)}">${escapeHtml(getDepartmentLabelByValue(departmentId, departments))}</option>`
      );
    }
    els.orgChartEditDepartment.value = departmentId || "";
  }
  if (els.orgChartEditPosition) {
    els.orgChartEditPosition.value = profile.position || "";
  }
  if (els.orgChartEditManager) {
    const managerOptions = users
      .filter((entry) => entry.userId !== normalizedUserId)
      .map((entry) => `<option value="${escapeHtml(entry.userId)}">${escapeHtml(entry.name)}</option>`);
    els.orgChartEditManager.innerHTML = ['<option value="">Keine Zuordnung (Top-Level)</option>', ...managerOptions].join("");
    const managerId = normalizeUserId(profile.managerUserId || "");
    const exists = managerId && users.some((entry) => entry.userId === managerId && entry.userId !== normalizedUserId);
    els.orgChartEditManager.value = exists ? managerId : "";
  }
  if (els.orgChartEditModal) {
    els.orgChartEditModal.classList.remove("hidden");
  }
  syncBodyModalOpenState();
  if (els.orgChartEditPosition) {
    window.setTimeout(() => {
      els.orgChartEditPosition.focus({ preventScroll: true });
    }, 0);
  }
}

async function handleOrgChartEditSave(event) {
  const selectedUserId = normalizeUserId(orgChartEditUserId);
  if (!selectedUserId) {
    return;
  }
  const submitter = event.submitter instanceof HTMLElement ? event.submitter : null;
  setActionButtonBusy(submitter, true, "Speichert...");
  try {
    const formData = new FormData(event.currentTarget);
    const profile = getEmployeeProfileByUserId(selectedUserId);
    const managerUserId = normalizeUserId(formData.get("managerUserId") || "");
    const nextProfile = {
      ...profile,
      department: sanitizeEmployeeDepartmentValue(formData.get("department"), getDepartments()),
      position: String(formData.get("position") || "").trim(),
      managerUserId: managerUserId && managerUserId !== selectedUserId ? managerUserId : "",
    };
    setEmployeeProfileByUserId(selectedUserId, nextProfile);
    saveState({ showFeedback: false });
    closeOrgChartEditModal();
    renderOrgChartSection();
    renderEmployeeAdminSection();
    showSuccessFeedback("Organigramm aktualisiert.");
  } finally {
    setActionButtonBusy(submitter, false);
  }
}

function renderOrgChartSection() {
  if (!els.orgChartBoard) {
    return;
  }
  if (els.orgChartSearchInput && els.orgChartSearchInput.value !== orgChartSearchTerm) {
    els.orgChartSearchInput.value = orgChartSearchTerm;
  }
  renderOrgChartDepartmentFilterOptions(orgChartDepartmentFilter);

  const canAccess = isRoleAdmin();
  if (!canAccess) {
    closeOrgChartEditModal();
    closeOrgChartInfoModal();
    els.orgChartBoard.innerHTML = "";
    if (els.orgChartEmpty) {
      els.orgChartEmpty.classList.remove("hidden");
      els.orgChartEmpty.textContent = "Nur Admin und Superadmin können das Organigramm sehen.";
    }
    return;
  }

  const managementDepartment = getOrgChartManagementDepartment();
  const { entries } = buildOrgChartEntries();
  const normalizedSearch = normalizeText(orgChartSearchTerm);
  const normalizedDepartmentFilter = normalizeOrgChartDepartmentFilter(orgChartDepartmentFilter);
  const showManagementByFilter =
    !!managementDepartment &&
    (normalizedDepartmentFilter === "all" || normalizedDepartmentFilter === managementDepartment.id);
  const showManagementBySearch =
    !!managementDepartment &&
    (!normalizedSearch || normalizeText(managementDepartment.name || "").includes(normalizedSearch));
  const hasManagementMember =
    !!managementDepartment && entries.some((entry) => entry.departmentId === managementDepartment.id);
  const showManagementTopPlaceholder = Boolean(
    managementDepartment && !hasManagementMember && showManagementByFilter && showManagementBySearch
  );
  const visibleEntries = entries.filter((entry) => {
    const matchesDepartment = normalizedDepartmentFilter === "all" || entry.departmentId === normalizedDepartmentFilter;
    if (!matchesDepartment) {
      return false;
    }
    if (!normalizedSearch) {
      return true;
    }
    const haystack = normalizeText(
      [
        entry.name,
        entry.email,
        entry.position,
        entry.departmentLabel,
        getRoleLabel(entry.role),
        entry.location,
        entry.responsibility,
      ].join(" ")
    );
    return haystack.includes(normalizedSearch);
  });

  if (!entries.length) {
    if (showManagementTopPlaceholder) {
      els.orgChartBoard.innerHTML = renderOrgChartTopDepartmentPlaceholder(managementDepartment, { standalone: true });
      if (els.orgChartEmpty) {
        els.orgChartEmpty.classList.add("hidden");
        els.orgChartEmpty.textContent = "";
      }
      return;
    }
    els.orgChartBoard.innerHTML = "";
    if (els.orgChartEmpty) {
      els.orgChartEmpty.classList.remove("hidden");
      els.orgChartEmpty.textContent = "Noch keine Mitarbeiterprofile vorhanden.";
    }
    return;
  }
  if (!visibleEntries.length) {
    if (showManagementTopPlaceholder) {
      els.orgChartBoard.innerHTML = renderOrgChartTopDepartmentPlaceholder(managementDepartment, { standalone: true });
      if (els.orgChartEmpty) {
        els.orgChartEmpty.classList.add("hidden");
        els.orgChartEmpty.textContent = "";
      }
      return;
    }
    els.orgChartBoard.innerHTML = "";
    if (els.orgChartEmpty) {
      els.orgChartEmpty.classList.remove("hidden");
      els.orgChartEmpty.textContent = "Keine Treffer für die aktuelle Filterung.";
    }
    return;
  }

  const visibleUserIdSet = new Set(visibleEntries.map((entry) => entry.userId));
  const visibleForTree = visibleEntries.map((entry) => ({
    ...entry,
    managerUserId: visibleUserIdSet.has(entry.managerUserId) ? entry.managerUserId : "",
  }));
  const childMap = buildOrgChartTreeMap(visibleForTree);
  const roots = childMap.has("")
    ? childMap.get("")
    : [];
  const safeRoots = roots && roots.length
    ? roots
    : visibleForTree.slice().sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "de"));
  const renderedUserIds = new Set();
  const treeMarkup = safeRoots
    .map((entry) => renderOrgChartTreeNode(entry, childMap, new Set(), renderedUserIds))
    .filter(Boolean)
    .join("");
  const orphanMarkup = visibleForTree
    .filter((entry) => !renderedUserIds.has(entry.userId))
    .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "de"))
    .map((entry) => renderOrgChartTreeNode(entry, childMap, new Set(), renderedUserIds))
    .filter(Boolean)
    .join("");

  const topPlaceholderMarkup = showManagementTopPlaceholder
    ? renderOrgChartTopDepartmentPlaceholder(managementDepartment)
    : "";

  els.orgChartBoard.innerHTML = `
    ${topPlaceholderMarkup}
    <div class="orgchart-graph-wrap">
      <ul class="orgchart-tree orgchart-tree--svg">
        ${treeMarkup}${orphanMarkup}
      </ul>
    </div>
  `;
  alignOrgChartRootNode();
  drawOrgChartConnectors();

  if (els.orgChartEmpty) {
    els.orgChartEmpty.classList.add("hidden");
    els.orgChartEmpty.textContent = "";
  }
}

function getEmploymentTypeLabel(type) {
  const normalizedType = sanitizeEmployeeAdminSelectValue(type, EMPLOYEE_EMPLOYMENT_TYPE_OPTIONS);
  const labels = {
    vollzeit: "Vollzeit",
    teilzeit: "Teilzeit",
    freelance: "Freelance",
    praktikum: "Praktikum",
    geringfugig: "Geringfügig",
    werksvertrag: "Werksvertrag",
    extern: "Extern",
  };
  return labels[normalizedType] || "Zusatzfelder";
}

function syncWerksvertragProvisionFieldsForForm(formElement, canEdit = true) {
  if (!formElement) {
    return;
  }
  const billingTypeField = formElement.elements?.employmentDetailWerksvertragBillingType;
  const normalizedBillingType = normalizeText(billingTypeField?.value || "");
  const isProvisionMode = normalizedBillingType === "provision";
  const provisionFieldSet = new Set(EMPLOYEE_WERKSVERTRAG_PROVISION_REQUIRED_FIELDS);
  formElement.querySelectorAll("[data-werksvertrag-provision-fields]").forEach((container) => {
    const field = container.querySelector("input, select, textarea");
    const fieldName = String(field?.name || "").trim();
    const canUseField = canEdit && isProvisionMode && provisionFieldSet.has(fieldName);
    container.classList.toggle("hidden", !canUseField);
    if (!field) {
      return;
    }
    field.disabled = !canUseField;
    field.required = canUseField;
  });
}

function syncEmploymentDetailsVisibilityForForm({
  formElement = null,
  detailsElement = null,
  titleElement = null,
  typeValue = "",
  canEdit = true,
} = {}) {
  if (!formElement || !detailsElement) {
    return;
  }
  const normalizedType = sanitizeEmployeeAdminSelectValue(typeValue, EMPLOYEE_EMPLOYMENT_TYPE_OPTIONS);
  const matchingPanel = normalizedType ? formElement.querySelector(`[data-employment-type-panel="${normalizedType}"]`) : null;
  const hasVisiblePanel = !!matchingPanel;
  detailsElement.classList.toggle("hidden", !hasVisiblePanel);
  if (titleElement) {
    titleElement.textContent = hasVisiblePanel ? `Zusatzfelder: ${getEmploymentTypeLabel(normalizedType)}` : "Zusatzfelder";
  }
  const activeTypeFields = new Set(EMPLOYEE_EMPLOYMENT_DETAIL_FIELDS[normalizedType] || []);
  const requiredTypeFields = new Set(EMPLOYEE_EMPLOYMENT_REQUIRED_DETAIL_FIELDS[normalizedType] || []);
  formElement.querySelectorAll("[data-employment-type-panel]").forEach((panel) => {
    const isActive = panel === matchingPanel;
    panel.classList.toggle("hidden", !isActive);
    panel.querySelectorAll("input, select, textarea").forEach((field) => {
      const fieldName = String(field.name || "").trim();
      const isRelevantField = isActive && activeTypeFields.has(fieldName);
      field.disabled = !canEdit || !isRelevantField;
      field.required = canEdit && isRelevantField && requiredTypeFields.has(fieldName);
    });
  });
  if (normalizedType === "werksvertrag") {
    syncWerksvertragProvisionFieldsForForm(formElement, canEdit);
  } else {
    formElement.querySelectorAll("[data-werksvertrag-provision-fields]").forEach((container) => {
      container.classList.add("hidden");
      const field = container.querySelector("input, select, textarea");
      if (!field) {
        return;
      }
      field.required = false;
      field.disabled = true;
    });
  }
}

function syncEmployeeEmploymentDetailsVisibility(typeValue = "", canEdit = true) {
  syncEmploymentDetailsVisibilityForForm({
    formElement: els.employeeAdminForm,
    detailsElement: els.employeeAdminEmploymentDetails,
    titleElement: els.employeeAdminEmploymentDetailsTitle,
    typeValue,
    canEdit,
  });
}

function syncUserEmploymentDetailsVisibility(typeValue = "", canEdit = true) {
  syncEmploymentDetailsVisibilityForForm({
    formElement: els.userForm,
    detailsElement: els.userEmploymentDetails,
    titleElement: els.userEmploymentDetailsTitle,
    typeValue,
    canEdit,
  });
}

function applyEmployeeEmploymentDetailsToForm(profile, formElement = els.employeeAdminForm) {
  if (!formElement) {
    return;
  }
  const details = normalizeEmployeeEmploymentDetailsRecord(profile?.employmentDetails || {});
  EMPLOYEE_EMPLOYMENT_DETAIL_KEYS.forEach((key) => {
    const field = formElement.elements?.[key];
    if (!field || typeof field.value !== "string") {
      return;
    }
    field.value = details[key] || "";
  });
}

function readEmployeeEmploymentDetailsFromForm(formData) {
  const details = createEmptyEmployeeEmploymentDetailsRecord();
  EMPLOYEE_EMPLOYMENT_DETAIL_KEYS.forEach((key) => {
    details[key] = normalizeEmployeeEmploymentDetailValue(formData.get(key));
  });
  return details;
}

function renderEmployeeAdminTaskList(userId, options = {}) {
  if (!els.employeeAdminTaskList) {
    return;
  }
  const readOnly = options?.readOnly === true;
  const tasks = getEmployeeTasksByUserId(userId).sort((left, right) => {
    if (!!left.done !== !!right.done) {
      return left.done ? 1 : -1;
    }
    const leftDue = left.dueDate || "9999-12-31";
    const rightDue = right.dueDate || "9999-12-31";
    if (leftDue !== rightDue) {
      return leftDue.localeCompare(rightDue);
    }
    return String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
  });

  if (!tasks.length) {
    els.employeeAdminTaskList.innerHTML = '<li class="empty">Noch keine Aufgaben für diesen Mitarbeiter.</li>';
    return;
  }

  els.employeeAdminTaskList.innerHTML = tasks
    .map((task) => {
      const taskId = String(task.id || "").trim();
      const dueLabel = task.dueDate ? `Fällig: ${formatEmployeeAdminDate(task.dueDate)}` : "Ohne Fälligkeit";
      return `
        <li class="employee-admin-task-item ${task.done ? "done" : ""}">
          <label class="employee-admin-task-check">
            <input
              type="checkbox"
              data-employee-task-toggle="${escapeHtml(taskId)}"
              ${task.done ? "checked" : ""}
              ${readOnly ? "disabled" : ""}
            />
            <span>${escapeHtml(task.title)}</span>
          </label>
          <div class="employee-admin-task-meta">
            <small>${escapeHtml(dueLabel)}</small>
            <button
              type="button"
              class="mini-btn danger"
              title="Aufgabe löschen"
              aria-label="Aufgabe löschen"
              data-employee-task-delete="${escapeHtml(taskId)}"
              ${readOnly ? "disabled" : ""}
            >✕</button>
          </div>
        </li>
      `;
    })
    .join("");
}

function setFormElementValue(formElements, fieldName, nextValue) {
  const field = formElements?.[fieldName];
  if (!field || typeof field.value !== "string") {
    return;
  }
  field.value = String(nextValue ?? "");
}

function renderEmployeeAdminSection() {
  if (!els.employeeAdminTableBody || !els.employeeAdminForm) {
    return;
  }
  setEmployeeAdminFormTab(employeeAdminFormTab);
  if (els.employeeAdminSearchInput && els.employeeAdminSearchInput.value !== employeeAdminSearchTerm) {
    els.employeeAdminSearchInput.value = employeeAdminSearchTerm;
  }
  const currentUser = getCurrentUser();
  const canManage = canCurrentUserEditEmployeeAdmin(currentUser);
  const showLoginAudit = isSuperAdmin(currentUser);
  document.querySelectorAll("[data-superadmin-login-audit]").forEach((element) => {
    element.classList.toggle("hidden", !showLoginAudit);
  });
  const users = getEmployeeAdminVisibleUsers(currentUser);
  if (els.employeeAdminSearchInput) {
    els.employeeAdminSearchInput.disabled = !canManage;
    if (!canManage) {
      employeeAdminSearchTerm = "";
      els.employeeAdminSearchInput.value = "";
    }
  }
  ensureEmployeeAdminSelection();
  const normalizedSearchTerm = normalizeText(employeeAdminSearchTerm);
  const filteredUsers = users.filter((entry) => {
    if (!canManage) {
      return true;
    }
    if (!normalizedSearchTerm) {
      return true;
    }
    const profile = getEmployeeProfileByUserId(entry.userId);
    const departmentLabel = getDepartmentLabelByValue(profile.department);
    const haystack = normalizeText(
      [
        entry.name,
        entry.email,
        departmentLabel,
        profile.department,
        profile.position,
        profile.location,
        profile.street,
        profile.postalCode,
        profile.city,
        profile.country,
        profile.phone,
        profile.email,
        profile.responsibility,
        profile.hrStatus,
      ].join(" ")
    );
    return haystack.includes(normalizedSearchTerm);
  });

  if (!users.length) {
    const emptyMessage = canManage
      ? "Keine Mitarbeiterprofile vorhanden."
      : "Kein eigenes Mitarbeiterprofil gefunden.";
    els.employeeAdminTableBody.innerHTML = `<tr><td colspan="${showLoginAudit ? 8 : 7}" class="empty">${escapeHtml(emptyMessage)}</td></tr>`;
  } else if (!filteredUsers.length) {
    els.employeeAdminTableBody.innerHTML =
      `<tr><td colspan="${showLoginAudit ? 8 : 7}" class="empty">Keine Mitarbeiter für die Suche gefunden.</td></tr>`;
  } else {
    els.employeeAdminTableBody.innerHTML = filteredUsers
      .map((entry) => {
        const profile = getEmployeeProfileByUserId(entry.userId);
        const departmentLabel = getDepartmentLabelByValue(profile.department) || "–";
        const isActiveRow = entry.userId === employeeAdminSelectedUserId;
        const statusLabel = profile.hrStatus
          ? profile.hrStatus.charAt(0).toUpperCase() + profile.hrStatus.slice(1)
          : "Aktiv";
        const provisionOverrideEnabled = hasEmployeeProvisionOverride(entry.userId, entry.email);
        const provisionRate = getEmployeeRateByUserId(entry.userId, entry.email);
        const provisionLabel = provisionOverrideEnabled
          ? `Override ${formatEuroAmount(provisionRate)}`
          : `Standard ${formatEuroAmount(provisionRate)}`;
        const openTaskCount = getOpenEmployeeTaskCountByUserId(entry.userId);
        const lastLoginAt = getEmployeeLastLoginAtByUserId(entry.userId);
        return `
          <tr class="${isActiveRow ? "employee-admin-row-active" : ""}">
            <td>
              <button
                type="button"
                class="employee-admin-select-btn"
                data-employee-admin-select="${escapeHtml(entry.userId)}"
              >
                ${escapeHtml(entry.name)}
              </button>
              <small>${escapeHtml(entry.email || "–")}</small>
            </td>
            <td>${escapeHtml(departmentLabel)}</td>
            <td>${escapeHtml(profile.position || "–")}</td>
            <td>${escapeHtml(profile.location || "–")}</td>
            <td>${escapeHtml(statusLabel)}</td>
            ${
              showLoginAudit
                ? `<td class="superadmin-login-audit-column">${escapeHtml(
                    lastLoginAt ? formatDateTime(lastLoginAt) : "Noch nie"
                  )}</td>`
                : ""
            }
            <td>${escapeHtml(provisionLabel)}</td>
            <td>${escapeHtml(String(openTaskCount))}</td>
          </tr>
        `;
      })
      .join("");
  }

  if (els.employeeAdminEmpty) {
    els.employeeAdminEmpty.classList.add("hidden");
    els.employeeAdminEmpty.textContent = "";
  }

  const selectedUser = users.find((entry) => entry.userId === employeeAdminSelectedUserId) || null;
  if (!selectedUser) {
    setFormControlsDisabled(els.employeeAdminForm, true);
    if (els.employeeAdminSelectedTitle) {
      els.employeeAdminSelectedTitle.textContent = "Mitarbeiter wählen";
    }
    els.employeeAdminForm.reset();
    renderEmployeeAdminDepartmentOptions("");
    renderEmployeeAdminManagerOptions("", "");
    if (els.employeeAdminTaskInput) {
      els.employeeAdminTaskInput.value = "";
      els.employeeAdminTaskInput.disabled = true;
    }
    if (els.employeeAdminTaskDue) {
      els.employeeAdminTaskDue.value = "";
      els.employeeAdminTaskDue.disabled = true;
    }
    if (els.employeeAdminTaskAddBtn) {
      els.employeeAdminTaskAddBtn.disabled = true;
    }
    if (els.employeeAdminTaskList) {
      els.employeeAdminTaskList.innerHTML = '<li class="empty">Bitte zuerst einen Mitarbeiter auswählen.</li>';
    }
    if (els.employeeAdminHonorariumEnabled) {
      els.employeeAdminHonorariumEnabled.checked = false;
      els.employeeAdminHonorariumEnabled.disabled = true;
    }
    if (els.employeeAdminHonorariumRate) {
      els.employeeAdminHonorariumRate.value = "0.00";
      els.employeeAdminHonorariumRate.disabled = true;
    }
    if (els.employeeAdminHonorariumHint) {
      els.employeeAdminHonorariumHint.textContent =
        "Provision für den ausgewählten Mitarbeiter hinterlegen.";
    }
    if (els.employeeAdminHonorariumField) {
      els.employeeAdminHonorariumField.classList.remove("hidden");
    }
    if (els.employeeAdminProvisionQuick) {
      els.employeeAdminProvisionQuick.innerHTML = '<p class="matrix-info">Mitarbeiter auswählen, um Provision und Provisions-Log zu sehen.</p>';
    }
    renderProvisionLogForUser("", els.employeeAdminProvisionLogMeta, els.employeeAdminProvisionLogList);
    syncEmployeeAdminHonorariumFieldState();
    employeeAdminResponsibilityDraft = [];
    if (els.employeeAdminResponsibilityInput) {
      els.employeeAdminResponsibilityInput.value = "";
      els.employeeAdminResponsibilityInput.disabled = true;
    }
    renderEmployeeAdminResponsibilityTags();
    syncEmployeeEmploymentDetailsVisibility("");
    return;
  }

  const profile = getEmployeeProfileByUserId(selectedUser.userId);
  const canEditSelectedUser = canCurrentUserEditEmployeeAdminUser(selectedUser.userId, currentUser);
  setFormControlsDisabled(els.employeeAdminForm, !canEditSelectedUser);
  if (!canEditSelectedUser) {
    els.employeeAdminFormTabButtons?.forEach((button) => {
      if (button instanceof HTMLButtonElement) {
        button.disabled = false;
      }
    });
  }
  if (els.employeeAdminSelectedTitle) {
    els.employeeAdminSelectedTitle.textContent =
      `${selectedUser.name} · ${getRoleLabel(selectedUser.role)} (${selectedUser.statusLabel || "aktiv"})`;
  }
  const formElements = els.employeeAdminForm.elements;
  const normalizedDepartmentValue = sanitizeEmployeeDepartmentValue(profile.department, getDepartments());
  renderEmployeeAdminDepartmentOptions(normalizedDepartmentValue);
  setFormElementValue(formElements, "department", normalizedDepartmentValue);
  setFormElementValue(
    formElements,
    "markerColor",
    sanitizeEmployeeMarkerColorValue(profile.markerColor) || getEmployeeMarkerColorByUserId(selectedUser.userId, selectedUser.name)
  );
  setFormElementValue(formElements, "position", profile.position || "");
  setFormElementValue(formElements, "location", profile.location || "");
  setFormElementValue(formElements, "birthDate", profile.birthDate || "");
  setFormElementValue(formElements, "street", profile.street || "");
  setFormElementValue(formElements, "postalCode", profile.postalCode || "");
  setFormElementValue(formElements, "city", profile.city || "");
  setFormElementValue(formElements, "country", profile.country || "");
  setFormElementValue(formElements, "email", profile.email || selectedUser.email || "");
  setFormElementValue(formElements, "phone", profile.phone || "");
  setFormElementValue(formElements, "employmentType", profile.employmentType || "");
  setFormElementValue(formElements, "workModel", profile.workModel || "");
  setFormElementValue(formElements, "startDate", profile.startDate || "");
  setFormElementValue(formElements, "nextReviewDate", profile.nextReviewDate || "");
  setFormElementValue(formElements, "hrStatus", profile.hrStatus || "aktiv");
  employeeAdminResponsibilityDraft = normalizeResponsibilityItems(profile.responsibility || "");
  if (els.employeeAdminResponsibilityInput) {
    els.employeeAdminResponsibilityInput.value = "";
    els.employeeAdminResponsibilityInput.disabled = !canEditSelectedUser;
  }
  renderEmployeeAdminResponsibilityTags();
  setFormElementValue(formElements, "notes", profile.notes || "");
  applyEmployeeEmploymentDetailsToForm(profile);
  syncEmployeeEmploymentDetailsVisibility(profile.employmentType || "", canEditSelectedUser);
  renderEmployeeAdminManagerOptions(selectedUser.userId, profile.managerUserId || "");

  if (els.employeeAdminHonorariumEnabled) {
    els.employeeAdminHonorariumEnabled.checked = isEmployeeHonorariumEnabled(selectedUser.userId, selectedUser.email);
    els.employeeAdminHonorariumEnabled.disabled = !canEditSelectedUser;
  }
  if (els.employeeAdminHonorariumRate) {
    els.employeeAdminHonorariumRate.value = formatRateInputValue(
      getEmployeeRateByUserId(selectedUser.userId, selectedUser.email)
    );
  }
  if (els.employeeAdminHonorariumHint) {
    if (!canEditSelectedUser) {
      els.employeeAdminHonorariumHint.textContent = "Nur Admin/Superadmin dürfen Provision ändern.";
    } else {
      els.employeeAdminHonorariumHint.textContent =
        `Standard-Provision ${formatEuroAmount(getDefaultProvisionRate())}. Mit aktivem Override wird der individuelle Satz genutzt.`;
    }
  }
  if (els.employeeAdminHonorariumField) {
    els.employeeAdminHonorariumField.classList.remove("hidden");
  }
  if (els.employeeAdminProvisionQuick) {
    const provisionOverrideEnabled = hasEmployeeProvisionOverride(selectedUser.userId, selectedUser.email);
    const provisionRate = getEmployeeRateByUserId(selectedUser.userId, selectedUser.email);
    const statusLabel = provisionOverrideEnabled ? "Override aktiv" : "Standard aktiv";
    els.employeeAdminProvisionQuick.innerHTML = `
      <article class="employee-admin-provision-quick-card">
        <strong>Provision: ${escapeHtml(statusLabel)}</strong>
        <span>Wert je LIVE: ${escapeHtml(formatEuroAmount(provisionRate))}</span>
      </article>
    `;
  }
  renderProvisionLogForUser(
    selectedUser.userId,
    els.employeeAdminProvisionLogMeta,
    els.employeeAdminProvisionLogList
  );
  syncEmployeeAdminHonorariumFieldState();

  if (els.employeeAdminTaskInput) {
    els.employeeAdminTaskInput.disabled = !canEditSelectedUser;
  }
  if (els.employeeAdminTaskDue) {
    els.employeeAdminTaskDue.disabled = !canEditSelectedUser;
  }
  if (els.employeeAdminTaskAddBtn) {
    els.employeeAdminTaskAddBtn.disabled = !canEditSelectedUser;
  }
  renderEmployeeAdminTaskList(selectedUser.userId, { readOnly: !canEditSelectedUser });
}

async function handleEmployeeAdminProfileSave(event) {
  const selectedUserId = normalizeUserId(employeeAdminSelectedUserId);
  if (!selectedUserId) {
    return;
  }
  if (!canCurrentUserEditEmployeeAdminUser(selectedUserId)) {
    showWarningFeedback("Nur Admin und Superadmin dürfen Mitarbeiterdaten bearbeiten.");
    return;
  }
  const submitter = event.submitter instanceof HTMLElement ? event.submitter : null;
  setActionButtonBusy(submitter, true, "Speichert...");
  try {
    addEmployeeAdminResponsibilityFromInput();
    const formData = new FormData(event.currentTarget);
    setEmployeeProfileByUserId(selectedUserId, {
      department: formData.get("department"),
      markerColor: formData.get("markerColor"),
      position: formData.get("position"),
      location: formData.get("location"),
      birthDate: formData.get("birthDate"),
      street: formData.get("street"),
      postalCode: formData.get("postalCode"),
      city: formData.get("city"),
      country: formData.get("country"),
      email: formData.get("email"),
      phone: formData.get("phone"),
      managerUserId: formData.get("managerUserId"),
      employmentType: formData.get("employmentType"),
      employmentDetails: readEmployeeEmploymentDetailsFromForm(formData),
      workModel: formData.get("workModel"),
      startDate: formData.get("startDate"),
      nextReviewDate: formData.get("nextReviewDate"),
      hrStatus: formData.get("hrStatus"),
      responsibility: formData.get("responsibility"),
      notes: formData.get("notes"),
    });
    applyEmployeeHonorariumFromPayload(
      selectedUserId,
      {
        honorariumEnabled: Boolean(formData.get("honorariumEnabled")),
        honorariumRate: String(formData.get("honorariumRate") || "").trim(),
      },
      String(formData.get("email") || "")
    );
    saveState({ showFeedback: false });
    renderEmployeeAdminSection();
    renderOrgChartSection();
    showSuccessFeedback("Mitarbeiter-Stammdaten gespeichert.");
  } finally {
    setActionButtonBusy(submitter, false);
  }
}

function handleEmployeeAdminTaskAdd() {
  const selectedUserId = normalizeUserId(employeeAdminSelectedUserId);
  if (!selectedUserId) {
    return;
  }
  if (!canCurrentUserEditEmployeeAdminUser(selectedUserId)) {
    showWarningFeedback("Nur Admin und Superadmin dürfen Aufgaben ändern.");
    return;
  }
  const title = String(els.employeeAdminTaskInput?.value || "").trim();
  if (!title) {
    return;
  }
  const dueDate = sanitizeEmployeeAdminDate(els.employeeAdminTaskDue?.value || "");
  const currentTasks = getEmployeeTasksByUserId(selectedUserId);
  currentTasks.push({
    id: createId("etask"),
    title,
    dueDate,
    done: false,
    createdAt: new Date().toISOString(),
  });
  setEmployeeTasksByUserId(selectedUserId, currentTasks);
  saveState({ showFeedback: false });
  if (els.employeeAdminTaskInput) {
    els.employeeAdminTaskInput.value = "";
  }
  if (els.employeeAdminTaskDue) {
    els.employeeAdminTaskDue.value = "";
  }
  renderEmployeeAdminSection();
  showSuccessFeedback("Aufgabe hinzugefügt.");
}

function handleEmployeeAdminTaskToggle(taskId, done) {
  const selectedUserId = normalizeUserId(employeeAdminSelectedUserId);
  if (!selectedUserId) {
    return;
  }
  if (!canCurrentUserEditEmployeeAdminUser(selectedUserId)) {
    showWarningFeedback("Nur Admin und Superadmin dürfen Aufgaben ändern.");
    return;
  }
  const normalizedTaskId = String(taskId || "").trim();
  if (!normalizedTaskId) {
    return;
  }
  const currentTasks = getEmployeeTasksByUserId(selectedUserId);
  const nextTasks = currentTasks.map((entry) =>
    String(entry.id || "").trim() === normalizedTaskId ? { ...entry, done: !!done } : entry
  );
  setEmployeeTasksByUserId(selectedUserId, nextTasks);
  saveState({ showFeedback: false });
  renderEmployeeAdminSection();
  showSuccessFeedback(done ? "Aufgabe als erledigt markiert." : "Aufgabe wieder geöffnet.");
}

function handleEmployeeAdminTaskDelete(taskId) {
  const selectedUserId = normalizeUserId(employeeAdminSelectedUserId);
  if (!selectedUserId) {
    return;
  }
  if (!canCurrentUserEditEmployeeAdminUser(selectedUserId)) {
    showWarningFeedback("Nur Admin und Superadmin dürfen Aufgaben ändern.");
    return;
  }
  const normalizedTaskId = String(taskId || "").trim();
  if (!normalizedTaskId) {
    return;
  }
  const currentTasks = getEmployeeTasksByUserId(selectedUserId);
  const nextTasks = currentTasks.filter((entry) => String(entry.id || "").trim() !== normalizedTaskId);
  setEmployeeTasksByUserId(selectedUserId, nextTasks);
  saveState({ showFeedback: false });
  renderEmployeeAdminSection();
  showSuccessFeedback("Aufgabe gelöscht.");
}

function sanitizeConversationContactType(value) {
  const normalized = normalizeText(value || "");
  return CONVERSATION_CONTACT_TYPES.has(normalized) ? normalized : "extern";
}

function sanitizeConversationChannel(value) {
  const normalized = normalizeText(value || "");
  return CONVERSATION_CHANNEL_TYPES.has(normalized) ? normalized : "meeting";
}

function getConversationChannelLabel(channel) {
  const normalized = sanitizeConversationChannel(channel);
  if (normalized === "telefon") {
    return "Telefon";
  }
  if (normalized === "email") {
    return "E-Mail";
  }
  if (normalized === "whatsapp") {
    return "WhatsApp";
  }
  if (normalized === "sonstiges") {
    return "Sonstiges";
  }
  return "Meeting";
}

function sanitizeConversationTaskStatus(value) {
  const normalized = normalizeText(value || "");
  return CONVERSATION_TASK_STATUSES.has(normalized) ? normalized : "offen";
}

function sanitizeConversationTaskPriority(value) {
  const normalized = normalizeText(value || "");
  return CONVERSATION_TASK_PRIORITIES.has(normalized) ? normalized : "mittel";
}

function sanitizeConversationTaskAssigneeType(value) {
  const normalized = normalizeText(value || "");
  return CONVERSATION_TASK_ASSIGNEE_TYPES.has(normalized) ? normalized : "employee";
}

function sanitizeConversationDate(value) {
  return sanitizeEmployeeAdminDate(value);
}

function getConversationTaskStatusLabel(status) {
  const normalized = sanitizeConversationTaskStatus(status);
  if (normalized === "in_arbeit") {
    return "In Arbeit";
  }
  if (normalized === "warten") {
    return "Warten";
  }
  if (normalized === "erledigt") {
    return "Erledigt";
  }
  return "Offen";
}

function getConversationTaskPriorityLabel(priority) {
  const normalized = sanitizeConversationTaskPriority(priority);
  if (normalized === "hoch") {
    return "Hoch";
  }
  if (normalized === "niedrig") {
    return "Niedrig";
  }
  return "Mittel";
}

function getConversationTaskAssigneeTypeLabel(type) {
  return sanitizeConversationTaskAssigneeType(type) === "organization" ? "Organisation" : "Mitarbeiter";
}

function isConversationTaskOverdue(task) {
  if (!task || sanitizeConversationTaskStatus(task.status) === "erledigt") {
    return false;
  }
  const dueDate = sanitizeConversationDate(task.dueDate);
  if (!dueDate) {
    return false;
  }
  const today = getTodayDateInputValue();
  return dueDate < today;
}

function decodeConversationTaskAssigneeStorage(rawValue) {
  const raw = String(rawValue || "").trim();
  const lowerRaw = raw.toLowerCase();
  if (lowerRaw.startsWith("org:")) {
    const organizationId = raw.slice(4).trim();
    return {
      assigneeType: "organization",
      assigneeUserId: "",
      assigneeOrganizationId: organizationId,
    };
  }
  return {
    assigneeType: "employee",
    assigneeUserId: normalizeUserId(raw),
    assigneeOrganizationId: "",
  };
}

function encodeConversationTaskAssigneeStorage(task) {
  const assigneeType = sanitizeConversationTaskAssigneeType(task?.assigneeType || task?.assignee_type || "");
  const assigneeOrganizationId = String(task?.assigneeOrganizationId || task?.assignee_organization_id || "").trim();
  const assigneeUserId = normalizeUserId(task?.assigneeUserId || task?.assignee_user_id || "");
  if (assigneeType === "organization") {
    return assigneeOrganizationId ? `org:${assigneeOrganizationId}` : "";
  }
  return assigneeUserId;
}

function resolveConversationTaskAssigneeSelection(selection, fallbackTask = null) {
  const fallbackType = sanitizeConversationTaskAssigneeType(fallbackTask?.assigneeType || "");
  const fallbackOrganizationId = String(fallbackTask?.assigneeOrganizationId || "").trim();
  const fallbackUserId = normalizeUserId(fallbackTask?.assigneeUserId || "");
  const requestedType = sanitizeConversationTaskAssigneeType(selection?.assigneeType || selection?.type || fallbackType);
  if (requestedType === "organization") {
    const assigneeOrganizationId = String(selection?.assigneeOrganizationId || selection?.organizationId || fallbackOrganizationId).trim();
    const organizationName = assigneeOrganizationId
      ? String(getConversationOrganizationById(assigneeOrganizationId)?.name || "").trim()
      : "";
    return {
      assigneeType: "organization",
      assigneeOrganizationId,
      assigneeUserId: "",
      assigneeName: organizationName,
    };
  }
  const assigneeUserId = normalizeUserId(selection?.assigneeUserId || selection?.userId || fallbackUserId || "");
  const assigneeName = assigneeUserId ? getUserDisplayNameByUserId(assigneeUserId) || assigneeUserId : "";
  return {
    assigneeType: "employee",
    assigneeOrganizationId: "",
    assigneeUserId,
    assigneeName,
  };
}

function getConversationTaskAssigneeLabel(task) {
  if (!task || typeof task !== "object") {
    return "Nicht zugewiesen";
  }
  const assigneeType = sanitizeConversationTaskAssigneeType(task.assigneeType || "");
  const assigneeName = String(task.assigneeName || "").trim();
  if (assigneeType === "organization") {
    return assigneeName || "Keine Organisation";
  }
  return assigneeName || "Nicht zugewiesen";
}

function normalizeConversationTaskRecord(task, index = 0) {
  if (!task || typeof task !== "object") {
    return null;
  }
  const title = String(task.title || task.task_title || "").trim();
  if (!title) {
    return null;
  }
  const id = String(task.id || `ctask_${index}`).trim();
  if (!id) {
    return null;
  }
  const createdAtRaw = String(task.createdAt || task.created_at || "").trim();
  const createdAt = Number.isNaN(new Date(createdAtRaw).getTime()) ? new Date().toISOString() : createdAtRaw;
  const updatedAtRaw = String(task.updatedAt || task.updated_at || createdAt).trim();
  const updatedAt = Number.isNaN(new Date(updatedAtRaw).getTime()) ? createdAt : updatedAtRaw;
  const storageAssignee = decodeConversationTaskAssigneeStorage(task.assigneeUserId || task.assignee_user_id || "");
  const explicitTypeRaw = normalizeText(task.assigneeType || task.assignee_type || "");
  const explicitType = CONVERSATION_TASK_ASSIGNEE_TYPES.has(explicitTypeRaw) ? explicitTypeRaw : "";
  const explicitOrganizationId = String(task.assigneeOrganizationId || task.assignee_organization_id || "").trim();
  const assigneeType = explicitType || storageAssignee.assigneeType;
  const assigneeOrganizationId =
    assigneeType === "organization"
      ? String(explicitOrganizationId || storageAssignee.assigneeOrganizationId || "").trim()
      : "";
  const assigneeUserId =
    assigneeType === "employee"
      ? normalizeUserId(task.assigneeUserId || task.assignee_user_id || storageAssignee.assigneeUserId || "")
      : "";
  const fallbackAssigneeName = assigneeType === "organization"
    ? String(getConversationOrganizationById(assigneeOrganizationId)?.name || "").trim()
    : getUserDisplayNameByUserId(assigneeUserId);
  const explicitAssigneeName = String(task.assigneeName || task.assignee_name || "").trim();
  const assigneeName = assigneeType === "organization"
    ? String(getConversationOrganizationById(assigneeOrganizationId)?.name || explicitAssigneeName || fallbackAssigneeName || "").trim()
    : String(explicitAssigneeName || fallbackAssigneeName || "").trim();
  return {
    id,
    title,
    assigneeType,
    assigneeOrganizationId,
    assigneeUserId,
    assigneeName,
    dueDate: sanitizeConversationDate(task.dueDate || task.due_date),
    priority: sanitizeConversationTaskPriority(task.priority || task.task_priority),
    status: sanitizeConversationTaskStatus(task.status || task.task_status),
    createdAt,
    createdByUserId: normalizeUserId(task.createdByUserId || task.created_by_user_id || ""),
    createdByName: String(task.createdByName || task.created_by_name || "").trim(),
    createdByRole: normalizeUserRole(task.createdByRole || task.created_by_role || ""),
    updatedAt,
    updatedByUserId: normalizeUserId(task.updatedByUserId || task.updated_by_user_id || ""),
    updatedByName: String(task.updatedByName || task.updated_by_name || "").trim(),
    updatedByRole: normalizeUserRole(task.updatedByRole || task.updated_by_role || ""),
  };
}

function normalizeConversationNoteRecord(note, index = 0) {
  if (!note || typeof note !== "object") {
    return null;
  }
  const text = String(note.text || note.note_text || "").trim();
  const linkedTaskId = String(note.linkedTaskId || note.linked_task_id || "").trim();
  if (!text && !linkedTaskId) {
    return null;
  }
  const id = String(note.id || `cnote_${index}`).trim();
  if (!id) {
    return null;
  }
  const createdAtRaw = String(note.createdAt || note.created_at || "").trim();
  const createdAt = Number.isNaN(new Date(createdAtRaw).getTime()) ? new Date().toISOString() : createdAtRaw;
  const updatedAtRaw = String(note.updatedAt || note.updated_at || createdAt).trim();
  const updatedAt = Number.isNaN(new Date(updatedAtRaw).getTime()) ? createdAt : updatedAtRaw;
  return {
    id,
    text,
    linkedTaskId,
    createdAt,
    createdByUserId: normalizeUserId(note.createdByUserId || note.created_by_user_id || ""),
    createdByName: String(note.createdByName || note.created_by_name || "").trim(),
    createdByRole: normalizeUserRole(note.createdByRole || note.created_by_role || ""),
    updatedAt,
    updatedByUserId: normalizeUserId(note.updatedByUserId || note.updated_by_user_id || ""),
    updatedByName: String(note.updatedByName || note.updated_by_name || "").trim(),
    updatedByRole: normalizeUserRole(note.updatedByRole || note.updated_by_role || ""),
  };
}

function normalizeConversationThreadRecord(thread, index = 0) {
  if (!thread || typeof thread !== "object") {
    return null;
  }
  const id = String(thread.id || `conv_${index}`).trim();
  if (!id) {
    return null;
  }
  const title = String(thread.title || thread.thread_title || "").trim() || "Gespräch";
  const contactName = String(thread.contactName || thread.contact_name || "").trim() || "Unbekannt";
  const createdAtRaw = String(thread.createdAt || thread.created_at || "").trim();
  const createdAt = Number.isNaN(new Date(createdAtRaw).getTime()) ? new Date().toISOString() : createdAtRaw;
  const updatedAtRaw = String(thread.updatedAt || thread.updated_at || createdAt).trim();
  const updatedAt = Number.isNaN(new Date(updatedAtRaw).getTime()) ? createdAt : updatedAtRaw;
  const tasksRaw = Array.isArray(thread.tasks)
    ? thread.tasks
    : Array.isArray(thread.conversation_tasks)
      ? thread.conversation_tasks
      : [];
  const tasks = Array.isArray(tasksRaw)
    ? tasksRaw.map((entry, taskIndex) => normalizeConversationTaskRecord(entry, taskIndex)).filter(Boolean)
    : [];
  const notesRaw = Array.isArray(thread.notes)
    ? thread.notes
    : Array.isArray(thread.conversation_notes)
      ? thread.conversation_notes
      : [];
  const notes = Array.isArray(notesRaw)
    ? notesRaw
        .map((entry, noteIndex) => normalizeConversationNoteRecord(entry, noteIndex))
        .filter(Boolean)
    : [];
  const internalParticipantUserIdsRaw = Array.isArray(thread.internalParticipantUserIds)
    ? thread.internalParticipantUserIds
    : Array.isArray(thread.internal_participant_user_ids)
      ? thread.internal_participant_user_ids
      : [];
  const internalParticipantUserIds = Array.from(
    new Set(
      internalParticipantUserIdsRaw
        .map((entry) => normalizeUserId(entry))
        .filter(Boolean)
    )
  );
  const internalParticipantNames = getConversationInternalParticipantNames(internalParticipantUserIds);
  const normalizedContactType = sanitizeConversationContactType(thread.contactType || thread.contact_type);
  return {
    id,
    title,
    contactName:
      normalizedContactType === "intern"
        ? contactName || internalParticipantNames.join(", ") || "Interne Teilnehmer"
        : contactName,
    contactType: normalizedContactType,
    organizationId: String(thread.organizationId || thread.organization_id || "").trim(),
    organization: String(thread.organization || "").trim(),
    channel: sanitizeConversationChannel(thread.channel),
    conversationDate: sanitizeConversationDate(thread.conversationDate || thread.conversation_date),
    internalParticipantUserIds,
    createdAt,
    createdByUserId: normalizeUserId(thread.createdByUserId || thread.created_by_user_id || ""),
    createdByName: String(thread.createdByName || thread.created_by_name || "").trim(),
    createdByRole: normalizeUserRole(thread.createdByRole || thread.created_by_role || ""),
    updatedAt,
    updatedByUserId: normalizeUserId(thread.updatedByUserId || thread.updated_by_user_id || ""),
    updatedByName: String(thread.updatedByName || thread.updated_by_name || "").trim(),
    updatedByRole: normalizeUserRole(thread.updatedByRole || thread.updated_by_role || ""),
    notes,
    tasks,
  };
}

function normalizeConversationThreads(rawList) {
  if (!Array.isArray(rawList)) {
    return [];
  }
  const seenIds = new Set();
  const normalized = [];
  rawList.forEach((entry, index) => {
    const normalizedEntry = normalizeConversationThreadRecord(entry, index);
    if (!normalizedEntry) {
      return;
    }
    const threadId = String(normalizedEntry.id || "").trim();
    if (!threadId || seenIds.has(threadId)) {
      return;
    }
    seenIds.add(threadId);
    normalized.push(normalizedEntry);
  });
  return normalized.sort((left, right) => String(right.updatedAt || "").localeCompare(String(left.updatedAt || "")));
}

function parseConversationTimestamp(value) {
  const raw = String(value || "").trim();
  if (!raw) {
    return 0;
  }
  const stamp = new Date(raw).getTime();
  return Number.isFinite(stamp) ? stamp : 0;
}

function mergeConversationEntityLists(primaryList, secondaryList) {
  const mergedById = new Map();
  const push = (entry) => {
    const id = String(entry?.id || "").trim();
    if (!id) {
      return;
    }
    const existing = mergedById.get(id);
    if (!existing) {
      mergedById.set(id, entry);
      return;
    }
    const existingStamp = parseConversationTimestamp(existing.updatedAt || existing.createdAt);
    const nextStamp = parseConversationTimestamp(entry.updatedAt || entry.createdAt);
    if (nextStamp >= existingStamp) {
      mergedById.set(id, entry);
    }
  };
  (Array.isArray(primaryList) ? primaryList : []).forEach(push);
  (Array.isArray(secondaryList) ? secondaryList : []).forEach(push);
  return Array.from(mergedById.values());
}

function mergeConversationThreadsPreferLatest(localThreads, remoteThreads) {
  const localList = Array.isArray(localThreads) ? localThreads : [];
  const remoteList = Array.isArray(remoteThreads) ? remoteThreads : [];
  const localById = new Map(localList.map((entry) => [String(entry?.id || "").trim(), entry]));
  const remoteById = new Map(remoteList.map((entry) => [String(entry?.id || "").trim(), entry]));
  const mergedIds = new Set([...localById.keys(), ...remoteById.keys()].filter(Boolean));
  const merged = [];

  mergedIds.forEach((threadId) => {
    const localEntry = localById.get(threadId) || null;
    const remoteEntry = remoteById.get(threadId) || null;
    if (!localEntry && remoteEntry) {
      merged.push(remoteEntry);
      return;
    }
    if (localEntry && !remoteEntry) {
      merged.push(localEntry);
      return;
    }
    if (!localEntry || !remoteEntry) {
      return;
    }
    const localStamp = parseConversationTimestamp(localEntry.updatedAt || localEntry.createdAt);
    const remoteStamp = parseConversationTimestamp(remoteEntry.updatedAt || remoteEntry.createdAt);
    const primary = localStamp >= remoteStamp ? localEntry : remoteEntry;
    const secondary = primary === localEntry ? remoteEntry : localEntry;
    merged.push({
      ...secondary,
      ...primary,
      organizationId: String(primary.organizationId || secondary.organizationId || "").trim(),
      organization: String(primary.organization || secondary.organization || "").trim(),
      notes: mergeConversationEntityLists(primary.notes, secondary.notes),
      tasks: mergeConversationEntityLists(primary.tasks, secondary.tasks),
    });
  });

  return normalizeConversationThreads(merged);
}

function normalizeConversationOrganizationRecord(entry, index = 0) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const normalizeContactRecord = (contactEntry, contactIndex = 0) => {
    if (!contactEntry || typeof contactEntry !== "object") {
      return null;
    }
    const contactName = String(contactEntry.name || contactEntry.contactName || "").trim();
    const functionLabel = String(contactEntry.function || contactEntry.role || "").trim();
    const phone = String(contactEntry.phone || "").trim();
    const email = normalizeUserEmail(contactEntry.email || "");
    if (!contactName && !functionLabel && !phone && !email) {
      return null;
    }
    return {
      id: String(contactEntry.id || `cc_${contactIndex}`).trim(),
      name: contactName,
      function: functionLabel,
      phone,
      email,
    };
  };
  const name = String(entry.name || "").trim();
  if (!name) {
    return null;
  }
  const id = String(entry.id || `corg_${index}`).trim();
  if (!id) {
    return null;
  }
  const contactsRaw = Array.isArray(entry.contacts)
    ? entry.contacts
    : Array.isArray(entry.contacts_json)
      ? entry.contacts_json
      : [];
  const contacts = contactsRaw
    .map((contactEntry, contactIndex) => normalizeContactRecord(contactEntry, contactIndex))
    .filter(Boolean);
  const primaryContact = contacts[0] || null;
  return {
    id,
    name,
    street: String(entry.street || "").trim(),
    postalCode: String(entry.postalCode || entry.postal_code || "").trim(),
    city: String(entry.city || "").trim(),
    country: String(entry.country || "").trim(),
    contactName: String(entry.contactName || entry.contact_name || primaryContact?.name || "").trim(),
    email: normalizeUserEmail(entry.email || primaryContact?.email || ""),
    phone: String(entry.phone || primaryContact?.phone || "").trim(),
    website: String(entry.website || "").trim(),
    contacts,
    createdAt: String(entry.createdAt || entry.created_at || "").trim() || new Date().toISOString(),
    createdByUserId: normalizeUserId(entry.createdByUserId || entry.created_by_user_id || ""),
    createdByName: String(entry.createdByName || entry.created_by_name || "").trim(),
    createdByRole: normalizeUserRole(entry.createdByRole || entry.created_by_role || ""),
    updatedAt:
      String(entry.updatedAt || entry.updated_at || "").trim()
      || String(entry.createdAt || entry.created_at || "").trim()
      || new Date().toISOString(),
    updatedByUserId: normalizeUserId(entry.updatedByUserId || entry.updated_by_user_id || ""),
    updatedByName: String(entry.updatedByName || entry.updated_by_name || "").trim(),
    updatedByRole: normalizeUserRole(entry.updatedByRole || entry.updated_by_role || ""),
  };
}

function normalizeConversationOrganizations(rawList) {
  if (!Array.isArray(rawList)) {
    return [];
  }
  const normalized = [];
  const seenIds = new Set();
  rawList.forEach((entry, index) => {
    const record = normalizeConversationOrganizationRecord(entry, index);
    if (!record) {
      return;
    }
    if (seenIds.has(record.id)) {
      return;
    }
    seenIds.add(record.id);
    normalized.push(record);
  });
  return normalized.sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "de"));
}

