// Die Glocke bleibt die verlässliche Quelle. Push informiert nur zusätzlich,
// wenn die Person die installierte Vertriebs-App dafür ausdrücklich aktiviert hat.
async function dispatchEmployeeMessagePush(message) {
  const recipientUserIds = Array.from(
    new Set((Array.isArray(message?.recipientUserIds) ? message.recipientUserIds : []).map((entry) => normalizeUserId(entry || "")).filter(Boolean))
  );
  if (!recipientUserIds.length || !String(message?.body || "").trim()) {
    return { ok: false, delivered: 0 };
  }
  const accessToken = await getAuthAccessToken({ forceRefresh: true });
  if (!accessToken) {
    console.warn("Push-Mitteilung wurde nicht ausgelöst: Superadmin-Login konnte nicht erneuert werden.");
    return { ok: false, delivered: 0 };
  }
  try {
    const send = async (token) => {
      const response = await fetch(WEB_PUSH_EMPLOYEE_MESSAGE_ENDPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
          "X-Supabase-Url": String(window.APP_CONFIG?.SUPABASE_URL || "").trim(),
        },
        body: JSON.stringify({
          messageId: String(message?.id || "").trim(),
          body: String(message?.body || "").trim(),
          senderName: String(message?.sentByName || "Superadmin").trim(),
          recipientUserIds,
        }),
      });
      return { response, payload: await readApiJsonPayload(response) };
    };
    let { response, payload } = await send(accessToken);
    if (!response.ok && isExpiredOrInvalidLoginTokenMessage(getApiErrorMessage(response, payload))) {
      const refreshedToken = await getAuthAccessToken({ forceRefresh: true });
      if (refreshedToken) ({ response, payload } = await send(refreshedToken));
    }
    if (!response.ok) {
      console.warn("Push-Mitteilung konnte nicht zugestellt werden.", response.status, getApiErrorMessage(response, payload));
      return { ok: false, delivered: 0 };
    }
    return { ok: true, delivered: Math.max(0, Number(payload?.delivered || 0) || 0) };
  } catch (error) {
    // Das Speichern der Glocken-Nachricht wurde bereits bestätigt und darf
    // durch eine temporär nicht erreichbare Push-Infrastruktur nicht scheitern.
    console.warn("Push-Mitteilung konnte nicht zugestellt werden.", error);
    return { ok: false, delivered: 0 };
  }
}

async function handleCeoSecretaryTeamMessageSubmit() {
  if (!isSuperAdmin()) {
    return;
  }
  const body = String(els.ceoSecretaryTeamMessageBody?.value || "").trim();
  const recipientSelection = String(els.ceoSecretaryTeamMessageRecipient?.value || "").trim();
  const recipients = getCeoSecretaryMessageRecipients();
  const senderUserId = normalizeUserId(getCurrentActorInfo()?.userId || "");
  const recipientUserIds = recipientSelection === "self"
    ? senderUserId ? [senderUserId] : []
    : recipientSelection === "all"
    ? recipients.map((entry) => entry.userId)
    : recipients.filter((entry) => entry.userId === recipientSelection).map((entry) => entry.userId);
  if (!body) {
    setCeoSecretaryTeamMessageStatus("Bitte eine Nachricht eingeben.", "error");
    els.ceoSecretaryTeamMessageBody?.focus();
    return;
  }
  if (!recipientUserIds.length) {
    setCeoSecretaryTeamMessageStatus("Bitte mindestens einen aktiven Mitarbeiter auswählen.", "error");
    return;
  }

  const actor = getCurrentActorInfo();
  const sentAt = new Date().toISOString();
  const message = {
    id: createId("employee_message"),
    body: body.slice(0, 800),
    recipientUserIds,
    sentAt,
    sentByUserId: normalizeUserId(actor?.userId || ""),
    sentByName: String(actor?.name || "Superadmin").trim() || "Superadmin",
  };
  const previousMessages = normalizeSecretaryEmployeeMessages(state.settings?.secretaryEmployeeMessages || []);
  state.settings = normalizeSettings({
    ...state.settings,
    secretaryEmployeeMessages: [message, ...previousMessages],
  });
  setCeoSecretaryTeamMessageStatus("Nachricht wird gesendet …", "info");
  setActionButtonBusy(els.ceoSecretaryTeamMessageSend, true);
  try {
    const persistence = await persistCriticalStateSnapshot({ retries: 3 });
    if (!persistence?.ok) {
      state.settings = normalizeSettings({
        ...state.settings,
        secretaryEmployeeMessages: previousMessages,
      });
      setCeoSecretaryTeamMessageStatus("Die Nachricht konnte nicht sicher gespeichert werden. Bitte erneut senden.", "error");
      return;
    }
    if (els.ceoSecretaryTeamMessageBody) {
      els.ceoSecretaryTeamMessageBody.value = "";
    }
    const recipientLabel = recipientSelection === "all"
      ? `an ${recipientUserIds.length} aktive Mitarbeiter`
      : recipientSelection === "self"
        ? "an das eigene Gerät"
      : `an ${recipients.find((entry) => entry.userId === recipientUserIds[0])?.name || "den Mitarbeiter"}`;
    const pushResult = await dispatchEmployeeMessagePush(message);
    const pushStatus = pushResult?.delivered
      ? ` Push an ${pushResult.delivered} aktivierte${pushResult.delivered === 1 ? "s Gerät" : " Geräte"} zugestellt.`
      : pushResult?.ok
        ? " Für diese Empfänger ist derzeit kein aktiviertes Push-Gerät gespeichert."
        : " Die Nachricht ist in der Glocke, die Push-Zustellung konnte aber nicht ausgelöst werden.";
    setCeoSecretaryTeamMessageStatus(`Nachricht ${recipientLabel} gesendet.${pushStatus}`, pushResult?.ok ? "success" : "info");
    renderAdminNotifications();
    showSuccessFeedback("Mitarbeiternachricht gesendet.", { toast: false, statusPersistMs: 2200 });
  } catch (error) {
    console.warn("Mitarbeiternachricht konnte nicht gespeichert werden.", error);
    state.settings = normalizeSettings({
      ...state.settings,
      secretaryEmployeeMessages: previousMessages,
    });
    setCeoSecretaryTeamMessageStatus("Die Nachricht konnte nicht sicher gespeichert werden. Bitte erneut senden.", "error");
  } finally {
    setActionButtonBusy(els.ceoSecretaryTeamMessageSend, false);
  }
}

function renderCeoSecretarySection() {
  if (!els.ceoSecretaryContent || !els.ceoSecretaryEntryList || !els.ceoSecretaryEmpty) {
    return;
  }
  if (!isSuperAdmin()) {
    els.ceoSecretaryContent.classList.add("hidden");
    return;
  }
  ceoSecretaryActiveView = normalizeCeoSecretaryView(ceoSecretaryActiveView);
  if (els.ceoSecretarySearchInput && els.ceoSecretarySearchInput.value !== ceoSecretarySearchTerm) {
    els.ceoSecretarySearchInput.value = ceoSecretarySearchTerm;
  }
  if (els.ceoSecretaryFilterSelect) {
    els.ceoSecretaryFilterSelect.value = ceoSecretaryFilter;
  }
  if (els.ceoSecretarySaveBtn) {
    els.ceoSecretarySaveBtn.textContent = ceoSecretaryEditingId ? "Änderung speichern" : "Senden";
  }
  renderCeoSecretaryMessageRecipients();
  els.ceoSecretaryCancelEditBtn?.classList.toggle("hidden", !ceoSecretaryEditingId);
  els.ceoSecretaryLoading?.classList.toggle("hidden", !ceoSecretaryLoadingRemote);
  const hasError = Boolean(ceoSecretaryLastError);
  els.ceoSecretaryError?.classList.toggle("hidden", !hasError);
  if (els.ceoSecretaryError) {
    els.ceoSecretaryError.textContent = ceoSecretaryLastError;
  }
  els.ceoSecretaryContent.classList.toggle("hidden", hasError);
  if (shouldHydrateCeoSecretaryNow() && !ceoSecretaryLoadedRemote && !ceoSecretaryLoadingRemote && !ceoSecretaryRemoteUnavailable) {
    void hydrateCeoSecretaryEntriesFromSupabase();
  }
  if (hasError) {
    return;
  }

  els.ceoSecretaryViewButtons?.forEach((button) => {
    const active = normalizeCeoSecretaryView(button.dataset.ceoSecretaryView || "") === ceoSecretaryActiveView;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  const panels = {
    secretary: els.ceoSecretaryViewSecretary,
    briefing: els.ceoSecretaryViewBriefing,
    memory: els.ceoSecretaryViewMemory,
  };
  Object.entries(panels).forEach(([view, panel]) => panel?.classList.toggle("hidden", view !== ceoSecretaryActiveView));
  const memoryCount = ceoSecretaryPreferences.memory.length;
  if (els.ceoSecretaryLearningStatus) {
    els.ceoSecretaryLearningStatus.textContent = ceoSecretaryAssistantWorking
      ? "Denkt mit ..."
      : memoryCount
        ? `Kennt ${memoryCount} deiner Präferenzen`
        : "Lernt deine Arbeitsweise";
  }
  if (els.ceoSecretaryHeaderStatus) {
    els.ceoSecretaryHeaderStatus.textContent = ceoSecretaryAssistantWorking
      ? "Ich bereite deine nächsten Schritte vor."
      : "Denkt mit, hält nach und schützt deinen Fokus.";
  }
  renderCeoSecretaryChat();
  renderCeoSecretaryBriefing();
  renderCeoSecretaryMemory();
}

function shouldHydrateCeoSecretaryNow() {
  return isSuperAdmin() && isSectionActive("ceo-secretary-section");
}

async function syncConversationThreadRemoteOrWarn(threadId, options = {}) {
  const result = await syncConversationThreadToSupabase(threadId, options);
  if (result?.ok) {
    conversationThreadsLoadedRemote = true;
    conversationThreadsRemoteUnavailable = false;
    return true;
  }
  if (result?.error && shouldUseConversationLocalFallback(result.error)) {
    conversationThreadsRemoteUnavailable = true;
    const technicalDetail = getSupabaseErrorSummary(result.error);
    showActionFeedback(
      isConversationTableMissingError(result.error)
        ? `SQL fehlt: Tabellen für Gesprächsnotizen bitte via Patch anlegen.${technicalDetail ? ` (${technicalDetail})` : ""}`
        : `Supabase-Sync für Gesprächsnotizen blockiert. Änderung lokal gespeichert.${technicalDetail ? ` (${technicalDetail})` : ""}`,
      { tone: "warning", toast: false, statusPersistMs: 6200 }
    );
    return false;
  }
  if (result?.error) {
    const technicalDetail = getSupabaseErrorSummary(result.error);
    showActionFeedback(
      `Gesprächsnotiz konnte nicht vollständig synchronisiert werden. Änderung bleibt lokal.${technicalDetail ? ` (${technicalDetail})` : ""}`,
      { tone: "warning", toast: false, statusPersistMs: 6200 }
    );
    console.warn("Gesprächsnotiz-Sync fehlgeschlagen.", result.error);
  }
  return false;
}

function getConversationThreadById(threadId) {
  const normalizedThreadId = String(threadId || "").trim();
  if (!normalizedThreadId) {
    return null;
  }
  return getConversationThreads().find((entry) => entry.id === normalizedThreadId) || null;
}

function ensureConversationSelection() {
  const threads = getConversationThreads();
  if (!threads.length) {
    conversationSelectedThreadId = "";
    return;
  }
  const selectedExists = threads.some((entry) => entry.id === conversationSelectedThreadId);
  if (!selectedExists) {
    conversationSelectedThreadId = threads[0].id;
  }
}

