function renderTourKpiStrip(selectedTour) {
  if (!els.tourKpiStrip) {
    return;
  }
  if (!selectedTour) {
    els.tourKpiStrip.innerHTML = "";
    return;
  }
  const providerById = new Map((state.providers || []).map((provider) => [String(provider.id || "").trim(), provider]));
  const totals = {
    total: 0,
    open: 0,
    progress: 0,
    live: 0,
    missing: 0,
  };
  (selectedTour.stops || []).forEach((stop) => {
    totals.total += 1;
    const provider = providerById.get(String(stop.providerId || "").trim());
    if (!provider) {
      totals.missing += 1;
      return;
    }
    const bucket = getProviderStatusBucket(provider.status);
    if (bucket === "live") {
      totals.live += 1;
      return;
    }
    if (bucket === "inProgress" || bucket === "livePending") {
      totals.progress += 1;
      return;
    }
    totals.open += 1;
  });

  els.tourKpiStrip.innerHTML = `
    <article class="tour-kpi-card">
      <span>Stops gesamt</span>
      <strong>${escapeHtml(String(totals.total))}</strong>
    </article>
    <article class="tour-kpi-card">
      <span>Offen</span>
      <strong>${escapeHtml(String(totals.open))}</strong>
    </article>
    <article class="tour-kpi-card">
      <span>In Bearbeitung</span>
      <strong>${escapeHtml(String(totals.progress))}</strong>
    </article>
    <article class="tour-kpi-card">
      <span>LIVE</span>
      <strong>${escapeHtml(String(totals.live))}</strong>
    </article>
    <article class="tour-kpi-card">
      <span>Nicht gefunden</span>
      <strong>${escapeHtml(String(totals.missing))}</strong>
    </article>
  `;
}

function normalizeTourProviderCountryFilterValue(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue || normalizeText(rawValue) === "all") {
    return "all";
  }
  return rawValue;
}

function normalizeTourProviderStateFilterValue(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue || normalizeText(rawValue) === "all") {
    return "all";
  }
  return rawValue;
}

function getTourProviderCountryOptions(providers) {
  const rows = Array.isArray(providers) ? providers : [];
  const countries = new Map();
  rows.forEach((provider) => {
    getProviderEffectiveLocations(provider).forEach((location) => {
      const countryLabel = String(location?.country || "").trim();
      if (!countryLabel) {
        return;
      }
      const key = normalizeText(countryLabel);
      if (!key || countries.has(key)) {
        return;
      }
      countries.set(key, countryLabel);
    });
  });
  return Array.from(countries.values()).sort((left, right) => left.localeCompare(right, "de"));
}

function getTourProviderStateOptionsForCountry(providers, countryFilter) {
  const selectedCountry = normalizeTourProviderCountryFilterValue(countryFilter);
  if (selectedCountry === "all") {
    return [];
  }
  const selectedCountryKey = normalizeText(selectedCountry);
  const states = new Map();
  (Array.isArray(providers) ? providers : []).forEach((provider) => {
    getProviderEffectiveLocations(provider).forEach((location) => {
      const countryLabel = String(location?.country || "").trim();
      if (!countryLabel || normalizeText(countryLabel) !== selectedCountryKey) {
        return;
      }
      const stateLabel = String(location?.state || "").trim();
      if (!stateLabel) {
        return;
      }
      const stateKey = normalizeText(stateLabel);
      if (!stateKey || states.has(stateKey)) {
        return;
      }
      states.set(stateKey, stateLabel);
    });
  });
  return Array.from(states.values()).sort((left, right) => left.localeCompare(right, "de"));
}

function renderTourProviderRegionFilters(providers) {
  if (!els.tourProviderCountryFilter || !els.tourProviderStateFilter) {
    return;
  }
  const rows = Array.isArray(providers) ? providers : [];
  const countryOptions = getTourProviderCountryOptions(rows);

  const selectedCountryKey = normalizeText(tourProviderCountryFilter);
  const selectedCountryExists =
    tourProviderCountryFilter === "all" ||
    countryOptions.some((countryLabel) => normalizeText(countryLabel) === selectedCountryKey);
  if (!selectedCountryExists) {
    tourProviderCountryFilter = "all";
    tourProviderStateFilter = "all";
  }

  els.tourProviderCountryFilter.innerHTML = ['<option value="all">Alle Länder</option>']
    .concat(
      countryOptions.map(
        (countryLabel) => `<option value="${escapeHtml(countryLabel)}">${escapeHtml(countryLabel)}</option>`
      )
    )
    .join("");
  els.tourProviderCountryFilter.value = normalizeTourProviderCountryFilterValue(tourProviderCountryFilter);

  const selectedCountry = normalizeTourProviderCountryFilterValue(tourProviderCountryFilter);
  const stateOptions = getTourProviderStateOptionsForCountry(rows, selectedCountry);
  const selectedStateKey = normalizeText(tourProviderStateFilter);
  const selectedStateExists =
    tourProviderStateFilter === "all" ||
    stateOptions.some((stateLabel) => normalizeText(stateLabel) === selectedStateKey);
  if (!selectedStateExists) {
    tourProviderStateFilter = "all";
  }

  els.tourProviderStateFilter.innerHTML = ['<option value="all">Alle Bundesländer</option>']
    .concat(
      stateOptions.map(
        (stateLabel) => `<option value="${escapeHtml(stateLabel)}">${escapeHtml(stateLabel)}</option>`
      )
    )
    .join("");
  els.tourProviderStateFilter.value = normalizeTourProviderStateFilterValue(tourProviderStateFilter);
  els.tourProviderStateFilter.disabled = selectedCountry === "all" || !stateOptions.length;
}

function providerMatchesTourProviderRegionFilter(provider) {
  const selectedCountry = normalizeTourProviderCountryFilterValue(tourProviderCountryFilter);
  const selectedState = normalizeTourProviderStateFilterValue(tourProviderStateFilter);
  if (selectedCountry !== "all" && !providerMatchesCountry(provider, selectedCountry)) {
    return false;
  }
  if (selectedCountry !== "all" && selectedState !== "all") {
    return providerMatchesTerritory(provider, {
      country: selectedCountry,
      state: selectedState,
    });
  }
  return true;
}

function calculateTourGeoDistanceKm(pointA, pointB) {
  if (!pointA || !pointB) {
    return Number.POSITIVE_INFINITY;
  }
  const latA = Number(pointA.lat);
  const lngA = Number(pointA.lng);
  const latB = Number(pointB.lat);
  const lngB = Number(pointB.lng);
  if (![latA, lngA, latB, lngB].every((value) => Number.isFinite(value))) {
    return Number.POSITIVE_INFINITY;
  }
  const toRad = (value) => (value * Math.PI) / 180;
  const earthRadiusKm = 6371;
  const deltaLat = toRad(latB - latA);
  const deltaLng = toRad(lngB - lngA);
  const latARad = toRad(latA);
  const latBRad = toRad(latB);
  const haversine =
    Math.sin(deltaLat / 2) * Math.sin(deltaLat / 2) +
    Math.cos(latARad) * Math.cos(latBRad) * Math.sin(deltaLng / 2) * Math.sin(deltaLng / 2);
  const arc = 2 * Math.atan2(Math.sqrt(haversine), Math.sqrt(1 - haversine));
  return earthRadiusKm * arc;
}

function getTourSmartStatusRank(status) {
  const bucket = getProviderStatusBucket(status);
  if (bucket === "open") {
    return 0;
  }
  if (bucket === "inProgress" || bucket === "livePending") {
    return 1;
  }
  return 3;
}

function buildTourSmartProviderSuggestion(selectedTour, providers) {
  if (!selectedTour) {
    return null;
  }
  const providerById = new Map((state.providers || []).map((provider) => [String(provider.id || "").trim(), provider]));
  const selectedProviderIds = new Set((selectedTour.stops || []).map((stop) => String(stop.providerId || "").trim()));
  const anchors = (selectedTour.stops || [])
    .map((stop, index) => {
      const provider = providerById.get(String(stop.providerId || "").trim());
      if (!provider) {
        return null;
      }
      const location = resolveTourProviderPrimaryLocation(provider);
      return {
        index,
        coords: getProviderCoordinates(location),
        countryKey: normalizeText(location?.country || ""),
        stateKey: normalizeText(location?.state || ""),
      };
    })
    .filter(Boolean);
  const anchorsWithCoords = anchors.filter((entry) => !!entry.coords);
  const referenceCountryKey = anchors[0]?.countryKey || "";
  const referenceStateKey = anchors[0]?.stateKey || "";

  const candidates = (Array.isArray(providers) ? providers : [])
    .filter((provider) => {
      const providerId = String(provider?.id || "").trim();
      if (!providerId || selectedProviderIds.has(providerId)) {
        return false;
      }
      if (findProviderPlanningConflict(providerId, selectedTour)) {
        return false;
      }
      if (isProviderInProgressLockedForCurrentUser(provider)) {
        return false;
      }
      if (!providerMatchesTourProviderRegionFilter(provider)) {
        return false;
      }
      return getProviderStatusBucket(provider?.status) !== "live";
    })
    .map((provider) => {
      const location = resolveTourProviderPrimaryLocation(provider);
      const coords = getProviderCoordinates(location);
      const statusRank = getTourSmartStatusRank(provider?.status);
      const providerCountryKey = normalizeText(location?.country || "");
      const providerStateKey = normalizeText(location?.state || "");
      let nearestDistanceKm = Number.POSITIVE_INFINITY;
      let nearestAnchorIndex = -1;

      if (coords && anchorsWithCoords.length) {
        anchorsWithCoords.forEach((anchor) => {
          const distanceKm = calculateTourGeoDistanceKm(coords, anchor.coords);
          if (distanceKm < nearestDistanceKm) {
            nearestDistanceKm = distanceKm;
            nearestAnchorIndex = anchor.index;
          }
        });
      }

      let score = Number.isFinite(nearestDistanceKm)
        ? nearestDistanceKm
        : anchorsWithCoords.length
          ? 700
          : 350;
      if (!coords) {
        score += 90;
      }
      score += statusRank * 25;
      if (referenceCountryKey && providerCountryKey && providerCountryKey !== referenceCountryKey) {
        score += 120;
      }
      if (referenceStateKey && providerStateKey && providerStateKey !== referenceStateKey) {
        score += 30;
      }

      return {
        provider,
        score,
        statusRank,
        distanceKm: nearestDistanceKm,
        nearestAnchorIndex,
      };
    })
    .sort((left, right) => {
      if (left.score !== right.score) {
        return left.score - right.score;
      }
      if (left.statusRank !== right.statusRank) {
        return left.statusRank - right.statusRank;
      }
      return String(left.provider?.name || "").localeCompare(String(right.provider?.name || ""), "de", {
        sensitivity: "base",
        ignorePunctuation: true,
      });
    });

  return candidates[0] || null;
}

function updateTourSmartAddUi(selectedTour, canEdit, suggestion) {
  if (els.tourSmartAddBtn) {
    els.tourSmartAddBtn.disabled = !selectedTour || !canEdit || !suggestion;
  }
  if (!els.tourSmartAddMeta) {
    return;
  }
  const setMeta = (markup, tone = "muted") => {
    const normalizedTone = ["muted", "ready", "warning"].includes(String(tone)) ? String(tone) : "muted";
    els.tourSmartAddMeta.className = `tour-smart-add-meta is-${normalizedTone}`;
    els.tourSmartAddMeta.innerHTML = markup;
  };
  if (!selectedTour) {
    setMeta('<span class="tour-smart-meta-hint">Erst Tour wählen.</span>', "muted");
    return;
  }
  if (!canEdit) {
    setMeta('<span class="tour-smart-meta-hint">Nur Lesemodus.</span>', "warning");
    return;
  }
  if (!suggestion?.provider) {
    setMeta('<span class="tour-smart-meta-hint">Kein Vorschlag. Manuell wählen.</span>', "muted");
    return;
  }
  const providerName = String(suggestion.provider.name || "Anbieter").trim();
  const providerNameSafe = escapeHtml(providerName);
  if (Number.isFinite(suggestion.distanceKm)) {
    const distanceLabel = `${suggestion.distanceKm.toLocaleString("de-AT", {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    })} km entfernt`;
    setMeta(
      `<span class="tour-smart-meta-title">Empfehlung</span>
       <strong class="tour-smart-meta-main">${providerNameSafe}</strong>
       <span class="tour-smart-meta-distance">${escapeHtml(distanceLabel)}</span>`,
      "ready"
    );
    return;
  }
  setMeta(
    `<span class="tour-smart-meta-title">Empfehlung</span>
     <strong class="tour-smart-meta-main">${providerNameSafe}</strong>`,
    "ready"
  );
}

function handleTourAddSuggestedProvider(tourId) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const providerCandidates = getVisibleProvidersForCurrentUser("all");
  const suggestion = buildTourSmartProviderSuggestion(tour, providerCandidates);
  if (!suggestion?.provider?.id) {
    showInfoFeedback("Kein Vorschlag.");
    return;
  }
  const providerName = String(suggestion.provider.name || "Anbieter").trim();
  const distanceLabel = Number.isFinite(suggestion.distanceKm)
    ? ` · ${suggestion.distanceKm.toLocaleString("de-AT", {
        minimumFractionDigits: 1,
        maximumFractionDigits: 1,
      })} km`
    : "";
  handleTourAddProvider(tourId, suggestion.provider.id, {
    successMessage: `Passender Anbieter hinzugefügt: ${providerName}${distanceLabel}`,
  });
}

function renderTourProviderSelectedList(selectedTour) {
  if (!els.tourProviderSelectedList) {
    return;
  }
  const canEdit = selectedTour ? canCurrentUserEditTour(selectedTour) : false;
  const providerById = new Map((state.providers || []).map((provider) => [String(provider.id || "").trim(), provider]));
  const stops = Array.isArray(selectedTour?.stops) ? selectedTour.stops : [];
  if (els.tourProviderSelectedMeta) {
    els.tourProviderSelectedMeta.textContent = `${stops.length} ${stops.length === 1 ? "Stopp" : "Stopps"}`;
  }

  if (!selectedTour) {
    els.tourProviderSelectedList.innerHTML = '<p class="empty">Tour wählen.</p>';
    return;
  }
  if (!stops.length) {
    els.tourProviderSelectedList.innerHTML = '<p class="empty">Noch keine Stopps.</p>';
    return;
  }

  els.tourProviderSelectedList.innerHTML = stops
    .map((stop, index) => {
      const provider = providerById.get(String(stop.providerId || "").trim());
      const providerName = String(provider?.name || stop.providerId || "Anbieter").trim();
      const locationLabel = provider ? getProviderCoverageSummary(provider) : "Datensatz fehlt";
      const isDone = Boolean(String(stop.doneAt || "").trim());
      return `
        <article class="tour-provider-selected-item ${isDone ? "is-done" : ""}">
          <span class="tour-provider-selected-order">${escapeHtml(String(index + 1))}</span>
          <div class="tour-provider-selected-main">
            <strong>${escapeHtml(providerName)}</strong>
            <span>${escapeHtml(locationLabel)}</span>
          </div>
          ${
            canEdit
              ? `<button
                   type="button"
                   class="mini-btn danger"
                   title="Stop entfernen"
                   aria-label="Stop entfernen"
                   data-tour-remove-stop="${escapeHtml(String(stop.id || "").trim())}"
                 >✕</button>`
              : ""
          }
        </article>
      `;
    })
    .join("");
}

function renderTourProviderPicker(selectedTour) {
  if (!els.tourProviderPicker) {
    return;
  }
  renderTourProviderSelectedList(selectedTour);
  renderTourProviderPlanningMetrics(selectedTour);
  const canEdit = selectedTour ? canCurrentUserEditTour(selectedTour) : false;
  const selectedProviderIds = new Set((selectedTour?.stops || []).map((stop) => String(stop.providerId || "").trim()));
  const searchTerm = normalizeText(tourProviderSearchTerm);
  if (els.tourProviderSearchInput && els.tourProviderSearchInput.value !== tourProviderSearchTerm) {
    els.tourProviderSearchInput.value = tourProviderSearchTerm;
  }

  const providerCandidates = getVisibleProvidersForCurrentUser("all");
  renderTourProviderRegionFilters(providerCandidates);
  const smartSuggestion = buildTourSmartProviderSuggestion(selectedTour, providerCandidates);
  updateTourSmartAddUi(selectedTour, canEdit, smartSuggestion);

  const providers = providerCandidates
    .filter((provider) => {
      if (!providerMatchesTourProviderRegionFilter(provider)) {
        return false;
      }
      if (!searchTerm) {
        return true;
      }
      const haystack = normalizeText(
        [
          provider.name,
          provider.city,
          provider.state,
          provider.country,
          provider.address,
          provider.status,
        ]
          .filter(Boolean)
          .join(" ")
      );
      return haystack.includes(searchTerm);
    })
    .sort((left, right) =>
      String(left?.name || "").localeCompare(String(right?.name || ""), "de", {
        sensitivity: "base",
        ignorePunctuation: true,
      })
    );

  const providerRows = providers.map((provider) => {
    const providerId = String(provider?.id || "").trim();
    const alreadyAdded = selectedProviderIds.has(providerId);
    const lockedByInProgress = isProviderInProgressLockedForCurrentUser(provider);
    const planningConflict =
      !alreadyAdded && !lockedByInProgress && selectedTour ? findProviderPlanningConflict(providerId, selectedTour) : null;
    return {
      provider,
      providerId,
      alreadyAdded,
      lockedByInProgress,
      planningConflict,
    };
  });
  const alreadyAddedVisibleCount = providerRows.reduce((count, row) => (row.alreadyAdded ? count + 1 : count), 0);
  const blockedVisibleCount = providerRows.reduce(
    (count, row) => (!row.alreadyAdded && (row.lockedByInProgress || row.planningConflict) ? count + 1 : count),
    0
  );
  if (els.tourProviderAvailableMeta) {
    const hitCount = providerRows.length;
    const hitLabel = `${hitCount} Treffer`;
    const addedLabel =
      selectedTour && alreadyAddedVisibleCount > 0
        ? ` · ${alreadyAddedVisibleCount} bereits in Tour`
        : "";
    const blockedLabel = selectedTour && blockedVisibleCount > 0 ? ` · ${blockedVisibleCount} gesperrt` : "";
    els.tourProviderAvailableMeta.textContent = `${hitLabel}${addedLabel}${blockedLabel}`;
  }

  if (!selectedTour) {
    els.tourProviderPicker.innerHTML = '<p class="empty">Tour wählen, dann Stopps hinzufügen.</p>';
    return;
  }
  if (!providerRows.length) {
    els.tourProviderPicker.innerHTML = '<p class="empty">Keine Treffer.</p>';
    return;
  }

  els.tourProviderPicker.innerHTML = providerRows
    .map((row) => {
      const provider = row.provider;
      const alreadyAdded = row.alreadyAdded;
      const lockedByInProgress = row.lockedByInProgress;
      const planningConflict = row.planningConflict;
      const statusLabel = getProviderStatusLabel(provider.status);
      const locationLabel = getProviderCoverageSummary(provider);
      const blockedByConflict = !!planningConflict;
      const lockedLabel = lockedByInProgress ? getProviderInProgressLockedLabel(provider) : "";
      const canSelect = !alreadyAdded && !lockedByInProgress && !blockedByConflict && canEdit;
      const conflictLabel = blockedByConflict
        ? `${planningConflict.assigneeName} · ${planningConflict.tourName}${
            planningConflict.plannedDateLabel ? ` (${planningConflict.plannedDateLabel})` : ""
          }`
        : "";
      const actionLabel = alreadyAdded ? "In Tour" : lockedByInProgress || blockedByConflict ? "Gesperrt" : "Auswählen";
      const actionTitle = lockedByInProgress
        ? lockedLabel
        : blockedByConflict
          ? `Bereits geplant bei ${conflictLabel}`
          : "";
      return `
        <article
          class="tour-provider-card ${canSelect ? "is-selectable" : ""} ${lockedByInProgress ? "is-locked" : ""}"
          ${canSelect ? `data-tour-add-provider-card="${escapeHtml(provider.id)}"` : ""}
        >
          <div class="tour-provider-card-main">
            <strong>${escapeHtml(provider.name || "Anbieter")}</strong>
            <span>${escapeHtml(locationLabel)}</span>
            <span class="tour-status-pill ${getTourStatusCssClass(provider.status)}">${escapeHtml(statusLabel)}</span>
            ${
              lockedByInProgress
                ? `<small class="tour-provider-lock-note">${escapeHtml(lockedLabel)}</small>`
                : ""
            }
            ${
              blockedByConflict
                ? `<small class="tour-provider-lock-note">Bereits geplant: ${escapeHtml(conflictLabel)}</small>`
                : ""
            }
          </div>
          <button
            type="button"
            class="btn btn-primary"
            data-tour-add-provider="${escapeHtml(provider.id)}"
            ${alreadyAdded || lockedByInProgress || blockedByConflict || !canEdit ? "disabled" : ""}
            ${actionTitle ? `title="${escapeHtml(actionTitle)}"` : ""}
          >${escapeHtml(actionLabel)}</button>
        </article>
      `;
    })
    .join("");
}

function renderTourStopList(selectedTour) {
  if (!els.tourStopList) {
    return;
  }
  if (!selectedTour) {
    els.tourStopList.innerHTML = '<p class="empty">Keine Tour gewählt.</p>';
    return;
  }

  const canEdit = canCurrentUserEditTour(selectedTour);
  const providerById = new Map((state.providers || []).map((provider) => [String(provider.id || "").trim(), provider]));
  const startPoint = buildTourRoutePointFromStart(selectedTour);
  const stops = Array.isArray(selectedTour.stops) ? selectedTour.stops : [];
  if (!stops.length) {
    els.tourStopList.innerHTML = '<p class="empty">Noch keine Stopps.</p>';
    return;
  }

  const listMarkup = stops
    .map((stop, index) => {
      const provider = providerById.get(String(stop.providerId || "").trim());
      const providerName = provider?.name || `Anbieter (${stop.providerId})`;
      const providerStatus = provider ? normalizeProviderStatusValue(provider.status) : "offen";
      const locationLabel = provider ? getProviderCoverageSummary(provider) : "Datensatz fehlt";
      const addedByName = String(stop.addedByName || "").trim() || getTourAssigneeNameByUserId(stop.addedByUserId, "Unbekannt");
      const isDone = Boolean(String(stop.doneAt || "").trim());
      const doneAtLabel = isDone ? formatDateTime(stop.doneAt) : "";
      const doneByLabel = isDone
        ? String(stop.doneByName || "").trim() || getTourAssigneeNameByUserId(stop.doneByUserId, "Unbekannt")
        : "";
      const routePoint = provider ? buildTourRoutePointFromProvider(provider, stop) : null;
      const mapsUrl = routePoint ? buildGoogleMapsTourUrl(startPoint ? [startPoint, routePoint] : [routePoint]) : "";
      const telHref = buildTelHref(provider?.phone || "");
      const stopId = String(stop.id || "").trim();
      const providerId = String(provider?.id || "").trim();
      return `
        <article
          class="tour-stop-card ${isDone ? "is-done" : ""} ${canEdit ? "is-draggable" : ""}"
          data-tour-stop-id="${escapeHtml(stopId)}"
          draggable="${canEdit && !isTourMobileViewport() ? "true" : "false"}"
        >
          <span class="tour-stop-order">${escapeHtml(String(index + 1))}</span>
          <div class="tour-stop-main">
            <strong>${escapeHtml(providerName)}</strong>
            <span>${escapeHtml(locationLabel)}</span>
            <div class="tour-stop-meta">
              <small>${escapeHtml(isDone ? `Erledigt: ${doneAtLabel} · ${doneByLabel}` : `Hinzugefügt: ${formatDateTime(stop.addedAt)} · ${addedByName}`)}</small>
            </div>
            <div class="tour-stop-tools">
              <label class="tour-stop-status-field">
                <span>Status</span>
                <select
                  data-tour-stop-provider-status="${escapeHtml(providerId)}"
                  data-tour-stop-id="${escapeHtml(stopId)}"
                  ${canEdit && providerId ? "" : "disabled"}
                >
                  <option value="offen" ${providerStatus === "offen" ? "selected" : ""}>Offen</option>
                  <option value="telefonakquise" ${providerStatus === PROVIDER_STATUS_TELEFONAKQUISE ? "selected" : ""}>Telefonakquise</option>
                  <option value="nicht_erreicht" ${providerStatus === PROVIDER_STATUS_NOT_REACHED ? "selected" : ""}>Nicht erreicht</option>
                  <option value="rueckruf" ${providerStatus === PROVIDER_STATUS_CALLBACK ? "selected" : ""}>Rückruf</option>
                  <option value="erreicht" ${providerStatus === PROVIDER_STATUS_REACHED ? "selected" : ""}>Erreicht</option>
                  <option value="in Bearbeitung" ${providerStatus === "in Bearbeitung" ? "selected" : ""}>In Bearbeitung</option>
                  <option value="tour_geplant" ${providerStatus === PROVIDER_STATUS_TOUR_PLANNED ? "selected" : ""}>Tour geplant</option>
                  <option value="live_pending" ${providerStatus === "live_pending" ? "selected" : ""}>Live beantragt</option>
                  <option value="live" ${providerStatus === "live" ? "selected" : ""}>Live</option>
                  <option value="kein_interesse" ${providerStatus === PROVIDER_STATUS_NO_INTEREST ? "selected" : ""}>Kein Interesse</option>
                  <option value="archiviert" ${providerStatus === PROVIDER_STATUS_ARCHIVED ? "selected" : ""}>Archiviert</option>
                </select>
              </label>
              <button
                type="button"
                class="tour-stop-action-btn"
                data-tour-stop-info="${escapeHtml(stopId)}"
              >Info</button>
            </div>
            <div class="tour-stop-actions">
              ${
                mapsUrl
                  ? `<a
                       class="tour-stop-action-btn"
                       href="${escapeHtml(mapsUrl)}"
                       target="_blank"
                       rel="noopener noreferrer"
                     >Navigation</a>`
                  : '<button type="button" class="tour-stop-action-btn" disabled>Navigation</button>'
              }
              ${
                telHref
                  ? `<a class="tour-stop-action-btn" href="${escapeHtml(telHref)}">Anrufen</a>`
                  : '<button type="button" class="tour-stop-action-btn" disabled>Anrufen</button>'
              }
              <button
                type="button"
                class="tour-stop-action-btn ${isDone ? "is-done" : ""}"
                data-tour-toggle-stop-done="${escapeHtml(stopId)}"
                ${canEdit ? "" : "disabled"}
              >${isDone ? "Offen" : "Erledigt"}</button>
              ${
                canEdit
                  ? `<button
                       type="button"
                       class="tour-stop-action-btn is-danger"
                       title="Stop entfernen"
                       aria-label="Stop entfernen"
                       data-tour-remove-stop="${escapeHtml(stopId)}"
                     >Entfernen</button>`
                  : ""
              }
            </div>
          </div>
        </article>
      `;
    })
    .join("");
  els.tourStopList.innerHTML = `
    <div class="tour-stop-list-head">
      <strong>${escapeHtml(String(stops.length))} ${stops.length === 1 ? "Stopp" : "Stopps"}</strong>
      <span>${escapeHtml(canEdit ? "Tippen für Aktion" : "Übersicht")}</span>
    </div>
    ${listMarkup}
  `;
}

function handleTourStartSubmit(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const startAddress = String(formData.get("startAddress") || "").trim();
  if (!startAddress) {
    showWarningFeedback("Tourstartpunkt fehlt.");
    return;
  }

  const draft = {
    address: startAddress,
    latitude: parseOptionalNumber(formData.get("startLatitude")),
    longitude: parseOptionalNumber(formData.get("startLongitude")),
  };

  if (tourStartModalMode === "edit") {
    const selectedTour = getSelectedTourForCurrentUser();
    if (!selectedTour || !canCurrentUserEditTour(selectedTour)) {
      return;
    }
    const currentAddress = String(selectedTour.startAddress || "").trim();
    const currentLatitude = parseOptionalNumber(selectedTour.startLatitude);
    const currentLongitude = parseOptionalNumber(selectedTour.startLongitude);
    const hasChanged =
      currentAddress !== draft.address ||
      currentLatitude !== draft.latitude ||
      currentLongitude !== draft.longitude;
    if (!hasChanged) {
      closeTourModals();
      return;
    }
    const actor = getCurrentActorInfo();
    const nowIso = new Date().toISOString();
    selectedTour.startAddress = draft.address;
    selectedTour.startLatitude = draft.latitude;
    selectedTour.startLongitude = draft.longitude;
    selectedTour.updatedAt = nowIso;
    selectedTour.updatedByUserId = normalizeUserId(actor.userId || "");
    selectedTour.updatedByName = actor.name;
    appendTourActivity(selectedTour, "tour_updated", "hat den Tourstartpunkt geändert.", actor, nowIso);
    saveState({ showFeedback: false });
    closeTourModals();
    renderToursSection({ forceRecenter: true });
    showSuccessFeedback("Tourstartpunkt aktualisiert.");
    return;
  }

  setPendingTourStartDraft(draft);
  openTourModal("create");
}

async function handleTourCreate(event) {
  const currentUser = getCurrentUser();
  if (!currentUser) {
    return;
  }
  const formData = new FormData(event.currentTarget);
  const name = String(formData.get("name") || "").trim();
  const startAddress = String(pendingTourStartDraft?.address || "").trim();
  if (!name) {
    return;
  }
  if (!startAddress) {
    showWarningFeedback("Tourstartpunkt fehlt.");
    return;
  }

  const nowIso = new Date().toISOString();
  const actor = getCurrentActorInfo();
  let assigneeUserId = normalizeUserId(formData.get("assigneeUserId") || "");
  assigneeUserId = upsertTourAssigneeSelectOptions(els.tourAssigneeSelect, assigneeUserId || getCurrentSalesUserId());
  const assigneeName = getTourAssigneeNameByUserId(assigneeUserId, currentUser.name || currentUser.email);

  const tour = normalizeTourRecord({
    id: createId("tour"),
    name,
    plannedDate: normalizeTourDateInput(formData.get("plannedDate"), getTodayDateInputValue()),
    startAddress,
    startLatitude: pendingTourStartDraft?.latitude,
    startLongitude: pendingTourStartDraft?.longitude,
    assigneeUserId,
    assigneeName,
    createdAt: nowIso,
    createdByUserId: normalizeUserId(actor.userId || ""),
    createdByName: actor.name,
    updatedAt: nowIso,
    updatedByUserId: normalizeUserId(actor.userId || ""),
    updatedByName: actor.name,
    stops: [],
    activity: [],
  });
  appendTourActivity(tour, "tour_created", `hat die Tour "${tour.name}" angelegt.`, actor, nowIso);

  state.tours.push(tour);
  selectedTourId = tour.id;
  saveState({ showFeedback: false });
  event.currentTarget.reset();
  if (els.tourDateInput) {
    els.tourDateInput.value = getTodayDateInputValue();
  }
  setPendingTourStartDraft(null);
  tourProviderSearchTerm = "";
  if (els.tourProviderSearchInput) {
    els.tourProviderSearchInput.value = "";
  }
  closeTourModals();
  renderToursSection();
  showSuccessFeedback("Tour angelegt.");
}

async function handleTourDetailSave(event) {
  const tour = getSelectedTourForCurrentUser();
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const formData = new FormData(event.currentTarget);
  const nextName = String(formData.get("name") || "").trim();
  if (!nextName) {
    return;
  }
  const nextDate = normalizeTourDateInput(formData.get("plannedDate"), tour.plannedDate || getTodayDateInputValue());
  let nextAssigneeUserId = normalizeUserId(formData.get("assigneeUserId") || "");
  nextAssigneeUserId = upsertTourAssigneeSelectOptions(els.tourSelectedAssigneeSelect, nextAssigneeUserId || tour.assigneeUserId);
  const nextAssigneeName = getTourAssigneeNameByUserId(nextAssigneeUserId, tour.assigneeName);

  const changes = [];
  if (tour.name !== nextName) {
    changes.push(`Name auf "${nextName}"`);
  }
  if (tour.plannedDate !== nextDate) {
    changes.push(`Datum auf ${formatTourDateLabel(nextDate)}`);
  }
  if (normalizeUserId(tour.assigneeUserId) !== normalizeUserId(nextAssigneeUserId)) {
    changes.push(`Vertrieb auf "${nextAssigneeName}"`);
  }
  if (!changes.length) {
    return;
  }
  if (normalizeUserId(tour.assigneeUserId) !== normalizeUserId(nextAssigneeUserId)) {
    const simulatedTour = {
      ...tour,
      assigneeUserId: nextAssigneeUserId,
      assigneeName: nextAssigneeName,
    };
    const providerIds = Array.from(
      new Set(
        (Array.isArray(tour.stops) ? tour.stops : [])
          .map((stop) => String(stop?.providerId || "").trim())
          .filter(Boolean)
      )
    );
    const firstConflict = providerIds
      .map((providerId) => findProviderPlanningConflict(providerId, simulatedTour))
      .find(Boolean);
    if (firstConflict) {
      const conflictDetails = `${firstConflict.assigneeName} · ${firstConflict.tourName}${
        firstConflict.plannedDateLabel ? ` (${firstConflict.plannedDateLabel})` : ""
      }`;
      showErrorFeedback(`Vertrieb kann nicht geändert werden. Anbieter bereits verplant: ${conflictDetails}`);
      return;
    }
  }

  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  tour.name = nextName;
  tour.plannedDate = nextDate;
  tour.assigneeUserId = nextAssigneeUserId;
  tour.assigneeName = nextAssigneeName;
  tour.updatedAt = nowIso;
  tour.updatedByUserId = normalizeUserId(actor.userId || "");
  tour.updatedByName = actor.name;
  appendTourActivity(tour, "tour_updated", `hat ${changes.join(", ")} geändert.`, actor, nowIso);

  saveState({ showFeedback: false });
  closeTourModals();
  renderToursSection();
  showSuccessFeedback("Tour aktualisiert.");
}

async function handleTourDelete(tourId) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const confirmed = await confirmDeleteAction(`Tour "${tour.name}" wirklich löschen?`);
  if (!confirmed) {
    return;
  }
  const index = (state.tours || []).findIndex((entry) => entry.id === tour.id);
  if (index < 0) {
    return;
  }
  state.tours.splice(index, 1);
  if (selectedTourId === tour.id) {
    selectedTourId = "";
  }
  saveState({ showFeedback: false });
  closeTourModals();
  renderToursSection();
  showSuccessFeedback("Tour gelöscht.");
}

function handleTourAddProvider(tourId, providerId, options = {}) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const normalizedProviderId = String(providerId || "").trim();
  if (!normalizedProviderId) {
    return;
  }
  const provider = state.providers.find((entry) => String(entry.id || "").trim() === normalizedProviderId);
  if (provider && isProviderInProgressLockedForCurrentUser(provider)) {
    showProviderLockedFeedback(provider);
    renderTourProviderPicker(tour);
    return;
  }
  const alreadyAdded = (tour.stops || []).some((stop) => String(stop.providerId || "").trim() === normalizedProviderId);
  if (alreadyAdded) {
    showInfoFeedback("Bereits in der Tour.");
    return;
  }
  const planningConflict = findProviderPlanningConflict(normalizedProviderId, tour);
  if (planningConflict) {
    const conflictDetails = `${planningConflict.assigneeName} · ${planningConflict.tourName}${
      planningConflict.plannedDateLabel ? ` (${planningConflict.plannedDateLabel})` : ""
    }`;
    showErrorFeedback(`Anbieter ist bereits verplant: ${conflictDetails}`);
    return;
  }
  const providerName = String(provider?.name || normalizedProviderId).trim();
  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();

  const nextStop = normalizeTourStopRecord({
    id: createId("tstop"),
    providerId: normalizedProviderId,
    addedAt: nowIso,
    addedByUserId: actor.userId,
    addedByName: actor.name,
  });
  if (!nextStop) {
    return;
  }
  const stops = Array.isArray(tour.stops) ? tour.stops.slice() : [];
  stops.push(nextStop);
  tour.stops = stops;
  tour.updatedAt = nowIso;
  tour.updatedByUserId = normalizeUserId(actor.userId || "");
  tour.updatedByName = actor.name;
  appendTourActivity(tour, "provider_added", `hat Anbieter "${providerName}" zur Tour hinzugefügt.`, actor, nowIso);

  let syncedProviderId = "";
  if (provider) {
    const currentStatus = normalizeProviderStatusValue(provider.status || "offen");
    if (![PROVIDER_STATUS_LIVE_PENDING, "live"].includes(currentStatus)) {
      const nextStatus = PROVIDER_STATUS_TOUR_PLANNED;
      provider.status = nextStatus;
      provider.updatedAt = nowIso;
      provider.updatedByName = actor.name;
      provider.updatedByRole = actor.role;
      provider.updatedByUserId = actor.userId;
      applyProviderResponsibilityForStatusTransition(provider, currentStatus, nextStatus, actor, nowIso);
      applyProviderInProgressClaim(provider, currentStatus, nextStatus, actor, nowIso);
      appendProviderStatusHistory(provider, currentStatus, nextStatus, actor, nowIso, "tour_planning");
      Object.assign(provider, normalizeProviderRecord(provider) || provider);
      syncedProviderId = provider.id;
    }
  }

  saveState({
    showFeedback: false,
    providersSync: syncedProviderId ? { upsertProviderIds: [syncedProviderId] } : null,
  });
  renderToursSection();
  const successMessage = String(options?.successMessage || "").trim() || "Stopp hinzugefügt.";
  showSuccessFeedback(successMessage);
}

function handleTourRemoveStop(tourId, stopId) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const normalizedStopId = String(stopId || "").trim();
  if (!normalizedStopId) {
    return;
  }
  const stops = Array.isArray(tour.stops) ? tour.stops.slice() : [];
  const removeIndex = stops.findIndex((stop) => String(stop.id || "").trim() === normalizedStopId);
  if (removeIndex < 0) {
    return;
  }
  const removedStop = stops[removeIndex];
  stops.splice(removeIndex, 1);
  tour.stops = stops;

  const provider = state.providers.find((entry) => String(entry.id || "").trim() === String(removedStop.providerId || "").trim());
  const providerName = String(provider?.name || removedStop.providerId || "Anbieter").trim();
  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  tour.updatedAt = nowIso;
  tour.updatedByUserId = normalizeUserId(actor.userId || "");
  tour.updatedByName = actor.name;
  appendTourActivity(tour, "provider_removed", `hat Anbieter "${providerName}" aus der Tour entfernt.`, actor, nowIso);

  saveState({ showFeedback: false });
  renderToursSection();
  showSuccessFeedback("Stop entfernt.");
}

function handleTourToggleStopDone(tourId, stopId) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const normalizedStopId = String(stopId || "").trim();
  if (!normalizedStopId) {
    return;
  }
  const stops = Array.isArray(tour.stops) ? tour.stops : [];
  const stop = stops.find((entry) => String(entry.id || "").trim() === normalizedStopId);
  if (!stop) {
    return;
  }

  const provider = state.providers.find((entry) => String(entry.id || "").trim() === String(stop.providerId || "").trim());
  const providerName = String(provider?.name || stop.providerId || "Stop").trim();
  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  const wasDone = Boolean(String(stop.doneAt || "").trim());

  if (wasDone) {
    stop.doneAt = "";
    stop.doneByUserId = "";
    stop.doneByName = "";
    appendTourActivity(tour, "stop_reopened", `hat Stop "${providerName}" auf offen gesetzt.`, actor, nowIso);
  } else {
    stop.doneAt = nowIso;
    stop.doneByUserId = normalizeUserId(actor.userId || "");
    stop.doneByName = actor.name;
    appendTourActivity(tour, "stop_done", `hat Stop "${providerName}" als erledigt markiert.`, actor, nowIso);
  }

  tour.updatedAt = nowIso;
  tour.updatedByUserId = normalizeUserId(actor.userId || "");
  tour.updatedByName = actor.name;
  saveState({ showFeedback: false });
  renderToursSection();
  showSuccessFeedback(wasDone ? "Stop auf offen gesetzt." : "Stop erledigt.");
}

function openTourStopInfoModal(tourId, stopId) {
  const tour = getTourById(tourId);
  if (!tour) {
    return;
  }
  const normalizedStopId = String(stopId || "").trim();
  if (!normalizedStopId) {
    return;
  }
  const stop = (Array.isArray(tour.stops) ? tour.stops : []).find(
    (entry) => String(entry?.id || "").trim() === normalizedStopId
  );
  if (!stop) {
    return;
  }
  const provider = state.providers.find(
    (entry) => String(entry?.id || "").trim() === String(stop.providerId || "").trim()
  );
  if (!provider) {
    showInfoFeedback("Anbieterdaten für diesen Stopp fehlen.");
    return;
  }

  const providerName = String(provider.name || "Anbieter").trim();
  const locationLabel = getProviderCoverageSummary(provider);
  const statusLabel = getProviderStatusLabel(provider.status);
  const contactName = buildProviderContactPersonName(provider);
  const phoneValue = String(provider.phone || "").trim();
  const emailValue = String(provider.email || "").trim();
  const websiteValue = String(provider.website || "").trim();
  const telHref = buildTelHref(phoneValue);
  const websiteUrl = normalizeProviderWebsiteUrl(websiteValue);
  const topics = (provider.topicIds || []).map((topicId) => getTopicById(topicId)).filter(Boolean);
  const categories = Array.from(new Set(topics.map((topic) => String(topic.categoryName || "").trim()).filter(Boolean))).sort(
    (left, right) => left.localeCompare(right, "de")
  );
  const subcategories = Array.from(
    new Set(topics.map((topic) => String(topic.subcategoryName || "").trim()).filter(Boolean))
  ).sort((left, right) => left.localeCompare(right, "de"));
  const topicNames = Array.from(new Set(topics.map((topic) => String(topic.name || "").trim()).filter(Boolean))).sort(
    (left, right) => left.localeCompare(right, "de")
  );

  if (els.tourStopInfoTitle) {
    els.tourStopInfoTitle.textContent = providerName;
  }
  if (els.tourStopInfoMeta) {
    els.tourStopInfoMeta.textContent = `${locationLabel} · Status: ${statusLabel}`;
  }
  if (els.tourStopInfoBody) {
    const phoneMarkup = telHref
      ? `<a href="${escapeHtml(telHref)}">${escapeHtml(phoneValue)}</a>`
      : '<span class="tour-stop-info-empty">Nicht hinterlegt</span>';
    const emailMarkup = emailValue
      ? `<a href="mailto:${escapeHtml(emailValue)}">${escapeHtml(emailValue)}</a>`
      : '<span class="tour-stop-info-empty">Nicht hinterlegt</span>';
    const websiteMarkup = websiteUrl
      ? `<a href="${escapeHtml(websiteUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(websiteValue || websiteUrl)}</a>`
      : '<span class="tour-stop-info-empty">Nicht hinterlegt</span>';
    const contactMarkup = contactName
      ? escapeHtml(contactName)
      : '<span class="tour-stop-info-empty">Nicht hinterlegt</span>';
    els.tourStopInfoBody.innerHTML = `
      <div class="tour-stop-info-contact-grid">
        <article class="tour-stop-info-contact-item">
          <h4>Ansprechpartner</h4>
          <p>${contactMarkup}</p>
        </article>
        <article class="tour-stop-info-contact-item">
          <h4>Telefon</h4>
          <p>${phoneMarkup}</p>
        </article>
        <article class="tour-stop-info-contact-item">
          <h4>E-Mail</h4>
          <p>${emailMarkup}</p>
        </article>
        <article class="tour-stop-info-contact-item">
          <h4>Website</h4>
          <p>${websiteMarkup}</p>
        </article>
      </div>
      <div class="tour-stop-info-topic-grid">
        <article class="tour-stop-info-topic-item">
          <h4>Kategorien</h4>
          ${buildTourStopInfoListMarkup(categories, "Keine Kategorien hinterlegt")}
        </article>
        <article class="tour-stop-info-topic-item">
          <h4>Themenbereiche</h4>
          ${buildTourStopInfoListMarkup(subcategories, "Keine Themenbereiche hinterlegt")}
        </article>
        <article class="tour-stop-info-topic-item">
          <h4>Themen</h4>
          ${buildTourStopInfoListMarkup(topicNames, "Keine Themen hinterlegt")}
        </article>
      </div>
    `;
  }
  openTourModal("stopinfo");
}

async function handleTourStopProviderStatusChange(tourId, stopId, providerId, nextStatusRaw) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return false;
  }
  const normalizedProviderId = String(providerId || "").trim();
  const normalizedStopId = String(stopId || "").trim();
  if (!normalizedProviderId || !normalizedStopId) {
    return false;
  }
  const provider = state.providers.find((entry) => String(entry?.id || "").trim() === normalizedProviderId);
  if (!provider) {
    return false;
  }
  if (!canCurrentUserOpenProvider(provider, getCurrentUser())) {
    showProviderLockedFeedback(provider);
    return false;
  }
  const currentStatus = normalizeProviderStatusValue(provider.status);
  const currentUser = getCurrentUser();
  const nextStatus = resolveProviderStatusTransitionForActor(currentStatus, nextStatusRaw, currentUser);
  if (nextStatus === currentStatus) {
    return false;
  }

  let selectedProvisionUserId = resolvePreferredProvisionUserIdForFinalLive(provider, currentStatus);
  if (nextStatus === "live" && currentStatus !== "live") {
    const requestedByNameForApproval =
      currentStatus === PROVIDER_STATUS_LIVE_PENDING ? resolveProviderLiveRequestorName(provider) : "";
    const requestedByUserIdForApproval =
      currentStatus === PROVIDER_STATUS_LIVE_PENDING ? resolveProviderLiveRequestorUserId(provider) : "";
    const requestedByRoleForApproval =
      currentStatus === PROVIDER_STATUS_LIVE_PENDING ? resolveProviderLiveRequestorRole(provider) : "";
    const confirmation = await confirmProviderLiveActivation(provider.name || "", {
      preselectedUserId: selectedProvisionUserId,
      requestedByName: requestedByNameForApproval,
      requestedByUserId: requestedByUserIdForApproval,
      requestedByRole: requestedByRoleForApproval,
      pendingRequest: currentStatus === PROVIDER_STATUS_LIVE_PENDING,
    });
    if (!confirmation?.confirmed) {
      return false;
    }
    selectedProvisionUserId = normalizeUserId(confirmation.provisionUserId || selectedProvisionUserId || "");
  }

  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  provider.status = nextStatus;
  provider.updatedAt = nowIso;
  provider.updatedByName = actor.name;
  provider.updatedByRole = actor.role;
  provider.updatedByUserId = actor.userId;
  applyProviderResponsibilityForStatusTransition(provider, currentStatus, nextStatus, actor, nowIso);
  applyProviderInProgressClaim(provider, currentStatus, nextStatus, actor, nowIso);
  const statusHistorySource =
    nextStatus === PROVIDER_STATUS_LIVE_PENDING
      ? "live_requested"
      : currentStatus === PROVIDER_STATUS_LIVE_PENDING && nextStatus === "live"
        ? "live_approved"
        : "tour_stop";
  appendProviderStatusHistory(provider, currentStatus, nextStatus, actor, nowIso, statusHistorySource);
  if (nextStatus === "live" && currentStatus !== "live") {
    ensureProviderLiveActivationMetadata(provider, actor, nowIso, {
      provisionUserId: selectedProvisionUserId,
    });
  } else if (nextStatus === PROVIDER_STATUS_LIVE_PENDING && currentStatus !== PROVIDER_STATUS_LIVE_PENDING) {
    ensureProviderLiveRequestMetadata(provider, actor, nowIso);
  }
  applyProvisionLedgerForStatusTransition(provider, currentStatus, nextStatus, actor, nowIso, {
    source: statusHistorySource,
    provisionUserId: selectedProvisionUserId || resolveProviderProvisionUserId(provider),
  });
  tour.updatedAt = nowIso;
  tour.updatedByUserId = normalizeUserId(actor.userId || "");
  tour.updatedByName = actor.name;

  const stop = (Array.isArray(tour.stops) ? tour.stops : []).find(
    (entry) => String(entry?.id || "").trim() === normalizedStopId
  );
  const providerName = String(provider.name || stop?.providerId || "Anbieter").trim();
  appendTourActivity(
    tour,
    "provider_status_changed",
    `hat Status bei "${providerName}" von "${getProviderStatusLabel(currentStatus)}" auf "${getProviderStatusLabel(nextStatus)}" geändert.`,
    actor,
    nowIso
  );

  saveState({ showFeedback: false });
  renderToursSection();
  showSuccessFeedback(`Status auf "${getProviderStatusLabel(nextStatus)}" gesetzt.`);
  return true;
}

function reorderTourStops(stops, draggedStopId, targetStopId, placeAfter = false) {
  const rows = Array.isArray(stops) ? stops.slice() : [];
  const normalizedDraggedId = String(draggedStopId || "").trim();
  const normalizedTargetId = String(targetStopId || "").trim();
  if (!normalizedDraggedId) {
    return { changed: false, stops: rows };
  }
  if (normalizedTargetId && normalizedDraggedId === normalizedTargetId) {
    return { changed: false, stops: rows };
  }
  const fromIndex = rows.findIndex((entry) => String(entry.id || "").trim() === normalizedDraggedId);
  if (fromIndex < 0) {
    return { changed: false, stops: rows };
  }
  const [draggedStop] = rows.splice(fromIndex, 1);
  if (!normalizedTargetId) {
    rows.push(draggedStop);
    const changed = fromIndex !== rows.length - 1;
    return { changed, stops: rows };
  }

  const targetIndexRaw = rows.findIndex((entry) => String(entry.id || "").trim() === normalizedTargetId);
  if (targetIndexRaw < 0) {
    rows.push(draggedStop);
    return { changed: fromIndex !== rows.length - 1, stops: rows };
  }
  const insertIndex = Math.max(0, Math.min(rows.length, targetIndexRaw + (placeAfter ? 1 : 0)));
  rows.splice(insertIndex, 0, draggedStop);

  const changed = rows.some((entry, index) => String(entry.id || "").trim() !== String(stops[index]?.id || "").trim());
  return { changed, stops: rows };
}

function handleTourReorderStops(tourId, draggedStopId, targetStopId, placeAfter = false) {
  const tour = getTourById(tourId);
  if (!tour || !canCurrentUserEditTour(tour)) {
    return;
  }
  const { changed, stops } = reorderTourStops(tour.stops || [], draggedStopId, targetStopId, placeAfter);
  if (!changed) {
    return;
  }
  tour.stops = stops;
  const draggedStop = stops.find((entry) => String(entry.id || "").trim() === String(draggedStopId || "").trim());
  const provider = state.providers.find(
    (entry) => String(entry.id || "").trim() === String(draggedStop?.providerId || "").trim()
  );
  const providerName = String(provider?.name || draggedStop?.providerId || "Stop").trim();

  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  tour.updatedAt = nowIso;
  tour.updatedByUserId = normalizeUserId(actor.userId || "");
  tour.updatedByName = actor.name;
  appendTourActivity(tour, "route_reordered", `hat die Reihenfolge angepasst (${providerName} verschoben).`, actor, nowIso);

  saveState({ showFeedback: false });
  renderToursSection();
}

function initGooglePlaces() {
  if (window.google?.maps?.places) {
    setupGooglePlacesServices();
    return;
  }

  const apiKey = getGoogleMapsApiKey();
  if (!apiKey) {
    googlePlacesLoadError = "Kein Google API-Key gefunden (config.js).";
    return;
  }

  if (document.querySelector("script[data-google-places-loader='1']")) {
    return;
  }

  window.__onGooglePlacesLoaded = () => {
    setupGooglePlacesServices();
  };

  window.gm_authFailure = () => {
    googlePlacesLoadError = "Google Auth-Fehler: API-Key ungültig oder nicht erlaubt.";
  };

  const script = document.createElement("script");
  script.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(
    apiKey
  )}&libraries=places&language=de&region=AT&callback=__onGooglePlacesLoaded`;
  script.async = true;
  script.defer = true;
  script.dataset.googlePlacesLoader = "1";
  script.onerror = () => {
    googlePlacesLoadError = "Google Script konnte nicht geladen werden (Netzwerk/Key/Referrer).";
  };
  document.head.appendChild(script);

  window.setTimeout(() => {
    if (!googleMapsReady && !googlePlacesLoadError) {
      googlePlacesLoadError =
        "Google Places nicht geladen. Prüfe Referrer-Regeln, APIs und Billing im Google-Projekt.";
    }
  }, 8000);
}

function setupGooglePlacesServices() {
  if (!window.google?.maps?.places) {
    return;
  }
  googleAutocompleteService = new window.google.maps.places.AutocompleteService();
  googlePlacesService = new window.google.maps.places.PlacesService(document.createElement("div"));
  googleGeocoder = new window.google.maps.Geocoder();
  googleSessionToken = new window.google.maps.places.AutocompleteSessionToken();
  googleMapsReady = true;
  googlePlacesLoadError = "";
  setupTourStartAutocompletes();
  setupUserAddressAutocomplete();
  setupCompanyAddressAutocomplete();
  setupAdditionalLocationAutocompletes();
  renderDashboardMap();
  renderToursSection();
}

function ensureGooglePlacesDetailsService() {
  if (googlePlacesService) {
    return googlePlacesService;
  }
  if (!window.google?.maps?.places) {
    return null;
  }
  try {
    googlePlacesService = new window.google.maps.places.PlacesService(document.createElement("div"));
  } catch (error) {
    console.warn("Google Places Details-Service konnte nicht initialisiert werden.", error);
    googlePlacesService = null;
  }
  return googlePlacesService;
}

function getGoogleMapsApiKey() {
  return (
    window.APP_CONFIG?.GOOGLE_MAPS_API_KEY ||
    window.GOOGLE_MAPS_API_KEY ||
    ""
  ).trim();
}

function queueAddressSuggestionSearch() {
  const query = els.providerAddressInput.value.trim();

  if (addressSearchDebounceId) {
    window.clearTimeout(addressSearchDebounceId);
  }

  if (query.length < 3) {
    clearAddressSuggestions();
    return;
  }

  if (!googleMapsReady || !googleAutocompleteService) {
    if (window.location.protocol === "file:") {
      showAddressSuggestionsMessage(
        "Google Places funktioniert nicht mit file://. Starte die Seite ueber http://localhost:8080."
      );
      return;
    }
    showAddressSuggestionsMessage(
      googlePlacesLoadError ||
        "Google Places ist noch nicht bereit. API-Key, Referrer, APIs und Billing pruefen."
    );
    return;
  }

  addressSearchDebounceId = window.setTimeout(() => {
    fetchGoogleAddressPredictions(query);
  }, 260);
}

function queueProviderNameSuggestionSearch() {
  if (!els.providerNameInput) {
    return;
  }
  const query = els.providerNameInput.value.trim();

  if (providerNameSearchDebounceId) {
    window.clearTimeout(providerNameSearchDebounceId);
  }

  if (query.length < 2) {
    clearProviderNameSuggestions();
    return;
  }

  if (!googleMapsReady || !googleAutocompleteService) {
    if (window.location.protocol === "file:") {
      showProviderNameSuggestionsMessage(
        "Google Places funktioniert nicht mit file://. Starte die Seite ueber http://localhost:8080."
      );
      return;
    }
    showProviderNameSuggestionsMessage(
      googlePlacesLoadError ||
        "Google Places ist noch nicht bereit. API-Key, Referrer, APIs und Billing pruefen."
    );
    return;
  }

  providerNameSearchDebounceId = window.setTimeout(() => {
    fetchProviderNamePredictions(query);
  }, 240);
}

function fetchGoogleAddressPredictions(query) {
  if (!googleAutocompleteService) {
    return;
  }

  const requestId = ++addressPredictionRequestId;
  googleAutocompleteService.getPlacePredictions(
    {
      input: query,
      sessionToken: googleSessionToken,
      types: ["address"],
      language: "de",
    },
    (predictions, status) => {
      if (requestId !== addressPredictionRequestId) {
        return;
      }

      const ok = status === window.google.maps.places.PlacesServiceStatus.OK;
      if (!ok || !predictions?.length) {
        showAddressSuggestionsMessage("Keine Adresse gefunden.");
        return;
      }

      currentAddressSuggestions = predictions.map((prediction) => ({
        placeId: prediction.place_id,
        mainText: prediction.structured_formatting?.main_text || prediction.description || "",
        secondaryText: prediction.structured_formatting?.secondary_text || "",
        description: prediction.description || "",
      }));

      renderAddressSuggestions();
    }
  );
}

function fetchProviderNamePredictions(query) {
  if (!googleAutocompleteService) {
    return;
  }

  const requestId = ++providerNamePredictionRequestId;
  googleAutocompleteService.getPlacePredictions(
    {
      input: query,
      sessionToken: googleSessionToken,
      language: "de",
    },
    (predictions, status) => {
      if (requestId !== providerNamePredictionRequestId) {
        return;
      }

      const ok = status === window.google.maps.places.PlacesServiceStatus.OK;
      if (ok && predictions?.length) {
        currentProviderNameSuggestions = predictions.map((prediction) =>
          mapGooglePredictionToSuggestion(prediction)
        );
        renderProviderNameSuggestions();
        return;
      }

      googleAutocompleteService.getQueryPredictions(
        {
          input: query,
        },
        (queryPredictions, queryStatus) => {
          if (requestId !== providerNamePredictionRequestId) {
            return;
          }
          const queryOk = queryStatus === window.google.maps.places.PlacesServiceStatus.OK;
          if (!queryOk || !queryPredictions?.length) {
            showProviderNameSuggestionsMessage("Keine Anbieter gefunden.");
            return;
          }
          currentProviderNameSuggestions = queryPredictions.map((prediction) =>
            mapGooglePredictionToSuggestion(prediction)
          );
          renderProviderNameSuggestions();
        }
      );
    }
  );
}

function mapGooglePredictionToSuggestion(prediction) {
  return {
    placeId: prediction.place_id || "",
    mainText: prediction.structured_formatting?.main_text || prediction.description || "",
    secondaryText: prediction.structured_formatting?.secondary_text || "",
    description: prediction.description || "",
  };
}

function renderAddressSuggestions() {
  if (!currentAddressSuggestions.length) {
    showAddressSuggestionsMessage("Keine Adresse gefunden.");
    return;
  }

  els.providerAddressSuggestions.innerHTML = currentAddressSuggestions
    .map(
      (entry, index) => `
        <button type="button" class="address-suggestion-item" data-address-index="${index}">
          <span class="address-suggestion-title">${escapeHtml(entry.mainText || entry.description)}</span>
          <span class="address-suggestion-meta">${escapeHtml(entry.secondaryText || "")}</span>
        </button>
      `
    )
    .join("");
  els.providerAddressSuggestions.classList.remove("hidden");
}

function renderProviderNameSuggestions() {
  if (!els.providerNameSuggestions) {
    return;
  }
  if (!currentProviderNameSuggestions.length) {
    showProviderNameSuggestionsMessage("Keine Anbieter gefunden.");
    return;
  }

  els.providerNameSuggestions.innerHTML = currentProviderNameSuggestions
    .map(
      (entry, index) => `
        <button type="button" class="address-suggestion-item" data-provider-name-index="${index}">
          <span class="address-suggestion-title">${escapeHtml(entry.mainText || entry.description)}</span>
          <span class="address-suggestion-meta">${escapeHtml(entry.secondaryText || "")}</span>
        </button>
      `
    )
    .join("");
  els.providerNameSuggestions.classList.remove("hidden");
}

function showAddressSuggestionsMessage(message) {
  currentAddressSuggestions = [];
  els.providerAddressSuggestions.innerHTML = `<p class="empty">${escapeHtml(message)}</p>`;
  els.providerAddressSuggestions.classList.remove("hidden");
}

function showProviderNameSuggestionsMessage(message) {
  if (!els.providerNameSuggestions) {
    return;
  }
  currentProviderNameSuggestions = [];
  els.providerNameSuggestions.innerHTML = `<p class="empty">${escapeHtml(message)}</p>`;
  els.providerNameSuggestions.classList.remove("hidden");
}

function applyAddressSuggestion(index) {
  const suggestion = currentAddressSuggestions[index];
  if (!suggestion) {
    return;
  }

  const formElements = els.providerForm.elements;
  const applyFallbackValues = () => {
    const fallback = mapAddressFromDescription(suggestion.description || "");
    formElements.name.value = pickFirstNonEmpty(formElements.name.value, suggestion.mainText);
    formElements.address.value = pickFirstNonEmpty(
      fallback.street,
      fallback.formatted,
      formElements.address.value || ""
    );
    formElements.postalCode.value = pickFirstNonEmpty(fallback.postalCode, formElements.postalCode.value || "");
    formElements.city.value = pickFirstNonEmpty(fallback.city, formElements.city.value || "");
    formElements.country.value = pickFirstNonEmpty(fallback.country, formElements.country.value || "");
    formElements.state.value = pickFirstNonEmpty(fallback.state, formElements.state.value || "");
    if (
      getSelectedCoverageModeFromForm() === PROVIDER_COVERAGE_MODE_BIG_PLAYER &&
      !getCoverageCountryFromForm() &&
      fallback.country
    ) {
      els.providerCoverageCountryInput.value = fallback.country;
      renderProviderCoverageStateOptions();
    }
    formElements.latitude.value = "";
    formElements.longitude.value = "";
    clearAddressSuggestions();
  };
  const detailsService = ensureGooglePlacesDetailsService();
  if (!detailsService) {
    applyFallbackValues();
    return;
  }

  detailsService.getDetails(
    {
      placeId: suggestion.placeId,
      fields: [
        "name",
        "address_components",
        "formatted_address",
        "geometry",
        "website",
        "formatted_phone_number",
        "international_phone_number",
      ],
      language: "de",
      sessionToken: googleSessionToken,
    },
    (place, status) => {
      const ok = status === window.google.maps.places.PlacesServiceStatus.OK;
      if (!ok || !place) {
        applyFallbackValues();
        googleSessionToken = new window.google.maps.places.AutocompleteSessionToken();
        return;
      }
      const mapped = ok && place ? mapGooglePlaceToAddress(place) : {};
      const fallback = mapAddressFromDescription(suggestion.description || "");
      const merged = {
        street: pickFirstNonEmpty(mapped.street, fallback.street),
        postalCode: pickFirstNonEmpty(mapped.postalCode, fallback.postalCode),
        city: pickFirstNonEmpty(mapped.city, fallback.city),
        state: pickFirstNonEmpty(mapped.state, fallback.state),
        country: pickFirstNonEmpty(mapped.country, fallback.country),
        formatted: pickFirstNonEmpty(mapped.formatted, fallback.formatted),
      };

      formElements.name.value = pickFirstNonEmpty(formElements.name.value, place?.name);
      formElements.address.value = merged.street || merged.formatted || "";
      formElements.postalCode.value = merged.postalCode || "";
      formElements.city.value = merged.city || "";
      formElements.country.value = merged.country || "";
      formElements.state.value = merged.state || "";
      formElements.website.value = pickFirstNonEmpty(place?.website, formElements.website.value || "");
      syncProviderWebsitePreviewLink();
      formElements.phone.value = pickFirstNonEmpty(
        place?.international_phone_number,
        place?.formatted_phone_number,
        formElements.phone.value || ""
      );
      if (
        getSelectedCoverageModeFromForm() === PROVIDER_COVERAGE_MODE_BIG_PLAYER &&
        !getCoverageCountryFromForm() &&
        merged.country
      ) {
        els.providerCoverageCountryInput.value = merged.country;
        renderProviderCoverageStateOptions();
      }
      formElements.latitude.value =
        typeof mapped.latitude === "number" && Number.isFinite(mapped.latitude)
          ? String(mapped.latitude)
          : "";
      formElements.longitude.value =
        typeof mapped.longitude === "number" && Number.isFinite(mapped.longitude)
          ? String(mapped.longitude)
          : "";

      googleSessionToken = new window.google.maps.places.AutocompleteSessionToken();
      clearAddressSuggestions();
    }
  );
}

function applyProviderNameSuggestion(index) {
  const suggestion = currentProviderNameSuggestions[index];
  if (!suggestion) {
    return;
  }

  const formElements = els.providerForm.elements;
  const applyFallbackValues = () => {
    const fallback = mapAddressFromDescription(suggestion.description || "");
    formElements.name.value = pickFirstNonEmpty(suggestion.mainText, formElements.name.value);
    formElements.address.value = pickFirstNonEmpty(
      fallback.street,
      fallback.formatted,
      formElements.address.value || ""
    );
    formElements.postalCode.value = pickFirstNonEmpty(fallback.postalCode, formElements.postalCode.value || "");
    formElements.city.value = pickFirstNonEmpty(fallback.city, formElements.city.value || "");
    formElements.state.value = pickFirstNonEmpty(fallback.state, formElements.state.value || "");
    formElements.country.value = pickFirstNonEmpty(fallback.country, formElements.country.value || "");
    if (
      getSelectedCoverageModeFromForm() === PROVIDER_COVERAGE_MODE_BIG_PLAYER &&
      !getCoverageCountryFromForm() &&
      fallback.country
    ) {
      els.providerCoverageCountryInput.value = fallback.country;
      renderProviderCoverageStateOptions();
    }
  };

  const applyPlaceValues = (place) => {
    const mapped = place ? mapGooglePlaceToAddress(place) : {};
    const fallback = mapAddressFromDescription(suggestion.description || "");
    const merged = {
      street: pickFirstNonEmpty(mapped.street, fallback.street),
      postalCode: pickFirstNonEmpty(mapped.postalCode, fallback.postalCode),
      city: pickFirstNonEmpty(mapped.city, fallback.city),
      state: pickFirstNonEmpty(mapped.state, fallback.state),
      country: pickFirstNonEmpty(mapped.country, fallback.country),
      formatted: pickFirstNonEmpty(mapped.formatted, fallback.formatted),
    };

    formElements.name.value = pickFirstNonEmpty(place?.name, suggestion.mainText, formElements.name.value);
    formElements.address.value = merged.street || merged.formatted || "";
    formElements.postalCode.value = merged.postalCode || "";
    formElements.city.value = merged.city || "";
    formElements.country.value = merged.country || "";
    formElements.state.value = merged.state || "";
    if (
      getSelectedCoverageModeFromForm() === PROVIDER_COVERAGE_MODE_BIG_PLAYER &&
      !getCoverageCountryFromForm() &&
      merged.country
    ) {
      els.providerCoverageCountryInput.value = merged.country;
      renderProviderCoverageStateOptions();
    }
    formElements.website.value = pickFirstNonEmpty(place?.website, formElements.website.value || "");
    syncProviderWebsitePreviewLink();
    formElements.phone.value = pickFirstNonEmpty(
      place?.international_phone_number,
      place?.formatted_phone_number,
      formElements.phone.value || ""
    );
    formElements.latitude.value =
      typeof mapped.latitude === "number" && Number.isFinite(mapped.latitude)
        ? String(mapped.latitude)
        : "";
    formElements.longitude.value =
      typeof mapped.longitude === "number" && Number.isFinite(mapped.longitude)
        ? String(mapped.longitude)
        : "";
  };

  const finalizeSuggestionApply = () => {
    googleSessionToken = new window.google.maps.places.AutocompleteSessionToken();
    clearProviderNameSuggestions();
    clearAddressSuggestions();
  };
  const detailsService = ensureGooglePlacesDetailsService();

  const applySuggestionByPlaceId = (placeId) => {
    if (!detailsService) {
      applyFallbackValues();
      finalizeSuggestionApply();
      return;
    }
    detailsService.getDetails(
      {
        placeId,
        fields: [
          "name",
          "address_components",
          "formatted_address",
          "geometry",
          "website",
          "formatted_phone_number",
          "international_phone_number",
        ],
        language: "de",
        sessionToken: googleSessionToken,
      },
      (place, status) => {
        const ok = status === window.google.maps.places.PlacesServiceStatus.OK;
        if (ok && place) {
          applyPlaceValues(place);
        } else {
          applyFallbackValues();
        }
        finalizeSuggestionApply();
      }
    );
  };

  if (suggestion.placeId) {
    applySuggestionByPlaceId(suggestion.placeId);
    return;
  }

  const query = pickFirstNonEmpty(suggestion.description, suggestion.mainText);
  if (!query || !detailsService || typeof detailsService.findPlaceFromQuery !== "function") {
    applyFallbackValues();
    finalizeSuggestionApply();
    return;
  }

  detailsService.findPlaceFromQuery(
    {
      query,
      fields: ["place_id"],
      language: "de",
    },
    (candidates, status) => {
      const ok = status === window.google.maps.places.PlacesServiceStatus.OK;
      const resolvedPlaceId =
        ok && Array.isArray(candidates) && candidates.length
          ? String(candidates[0]?.place_id || "").trim()
          : "";
      if (resolvedPlaceId) {
        applySuggestionByPlaceId(resolvedPlaceId);
        return;
      }
      applyFallbackValues();
      finalizeSuggestionApply();
    }
  );
}

function mapGooglePlaceToAddress(place) {
  const components = Array.isArray(place.address_components) ? place.address_components : [];
  const findByTypes = (types) => {
    for (const type of types) {
      const value =
        components.find((component) => component.types?.includes(type))?.long_name || "";
      if (value) {
        return value;
      }
    }
    return "";
  };

  const streetNumber = findByTypes(["street_number"]);
  const route = findByTypes(["route", "premise", "point_of_interest"]);
  const city = findByTypes([
    "locality",
    "postal_town",
    "administrative_area_level_3",
    "administrative_area_level_2",
    "sublocality",
    "sublocality_level_1",
  ]);

  return {
    street: [route, streetNumber].filter(Boolean).join(" ").trim(),
    postalCode: findByTypes(["postal_code"]),
    city,
    state: findByTypes(["administrative_area_level_1", "administrative_area_level_2"]),
    country: findByTypes(["country"]),
    formatted: place.formatted_address || "",
    latitude:
      typeof place.geometry?.location?.lat === "function" ? Number(place.geometry.location.lat()) : null,
    longitude:
      typeof place.geometry?.location?.lng === "function" ? Number(place.geometry.location.lng()) : null,
  };
}

function mapAddressFromDescription(description) {
  const parts = String(description)
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);

  if (!parts.length) {
    return {};
  }

  const street = parts[0] || "";
  const country = parts[parts.length - 1] || "";
  const middle = parts.slice(1, -1);
  let postalCode = "";
  let city = "";
  let state = "";

  for (const chunk of middle) {
    const match = chunk.match(/\b(\d{4,6})\b\s*(.*)/);
    if (match) {
      postalCode = postalCode || match[1];
      city = city || (match[2] || "").trim();
    } else if (!state) {
      state = chunk;
    } else if (!city) {
      city = chunk;
    }
  }

  return {
    street,
    postalCode,
    city,
    state,
    country,
    formatted: description || "",
  };
}

function pickFirstNonEmpty(...values) {
  for (const value of values) {
    if (String(value || "").trim()) {
      return String(value).trim();
    }
  }
  return "";
}

