function applyTourStartAutocomplete(inputElement, latitudeElement, longitudeElement, place) {
  if (!inputElement) {
    return;
  }
  const mapped = place ? mapGooglePlaceToAddress(place) : {};
  const fallback = mapAddressFromDescription(place?.formatted_address || "");
  inputElement.value = pickFirstNonEmpty(mapped.formatted, fallback.formatted, mapped.street, fallback.street, inputElement.value || "");
  if (latitudeElement) {
    latitudeElement.value =
      typeof mapped.latitude === "number" && Number.isFinite(mapped.latitude)
        ? String(mapped.latitude)
        : "";
  }
  if (longitudeElement) {
    longitudeElement.value =
      typeof mapped.longitude === "number" && Number.isFinite(mapped.longitude)
        ? String(mapped.longitude)
        : "";
  }
}

function bindTourStartAutocomplete(inputElement, latitudeElement, longitudeElement, currentBinding) {
  currentBinding?.placeChangedListener?.remove?.();
  currentBinding?.inputListener?.();
  if (!googleMapsReady || !window.google?.maps?.places || !inputElement) {
    return null;
  }

  const clearCoordinates = () => {
    if (latitudeElement) {
      latitudeElement.value = "";
    }
    if (longitudeElement) {
      longitudeElement.value = "";
    }
  };

  const autocomplete = new window.google.maps.places.Autocomplete(inputElement, {
    fields: ["address_components", "formatted_address", "geometry"],
    types: ["address"],
  });
  const placeChangedListener = autocomplete.addListener("place_changed", () => {
    applyTourStartAutocomplete(inputElement, latitudeElement, longitudeElement, autocomplete.getPlace());
  });
  inputElement.addEventListener("input", clearCoordinates);

  return {
    autocomplete,
    placeChangedListener,
    inputListener: () => inputElement.removeEventListener("input", clearCoordinates),
  };
}

function setupTourStartAutocompletes() {
  tourStartAutocompleteBinding = bindTourStartAutocomplete(
    els.tourStartLocationInput,
    els.tourStartLatitudeInput,
    els.tourStartLongitudeInput,
    tourStartAutocompleteBinding
  );
}

