function renderProviderBigPlayerTopicTools() {
  if (
    !els.providerBigPlayerTopicTools ||
    !els.providerBigPlayerCategorySelect ||
    !els.providerBigPlayerSubcategorySelect ||
    !els.providerBigPlayerSubcategoryCategorySelect
  ) {
    return;
  }
  const showTools = isAdmin() && getSelectedCoverageModeFromForm() === PROVIDER_COVERAGE_MODE_BIG_PLAYER;
  els.providerBigPlayerTopicTools.classList.toggle("hidden", !showTools);
  if (!showTools) {
    return;
  }

  const categories = state.categories
    .slice()
    .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "de"));
  const currentCategoryId = String(els.providerBigPlayerCategorySelect.value || "").trim();
  const currentSubCategoryCategoryId = String(els.providerBigPlayerSubcategoryCategorySelect.value || "").trim();
  els.providerBigPlayerCategorySelect.innerHTML = categories.length
    ? categories
        .map(
          (category) =>
            `<option value="${escapeHtml(category.id)}">${escapeHtml(category.name || "Kategorie")}</option>`
        )
        .join("")
    : '<option value="">Keine Kategorien</option>';
  els.providerBigPlayerSubcategoryCategorySelect.innerHTML = categories.length
    ? categories
        .map(
          (category) =>
            `<option value="${escapeHtml(category.id)}">${escapeHtml(category.name || "Kategorie")}</option>`
        )
        .join("")
    : '<option value="">Keine Kategorien</option>';

  let selectedCategoryId = currentCategoryId;
  if (!categories.some((category) => category.id === selectedCategoryId)) {
    selectedCategoryId = categories[0]?.id || "";
  }
  els.providerBigPlayerCategorySelect.value = selectedCategoryId;

  let selectedSubcategoryCategoryId = currentSubCategoryCategoryId;
  if (!categories.some((category) => category.id === selectedSubcategoryCategoryId)) {
    selectedSubcategoryCategoryId = selectedCategoryId;
  }
  els.providerBigPlayerSubcategoryCategorySelect.value = selectedSubcategoryCategoryId;

  const selectedCategory = categories.find((category) => category.id === selectedCategoryId) || null;
  const selectedSubcategoryCategory =
    categories.find((category) => category.id === selectedSubcategoryCategoryId) || null;
  const subcategories = (selectedSubcategoryCategory?.subcategories || [])
    .slice()
    .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "de"));
  const currentSubcategoryId = String(els.providerBigPlayerSubcategorySelect.value || "").trim();
  els.providerBigPlayerSubcategorySelect.innerHTML = subcategories.length
    ? subcategories
        .map(
          (subcategory) =>
            `<option value="${escapeHtml(subcategory.id)}">${escapeHtml(subcategory.name || "Themenbereich")}</option>`
        )
        .join("")
    : '<option value="">Keine Themenbereiche</option>';

  let selectedSubcategoryId = currentSubcategoryId;
  if (!subcategories.some((subcategory) => subcategory.id === selectedSubcategoryId)) {
    selectedSubcategoryId = subcategories[0]?.id || "";
  }
  els.providerBigPlayerSubcategorySelect.value = selectedSubcategoryId;

  if (els.providerBigPlayerAllBtn) {
    els.providerBigPlayerAllBtn.disabled = !getAllTopics().length;
  }
  if (els.providerBigPlayerCategoryBtn) {
    els.providerBigPlayerCategoryBtn.disabled = !selectedCategory;
  }
  if (els.providerBigPlayerSubcategoryBtn) {
    els.providerBigPlayerSubcategoryBtn.disabled = !selectedSubcategoryId;
  }

  const mode = getProviderBigPlayerAssignMode();
  if (els.providerBigPlayerRowAll) {
    els.providerBigPlayerRowAll.classList.toggle("hidden", mode !== "all");
  }
  if (els.providerBigPlayerRowCategory) {
    els.providerBigPlayerRowCategory.classList.toggle("hidden", mode !== "category");
  }
  if (els.providerBigPlayerRowSubcategory) {
    els.providerBigPlayerRowSubcategory.classList.toggle("hidden", mode !== "subcategory");
  }

  if (els.providerBigPlayerSelectionSummary) {
    const allTopics = getAllTopics();
    const validTopicIds = new Set(allTopics.map((topic) => topic.id));
    const selectedCount = Array.from(providerTopicSelection).filter((topicId) => validTopicIds.has(topicId)).length;
    els.providerBigPlayerSelectionSummary.textContent = `${selectedCount} von ${allTopics.length} Themen aktuell zugeordnet`;
  }
}

async function submitDesktopTopicRequest(form) {
  const formData = new FormData(form); const topic = String(formData.get("topic") || "").trim(); const note = String(formData.get("note") || "").trim();
  if (!topic) return;
  const actor = getCurrentActorInfo();
  const request = { id: createId("topic_request"), topic: topic.slice(0, 120), note: note.slice(0, 400), providerName: String(els.providerForm?.elements?.name?.value || "").trim().slice(0, 180), requestedByName: String(actor?.name || "Mitarbeiter").trim(), requestedByUserId: normalizeUserId(actor?.userId || ""), createdAt: new Date().toISOString(), status: "open" };
  const button = form.querySelector('button[type="submit"]'); setActionButtonBusy(button, true);
  try {
    const client = getSupabaseClient();
    if (!client) throw new Error("Supabase-Verbindung nicht verfügbar.");
    const { error } = await client.from(TOPIC_REQUESTS_TABLE).insert({
      id: request.id, topic: request.topic, note: request.note, provider_id: editingProviderId || null, provider_name: request.providerName,
      requested_by_user_id: request.requestedByUserId, requested_by_name: request.requestedByName, requested_at: request.createdAt, status: "open",
    });
    if (error) throw error;
    await hydrateTopicRequestsFromSupabase();
    showSuccessFeedback("Kategorieanfrage wurde an den Superadmin gesendet.");
    if (els.providerTopicSearch) els.providerTopicSearch.value = "";
    renderProviderTopicPicker();
  } catch (error) {
    showErrorFeedback(`Kategorieanfrage konnte nicht gesendet werden: ${String(error?.message || "Bitte erneut versuchen.")}`);
  } finally { setActionButtonBusy(button, false); }
}

function openTopicRequestModal(topic = "") {
  document.getElementById("topic-request-modal")?.remove();
  const modal = document.createElement("div"); modal.id = "topic-request-modal"; modal.className = "topic-request-modal";
  modal.innerHTML = `<div class="topic-request-modal-card"><button type="button" data-close-topic-request aria-label="Schließen">×</button><p>KATEGORIEANFRAGE</p><h3>Wunsch an Superadmin</h3><form data-topic-request-form><input name="topic" value="${escapeHtml(topic)}" maxlength="120" required placeholder="Wunschkategorie" autofocus /><textarea name="note" maxlength="400" placeholder="Kurze Ergänzung (optional)"></textarea><button type="submit" class="btn btn-primary">Anfrage senden</button></form></div>`;
  document.body.appendChild(modal);
  modal.addEventListener("click", (event) => { if (event.target === modal || event.target.closest("[data-close-topic-request]")) modal.remove(); });
  modal.querySelector("form").addEventListener("submit", async (event) => { event.preventDefault(); await submitDesktopTopicRequest(event.currentTarget); modal.remove(); });
}

function renderProviderTopicPicker() {
  renderProviderBigPlayerTopicTools();
  const allTopics = getAllTopics().sort((a, b) => {
    const categoryOrder = String(a.categoryName || "").localeCompare(String(b.categoryName || ""), "de");
    if (categoryOrder !== 0) {
      return categoryOrder;
    }
    const subcategoryOrder = String(a.subcategoryName || "").localeCompare(String(b.subcategoryName || ""), "de");
    if (subcategoryOrder !== 0) {
      return subcategoryOrder;
    }
    return String(a.name || "").localeCompare(String(b.name || ""), "de");
  });
  const availableTopicIds = new Set(allTopics.map((topic) => topic.id));
  providerTopicSelection.forEach((topicId) => {
    if (!availableTopicIds.has(topicId)) {
      providerTopicSelection.delete(topicId);
    }
  });

  if (!allTopics.length) {
    els.providerTopicResults.innerHTML =
      '<p class="empty">Noch keine Kategorien vorhanden. Bitte zuerst unter Verwaltung anlegen.</p>';
    els.providerTopicChips.innerHTML = '<p class="empty">Noch keine Kategorien zugeordnet.</p>';
    return;
  }

  const query = normalizeText(els.providerTopicSearch?.value || "");
  const filteredTopics = allTopics.filter((topic) => {
    if (!query) return false;
    const subtopicNames = getTopicSubtopics(topic.id).map((entry) => entry.name).join(" ");
    const searchText = normalizeText(`${topic.name} ${subtopicNames} ${topic.subcategoryName} ${topic.categoryName}`);
    return searchText.includes(query);
  });
  const activeSearchLabel = String(els.providerTopicSearch?.value || "").trim();
  const summaryLabel = query ? `${filteredTopics.length} von ${allTopics.length} Kategorien` : "Kategorie suchen";
  const searchMeta = activeSearchLabel ? ` · Suche: "${activeSearchLabel}"` : "";
  const summaryHtml = `<p class="topic-list-summary">${escapeHtml(summaryLabel + searchMeta)}</p>`;

  els.providerTopicResults.innerHTML = filteredTopics.length
    ? summaryHtml +
      filteredTopics
        .map((topic) => {
          const selected = providerTopicSelection.has(topic.id);
          const matchedSubtopics = query
            ? getTopicSubtopics(topic.id).filter((entry) => normalizeText(entry.name).includes(query))
            : [];
          const matchingHint = matchedSubtopics.length
            ? ` · gefunden über Sub-Thema: ${matchedSubtopics.map((entry) => entry.name).join(", ")}`
            : "";
          return `
            <button
              type="button"
              class="topic-result ${selected ? "selected" : ""}"
              data-topic-id="${escapeHtml(topic.id)}"
            >
              <span class="topic-result-title">${escapeHtml(topic.name)}</span>
              <span class="topic-result-meta">${escapeHtml(topic.subcategoryName)} · ${escapeHtml(
                topic.categoryName
              )}${escapeHtml(matchingHint)}</span>
            </button>
          `;
        })
        .join("")
    : summaryHtml;

  const topicRequestMarkup = `<button type="button" class="topic-request-box topic-request-open" data-open-topic-request data-topic-query="${escapeHtml(activeSearchLabel)}"><strong>Kategorie fehlt?</strong><span>Anfrage an Superadmin senden ›</span></button>`;
  els.providerTopicResults.insertAdjacentHTML("beforeend", topicRequestMarkup);

  const selectedTopics = allTopics.filter((topic) => providerTopicSelection.has(topic.id));
  els.providerTopicChips.innerHTML = selectedTopics.length
    ? selectedTopics
        .map(
          (topic) => `
            <div class="topic-chip">
              <div class="topic-chip-text">
                <strong>${escapeHtml(topic.name)}</strong>
                <span>${escapeHtml(topic.subcategoryName)} · ${escapeHtml(topic.categoryName)}</span>
              </div>
              <button
                type="button"
                class="mini-btn danger"
                data-remove-topic="${escapeHtml(topic.id)}"
                title="Zuordnung entfernen"
                aria-label="Zuordnung entfernen"
              >✕</button>
            </div>
          `
        )
        .join("")
    : '<p class="empty">Noch keine Kategorien zugeordnet.</p>';
}

function createEmptyProviderLocation() {
  return {
    address: "",
    postalCode: "",
    city: "",
    state: "",
    country: "",
    latitude: null,
    longitude: null,
  };
}

function normalizeProviderCoverageMode(modeLike) {
  const normalizedMode = normalizeText(modeLike).replace(/[\s_-]+/g, "");
  const bigPlayerKey = normalizeText(PROVIDER_COVERAGE_MODE_BIG_PLAYER).replace(/[\s_-]+/g, "");
  return normalizedMode === bigPlayerKey ? PROVIDER_COVERAGE_MODE_BIG_PLAYER : PROVIDER_COVERAGE_MODE_LOCATIONS;
}

function normalizeProviderCoverageStates(statesLike) {
  if (!Array.isArray(statesLike)) {
    return [];
  }
  const seen = new Set();
  const normalized = [];
  statesLike.forEach((stateLabel) => {
    const label = String(stateLabel || "").trim();
    if (!label) {
      return;
    }
    const key = normalizeText(label);
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    normalized.push(label);
  });
  return normalized.sort((a, b) => a.localeCompare(b, "de"));
}

function getPredefinedStatesForCountry(country) {
  const countryKey = normalizeText(country);
  if (!countryKey) {
    return [];
  }
  return Array.isArray(PREDEFINED_STATES_BY_COUNTRY[countryKey]) ? PREDEFINED_STATES_BY_COUNTRY[countryKey] : [];
}

function normalizeProviderCoverageStatesForCountry(statesLike, country) {
  const normalizedStates = normalizeProviderCoverageStates(statesLike);
  const predefinedStates = getPredefinedStatesForCountry(country);
  if (!predefinedStates.length) {
    return normalizedStates;
  }

  const predefinedByKey = new Map(
    predefinedStates.map((stateLabel) => [normalizeText(stateLabel), stateLabel])
  );
  const seen = new Set();
  const sanitized = [];
  normalizedStates.forEach((stateLabel) => {
    const stateKey = normalizeText(stateLabel);
    if (!stateKey || seen.has(stateKey)) {
      return;
    }
    const canonicalStateLabel = predefinedByKey.get(stateKey);
    if (!canonicalStateLabel) {
      return;
    }
    seen.add(stateKey);
    sanitized.push(canonicalStateLabel);
  });
  return sanitized.sort((a, b) => a.localeCompare(b, "de"));
}

function getProviderCoverageMode(provider) {
  return normalizeProviderCoverageMode(provider?.coverageMode);
}

function isBigPlayerProvider(provider) {
  return getProviderCoverageMode(provider) === PROVIDER_COVERAGE_MODE_BIG_PLAYER;
}

function getProviderCoverageCountry(provider) {
  const fromCoverage = String(provider?.coverageCountry || "").trim();
  if (fromCoverage) {
    return fromCoverage;
  }
  const firstLocation = getProviderLocations(provider)[0];
  return String(firstLocation?.country || provider?.country || "").trim();
}

function getProviderCoverageStates(provider) {
  return normalizeProviderCoverageStatesForCountry(
    provider?.coverageStates || [],
    getProviderCoverageCountry(provider)
  );
}

function getStateCenterCoordinates(country, stateLabel) {
  const countryKey = normalizeText(country);
  const stateKey = normalizeText(stateLabel);
  if (!countryKey || !stateKey) {
    return null;
  }
  const countryMap = PREDEFINED_STATE_COORDINATES_BY_COUNTRY[countryKey];
  if (!countryMap) {
    return null;
  }
  return countryMap[stateKey] || null;
}

function getProviderEffectiveLocations(provider) {
  const rawLocations = getProviderLocations(provider);
  if (!isBigPlayerProvider(provider)) {
    return rawLocations.map((location, locationIndex) => ({
      ...location,
      __coverageVirtual: false,
      __sourceLocationIndex: locationIndex,
    }));
  }

  const country = getProviderCoverageCountry(provider);
  if (!country) {
    return rawLocations.map((location, locationIndex) => ({
      ...location,
      __coverageVirtual: false,
      __sourceLocationIndex: locationIndex,
    }));
  }

  const selectedStates = getProviderCoverageStates(provider);
  const predefinedStates = getPredefinedStatesForCountry(country);
  const locationStates = normalizeProviderCoverageStatesForCountry(
    rawLocations.map((location) => location.state),
    country
  );
  const states = selectedStates.length
    ? selectedStates
    : normalizeProviderCoverageStatesForCountry(predefinedStates.concat(locationStates), country);
  if (!states.length) {
    const fallbackBase = rawLocations[0] || createEmptyProviderLocation();
    return [
      {
        ...fallbackBase,
        country,
        state: "",
        latitude: parseOptionalNumber(fallbackBase.latitude),
        longitude: parseOptionalNumber(fallbackBase.longitude),
        __coverageVirtual: true,
        __sourceLocationIndex: null,
      },
    ];
  }

  const fallbackBase = rawLocations[0] || createEmptyProviderLocation();
  return states.map((stateLabel, stateIndex) => {
    const center = getStateCenterCoordinates(country, stateLabel);
    return {
      ...fallbackBase,
      country,
      state: stateLabel,
      city: fallbackBase.city || stateLabel,
      latitude: center?.lat ?? parseOptionalNumber(fallbackBase.latitude),
      longitude: center?.lng ?? parseOptionalNumber(fallbackBase.longitude),
      __coverageVirtual: true,
      __sourceLocationIndex: `coverage-${stateIndex}`,
    };
  });
}

function normalizeProviderNoteRecord(note, index = 0) {
  if (!note || typeof note !== "object") {
    return null;
  }
  const parsedNote = parseProviderNoteText(note.text || note.note_text || "");
  const text = parsedNote.text;
  const createdByUserId = normalizeUserId(note.createdByUserId || note.created_by_user_id || "");
  if (!text || !createdByUserId) {
    return null;
  }
  const explicitDone = Boolean(note.done || note.is_done || parsedNote.done);
  const createdAt = String(note.createdAt || note.created_at || "").trim();
  const fallbackUpdatedAt = String(note.updatedAt || note.updated_at || "").trim();
  const parsedUpdatedAt = String(parsedNote.updatedAt || "").trim();
  const createdAtMs = Number.isFinite(Date.parse(createdAt)) ? Date.parse(createdAt) : 0;
  const fallbackUpdatedAtMs = Number.isFinite(Date.parse(fallbackUpdatedAt)) ? Date.parse(fallbackUpdatedAt) : 0;
  const effectiveUpdatedAt =
    parsedUpdatedAt ||
    (fallbackUpdatedAtMs && createdAtMs && Math.abs(fallbackUpdatedAtMs - createdAtMs) > 2000 ? fallbackUpdatedAt : "");
  const task = Boolean(note.task || parsedNote.task);
  const dueDate = task ? sanitizeEmployeeAdminDate(note.dueDate || note.due_date || parsedNote.dueDate || "") : "";
  const doneAt = explicitDone
    ? String(note.doneAt || note.done_at || parsedNote.doneAt || "").trim()
    : "";
  const doneByUserId = explicitDone
    ? normalizeUserId(note.doneByUserId || note.done_by_user_id || parsedNote.doneByUserId || "")
    : "";
  const doneByName = explicitDone
    ? String(note.doneByName || note.done_by_name || parsedNote.doneByName || "").trim()
    : "";
  const doneByRoleRaw = explicitDone
    ? String(note.doneByRole || note.done_by_role || parsedNote.doneByRole || "").trim()
    : "";
  const doneByRole = doneByRoleRaw ? normalizeUserRole(doneByRoleRaw) : "";
  const updatedByUserId = normalizeUserId(
    note.updatedByUserId || note.updated_by_user_id || parsedNote.updatedByUserId || ""
  );
  const updatedByName = String(note.updatedByName || note.updated_by_name || parsedNote.updatedByName || "").trim();
  const updatedByRoleRaw = String(note.updatedByRole || note.updated_by_role || parsedNote.updatedByRole || "").trim();
  const updatedByRole = updatedByRoleRaw ? normalizeUserRole(updatedByRoleRaw) : "";
  return {
    id: String(note.id || `note_${index}_${createdByUserId || "user"}`).trim(),
    text,
    createdAt,
    createdByUserId,
    createdByName: String(note.createdByName || note.created_by_name || "").trim(),
    createdByRole: normalizeUserRole(note.createdByRole || note.created_by_role),
    task,
    dueDate,
    done: explicitDone,
    doneAt,
    doneByUserId,
    doneByName,
    doneByRole,
    updatedAt: effectiveUpdatedAt,
    updatedByUserId,
    updatedByName,
    updatedByRole,
  };
}

function parseProviderNoteText(rawTextLike) {
  const rawText = String(rawTextLike || "").trim();
  if (!rawText) {
    return {
      text: "",
      done: false,
      doneAt: "",
      doneByUserId: "",
      doneByName: "",
      doneByRole: "",
      task: false,
      dueDate: "",
      updatedAt: "",
      updatedByUserId: "",
      updatedByName: "",
      updatedByRole: "",
    };
  }
  const metadataMatch = rawText.match(/^\[(VMMETA@)([^\]]+)\]\s*/i);
  if (metadataMatch) {
    const metadataEncoded = String(metadataMatch[2] || "").trim();
    let metadata = {};
    try {
      metadata = JSON.parse(decodeURIComponent(metadataEncoded));
    } catch (_error) {
      metadata = {};
    }
    const text = rawText.replace(/^\[(VMMETA@)([^\]]+)\]\s*/i, "").trim();
    return {
      text,
      done: Boolean(metadata.done),
      doneAt: String(metadata.doneAt || "").trim(),
      doneByUserId: normalizeUserId(metadata.doneByUserId || ""),
      doneByName: String(metadata.doneByName || "").trim(),
      doneByRole: String(metadata.doneByRole || "").trim()
        ? normalizeUserRole(metadata.doneByRole || "")
        : "",
      task: Boolean(metadata.task),
      dueDate: sanitizeEmployeeAdminDate(metadata.dueDate || ""),
      updatedAt: String(metadata.updatedAt || "").trim(),
      updatedByUserId: normalizeUserId(metadata.updatedByUserId || ""),
      updatedByName: String(metadata.updatedByName || "").trim(),
      updatedByRole: String(metadata.updatedByRole || "").trim()
        ? normalizeUserRole(metadata.updatedByRole || "")
        : "",
    };
  }
  const doneMatch = rawText.match(/^\[erledigt(?:@([^\]]+))?\]\s*/i);
  const done = Boolean(doneMatch);
  const metadataRaw = done ? String(doneMatch?.[1] || "").trim() : "";
  const metadataParts = metadataRaw ? metadataRaw.split("|") : [];
  const decodeMeta = (value) => {
    const rawValue = String(value || "").trim();
    if (!rawValue) {
      return "";
    }
    try {
      return decodeURIComponent(rawValue);
    } catch (_error) {
      return rawValue;
    }
  };
  const doneAt = done ? decodeMeta(metadataParts[0] || metadataRaw) : "";
  const doneByUserId = done ? normalizeUserId(decodeMeta(metadataParts[1] || "")) : "";
  const doneByName = done ? decodeMeta(metadataParts[2] || "") : "";
  const doneByRoleRaw = done ? decodeMeta(metadataParts[3] || "") : "";
  const doneByRole = doneByRoleRaw ? normalizeUserRole(doneByRoleRaw) : "";
  const text = done ? rawText.replace(/^\[erledigt(?:@([^\]]+))?\]\s*/i, "").trim() : rawText;
  return {
    text,
    done,
    doneAt,
    doneByUserId,
    doneByName,
    doneByRole,
    task: false,
    dueDate: "",
    updatedAt: "",
    updatedByUserId: "",
    updatedByName: "",
    updatedByRole: "",
  };
}

function toProviderNoteStorageText(note) {
  const text = String(note?.text || "").trim();
  if (!text) {
    return "";
  }
  const metadata = {
    done: Boolean(note?.done),
    doneAt: note?.done ? String(note?.doneAt || "").trim() || new Date().toISOString() : "",
    doneByUserId: note?.done ? normalizeUserId(note?.doneByUserId || "") : "",
    doneByName: note?.done ? String(note?.doneByName || "").trim() : "",
    doneByRole:
      note?.done && String(note?.doneByRole || "").trim() ? normalizeUserRole(note?.doneByRole || "") : "",
    task: Boolean(note?.task),
    dueDate: note?.task ? sanitizeEmployeeAdminDate(note?.dueDate || "") : "",
    updatedAt: String(note?.updatedAt || "").trim(),
    updatedByUserId: normalizeUserId(note?.updatedByUserId || ""),
    updatedByName: String(note?.updatedByName || "").trim(),
    updatedByRole: String(note?.updatedByRole || "").trim() ? normalizeUserRole(note?.updatedByRole || "") : "",
  };
  return `[${PROVIDER_NOTE_STORAGE_PREFIX}${encodeURIComponent(JSON.stringify(metadata))}] ${text}`;
}

function normalizeProviderNotes(notesLike) {
  if (!Array.isArray(notesLike)) {
    return [];
  }
  return notesLike
    .map((note, index) => normalizeProviderNoteRecord(note, index))
    .filter(Boolean)
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")));
}

function getCurrentProviderExportHistoryUserId() {
  return normalizeUserId(getCurrentUserId());
}

function getProviderExportHistoryByUserId(userId = getCurrentProviderExportHistoryUserId()) {
  const normalizedUserId = normalizeUserId(userId);
  if (!normalizedUserId) {
    return [];
  }
  const historyMap = normalizeProviderExportHistoryByUserId(state.settings?.providerExportHistoryByUserId || {});
  return Array.isArray(historyMap[normalizedUserId]) ? historyMap[normalizedUserId].slice() : [];
}

function setProviderExportHistoryByUserId(userId, historyEntries) {
  const normalizedUserId = normalizeUserId(userId);
  if (!normalizedUserId) {
    return;
  }
  const historyMap = normalizeProviderExportHistoryByUserId(state.settings?.providerExportHistoryByUserId || {});
  const normalizedHistory = Array.isArray(historyEntries)
    ? historyEntries
        .map((entry, index) => normalizeProviderExportHistoryEntry(entry, index))
        .filter(Boolean)
        .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
        .slice(0, PROVIDER_EXPORT_HISTORY_MAX_ENTRIES_PER_USER)
    : [];
  if (normalizedHistory.length) {
    historyMap[normalizedUserId] = normalizedHistory;
  } else {
    delete historyMap[normalizedUserId];
  }
  state.settings = normalizeSettings({
    ...state.settings,
    providerExportHistoryByUserId: historyMap,
  });
}

function getExportedProviderIdSetForCurrentUser() {
  const history = getProviderExportHistoryByUserId();
  const exportedProviderIds = new Set();
  history.forEach((entry) => {
    (Array.isArray(entry?.providerIds) ? entry.providerIds : []).forEach((providerId) => {
      const normalizedProviderId = String(providerId || "").trim();
      if (normalizedProviderId) {
        exportedProviderIds.add(normalizedProviderId);
      }
    });
  });
  return exportedProviderIds;
}

function appendProviderExportHistoryEntry(entry) {
  const userId = getCurrentProviderExportHistoryUserId();
  if (!userId) {
    return;
  }
  const history = getProviderExportHistoryByUserId(userId);
  history.unshift({
    id: createId("pexp"),
    createdAt: new Date().toISOString(),
    fieldIds: Array.isArray(entry?.fieldIds) ? entry.fieldIds : [],
    providerIds: Array.isArray(entry?.providerIds) ? entry.providerIds : [],
    fileName: String(entry?.fileName || "").trim(),
    excludedCount: Math.max(0, Math.round(Number(entry?.excludedCount || 0) || 0)),
  });
  setProviderExportHistoryByUserId(userId, history);
}

function clearProviderExportHistoryForCurrentUser() {
  const userId = getCurrentProviderExportHistoryUserId();
  if (!userId) {
    return;
  }
  setProviderExportHistoryByUserId(userId, []);
}

function getProviderNoteAuditLog() {
  return normalizeProviderNoteAuditLog(state.settings?.providerNoteAuditLog || []);
}

function appendProviderNoteAuditEntry(entry, options = {}) {
  const currentLog = getProviderNoteAuditLog();
  currentLog.push({
    id: createId("pna"),
    providerId: String(entry?.providerId || "").trim(),
    noteId: String(entry?.noteId || "").trim(),
    action: String(entry?.action || "").trim().toLowerCase(),
    at: String(entry?.at || "").trim() || new Date().toISOString(),
    actorUserId: normalizeUserId(entry?.actorUserId || ""),
    actorName: String(entry?.actorName || "").trim(),
    actorRole: normalizeUserRole(entry?.actorRole || ""),
    providerName: String(entry?.providerName || "").trim(),
    noteText: String(entry?.noteText || "").trim(),
    dueDate: sanitizeEmployeeAdminDate(entry?.dueDate || ""),
    done: Boolean(entry?.done),
  });
  state.settings = normalizeSettings({
    ...state.settings,
    providerNoteAuditLog: currentLog.slice(-PROVIDER_NOTE_AUDIT_LOG_MAX_ENTRIES),
  });
  if (options?.persist !== false) {
    saveState({ showFeedback: false });
  }
}

function canCurrentUserManageProviderNote(note) {
  const currentUserId = normalizeUserId(getCurrentUserId());
  return !!currentUserId && currentUserId === normalizeUserId(note?.createdByUserId || "");
}

function canCurrentUserDeleteProviderNote(note) {
  const currentUserId = normalizeUserId(getCurrentUserId());
  if (isRoleAdmin()) {
    return Boolean(currentUserId && String(note?.id || "").trim());
  }
  const noteId = String(note?.id || "").trim();
  const noteOwnerUserId = normalizeUserId(note?.createdByUserId || note?.created_by_user_id || "");
  return Boolean(currentUserId && noteId && noteOwnerUserId && currentUserId === noteOwnerUserId);
}

function isProviderTaskNote(note) {
  return Boolean(note?.task);
}

function buildProviderNoteMergeKey(note) {
  const noteId = String(note?.id || "").trim();
  if (noteId) {
    return `id:${noteId}`;
  }
  return [
    "sig",
    normalizeUserId(note?.createdByUserId || ""),
    normalizeText(note?.text || ""),
    String(note?.createdAt || "").trim(),
  ].join("|");
}

function mergeProviderNoteCollections(primaryNotes, secondaryNotes) {
  const mergedMap = new Map();
  const appendNotes = (notes) => {
    normalizeProviderNotes(notes || []).forEach((note) => {
      const key = buildProviderNoteMergeKey(note);
      if (!mergedMap.has(key)) {
        mergedMap.set(key, note);
      }
    });
  };
  appendNotes(primaryNotes);
  appendNotes(secondaryNotes);
  return Array.from(mergedMap.values()).sort((left, right) =>
    String(right.createdAt || "").localeCompare(String(left.createdAt || ""))
  );
}

function normalizeProviderLocation(location) {
  return {
    address: String(location?.address || "").trim(),
    postalCode: String(location?.postalCode || "").trim(),
    city: String(location?.city || "").trim(),
    state: String(location?.state || "").trim(),
    country: normalizeCountryLabel(location?.country || ""),
    latitude: parseOptionalNumber(location?.latitude),
    longitude: parseOptionalNumber(location?.longitude),
  };
}

function hasProviderLocationContent(location) {
  const normalized = normalizeProviderLocation(location);
  return Boolean(
    normalized.address ||
      normalized.postalCode ||
      normalized.city ||
      normalized.state ||
      normalized.country ||
      typeof normalized.latitude === "number" ||
      typeof normalized.longitude === "number"
  );
}

function isProviderLocationComplete(location) {
  const normalized = normalizeProviderLocation(location);
  return Boolean(
    normalized.address &&
      normalized.postalCode &&
      normalized.city &&
      normalized.state &&
      normalized.country
  );
}

function normalizeProviderLocations(locations, providerFallback = null) {
  const normalized = Array.isArray(locations)
    ? locations
        .map((location) => normalizeProviderLocation(location))
        .filter((location) => hasProviderLocationContent(location))
    : [];
  if (normalized.length) {
    return normalized;
  }

  if (providerFallback && typeof providerFallback === "object") {
    const legacyLocation = normalizeProviderLocation({
      address: providerFallback.address,
      postalCode: providerFallback.postalCode,
      city: providerFallback.city,
      state: providerFallback.state,
      country: providerFallback.country,
      latitude: providerFallback.latitude,
      longitude: providerFallback.longitude,
    });
    if (hasProviderLocationContent(legacyLocation)) {
      return [legacyLocation];
    }
  }
  return [];
}

function getProviderLocations(provider) {
  return normalizeProviderLocations(provider?.locations, provider);
}

function syncProviderPrimaryLocationFields(provider) {
  const primaryLocation = getProviderLocations(provider)[0] || createEmptyProviderLocation();
  provider.address = primaryLocation.address;
  provider.postalCode = primaryLocation.postalCode;
  provider.city = primaryLocation.city;
  provider.state = primaryLocation.state;
  provider.country = primaryLocation.country;
  provider.latitude = primaryLocation.latitude;
  provider.longitude = primaryLocation.longitude;
}

function syncProviderCoverageStatesDraftFromDom() {
  if (!els.providerCoverageStateList) {
    return;
  }
  providerCoverageStatesDraft = Array.from(
    els.providerCoverageStateList.querySelectorAll('input[data-provider-coverage-state]:checked')
  ).map((checkbox) => String(checkbox.dataset.providerCoverageState || "").trim());
  providerCoverageStatesDraft = normalizeProviderCoverageStatesForCountry(
    providerCoverageStatesDraft,
    getCoverageCountryFromForm()
  );
}

function getSelectedCoverageModeFromForm() {
  const checked = els.providerForm.querySelector('input[name="coverageMode"]:checked');
  return normalizeProviderCoverageMode(checked?.value);
}

function setCoverageModeInForm(mode) {
  const normalizedMode = normalizeProviderCoverageMode(mode);
  els.providerForm.querySelectorAll('input[name="coverageMode"]').forEach((input) => {
    input.checked = normalizeProviderCoverageMode(input.value) === normalizedMode;
  });
}

function getCoverageCountryFromForm() {
  return String(els.providerCoverageCountryInput?.value || "").trim();
}

function normalizeProviderWebsiteUrl(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue) {
    return "";
  }
  const hasScheme = /^[a-zA-Z][a-zA-Z\d+\-.]*:/.test(rawValue);
  const candidate = hasScheme ? rawValue : `https://${rawValue}`;
  try {
    const parsed = new URL(candidate);
    const protocol = String(parsed.protocol || "").toLowerCase();
    if (protocol !== "http:" && protocol !== "https:") {
      return "";
    }
    return parsed.href;
  } catch (_error) {
    return "";
  }
}

function extractComparableWebsiteHost(value) {
  const normalizedUrl = normalizeProviderWebsiteUrl(value);
  if (!normalizedUrl) {
    return "";
  }
  try {
    return String(new URL(normalizedUrl).hostname || "")
      .trim()
      .toLowerCase()
      .replace(/^www\./, "");
  } catch (_error) {
    return "";
  }
}

function normalizeComparablePhone(value) {
  const digits = String(value || "").replace(/\D+/g, "");
  return digits.length >= 6 ? digits : "";
}

function normalizeProviderContactSalutation(value) {
  const normalized = normalizeText(value || "");
  if (normalized === "herr") {
    return "Herr";
  }
  if (normalized === "frau") {
    return "Frau";
  }
  if (normalized === "firma") {
    return "Firma";
  }
  if (normalized === "divers") {
    return "Divers";
  }
  return "";
}

function normalizeProviderContactTitle(value) {
  const normalized = normalizeText(value || "").replace(/\./g, "");
  const titleMap = new Map([
    ["dr", "Dr."],
    ["ddr", "DDr."],
    ["mag", "Mag."],
    ["mmag", "MMag."],
    ["mag (fh)", "Mag. (FH)"],
    ["di", "DI"],
    ["di (fh)", "DI (FH)"],
    ["dipl ing", "Dipl.-Ing."],
    ["dipl-ing", "Dipl.-Ing."],
    ["dipl.ing", "Dipl.-Ing."],
    ["ing", "Ing."],
    ["bsc", "BSc"],
    ["ba", "BA"],
    ["msc", "MSc"],
    ["ma", "MA"],
    ["mba", "MBA"],
    ["phd", "PhD"],
    ["llm", "LL.M."],
    ["univ prof", "Univ.-Prof."],
    ["univ-prof", "Univ.-Prof."],
    ["univ.prof", "Univ.-Prof."],
    ["prof", "Prof."],
  ]);
  return titleMap.get(normalized) || "";
}

function getProviderContactLegacyParts(provider) {
  const rawName = String(provider?.contactPerson || provider?.contact_person || "").trim();
  if (!rawName) {
    return { salutation: "", title: "", firstName: "", lastName: "" };
  }
  const words = rawName.split(/\s+/).filter(Boolean);
  const salutation = normalizeProviderContactSalutation(words[0] || "");
  const wordsAfterSalutation = salutation ? words.slice(1) : words;
  const title = normalizeProviderContactTitle(wordsAfterSalutation[0] || "");
  const nameWords = title ? wordsAfterSalutation.slice(1) : wordsAfterSalutation;
  if (!nameWords.length) {
    return { salutation, title, firstName: "", lastName: "" };
  }
  if (nameWords.length === 1) {
    return { salutation, title, firstName: nameWords[0], lastName: "" };
  }
  return {
    salutation,
    title,
    firstName: nameWords[0],
    lastName: nameWords.slice(1).join(" "),
  };
}

function hasStructuredProviderContactParts(provider) {
  const salutation = normalizeProviderContactSalutation(provider?.contactSalutation || provider?.contact_salutation || "");
  const title = normalizeProviderContactTitle(provider?.contactTitle || provider?.contact_title || "");
  const firstName = String(provider?.contactFirstName || provider?.contact_first_name || "").trim();
  const lastName = String(provider?.contactLastName || provider?.contact_last_name || "").trim();
  return Boolean(salutation || title || firstName || lastName);
}

function getProviderContactSalutation(provider) {
  const structured = normalizeProviderContactSalutation(provider?.contactSalutation || provider?.contact_salutation || "");
  if (structured) {
    return structured;
  }
  if (hasStructuredProviderContactParts(provider)) {
    return "";
  }
  return getProviderContactLegacyParts(provider).salutation;
}

function getProviderContactTitle(provider) {
  const structured = normalizeProviderContactTitle(provider?.contactTitle || provider?.contact_title || "");
  if (structured) {
    return structured;
  }
  if (hasStructuredProviderContactParts(provider)) {
    return "";
  }
  return getProviderContactLegacyParts(provider).title;
}

function getProviderContactFirstName(provider) {
  const structured = String(provider?.contactFirstName || provider?.contact_first_name || "").trim();
  if (structured) {
    return structured;
  }
  if (hasStructuredProviderContactParts(provider)) {
    return "";
  }
  return getProviderContactLegacyParts(provider).firstName;
}

function getProviderContactLastName(provider) {
  const structured = String(provider?.contactLastName || provider?.contact_last_name || "").trim();
  if (structured) {
    return structured;
  }
  if (hasStructuredProviderContactParts(provider)) {
    return "";
  }
  return getProviderContactLegacyParts(provider).lastName;
}

function buildProviderContactPersonName(provider) {
  const structuredName = [
    getProviderContactSalutation(provider),
    getProviderContactTitle(provider),
    getProviderContactFirstName(provider),
    getProviderContactLastName(provider),
  ]
    .filter(Boolean)
    .join(" ")
    .trim();
  return structuredName || String(provider?.contactPerson || provider?.contact_person || "").trim();
}

function syncProviderWebsitePreviewLink() {
  if (!els.providerWebsitePreviewLink) {
    return;
  }
  const rawValue = String(
    els.providerWebsiteInput?.value || els.providerForm?.elements?.website?.value || ""
  ).trim();
  const websiteUrl = normalizeProviderWebsiteUrl(rawValue);
  if (!websiteUrl) {
    els.providerWebsitePreviewLink.classList.add("hidden");
    els.providerWebsitePreviewLink.removeAttribute("href");
    els.providerWebsitePreviewLink.textContent = "";
    return;
  }
  els.providerWebsitePreviewLink.href = websiteUrl;
  els.providerWebsitePreviewLink.textContent = "Website öffnen";
  els.providerWebsitePreviewLink.classList.remove("hidden");
}

function renderProviderCoverageCountryDatalist() {
  if (!els.providerCoverageCountryDatalist) {
    return;
  }
  const countries = getAvailableCountriesFromProviders();
  els.providerCoverageCountryDatalist.innerHTML = countries
    .map((country) => `<option value="${escapeHtml(country)}"></option>`)
    .join("");
}

function renderProviderCoverageStateOptions() {
  if (!els.providerCoverageStateList || !els.providerCoverageStateWrap) {
    return;
  }
  const country = getCoverageCountryFromForm();
  if (!country) {
    els.providerCoverageStateList.innerHTML = "";
    els.providerCoverageStateWrap.classList.add("hidden");
    return;
  }

  const states = getAvailableStatesForCountry(country);
  providerCoverageStatesDraft = normalizeProviderCoverageStatesForCountry(providerCoverageStatesDraft, country);
  const selectedStates = new Set(
    providerCoverageStatesDraft.map((stateLabel) => normalizeText(stateLabel))
  );

  if (!states.length) {
    els.providerCoverageStateWrap.classList.remove("hidden");
    els.providerCoverageStateList.innerHTML =
      '<p class="provider-coverage-empty">Keine Bundesländer für dieses Land hinterlegt. Ohne Auswahl gilt das gesamte Land.</p>';
    return;
  }

  els.providerCoverageStateWrap.classList.remove("hidden");
  els.providerCoverageStateList.innerHTML = states
    .map(
      (stateLabel) => `
        <label class="provider-coverage-state-item">
          <input
            type="checkbox"
            data-provider-coverage-state="${escapeHtml(stateLabel)}"
            ${selectedStates.has(normalizeText(stateLabel)) ? "checked" : ""}
          />
          <span>${escapeHtml(stateLabel)}</span>
        </label>
      `
    )
    .join("");
}

function syncProviderCoverageFormState() {
  const mode = getSelectedCoverageModeFromForm();
  const isBigPlayer = mode === PROVIDER_COVERAGE_MODE_BIG_PLAYER;
  if (els.providerCoverageConfig) {
    els.providerCoverageConfig.classList.toggle("hidden", !isBigPlayer);
  }
  if (els.providerLocationsList?.closest(".provider-locations-panel")) {
    els.providerLocationsList.closest(".provider-locations-panel").classList.toggle("hidden", isBigPlayer);
  }

  const requiredInLocationMode = [
    els.providerAddressInput,
    els.providerForm.elements.postalCode,
    els.providerForm.elements.city,
    els.providerForm.elements.country,
    els.providerForm.elements.state,
  ];
  requiredInLocationMode.forEach((field) => {
    if (!field) {
      return;
    }
    field.required = !isBigPlayer;
  });

  if (!isBigPlayer) {
    providerCoverageStatesDraft = [];
  }
  renderProviderCoverageStateOptions();
  renderProviderBigPlayerTopicTools();
}

function getProviderCoverageSummary(provider) {
  if (!isBigPlayerProvider(provider)) {
    const locations = getProviderLocations(provider);
    const firstLocationLabel = locations[0]?.city || provider.city || "–";
    const baseLabel = locations.length > 1 ? `${firstLocationLabel} (+${locations.length - 1})` : firstLocationLabel;
    if (isProviderOnlineOnly(provider)) {
      return `Online · ${baseLabel}`;
    }
    return baseLabel;
  }

  const country = getProviderCoverageCountry(provider);
  const selectedStates = getProviderCoverageStates(provider);
  const stateCount = selectedStates.length || getAvailableStatesForCountry(country).length;
  const onlinePrefix = isProviderOnlineOnly(provider) ? "Online · " : "";
  if (!country) {
    return `${onlinePrefix}Big Player`;
  }
  if (!stateCount) {
    return `${onlinePrefix}Big Player · ${country}`;
  }
  if (!selectedStates.length) {
    return `${onlinePrefix}Big Player · ${country} (alle ${stateCount})`;
  }
  return `${onlinePrefix}Big Player · ${country} (${stateCount})`;
}

function syncProviderAdditionalLocationsDraftFromDom() {
  if (!els.providerLocationsList) {
    return;
  }
  const rows = Array.from(els.providerLocationsList.querySelectorAll("[data-provider-location-index]"));
  providerAdditionalLocationsDraft = rows.map((row) =>
    normalizeProviderLocation({
      address: row.querySelector('input[data-location-field="address"]')?.value || "",
      postalCode: row.querySelector('input[data-location-field="postalCode"]')?.value || "",
      city: row.querySelector('input[data-location-field="city"]')?.value || "",
      state: row.querySelector('input[data-location-field="state"]')?.value || "",
      country: row.querySelector('input[data-location-field="country"]')?.value || "",
      latitude: row.querySelector('input[data-location-field="latitude"]')?.value || "",
      longitude: row.querySelector('input[data-location-field="longitude"]')?.value || "",
    })
  );
}

function renderProviderAdditionalLocations() {
  if (!els.providerLocationsList) {
    return;
  }
  if (!providerAdditionalLocationsDraft.length) {
    els.providerLocationsList.innerHTML = '<p class="empty">Keine weiteren Standorte.</p>';
    return;
  }

  els.providerLocationsList.innerHTML = providerAdditionalLocationsDraft
    .map((location, index) => {
      const normalized = normalizeProviderLocation(location);
      return `
        <div class="provider-location-row" data-provider-location-index="${index}">
          <div class="provider-location-row-head">
            <strong>Standort ${index + 2}</strong>
            <button
              type="button"
              class="mini-btn danger"
              title="Standort entfernen"
              aria-label="Standort entfernen"
              data-remove-provider-location="${index}"
            >✕</button>
          </div>
          <div class="provider-location-row-grid">
            <label>
              Adresse
              <input type="text" data-location-field="address" value="${escapeHtml(normalized.address)}" autocomplete="off" />
            </label>
            <label>
              PLZ
              <input type="text" data-location-field="postalCode" value="${escapeHtml(normalized.postalCode)}" />
            </label>
            <label>
              Ort
              <input type="text" data-location-field="city" value="${escapeHtml(normalized.city)}" />
            </label>
            <label>
              Bundesland
              <input type="text" data-location-field="state" value="${escapeHtml(normalized.state)}" />
            </label>
            <label>
              Land
              <input type="text" data-location-field="country" value="${escapeHtml(normalized.country)}" />
            </label>
            <input type="hidden" data-location-field="latitude" value="${escapeHtml(String(normalized.latitude ?? ""))}" />
            <input type="hidden" data-location-field="longitude" value="${escapeHtml(String(normalized.longitude ?? ""))}" />
          </div>
        </div>
      `;
    })
    .join("");
  setupAdditionalLocationAutocompletes();
}

function fillProviderForm(provider) {
  const locations = getProviderLocations(provider);
  const primaryLocation = locations[0] || createEmptyProviderLocation();
  const coverageMode = getProviderCoverageMode(provider);
  const coverageCountry = getProviderCoverageCountry(provider);
  const coverageStates = getProviderCoverageStates(provider);
  const formElements = els.providerForm.elements;
  formElements.name.value = provider.name;
  formElements.address.value = primaryLocation.address;
  formElements.postalCode.value = primaryLocation.postalCode;
  formElements.city.value = primaryLocation.city;
  formElements.country.value = primaryLocation.country;
  formElements.state.value = primaryLocation.state;
  if (formElements.contactSalutation) {
    formElements.contactSalutation.value = getProviderContactSalutation(provider);
  }
  if (formElements.contactTitle) {
    formElements.contactTitle.value = getProviderContactTitle(provider);
  }
  if (formElements.contactFirstName) {
    formElements.contactFirstName.value = getProviderContactFirstName(provider);
  }
  if (formElements.contactLastName) {
    formElements.contactLastName.value = getProviderContactLastName(provider);
  }
  if (formElements.contactPersonPhone) {
    formElements.contactPersonPhone.value = String(
      provider.contactPersonPhone || provider.contact_person_phone || ""
    ).trim();
  }
  if (formElements.contactPersonEmail) {
    formElements.contactPersonEmail.value = String(
      provider.contactPersonEmail || provider.contact_person_email || ""
    ).trim();
  }
  if (formElements.partnerRequestRedemptionMethod) {
    formElements.partnerRequestRedemptionMethod.value = String(
      provider.partnerRequestRedemptionMethod || provider.partner_request_redemption_method || ""
    ).trim();
  }
  if (formElements.partnerRequestMessage) {
    formElements.partnerRequestMessage.value = String(
      provider.partnerRequestMessage || provider.partner_request_message || ""
    ).trim();
  }
  formElements.website.value = provider.website;
  syncProviderWebsitePreviewLink();
  formElements.email.value = provider.email;
  formElements.phone.value = provider.phone;
  setProviderStatusInForm(provider.status);
  if (formElements.adminOnly) {
    formElements.adminOnly.checked = isProviderAdminOnly(provider);
  }
  if (formElements.dashboardCreated) {
    formElements.dashboardCreated.checked = isProviderDashboardCreated(provider);
  }
  setProviderCompetitorFormValues(isProviderCompetitor(provider), getProviderCompetitorName(provider));
  if (formElements.onlineOnly) {
    formElements.onlineOnly.checked = isProviderOnlineOnly(provider);
  }
  formElements.latitude.value =
    typeof primaryLocation.latitude === "number" && Number.isFinite(primaryLocation.latitude)
      ? String(primaryLocation.latitude)
      : "";
  formElements.longitude.value =
    typeof primaryLocation.longitude === "number" && Number.isFinite(primaryLocation.longitude)
      ? String(primaryLocation.longitude)
      : "";
  setCoverageModeInForm(coverageMode);
  if (els.providerCoverageCountryInput) {
    els.providerCoverageCountryInput.value = coverageCountry;
  }
  providerCoverageStatesDraft = normalizeProviderCoverageStatesForCountry(
    coverageStates,
    coverageCountry
  );
  syncProviderCoverageFormState();
  if (els.providerCreatedMeta) {
    els.providerCreatedMeta.textContent = formatAuditStamp(
      provider.createdAt,
      provider.createdByRole,
      provider.createdByName
    );
  }
  if (els.providerUpdatedMeta) {
    els.providerUpdatedMeta.textContent = formatAuditStamp(
      provider.updatedAt,
      provider.updatedByRole,
      provider.updatedByName
    );
  }
  if (els.providerLiveMeta) {
    els.providerLiveMeta.textContent = getProviderLiveAuditStamp(provider);
  }

  clearProviderNameSuggestions();
  clearAddressSuggestions();
  resetProviderNoteEditorState();
  providerAdditionalLocationsDraft = locations.slice(1).map((location) => ({ ...location }));
  renderProviderAdditionalLocations();
  providerTopicSelection = new Set(provider.topicIds || []);
  if (els.providerTopicSearch) {
    els.providerTopicSearch.value = "";
  }
  providerLiveStatusConfirmedInForm = isLiveStatus(provider.status);
  providerLiveProvisionAssigneeInForm = isLiveStatus(provider.status)
    ? resolveProviderProvisionUserId(provider)
    : "";
  renderProviderTopicPicker();
  renderProviderNotes();
  syncProviderStatusSliderUi();
  providerStatusTouchedInForm = false;
  setProviderDetailTab("master");
  syncProviderCompetitorLockUi(provider);
  void fetchProviderNotesForProvider(provider.id, { force: true });
  providerFormDirty = false;
  providerDraftPendingResume = false;
}

function normalizeUserFormTab(value) {
  const normalizedValue = String(value || "").trim().toLowerCase();
  if (["profil", "anstellung", "provision", "notizen", "role", "visibility"].includes(normalizedValue)) {
    return normalizedValue;
  }
  return "profil";
}

const USER_FORM_STEP_ORDER = ["profil", "anstellung", "provision", "role", "visibility", "notizen"];
const USER_FORM_STEP_LABELS = {
  profil: "Profil",
  anstellung: "Anstellung",
  provision: "Provision",
  notizen: "Notizen",
  role: "Rolle",
  visibility: "Sichtbarkeit",
};

function getUserFormStepIndex(tab = userFormTab) {
  const normalizedTab = normalizeUserFormTab(tab);
  const index = USER_FORM_STEP_ORDER.indexOf(normalizedTab);
  return index >= 0 ? index : 0;
}

function getUserFormStepLabel(tab = userFormTab) {
  const normalizedTab = normalizeUserFormTab(tab);
  return USER_FORM_STEP_LABELS[normalizedTab] || "Profil";
}

function setUserFormGuidedMode(guided) {
  userFormGuidedMode = Boolean(guided);
  if (els.userFormWizardBar) {
    els.userFormWizardBar.classList.toggle("hidden", !userFormGuidedMode);
  }
  setUserFormTab(userFormTab);
}

function validateUserFormIdentityFields() {
  const identityFields = ["name", "address", "email", "phone"];
  for (const fieldName of identityFields) {
    const field = els.userForm?.elements?.[fieldName];
    if (!field || typeof field.reportValidity !== "function") {
      continue;
    }
    if (!field.reportValidity()) {
      return false;
    }
  }
  return true;
}

function validateCurrentUserFormStep() {
  if (!validateUserFormIdentityFields()) {
    return false;
  }
  const activePanel = Array.from(els.userFormTabPanels || []).find((panel) => !panel.classList.contains("hidden"));
  if (!activePanel) {
    return true;
  }
  const controls = activePanel.querySelectorAll("input, select, textarea");
  for (const control of controls) {
    if (control.disabled || typeof control.reportValidity !== "function") {
      continue;
    }
    if (!control.reportValidity()) {
      return false;
    }
  }
  return true;
}

function navigateUserFormToTab(targetTab) {
  if (!userFormGuidedMode) {
    setUserFormTab(targetTab);
    return;
  }
  const nextIndex = getUserFormStepIndex(targetTab);
  const currentIndex = getUserFormStepIndex(userFormTab);
  if (nextIndex === currentIndex) {
    return;
  }
  if (nextIndex > currentIndex) {
    if (nextIndex > currentIndex + 1) {
      return;
    }
    if (!validateCurrentUserFormStep()) {
      return;
    }
  }
  setUserFormTab(USER_FORM_STEP_ORDER[nextIndex]);
}

function navigateUserFormStep(direction) {
  if (!userFormGuidedMode) {
    return;
  }
  const currentIndex = getUserFormStepIndex(userFormTab);
  if (direction < 0) {
    const previousIndex = Math.max(0, currentIndex - 1);
    setUserFormTab(USER_FORM_STEP_ORDER[previousIndex]);
    return;
  }
  if (!validateCurrentUserFormStep()) {
    return;
  }
  const nextIndex = Math.min(USER_FORM_STEP_ORDER.length - 1, currentIndex + 1);
  setUserFormTab(USER_FORM_STEP_ORDER[nextIndex]);
}

function setUserFormTab(nextTab) {
  userFormTab = normalizeUserFormTab(nextTab);
  const currentIndex = getUserFormStepIndex(userFormTab);
  const lastIndex = USER_FORM_STEP_ORDER.length - 1;
  const stepLabel = getUserFormStepLabel(userFormTab);
  els.userFormTabButtons?.forEach((button) => {
    const target = normalizeUserFormTab(button.dataset.userFormTab || "");
    const targetIndex = getUserFormStepIndex(target);
    const isActive = target === userFormTab;
    button.classList.toggle("is-active", isActive);
    setTabButtonA11yState(button, isActive);
    button.disabled = userFormGuidedMode && targetIndex > currentIndex;
  });
  els.userFormTabPanels?.forEach((panel) => {
    const target = normalizeUserFormTab(panel.dataset.userFormTabPanel || "");
    const isActive = target === userFormTab;
    panel.classList.toggle("hidden", !isActive);
    setTabPanelA11yState(panel, isActive);
  });
  if (els.userFormStepMeta) {
    els.userFormStepMeta.textContent = userFormGuidedMode
      ? `Schritt ${currentIndex + 1} von ${USER_FORM_STEP_ORDER.length} · ${stepLabel}`
      : `Bearbeitung · ${stepLabel}`;
  }
  if (els.userFormStepProgressFill) {
    const progressValue = ((currentIndex + 1) / USER_FORM_STEP_ORDER.length) * 100;
    els.userFormStepProgressFill.style.width = `${progressValue.toFixed(2)}%`;
  }
  if (els.userFormPrevBtn) {
    els.userFormPrevBtn.disabled = currentIndex === 0;
    els.userFormPrevBtn.classList.toggle("hidden", !userFormGuidedMode);
  }
  if (els.userFormNextBtn) {
    const isLastStep = currentIndex >= lastIndex;
    els.userFormNextBtn.classList.toggle("hidden", !userFormGuidedMode || isLastStep);
  }
  if (els.userSaveBtn) {
    const showSave = !userFormGuidedMode || currentIndex >= lastIndex;
    els.userSaveBtn.classList.toggle("hidden", !showSave);
  }
}

function resolveUserProfileUserId(user = null, emailFallback = "") {
  if (user?.source === "profile" || user?.source === "invite") {
    return normalizeUserId(user.sourceId || "");
  }
  const fallbackUserId = normalizeUserId(user?.id || "");
  if (fallbackUserId) {
    return fallbackUserId;
  }
  const normalizedEmail = normalizeUserEmail(emailFallback || user?.email || "");
  if (!normalizedEmail) {
    return "";
  }
  const matchedUser = state.users.find(
    (entry) =>
      (entry.source === "profile" || entry.source === "invite") && normalizeUserEmail(entry.email) === normalizedEmail
  );
  return normalizeUserId(matchedUser?.sourceId || matchedUser?.id || "");
}

function normalizeResponsibilityItems(value) {
  const rawItems = Array.isArray(value)
    ? value
    : String(value || "")
        .split(/\r?\n|;/g)
        .flatMap((entry) => String(entry || "").split("•"));
  const seen = new Set();
  return rawItems
    .map((entry) =>
      String(entry || "")
        .replace(/^[\s\-*•]+/, "")
        .trim()
    )
    .filter(Boolean)
    .filter((entry) => {
      const key = normalizeText(entry);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
}

function serializeResponsibilityItems(items) {
  return normalizeResponsibilityItems(items).join("\n");
}

function getResponsibilityTagSuggestions() {
  const departments = getDepartments();
  const profilesMap = normalizeEmployeeProfilesByUserId(state.settings?.employeeProfilesByUserId || {}, departments);
  const existingTags = Object.values(profilesMap).flatMap((profile) =>
    normalizeResponsibilityItems(profile?.responsibility || "")
  );
  const draftTags = normalizeResponsibilityItems([...userResponsibilityDraft, ...employeeAdminResponsibilityDraft]);
  return normalizeResponsibilityItems([...existingTags, ...draftTags]).sort((left, right) =>
    left.localeCompare(right, "de")
  );
}

function renderResponsibilityTagSuggestions() {
  if (!els.responsibilityTagSuggestionsDatalist) {
    return;
  }
  const suggestions = getResponsibilityTagSuggestions();
  els.responsibilityTagSuggestionsDatalist.innerHTML = suggestions
    .map((tag) => `<option value="${escapeHtml(tag)}"></option>`)
    .join("");
}

function getResponsibilityListMarkup(value, emptyLabel = "Keine Aufgabenbeschreibung hinterlegt.") {
  const items = normalizeResponsibilityItems(value);
  if (!items.length) {
    return `<p class="orgchart-info-responsibility-empty">${escapeHtml(emptyLabel)}</p>`;
  }
  return `<ul class="orgchart-info-responsibility-list">${items
    .map((item) => `<li>${escapeHtml(item)}</li>`)
    .join("")}</ul>`;
}

function getSharedResponsibilityGroups(selectedUserId, selectedResponsibilityItems) {
  const normalizedSelectedUserId = normalizeUserId(selectedUserId);
  const selectedTags = normalizeResponsibilityItems(selectedResponsibilityItems);
  if (!normalizedSelectedUserId || !selectedTags.length) {
    return [];
  }
  const selectedTagByKey = new Map();
  selectedTags.forEach((tag) => {
    selectedTagByKey.set(normalizeText(tag), tag);
  });
  const groupsByTagKey = new Map();
  const users = getOrgChartManagedUsers();
  users.forEach((user) => {
    const userId = normalizeUserId(user.userId || "");
    if (!userId || userId === normalizedSelectedUserId) {
      return;
    }
    const profile = getEmployeeProfileByUserId(userId);
    const userTags = normalizeResponsibilityItems(profile.responsibility || "");
    if (!userTags.length) {
      return;
    }
    const departmentLabel = getDepartmentLabelByValue(profile.department) || "Ohne Abteilung";
    userTags.forEach((tag) => {
      const tagKey = normalizeText(tag);
      if (!tagKey || !selectedTagByKey.has(tagKey)) {
        return;
      }
      if (!groupsByTagKey.has(tagKey)) {
        groupsByTagKey.set(tagKey, {
          tag: selectedTagByKey.get(tagKey) || tag,
          members: [],
        });
      }
      const group = groupsByTagKey.get(tagKey);
      const memberExists = group.members.some((entry) => entry.userId === userId);
      if (memberExists) {
        return;
      }
      group.members.push({
        userId,
        name: String(user.name || "").trim() || "Unbekannt",
        departmentLabel,
      });
    });
  });
  const groups = Array.from(groupsByTagKey.values())
    .map((group) => ({
      tag: group.tag,
      members: group.members.sort((left, right) => left.name.localeCompare(right.name, "de")),
    }))
    .sort((left, right) => {
      if (right.members.length !== left.members.length) {
        return right.members.length - left.members.length;
      }
      return left.tag.localeCompare(right.tag, "de");
    });
  return groups;
}

function getSharedResponsibilityMarkup(selectedUserId, selectedResponsibilityItems) {
  const selectedTags = normalizeResponsibilityItems(selectedResponsibilityItems);
  if (!selectedTags.length) {
    return '<p class="orgchart-info-responsibility-empty">Keine Aufgabenbeschreibung hinterlegt.</p>';
  }
  const groups = getSharedResponsibilityGroups(selectedUserId, selectedTags);
  if (!groups.length) {
    return '<p class="orgchart-info-responsibility-empty">Noch keine gemeinsamen Zuständigkeiten mit anderen Mitarbeitern gefunden.</p>';
  }
  return `<ul class="orgchart-info-shared-list">${groups
    .map(
      (group) => `
        <li class="orgchart-info-shared-item">
          <div class="orgchart-info-shared-tag">
            <strong>${escapeHtml(group.tag)}</strong>
            <span>${group.members.length}</span>
          </div>
          <div class="orgchart-info-shared-members">${group.members
            .map((member) => `<span>${escapeHtml(member.name)} · ${escapeHtml(member.departmentLabel)}</span>`)
            .join("")}</div>
        </li>
      `
    )
    .join("")}</ul>`;
}

function renderUserResponsibilityTags() {
  if (!els.userResponsibilityTags) {
    return;
  }
  renderResponsibilityTagSuggestions();
  els.userResponsibilityTags.innerHTML = userResponsibilityDraft.length
    ? userResponsibilityDraft
        .map(
          (item, index) => `
            <span class="tag-input-chip">
              <span>${escapeHtml(item)}</span>
              <button type="button" class="mini-btn danger" data-user-responsibility-remove="${index}" aria-label="Eintrag löschen">✕</button>
            </span>
          `
        )
        .join("")
    : '<span class="tag-input-empty">Noch keine Aufgabenbeschreibung erfasst.</span>';
  if (els.userResponsibilityHidden) {
    els.userResponsibilityHidden.value = serializeResponsibilityItems(userResponsibilityDraft);
  }
}

function renderEmployeeAdminResponsibilityTags() {
  if (!els.employeeAdminResponsibilityTags) {
    return;
  }
  renderResponsibilityTagSuggestions();
  els.employeeAdminResponsibilityTags.innerHTML = employeeAdminResponsibilityDraft.length
    ? employeeAdminResponsibilityDraft
        .map(
          (item, index) => `
            <span class="tag-input-chip">
              <span>${escapeHtml(item)}</span>
              <button type="button" class="mini-btn danger" data-employee-admin-responsibility-remove="${index}" aria-label="Eintrag löschen">✕</button>
            </span>
          `
        )
        .join("")
    : '<span class="tag-input-empty">Noch keine Aufgabenbeschreibung erfasst.</span>';
  if (els.employeeAdminResponsibilityHidden) {
    els.employeeAdminResponsibilityHidden.value = serializeResponsibilityItems(employeeAdminResponsibilityDraft);
  }
}

function addUserResponsibilityFromInput() {
  const input = els.userResponsibilityInput;
  if (!input) {
    return;
  }
  const value = String(input.value || "").trim();
  if (!value) {
    return;
  }
  userResponsibilityDraft = normalizeResponsibilityItems([...userResponsibilityDraft, value]);
  input.value = "";
  renderUserResponsibilityTags();
}

function addEmployeeAdminResponsibilityFromInput() {
  const input = els.employeeAdminResponsibilityInput;
  if (!input) {
    return;
  }
  const value = String(input.value || "").trim();
  if (!value) {
    return;
  }
  employeeAdminResponsibilityDraft = normalizeResponsibilityItems([...employeeAdminResponsibilityDraft, value]);
  input.value = "";
  renderEmployeeAdminResponsibilityTags();
}

function renderUserProfileDepartmentOptions(selectedValue = "") {
  if (!els.userProfileDepartmentSelect) {
    return;
  }
  const departments = getDepartments();
  const options = ['<option value="">Keine Zuordnung</option>'].concat(
    departments.map((entry) => `<option value="${escapeHtml(entry.id)}">${escapeHtml(entry.name)}</option>`)
  );
  const normalizedSelectedValue = String(selectedValue || "").trim();
  const knownValue = normalizedSelectedValue && departments.some((entry) => entry.id === normalizedSelectedValue);
  if (normalizedSelectedValue && !knownValue) {
    options.push(
      `<option value="${escapeHtml(normalizedSelectedValue)}">${escapeHtml(
        getDepartmentLabelByValue(normalizedSelectedValue, departments)
      )}</option>`
    );
  }
  els.userProfileDepartmentSelect.innerHTML = options.join("");
  els.userProfileDepartmentSelect.value = normalizedSelectedValue || "";
}

function renderUserProfileManagerOptions(selectedUserId = "", managerUserId = "") {
  if (!els.userProfileManagerSelect) {
    return;
  }
  const options = getEmployeeAdminManagedUsers()
    .filter((entry) => entry.userId !== selectedUserId)
    .map((entry) => `<option value="${escapeHtml(entry.userId)}">${escapeHtml(entry.name)}</option>`);
  els.userProfileManagerSelect.innerHTML = ['<option value="">Keine Zuordnung</option>', ...options].join("");
  const normalizedManagerId = normalizeUserId(managerUserId);
  const managerExists = normalizedManagerId
    ? Array.from(els.userProfileManagerSelect.options).some((option) => option.value === normalizedManagerId)
    : false;
  els.userProfileManagerSelect.value = managerExists ? normalizedManagerId : "";
}

function renderUserProfileTaskList(userId = userProfileTasksUserId) {
  if (!els.userProfileTaskList) {
    return;
  }
  const normalizedUserId = normalizeUserId(userId);
  if (!normalizedUserId) {
    els.userProfileTaskList.innerHTML =
      '<li class="empty">Aufgaben sind verfügbar, sobald der Mitarbeiter ein aktives Profil hat.</li>';
    return;
  }
  const tasks = getEmployeeTasksByUserId(normalizedUserId).sort((left, right) => {
    if (!!left.done !== !!right.done) {
      return left.done ? 1 : -1;
    }
    const leftDue = left.dueDate || "9999-12-31";
    const rightDue = right.dueDate || "9999-12-31";
    if (leftDue !== rightDue) {
      return leftDue.localeCompare(rightDue);
    }
    return String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
  });
  if (!tasks.length) {
    els.userProfileTaskList.innerHTML = '<li class="empty">Noch keine Aufgaben für diesen Mitarbeiter.</li>';
    return;
  }
  els.userProfileTaskList.innerHTML = tasks
    .map((task) => {
      const taskId = String(task.id || "").trim();
      const dueLabel = task.dueDate ? `Fällig: ${formatEmployeeAdminDate(task.dueDate)}` : "Ohne Fälligkeit";
      return `
        <li class="employee-admin-task-item ${task.done ? "done" : ""}">
          <label class="employee-admin-task-check">
            <input type="checkbox" data-user-profile-task-toggle="${escapeHtml(taskId)}" ${task.done ? "checked" : ""} />
            <span>${escapeHtml(task.title)}</span>
          </label>
          <div class="employee-admin-task-meta">
            <small>${escapeHtml(dueLabel)}</small>
            <button type="button" class="mini-btn danger" title="Aufgabe löschen" aria-label="Aufgabe löschen" data-user-profile-task-delete="${escapeHtml(
              taskId
            )}">✕</button>
          </div>
        </li>
      `;
    })
    .join("");
}

function syncUserProfileTaskControls(userId = userProfileTasksUserId) {
  const normalizedUserId = normalizeUserId(userId);
  const enabled = !!normalizedUserId;
  if (els.userProfileTaskInput) {
    els.userProfileTaskInput.disabled = !enabled;
    if (!enabled) {
      els.userProfileTaskInput.value = "";
    }
  }
  if (els.userProfileTaskDue) {
    els.userProfileTaskDue.disabled = !enabled;
    if (!enabled) {
      els.userProfileTaskDue.value = "";
    }
  }
  if (els.userProfileTaskAddBtn) {
    els.userProfileTaskAddBtn.disabled = !enabled;
  }
}

function syncUserProfileFieldControls(userId = userProfileTasksUserId) {
  const normalizedUserId = normalizeUserId(userId);
  const enabled = userFormGuidedMode || !!normalizedUserId;
  const fieldNames = [
    "profileDepartment",
    "profileMarkerColor",
    "profilePosition",
    "profileLocation",
    "profileBirthDate",
    "profileManagerUserId",
    "profileHrStatus",
    "profileStreet",
    "profilePostalCode",
    "profileCity",
    "profileCountry",
    "profileEmail",
    "profilePhone",
    "profileEmploymentType",
    "profileWorkModel",
    "profileStartDate",
    "profileNextReviewDate",
    "profileResponsibility",
    "profileNotes",
  ];
  fieldNames.forEach((fieldName) => {
    const field = els.userForm?.elements?.[fieldName];
    if (!field || typeof field.disabled !== "boolean") {
      return;
    }
    field.disabled = !enabled;
  });
  if (els.userResponsibilityInput) {
    els.userResponsibilityInput.disabled = !enabled;
  }
  const selectedEmploymentType = String(els.userForm?.elements?.profileEmploymentType?.value || "").trim();
  syncUserEmploymentDetailsVisibility(selectedEmploymentType, enabled);
}

function fillUserForm(user) {
  setUserFormGuidedMode(false);
  setUserFormTab("profil");
  const formElements = els.userForm.elements;
  formElements.name.value = user.name;
  formElements.address.value = user.address;
  formElements.email.value = user.email;
  formElements.phone.value = user.phone;
  formElements.role.value = normalizeUserRole(user.role);
  renderUserTerritoryOptions(user.territories);
  formElements.email.disabled = user.source === "profile";
  userProfileTasksUserId = resolveUserProfileUserId(user);
  const profile = getEmployeeProfileByUserId(userProfileTasksUserId);
  const normalizedDepartmentValue = sanitizeEmployeeDepartmentValue(profile.department, getDepartments());
  renderUserProfileDepartmentOptions(normalizedDepartmentValue);
  renderUserProfileManagerOptions(userProfileTasksUserId, profile.managerUserId || "");
  formElements.profileDepartment.value = normalizedDepartmentValue;
  formElements.profileMarkerColor.value =
    sanitizeEmployeeMarkerColorValue(profile.markerColor) || getEmployeeMarkerColorByUserId(userProfileTasksUserId, user.name);
  formElements.profilePosition.value = profile.position || "";
  formElements.profileLocation.value = profile.location || "";
  formElements.profileBirthDate.value = profile.birthDate || "";
  formElements.profileHrStatus.value = profile.hrStatus || "aktiv";
  formElements.profileStreet.value = profile.street || "";
  formElements.profilePostalCode.value = profile.postalCode || "";
  formElements.profileCity.value = profile.city || "";
  formElements.profileCountry.value = profile.country || "";
  formElements.profileEmail.value = profile.email || user.email || "";
  formElements.profilePhone.value = profile.phone || user.phone || "";
  formElements.profileEmploymentType.value = profile.employmentType || "";
  applyEmployeeEmploymentDetailsToForm(profile, els.userForm);
  formElements.profileWorkModel.value = profile.workModel || "";
  formElements.profileStartDate.value = profile.startDate || "";
  formElements.profileNextReviewDate.value = profile.nextReviewDate || "";
  userResponsibilityDraft = normalizeResponsibilityItems(profile.responsibility || "");
  if (els.userResponsibilityInput) {
    els.userResponsibilityInput.value = "";
  }
  renderUserResponsibilityTags();
  formElements.profileNotes.value = profile.notes || "";
  formElements.profileManagerUserId.value = normalizeUserId(profile.managerUserId || "");
  syncUserProfileFieldControls(userProfileTasksUserId);
  syncUserProfileTaskControls(userProfileTasksUserId);
  renderUserProfileTaskList(userProfileTasksUserId);
  if (els.userHonorariumEnabled) {
    els.userHonorariumEnabled.checked = isEmployeeHonorariumEnabled(user.sourceId, user.email);
    els.userHonorariumEnabled.disabled = false;
  }
  if (els.userHonorariumRate) {
    els.userHonorariumRate.value = formatRateInputValue(getEmployeeRateByUserId(user.sourceId, user.email));
  }
  if (els.userHonorariumHint) {
    const defaultRate = formatEuroAmount(getDefaultProvisionRate());
    els.userHonorariumHint.textContent =
      `Standard-Provision: ${defaultRate}. Mit aktivem Override wird der individuelle Satz verwendet.`;
  }
  if (els.userHonorariumField) {
    els.userHonorariumField.classList.remove("hidden");
  }
  renderProvisionLogForUser(userProfileTasksUserId, els.userProvisionLogMeta, els.userProvisionLogList);
  syncUserHonorariumFieldState();
  els.userSaveBtn.textContent = "Aktualisieren";
}

function clearUserForm() {
  editingUserId = null;
  setUserFormGuidedMode(true);
  setUserFormTab("profil");
  userProfileTasksUserId = "";
  els.userForm.reset();
  renderUserTerritoryOptions([]);
  renderUserProfileDepartmentOptions("");
  renderUserProfileManagerOptions("", "");
  syncUserProfileFieldControls("");
  userResponsibilityDraft = [];
  if (els.userResponsibilityInput) {
    els.userResponsibilityInput.value = "";
  }
  renderUserResponsibilityTags();
  syncUserProfileTaskControls("");
  renderUserProfileTaskList("");
  els.userForm.elements.email.disabled = false;
  if (els.userHonorariumEnabled) {
    els.userHonorariumEnabled.checked = false;
    els.userHonorariumEnabled.disabled = false;
  }
  if (els.userHonorariumRate) {
    els.userHonorariumRate.value = "0.00";
  }
  if (els.userHonorariumHint) {
    const defaultRate = formatEuroAmount(getDefaultProvisionRate());
    els.userHonorariumHint.textContent =
      `Standard-Provision: ${defaultRate}. Ohne Override gilt der Standardwert aus Parameter.`;
  }
  if (els.userHonorariumField) {
    els.userHonorariumField.classList.remove("hidden");
  }
  renderProvisionLogForUser("", els.userProvisionLogMeta, els.userProvisionLogList);
  syncUserHonorariumFieldState();
  els.userSaveBtn.textContent = "Speichern";
}

function syncUserHonorariumFieldState() {
  if (!els.userHonorariumRate) {
    return;
  }
  const canUseHonorarium = !!els.userHonorariumEnabled && !els.userHonorariumEnabled.disabled;
  const enabled = canUseHonorarium && els.userHonorariumEnabled.checked;
  els.userHonorariumRate.disabled = !enabled;
}

function syncEmployeeAdminHonorariumFieldState() {
  if (!els.employeeAdminHonorariumRate) {
    return;
  }
  const canUseHonorarium =
    !!els.employeeAdminHonorariumEnabled && !els.employeeAdminHonorariumEnabled.disabled;
  const enabled = canUseHonorarium && !!els.employeeAdminHonorariumEnabled?.checked;
  els.employeeAdminHonorariumRate.disabled = !canUseHonorarium || !enabled;
}

function handleUserProfileTaskAdd() {
  const normalizedUserId = normalizeUserId(userProfileTasksUserId);
  if (!normalizedUserId) {
    return;
  }
  const title = String(els.userProfileTaskInput?.value || "").trim();
  if (!title) {
    return;
  }
  const dueDate = sanitizeEmployeeAdminDate(els.userProfileTaskDue?.value || "");
  const currentTasks = getEmployeeTasksByUserId(normalizedUserId);
  currentTasks.push({
    id: createId("etask"),
    title,
    dueDate,
    done: false,
    createdAt: new Date().toISOString(),
  });
  setEmployeeTasksByUserId(normalizedUserId, currentTasks);
  saveState({ showFeedback: false });
  if (els.userProfileTaskInput) {
    els.userProfileTaskInput.value = "";
  }
  if (els.userProfileTaskDue) {
    els.userProfileTaskDue.value = "";
  }
  renderUserProfileTaskList(normalizedUserId);
}

function handleUserProfileTaskToggle(taskId, done) {
  const normalizedUserId = normalizeUserId(userProfileTasksUserId);
  if (!normalizedUserId) {
    return;
  }
  const normalizedTaskId = String(taskId || "").trim();
  if (!normalizedTaskId) {
    return;
  }
  const currentTasks = getEmployeeTasksByUserId(normalizedUserId);
  const nextTasks = currentTasks.map((entry) =>
    String(entry.id || "").trim() === normalizedTaskId ? { ...entry, done: !!done } : entry
  );
  setEmployeeTasksByUserId(normalizedUserId, nextTasks);
  saveState({ showFeedback: false });
  renderUserProfileTaskList(normalizedUserId);
}

function handleUserProfileTaskDelete(taskId) {
  const normalizedUserId = normalizeUserId(userProfileTasksUserId);
  if (!normalizedUserId) {
    return;
  }
  const normalizedTaskId = String(taskId || "").trim();
  if (!normalizedTaskId) {
    return;
  }
  const currentTasks = getEmployeeTasksByUserId(normalizedUserId);
  const nextTasks = currentTasks.filter((entry) => String(entry.id || "").trim() !== normalizedTaskId);
  setEmployeeTasksByUserId(normalizedUserId, nextTasks);
  saveState({ showFeedback: false });
  renderUserProfileTaskList(normalizedUserId);
}

function getProviderRecordById(providerId) {
  const normalizedProviderId = String(providerId || "").trim();
  if (!normalizedProviderId) {
    return null;
  }
  return (state.providers || []).find((entry) => String(entry?.id || "").trim() === normalizedProviderId) || null;
}

function getCurrentProviderWorkspaceProvider() {
  return getProviderRecordById(editingProviderId);
}

function getProviderPhoneCalls(providerId) {
  const normalizedProviderId = String(providerId || "").trim();
  if (!normalizedProviderId) {
    return [];
  }
  return getSalesPhoneCalls()
    .filter((entry) => String(entry?.providerId || "").trim() === normalizedProviderId)
    .sort((left, right) => {
      const leftFinal = isSalesPhoneStatusFinal(left?.status);
      const rightFinal = isSalesPhoneStatusFinal(right?.status);
      if (leftFinal !== rightFinal) {
        return leftFinal ? 1 : -1;
      }
      const leftDate = sanitizeEmployeeAdminDate(left?.plannedDate || "");
      const rightDate = sanitizeEmployeeAdminDate(right?.plannedDate || "");
      if (leftDate !== rightDate) {
        if (!leftDate) {
          return 1;
        }
        if (!rightDate) {
          return -1;
        }
        return leftDate.localeCompare(rightDate);
      }
      return String(right?.updatedAt || "").localeCompare(String(left?.updatedAt || ""));
    });
}

function ensureProviderPhoneSelectedCall(providerId, calls = getProviderPhoneCalls(providerId)) {
  const normalizedProviderId = String(providerId || "").trim();
  const selectedCall = calls.find(
    (entry) =>
      String(entry?.id || "").trim() === String(salesPhoneSelectedCallId || "").trim() &&
      String(entry?.providerId || "").trim() === normalizedProviderId
  );
  if (selectedCall) {
    return selectedCall;
  }
  const nextCall = calls[0] || null;
  salesPhoneSelectedCallId = String(nextCall?.id || "").trim();
  return nextCall;
}

function renderProviderPhoneAssigneeOptions(selectedAssigneeUserId = "") {
  const assignees = getSalesPhoneAssignableUsers();
  const candidateId = normalizeUserId(selectedAssigneeUserId || getCurrentActorInfo().userId || "");
  const hasCandidate = candidateId && assignees.some((entry) => normalizeUserId(entry.userId) === candidateId);
  const nextAssigneeId = hasCandidate ? candidateId : normalizeUserId(assignees[0]?.userId || "");
  return {
    selectedAssigneeId: nextAssigneeId,
    markup: assignees
      .map((entry) => {
        const userId = normalizeUserId(entry.userId || "");
        return `<option value="${escapeHtml(userId)}" ${userId === nextAssigneeId ? "selected" : ""}>${escapeHtml(
          entry.name || userId || "Unbekannt"
        )}</option>`;
      })
      .join(""),
  };
}

function renderProviderPhoneStatusOptions(call) {
  const normalized = resolveSalesPhoneProviderStatus(call);
  return SALES_PHONE_PROVIDER_STATUS_FLOW.map((entry) => {
    const value = normalizeProviderStatusValue(entry.id);
    return `
      <label class="provider-crm-status-option ${value === normalized ? "active" : ""}">
        <input
          type="radio"
          name="providerPhoneStatus"
          value="${escapeHtml(value)}"
          data-provider-phone-status-radio="true"
          ${value === normalized ? "checked" : ""}
        />
        <span>${escapeHtml(entry.label)}</span>
      </label>
    `;
  }).join("");
}

function renderProviderPhoneTaskList(call) {
  const tasks = (Array.isArray(call?.tasks) ? call.tasks : []).slice().sort((left, right) => {
    const leftDone = sanitizeSalesPhoneTaskStatus(left?.status) === "erledigt";
    const rightDone = sanitizeSalesPhoneTaskStatus(right?.status) === "erledigt";
    if (leftDone !== rightDone) {
      return leftDone ? 1 : -1;
    }
    const leftDue = sanitizeEmployeeAdminDate(left?.dueDate || "");
    const rightDue = sanitizeEmployeeAdminDate(right?.dueDate || "");
    if (leftDue !== rightDue) {
      return (leftDue || "9999-12-31").localeCompare(rightDue || "9999-12-31");
    }
    return String(right?.updatedAt || "").localeCompare(String(left?.updatedAt || ""));
  });
  if (!tasks.length) {
    return '<p class="empty">Noch keine Aufgaben.</p>';
  }
  return tasks
    .map((task) => {
      const done = sanitizeSalesPhoneTaskStatus(task?.status) === "erledigt";
      const taskId = String(task?.id || "").trim();
      const assigneeName = String(task?.assigneeName || getUserDisplayNameByUserId(task?.assigneeUserId) || "Unbekannt").trim();
      const dueLabel = task?.dueDate ? formatEmployeeAdminDate(task.dueDate) : "ohne Fälligkeit";
      return `
        <article class="provider-crm-task-item ${done ? "is-done" : ""}">
          <label>
            <input type="checkbox" data-provider-phone-task-toggle="${escapeHtml(taskId)}" ${done ? "checked" : ""} />
            <span>${escapeHtml(task.title || "Aufgabe")}</span>
          </label>
          <small>${escapeHtml(assigneeName)} · ${escapeHtml(dueLabel)}</small>
          <button
            type="button"
            class="mini-btn danger"
            title="Aufgabe löschen"
            aria-label="Aufgabe löschen"
            data-provider-phone-task-delete="${escapeHtml(taskId)}"
          >✕</button>
        </article>
      `;
    })
    .join("");
}

function renderProviderPhoneNotes(call) {
  const notes = (Array.isArray(call?.notes) ? call.notes : []).slice().sort((left, right) => {
    return String(right?.createdAt || "").localeCompare(String(left?.createdAt || ""));
  });
  if (!notes.length) {
    return '<p class="empty">Noch keine Gesprächsnotizen.</p>';
  }
  return notes
    .map((note) => {
      const createdBy = String(note?.createdByName || "Unbekannt").trim();
      const noteId = String(note?.id || "").trim();
      return `
        <article class="provider-crm-note-item provider-phone-note-item">
          <div>
            <p>${escapeHtml(String(note?.text || "")).replace(/\n/g, "<br/>")}</p>
            <small>${escapeHtml(formatDateTime(note?.createdAt || ""))} · ${escapeHtml(createdBy)}</small>
          </div>
          <button
            type="button"
            class="mini-btn danger"
            title="Notiz löschen"
            aria-label="Notiz löschen"
            data-provider-phone-note-delete="${escapeHtml(noteId)}"
          >✕</button>
        </article>
      `;
    })
    .join("");
}

function renderProviderPhoneDetail(call) {
  if (!call) {
    return `
      <section class="provider-crm-detail-panel">
        <p class="empty">Noch kein Anrufplan für diesen Anbieter. Lege oben einen Eintrag an.</p>
      </section>
    `;
  }
  const provider = getProviderRecordById(call.providerId) || {};
  const callId = String(call.id || "").trim();
  const phoneValue = String(provider.phone || call.providerPhone || "").trim();
  const telHref = buildTelHref(phoneValue);
  const plannedDateLabel = call.plannedDate ? formatTourDateLabel(call.plannedDate) : "ohne Datum";
  const reminderValue = toDateTimeLocalInputValue(call.reminderAt || "");
  const lastContactLabel = call.lastContactAt ? formatDateTime(call.lastContactAt) : "noch kein Kontakt";
  return `
    <section class="provider-crm-detail-panel" data-provider-phone-detail-call="${escapeHtml(callId)}">
      <div class="provider-crm-panel-head">
        <div>
          <p>Aktueller Anrufplan</p>
          <h4>${escapeHtml(getSalesPhoneNextStepLabel(call))}</h4>
        </div>
        <span class="sales-phone-status ${getSalesPhoneDisplayStatusCssClass(call)}">${escapeHtml(
          getSalesPhoneDisplayStatusLabel(call)
        )}</span>
      </div>
      <div class="provider-crm-info-grid provider-phone-info-grid">
        <article>
          <span>Telefon</span>
          <strong>${telHref ? `<a href="${escapeHtml(telHref)}">${escapeHtml(phoneValue)}</a>` : "nicht hinterlegt"}</strong>
        </article>
        <article>
          <span>Planung</span>
          <strong>${escapeHtml(plannedDateLabel)} · ${escapeHtml(getSalesPhonePlanSlotLabel(call.planSlot))}</strong>
        </article>
        <article>
          <span>Vertrieb</span>
          <strong>${escapeHtml(call.assigneeName || getUserDisplayNameByUserId(call.assigneeUserId) || "Unbekannt")}</strong>
        </article>
        <article>
          <span>Letzter Kontakt</span>
          <strong>${escapeHtml(lastContactLabel)}</strong>
        </article>
      </div>
      <div class="provider-crm-status-grid">
        ${renderProviderPhoneStatusOptions(call)}
      </div>
      <div class="provider-crm-inline-grid provider-phone-reminder-row">
        <label>
          Reminder
          <input type="datetime-local" data-provider-phone-reminder-save value="${escapeHtml(reminderValue)}" />
        </label>
        <button
          type="button"
          class="btn btn-primary"
          data-provider-phone-save-call="${escapeHtml(callId)}"
        >Speichern</button>
      </div>
      <div class="provider-crm-columns provider-phone-work-grid">
        <section class="provider-phone-note-editor">
          <h4>Gesprächsnotiz</h4>
          <textarea
            rows="10"
            data-provider-phone-note-input
            placeholder="Gespräch, Einwand, Zusage oder nächster Schritt"
          ></textarea>
          <button type="button" class="btn btn-success" data-provider-phone-add-note="${escapeHtml(callId)}">
            Notiz speichern
          </button>
          <div class="provider-crm-note-list">${renderProviderPhoneNotes(call)}</div>
        </section>
      </div>
      <div class="provider-crm-danger-row">
        <button
          type="button"
          class="mini-btn danger"
          title="Anrufplan löschen"
          aria-label="Anrufplan löschen"
          data-provider-phone-delete-call="${escapeHtml(callId)}"
        >✕</button>
      </div>
    </section>
  `;
}

function renderProviderPhoneTab(providerId = editingProviderId) {
  if (!els.providerPhoneTabPanel) {
    return;
  }
  const provider = getProviderRecordById(providerId);
  if (!provider) {
    els.providerPhoneTabPanel.innerHTML = `
      <div class="provider-crm-empty-state">
        <h3>Telefonakquise</h3>
        <p>Bitte Anbieter zuerst speichern. Danach ist diese Ansicht fest mit diesem Anbieter verknüpft.</p>
      </div>
    `;
    return;
  }

  const providerIdValue = String(provider.id || "").trim();
  const calls = getProviderPhoneCalls(providerIdValue);
  const selectedCall = ensureProviderPhoneSelectedCall(providerIdValue, calls);
  const activeCalls = calls.filter((entry) => !isSalesPhoneStatusFinal(entry?.status));
  const finalCalls = calls.length - activeCalls.length;
  const phoneValue = String(provider.phone || "").trim();
  const telHref = buildTelHref(phoneValue);
  const assigneeOptions = renderProviderPhoneAssigneeOptions();
  const callCards = calls.length
    ? calls
        .map((entry) => {
          const callId = String(entry.id || "").trim();
          const isActive = callId === String(selectedCall?.id || "").trim();
          const plannedDateLabel = entry.plannedDate ? formatTourDateLabel(entry.plannedDate) : "ohne Datum";
          return `
            <button
              type="button"
              class="provider-crm-list-item ${isActive ? "active" : ""}"
              data-provider-phone-select-call="${escapeHtml(callId)}"
            >
              <strong>${escapeHtml(getSalesPhoneNextStepLabel(entry))}</strong>
              <span>${escapeHtml(plannedDateLabel)} · ${escapeHtml(getSalesPhoneDisplayStatusLabel(entry))}</span>
            </button>
          `;
        })
        .join("")
    : '<p class="empty">Keine Anrufpläne vorhanden.</p>';

  els.providerPhoneTabPanel.innerHTML = `
    <div class="provider-crm-workspace provider-phone-workspace">
      <header class="provider-crm-header provider-crm-header-phone">
        <div>
          <p>Telefonakquise für Anbieter</p>
          <h3>${escapeHtml(provider.name || "Anbieter")}</h3>
        </div>
        <div class="provider-crm-header-actions">
          ${telHref ? `<a class="btn btn-primary" href="${escapeHtml(telHref)}">Anrufen</a>` : ""}
          <button type="button" class="btn btn-secondary" data-provider-phone-open-global>Gesamtübersicht</button>
        </div>
      </header>
      <div class="provider-crm-kpis">
        <article><span>Offen</span><strong>${escapeHtml(String(activeCalls.length))}</strong></article>
        <article><span>Abgeschlossen</span><strong>${escapeHtml(String(finalCalls))}</strong></article>
        <article><span>Status</span><strong>${escapeHtml(getProviderStatusLabel(provider.status))}</strong></article>
      </div>
      <section class="provider-crm-create-panel provider-phone-planner-card">
        <div class="provider-crm-panel-head">
          <div>
            <p>Neuen Anrufplan</p>
            <h4>Weiteren Eintrag anlegen</h4>
          </div>
        </div>
        <div class="provider-crm-inline-grid">
          <label>
            Mitarbeiter
            <select data-provider-phone-assignee>${assigneeOptions.markup}</select>
          </label>
          <label>
            Datum
            <input type="date" data-provider-phone-date value="${escapeHtml(getTodayDateInputValue())}" />
          </label>
          <label>
            Zeitfenster
            <select data-provider-phone-slot>
              <option value="vormittag">Vormittag</option>
              <option value="mittag">Mittag</option>
              <option value="nachmittag">Nachmittag</option>
              <option value="abend">Abend</option>
            </select>
          </label>
          <label>
            Reminder
            <input type="datetime-local" data-provider-phone-reminder />
          </label>
          <button type="button" class="btn btn-success" data-provider-phone-create>
            Einplanen
          </button>
        </div>
      </section>
      <div class="provider-crm-split">
        <aside class="provider-crm-list-panel">
          <div class="provider-crm-panel-head">
            <div>
              <p>Verlauf</p>
              <h4>${escapeHtml(String(calls.length))} Einträge</h4>
            </div>
          </div>
          <div class="provider-crm-list">${callCards}</div>
        </aside>
        ${renderProviderPhoneDetail(selectedCall)}
      </div>
    </div>
  `;
}

async function handleProviderPhoneCreateCall() {
  const provider = getCurrentProviderWorkspaceProvider();
  if (!provider) {
    showWarningFeedback("Bitte Anbieter zuerst speichern.");
    return;
  }
  if (isProviderInProgressLockedForCurrentUser(provider)) {
    showProviderLockedFeedback(provider);
    renderProviderPhoneTab(String(provider.id || "").trim());
    return;
  }
  const panel = els.providerPhoneTabPanel;
  const providerId = String(provider.id || "").trim();
  const calls = getSalesPhoneCalls();
  const assigneeSelect = panel?.querySelector("[data-provider-phone-assignee]");
  const dateInput = panel?.querySelector("[data-provider-phone-date]");
  const slotSelect = panel?.querySelector("[data-provider-phone-slot]");
  const reminderInput = panel?.querySelector("[data-provider-phone-reminder]");
  const assigneeUserId = normalizeUserId(assigneeSelect?.value || getCurrentActorInfo().userId || "");
  const assigneeName =
    getUserDisplayNameByUserId(assigneeUserId) ||
    String(assigneeSelect?.selectedOptions?.[0]?.textContent || "").trim() ||
    "Unbekannt";
  const plannedDate = sanitizeEmployeeAdminDate(dateInput?.value || getTodayDateInputValue()) || getTodayDateInputValue();
  const planSlot = sanitizeSalesPhonePlanSlot(slotSelect?.value || "vormittag");
  const reminderAt = normalizeSalesPhoneReminderAt(reminderInput?.value || "");
  const actor = getCurrentActorInfo();
  const nowIso = new Date().toISOString();
  const duplicate = calls.find(
    (entry) =>
      String(entry.providerId || "").trim() === providerId &&
      sanitizeEmployeeAdminDate(entry.plannedDate) === plannedDate &&
      sanitizeSalesPhonePlanSlot(entry.planSlot) === planSlot &&
      normalizeUserId(entry.assigneeUserId) === assigneeUserId &&
      !isSalesPhoneStatusFinal(entry.status)
  );
  if (duplicate) {
    salesPhoneSelectedCallId = duplicate.id;
    renderProviderPhoneTab(providerId);
    showInfoFeedback("Dieser Anrufplan ist bereits vorhanden und wurde geöffnet.");
    return;
  }
  const nextCall = {
    id: createId("scall"),
    providerId,
    providerName: String(provider.name || "Anbieter").trim(),
    providerPhone: String(provider.phone || "").trim(),
    assigneeUserId,
    assigneeName,
    plannedDate,
    planSlot,
    status: "neu",
    reminderAt,
    lastContactAt: "",
    createdAt: nowIso,
    createdByUserId: actor.userId,
    createdByName: actor.name,
    createdByRole: actor.role,
    updatedAt: nowIso,
    updatedByUserId: actor.userId,
    updatedByName: actor.name,
    updatedByRole: actor.role,
    notes: [],
    tasks: [],
  };
  setSalesPhoneCalls(calls.concat(nextCall));
  const syncedProviderId = updateProviderStatusFromSalesPhoneCall(nextCall, actor, nowIso);
  salesPhoneSelectedCallId = nextCall.id;
  saveState({
    showFeedback: false,
    providersSync: syncedProviderId ? { upsertProviderIds: [syncedProviderId] } : null,
  });
  renderProviderPhoneTab(providerId);
  renderSalesPhoneSection();
  showSuccessFeedback("Anrufplan für diesen Anbieter angelegt.");
}

function updateSalesPhoneCallById(callId, updater) {
  const normalizedCallId = String(callId || "").trim();
  if (!normalizedCallId || typeof updater !== "function") {
    return null;
  }
  let updatedCall = null;
  const nextCalls = getSalesPhoneCalls()
    .map((entry) => {
      if (String(entry?.id || "").trim() !== normalizedCallId) {
        return entry;
      }
      const nextEntry = updater(entry);
      updatedCall = normalizeSalesPhoneCallRecord(nextEntry || entry);
      return updatedCall;
    })
    .filter(Boolean);
  if (!updatedCall) {
    return null;
  }
  setSalesPhoneCalls(nextCalls);
  return updatedCall;
}

