function sanitizeHelpHttpsUrl(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue) {
    return "";
  }
  try {
    const parsed = new URL(rawValue);
    return parsed.protocol === "https:" ? parsed.href : "";
  } catch (_error) {
    return "";
  }
}

function sanitizeHelpImageSrc(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue) {
    return "";
  }
  const dataImagePattern = /^data:image\/(?:png|jpe?g|webp);base64,[a-z0-9+/=]+$/i;
  if (rawValue.length <= HELP_TOPIC_IMAGE_MAX_DATA_URL_LENGTH && dataImagePattern.test(rawValue)) {
    return rawValue;
  }
  return sanitizeHelpHttpsUrl(rawValue);
}

function normalizeHelpImageSize(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return HELP_TOPIC_IMAGE_SIZES.has(normalized) ? normalized : "full";
}

function normalizeHelpImageAlign(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return HELP_TOPIC_IMAGE_ALIGNS.has(normalized) ? normalized : "center";
}

function getHelpVimeoVideoParts(parsedUrl, host) {
  const pathParts = parsedUrl.pathname.split("/").filter(Boolean);
  let videoId = "";
  let videoHash = String(parsedUrl.searchParams.get("h") || "").trim();
  if (host === "player.vimeo.com") {
    videoId = pathParts[0] === "video" && /^\d+$/.test(pathParts[1] || "") ? pathParts[1] : "";
  } else if (host === "vimeo.com") {
    if (/^\d+$/.test(pathParts[0] || "")) {
      videoId = pathParts[0];
      if (!videoHash && /^[a-f0-9]{6,64}$/i.test(pathParts[1] || "")) {
        videoHash = pathParts[1];
      }
    } else {
      const videoSegmentIndex = pathParts.findIndex((segment) => segment === "video" || segment === "videos");
      const candidateId = videoSegmentIndex >= 0 ? pathParts[videoSegmentIndex + 1] : "";
      videoId = /^\d+$/.test(candidateId || "") ? candidateId : "";
    }
  }
  if (!/^\d{2,20}$/.test(videoId)) {
    return null;
  }
  return {
    id: videoId,
    hash: /^[a-f0-9]{6,64}$/i.test(videoHash) ? videoHash : "",
  };
}

function createHelpVimeoEmbedUrl(vimeoParts) {
  const params = new URLSearchParams();
  if (vimeoParts.hash) {
    params.set("h", vimeoParts.hash);
  }
  params.set("api", "1");
  return `https://player.vimeo.com/video/${vimeoParts.id}?${params.toString()}`;
}

function isVimeoResolvableUrl(value) {
  const normalizedUrl = sanitizeHelpHttpsUrl(value);
  if (!normalizedUrl) {
    return false;
  }
  try {
    const parsed = new URL(normalizedUrl);
    const host = parsed.hostname.toLowerCase().replace(/^www\./, "");
    return (
      host === "vimeo.com" &&
      (/^\/share\/[0-9a-f-]{20,80}\/?$/i.test(parsed.pathname) ||
        /^\/reviews\/[0-9a-f-]{20,80}\/videos\/\d+\/?$/i.test(parsed.pathname))
    );
  } catch (_error) {
    return false;
  }
}

async function resolveHelpVideoUrl(value) {
  const normalizedUrl = sanitizeHelpHttpsUrl(value);
  if (!normalizedUrl || !isVimeoResolvableUrl(normalizedUrl)) {
    return normalizedUrl;
  }
  const response = await fetch(HELP_VIDEO_RESOLVE_VIMEO_ENDPOINT, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ url: normalizedUrl }),
  });
  const payload = await response.json().catch(() => null);
  const embedUrl = sanitizeHelpHttpsUrl(payload?.embedUrl);
  if (!response.ok || !embedUrl) {
    throw new Error(String(payload?.error || "Der Vimeo-Link konnte nicht aufgeloest werden."));
  }
  return embedUrl;
}

async function resolveConfiguredVimeoShareLinks() {
  if (helpVimeoResolutionInFlight || !isRoleAdmin()) {
    return;
  }
  const current = getHelpCenterSettings();
  const urls = [current.startVideo.url]
    .concat(current.onboardingVideos.map((video) => video.url))
    .concat(current.topics.map((topic) => topic.videoUrl));
  if (!urls.some((url) => isVimeoResolvableUrl(url))) {
    return;
  }
  helpVimeoResolutionInFlight = true;
  try {
    let changed = false;
    const resolveEntry = async (entry) => {
      if (!isVimeoResolvableUrl(entry?.url)) {
        return entry;
      }
      try {
        const url = await resolveHelpVideoUrl(entry.url);
        if (url && url !== entry.url) {
          changed = true;
          return { ...entry, url };
        }
      } catch (_error) {
        // Keep the existing value so an admin can retry or replace the link.
      }
      return entry;
    };
    const [startVideo, onboardingVideos, topics] = await Promise.all([
      resolveEntry(current.startVideo),
      Promise.all(current.onboardingVideos.map(resolveEntry)),
      Promise.all(current.topics.map(async (topic) => {
        const resolved = await resolveEntry({ url: topic.videoUrl });
        return resolved.url !== topic.videoUrl ? { ...topic, videoUrl: resolved.url } : topic;
      })),
    ]);
    if (changed) {
      saveHelpCenterConfiguration({ ...current, startVideo, onboardingVideos, topics });
      showSuccessFeedback("Vimeo-Link wurde fuer den Player aufgeloest.");
    }
  } finally {
    helpVimeoResolutionInFlight = false;
  }
}

function createHelpParagraphMarkup(value) {
  return String(value || "")
    .trim()
    .split(/\r?\n\s*\r?\n/)
    .filter(Boolean)
    .map((paragraph) => `<p>${escapeHtml(paragraph).replace(/\r?\n/g, "<br />")}</p>`)
    .join("");
}

function sanitizeHelpCssColor(value) {
  const color = String(value || "").trim();
  if (/^#(?:[\da-f]{3}|[\da-f]{4}|[\da-f]{6}|[\da-f]{8})$/i.test(color)) {
    return color;
  }
  if (/^rgba?\(\s*(?:\d{1,3}%?\s*,\s*){2}\d{1,3}%?(?:\s*,\s*(?:0|0?\.\d+|1))?\s*\)$/i.test(color)) {
    return color;
  }
  return "";
}

function sanitizeHelpCssLength(value, options = {}) {
  const match = String(value || "")
    .trim()
    .match(/^(-?)(\d+(?:\.\d{1,2})?)\s*(px|rem|em|%)$/i);
  if (!match || (match[1] === "-" && options.allowNegative !== true)) {
    return "";
  }
  const size = Number(match[2]);
  const unit = match[3].toLowerCase();
  const validRange =
    (unit === "px" && size <= 96) ||
    ((unit === "rem" || unit === "em") && size <= 6) ||
    (unit === "%" && size <= 400);
  if (!Number.isFinite(size) || size < 0 || !validRange) {
    return "";
  }
  return `${match[1]}${size}${unit}`;
}

function sanitizeHelpCssSpacing(value, options = {}) {
  const parts = String(value || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length || parts.length > 4) {
    return "";
  }
  const sanitized = parts.map((part) => sanitizeHelpCssLength(part, options));
  return sanitized.every(Boolean) ? sanitized.join(" ") : "";
}

function sanitizeHelpHtmlClasses(value) {
  const classes = String(value || "")
    .split(/\s+/)
    .map((entry) => entry.trim())
    .filter((entry) => HELP_TOPIC_HTML_ALLOWED_CLASSES.has(entry));
  return Array.from(new Set(classes)).join(" ");
}

function sanitizeHelpTextStyle(value) {
  const safeDeclarations = new Map();
  String(value || "")
    .split(";")
    .map((entry) => entry.trim())
    .filter(Boolean)
    .forEach((declaration) => {
      const separatorIndex = declaration.indexOf(":");
      if (separatorIndex < 1) {
        return;
      }
      const property = declaration.slice(0, separatorIndex).trim().toLowerCase();
      const rawValue = declaration.slice(separatorIndex + 1).trim();
      let safeValue = "";
      if (property === "font-size") {
        safeValue = sanitizeHelpCssLength(rawValue);
      } else if (property === "color" || property === "background-color") {
        safeValue = sanitizeHelpCssColor(rawValue);
      } else if (property === "text-align" && ["left", "center", "right", "justify"].includes(rawValue.toLowerCase())) {
        safeValue = rawValue.toLowerCase();
      } else if (property === "font-weight" && /^(?:normal|bold|[1-9]00)$/i.test(rawValue)) {
        safeValue = rawValue.toLowerCase();
      } else if (property === "font-style" && /^(?:normal|italic)$/i.test(rawValue)) {
        safeValue = rawValue.toLowerCase();
      } else if (property === "text-decoration" && /^(?:none|underline|line-through)$/i.test(rawValue)) {
        safeValue = rawValue.toLowerCase();
      } else if (property === "line-height") {
        const numericLineHeight = Number(rawValue);
        const lengthLineHeight = sanitizeHelpCssLength(rawValue);
        safeValue =
          Number.isFinite(numericLineHeight) && numericLineHeight >= 0.8 && numericLineHeight <= 3
            ? String(numericLineHeight)
            : lengthLineHeight;
      } else if (property === "letter-spacing") {
        safeValue = sanitizeHelpCssLength(rawValue, { allowNegative: true });
      } else if (property === "margin" || property === "margin-top" || property === "margin-bottom") {
        safeValue = sanitizeHelpCssSpacing(rawValue, { allowNegative: true });
      } else if (property === "padding" || property === "padding-top" || property === "padding-bottom") {
        safeValue = sanitizeHelpCssSpacing(rawValue);
      }
      if (safeValue) {
        safeDeclarations.set(property, safeValue);
      }
    });
  return Array.from(safeDeclarations, ([property, safeValue]) => `${property}: ${safeValue};`).join(" ");
}

function sanitizeHelpRichHtml(value) {
  const raw = String(value || "").trim().slice(0, HELP_TOPIC_CONTENT_MAX_HTML_LENGTH);
  if (!raw) {
    return "";
  }
  const source = /<\/?[a-z][^>]*>/i.test(raw) ? raw : createHelpParagraphMarkup(raw);
  if (typeof document === "undefined") {
    return createHelpParagraphMarkup(raw);
  }
  const template = document.createElement("template");
  template.innerHTML = source;
  const output = document.createElement("div");
  const allowedTags = new Set([
    "p", "br", "strong", "b", "em", "i", "u", "s", "del", "mark", "small", "span", "div", "section", "article", "header",
    "ul", "ol", "li", "h2", "h3", "h4", "h5", "h6", "blockquote", "hr", "a", "img", "figure", "figcaption",
    "pre", "code", "kbd", "table", "thead", "tbody", "tfoot", "tr", "th", "td", "details", "summary",
  ]);
  const droppedTags = new Set(["script", "style", "iframe", "object", "embed", "svg", "math", "form", "input", "button", "video", "audio"]);

  const copyNodes = (sourceParent, targetParent) => {
    Array.from(sourceParent.childNodes).forEach((node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        targetParent.appendChild(document.createTextNode(node.textContent || ""));
        return;
      }
      if (node.nodeType !== Node.ELEMENT_NODE) {
        return;
      }
      const tagName = String(node.tagName || "").toLowerCase();
      if (droppedTags.has(tagName)) {
        return;
      }
      if (!allowedTags.has(tagName)) {
        copyNodes(node, targetParent);
        return;
      }
      const cleanTagName = tagName;
      const cleanNode = document.createElement(cleanTagName);
      const safeClasses = sanitizeHelpHtmlClasses(node.getAttribute("class") || "");
      if (safeClasses) {
        cleanNode.setAttribute("class", safeClasses);
      }
      if (cleanTagName === "a") {
        const href = sanitizeHelpHttpsUrl(node.getAttribute("href") || "");
        if (!href) {
          copyNodes(node, targetParent);
          return;
        }
        cleanNode.setAttribute("href", href);
        cleanNode.setAttribute("target", "_blank");
        cleanNode.setAttribute("rel", "noopener noreferrer");
      }
      if (["span", "p", "h2", "h3", "h4", "h5", "h6", "li", "blockquote", "div", "section", "article"].includes(cleanTagName)) {
        const textSize = normalizeHelpTopicTextSize(node.getAttribute("data-help-text-size") || "");
        if (textSize) {
          cleanNode.setAttribute("data-help-text-size", textSize);
        }
      }
      if (["span", "p", "h2", "h3", "h4", "h5", "h6", "li", "blockquote", "div", "section", "article", "strong", "b", "em", "i", "u", "s", "del", "mark", "small", "figure", "figcaption", "td", "th"].includes(cleanTagName)) {
        const safeStyle = sanitizeHelpTextStyle(node.getAttribute("style") || "");
        if (safeStyle) {
          cleanNode.setAttribute("style", safeStyle);
        }
      }
      if (cleanTagName === "img") {
        const src = sanitizeHelpImageSrc(node.getAttribute("src") || "");
        if (!src) {
          return;
        }
        cleanNode.setAttribute("src", src);
        cleanNode.setAttribute("alt", String(node.getAttribute("alt") || "Hilfe-Bild").trim().slice(0, 120) || "Hilfe-Bild");
        cleanNode.setAttribute("data-help-image-size", normalizeHelpImageSize(node.getAttribute("data-help-image-size")));
        cleanNode.setAttribute("data-help-image-align", normalizeHelpImageAlign(node.getAttribute("data-help-image-align")));
        cleanNode.setAttribute("loading", "lazy");
        cleanNode.setAttribute("decoding", "async");
      }
      targetParent.appendChild(cleanNode);
      copyNodes(node, cleanNode);
      if (cleanTagName === "li" && isHelpListGapElement(node) && isHelpListItemEmpty(cleanNode)) {
        cleanNode.setAttribute("data-help-list-gap", "true");
      }
    });
  };

  copyNodes(template.content, output);
  normalizeHelpTopicListGaps(output);
  return output.innerHTML.trim();
}

function isHelpTopicWebDocument(value) {
  const content = String(value || "").trim();
  return /<!doctype\s+html|<html[\s>]|<head[\s>]|<style[\s>]/i.test(content);
}

function sanitizeHelpWebDocumentCss(value) {
  return String(value || "")
    .replace(/@import\s+(?:url\([^)]*\)|[^;]+);?/gi, "")
    .replace(/url\(\s*(['"]?)\s*javascript:[\s\S]*?\1\s*\)/gi, "")
    .replace(/expression\s*\(/gi, "");
}

function sanitizeHelpWebDocument(value) {
  const raw = String(value || "").trim().slice(0, HELP_TOPIC_CONTENT_MAX_HTML_LENGTH);
  if (!raw || !isHelpTopicWebDocument(raw)) {
    return "";
  }
  if (typeof document === "undefined" || typeof DOMParser === "undefined") {
    return raw
      .replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi, "")
      .replace(/<(?:iframe|object|embed|base|link)\b[^>]*>[\s\S]*?<\/(?:iframe|object|embed)\s*>/gi, "");
  }
  const parsed = new DOMParser().parseFromString(raw, "text/html");
  parsed.querySelectorAll("script, iframe, object, embed, base, link, form, input, button, textarea, select, option, meta[http-equiv]").forEach((element) => element.remove());
  const styles = Array.from(parsed.querySelectorAll("style"));
  const css = styles.map((style) => sanitizeHelpWebDocumentCss(style.textContent || "")).filter(Boolean).join("\n");
  styles.forEach((style) => style.remove());
  parsed.querySelectorAll("*").forEach((element) => {
    Array.from(element.attributes).forEach((attribute) => {
      const name = String(attribute.name || "").toLowerCase();
      const attributeValue = String(attribute.value || "").trim();
      if (name.startsWith("on") || name === "srcdoc") {
        element.removeAttribute(attribute.name);
        return;
      }
      if (["href", "src", "action", "formaction"].includes(name) && /^\s*(?:javascript|vbscript):/i.test(attributeValue)) {
        element.removeAttribute(attribute.name);
      }
    });
  });
  const language = String(parsed.documentElement.getAttribute("lang") || "de").trim().slice(0, 24) || "de";
  const title = String(parsed.querySelector("title")?.textContent || "Hilfe-Thema").trim().slice(0, 160) || "Hilfe-Thema";
  return `<!doctype html><html lang="${escapeHtml(language)}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>${escapeHtml(title)}</title>${
    css ? `<style>${css}</style>` : ""
  }</head><body>${parsed.body.innerHTML}</body></html>`;
}

function normalizeHelpTopicContent(value) {
  return isHelpTopicWebDocument(value) ? sanitizeHelpWebDocument(value) : sanitizeHelpRichHtml(value);
}

function getHelpTopicWebDocumentMarkup(value, options = {}) {
  const documentMarkup = sanitizeHelpWebDocument(value);
  if (!documentMarkup) {
    return "";
  }
  const title = String(options.title || "Hilfe-Thema").trim() || "Hilfe-Thema";
  return `<iframe class="help-topic-web-document-frame" sandbox="allow-same-origin" referrerpolicy="no-referrer" title="${escapeHtml(
    title
  )}" srcdoc="${escapeHtml(documentMarkup)}"></iframe>`;
}

function resizeHelpTopicWebDocumentFrame(frame) {
  if (!(frame instanceof HTMLIFrameElement)) {
    return;
  }
  try {
    const documentElement = frame.contentDocument?.documentElement;
    const body = frame.contentDocument?.body;
    const height = Math.max(
      Number(documentElement?.scrollHeight || 0),
      Number(documentElement?.offsetHeight || 0),
      Number(body?.scrollHeight || 0),
      Number(body?.offsetHeight || 0),
      420
    );
    frame.style.height = `${Math.ceil(height)}px`;
  } catch (_error) {
    // Der Frame bleibt auch ohne Zugriff lesbar; die Sandbox schützt dabei die App.
  }
}

function resizeHelpTopicWebDocumentFrames(root = document) {
  if (!root?.querySelectorAll) {
    return;
  }
  root.querySelectorAll("iframe.help-topic-web-document-frame").forEach((frame) => {
    resizeHelpTopicWebDocumentFrame(frame);
  });
}

function getHelpRichTextLength(value) {
  if (isHelpTopicWebDocument(value)) {
    if (typeof DOMParser === "undefined") {
      return String(value || "").replace(/<style[\s\S]*?<\/style\s*>/gi, "").replace(/<[^>]+>/g, " ").trim().length;
    }
    const documentMarkup = sanitizeHelpWebDocument(value);
    const parsed = new DOMParser().parseFromString(documentMarkup, "text/html");
    return String(parsed.body?.textContent || "").trim().length;
  }
  if (typeof document === "undefined") {
    return String(value || "").replace(/<[^>]+>/g, "").trim().length;
  }
  const container = document.createElement("div");
  container.innerHTML = sanitizeHelpRichHtml(value);
  return String(container.textContent || "").trim().length;
}

function hasHelpRichMedia(value) {
  const rawValue = String(value || "");
  if (isHelpTopicWebDocument(rawValue)) {
    return /<img\b/i.test(sanitizeHelpWebDocument(rawValue));
  }
  if (typeof document === "undefined") {
    return /<img\b/i.test(rawValue);
  }
  const container = document.createElement("div");
  container.innerHTML = sanitizeHelpRichHtml(rawValue);
  return Boolean(container.querySelector("img"));
}

function normalizeHelpVersion(value) {
  const parsed = Math.floor(Number(value));
  return Number.isFinite(parsed) && parsed > 0 ? Math.min(parsed, 1000000) : 1;
}

function normalizeHelpOnboardingVideo(videoLike, index = 0) {
  if (!videoLike || typeof videoLike !== "object") {
    return null;
  }
  const url = sanitizeHelpHttpsUrl(videoLike.url);
  if (!url) {
    return null;
  }
  const id = String(videoLike.id || `help_video_${index + 1}`).trim().slice(0, 180);
  if (!id || id === "help_start_video") {
    return null;
  }
  return {
    id,
    title: String(videoLike.title || `Onboarding-Video ${index + 2}`).trim().slice(0, 120) || `Onboarding-Video ${index + 2}`,
    url,
    version: normalizeHelpVersion(videoLike.version),
    sortOrder: Math.max(1, Math.floor(Number(videoLike.sortOrder)) || index + 1),
  };
}

function normalizeHelpRoleList(rolesLike) {
  const candidates = Array.isArray(rolesLike)
    ? rolesLike
    : String(rolesLike || "")
        .split(",")
        .filter(Boolean);
  const roles = [];
  candidates.forEach((role) => {
    const normalized = normalizeUserRole(role);
    if (HELP_ALL_ROLES.includes(normalized) && !roles.includes(normalized)) {
      roles.push(normalized);
    }
  });
  return roles.length ? roles : [...HELP_ALL_ROLES];
}

function normalizeHelpCountryList(countriesLike) {
  const candidates = Array.isArray(countriesLike)
    ? countriesLike
    : String(countriesLike || "")
        .split(",")
        .filter(Boolean);
  const countries = [];
  const seen = new Set();
  candidates.forEach((country) => {
    const label = String(country || "").trim();
    const key = normalizeText(label);
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    countries.push(key === "all" || key === "alle" ? "all" : label);
  });
  return countries.length ? countries : ["all"];
}

function normalizeHelpTopic(topicLike, index = 0) {
  if (!topicLike || typeof topicLike !== "object") {
    return null;
  }
  const id = String(topicLike.id || "").trim().slice(0, 180);
  const title = String(topicLike.title || "").trim().slice(0, 120);
  const summary = String(topicLike.summary || "").trim().slice(0, 260);
  const content = normalizeHelpTopicContent(topicLike.content);
  if (!id || !title || !summary || !content || (!getHelpRichTextLength(content) && !hasHelpRichMedia(content))) {
    return null;
  }
  const rawStatus = String(topicLike.status || "active").trim().toLowerCase();
  const targetSection = String(topicLike.targetSection || "").trim();
  return {
    id,
    title,
    summary,
    content,
    videoUrl: sanitizeHelpHttpsUrl(topicLike.videoUrl),
    targetSection: HELP_TARGET_SECTIONS.has(targetSection) ? targetSection : "",
    roles: normalizeHelpRoleList(topicLike.roles),
    countries: normalizeHelpCountryList(topicLike.countries),
    status: HELP_TOPIC_STATUSES.has(rawStatus) ? rawStatus : "draft",
    required: Boolean(topicLike.required),
    version: normalizeHelpVersion(topicLike.version),
    sortOrder: Math.max(1, Math.floor(Number(topicLike.sortOrder)) || index + 1),
  };
}

function normalizeHelpCenterSettings(helpCenterLike) {
  const defaults = createDefaultHelpCenterSettings();
  const source = helpCenterLike && typeof helpCenterLike === "object" ? helpCenterLike : {};
  const startVideoSource = source.startVideo && typeof source.startVideo === "object" ? source.startVideo : {};
  const videoUrl = sanitizeHelpHttpsUrl(startVideoSource.url);
  const onboardingVideosSource = Array.isArray(source.onboardingVideos) ? source.onboardingVideos : defaults.onboardingVideos;
  const topicsSource = Array.isArray(source.topics) ? source.topics : defaults.topics;
  const seenIds = new Set();
  const topics = topicsSource
    .map((topic, index) => normalizeHelpTopic(topic, index))
    .filter((topic) => {
      if (!topic || seenIds.has(topic.id)) {
        return false;
      }
      seenIds.add(topic.id);
      return true;
    })
    .sort((left, right) => left.sortOrder - right.sortOrder || left.title.localeCompare(right.title))
    .map((topic, index) => ({ ...topic, sortOrder: index + 1 }));
  const seenVideoIds = new Set(["help_start_video"]);
  const onboardingVideos = onboardingVideosSource
    .map((video, index) => normalizeHelpOnboardingVideo(video, index))
    .filter((video) => {
      if (!video || seenVideoIds.has(video.id)) {
        return false;
      }
      seenVideoIds.add(video.id);
      return true;
    })
    .sort((left, right) => left.sortOrder - right.sortOrder || left.title.localeCompare(right.title))
    .map((video, index) => ({ ...video, sortOrder: index + 1 }));

  return {
    startVideo: {
      title: String(startVideoSource.title || defaults.startVideo.title).trim().slice(0, 120) || defaults.startVideo.title,
      url: videoUrl,
      required: Boolean(startVideoSource.required) && Boolean(videoUrl),
      version: normalizeHelpVersion(startVideoSource.version),
    },
    onboardingVideos,
    privacyNoticeUrl: sanitizeHelpHttpsUrl(source.privacyNoticeUrl),
    supportEmail: normalizeUserEmail(source.supportEmail || HELP_DEFAULT_SUPPORT_EMAIL).slice(0, 180) || HELP_DEFAULT_SUPPORT_EMAIL,
    topics,
  };
}

function normalizeOnboardingProgressByUserId(progressLike) {
  if (!progressLike || typeof progressLike !== "object" || Array.isArray(progressLike)) {
    return {};
  }
  const normalized = {};
  Object.entries(progressLike).forEach(([userId, record]) => {
    const key = String(userId || "").trim().slice(0, 180);
    if (!key || !record || typeof record !== "object" || Array.isArray(record)) {
      return;
    }
    const seenVersions = {};
    Object.entries(record.seenVersions || {}).forEach(([itemId, version]) => {
      const itemKey = String(itemId || "").trim().slice(0, 180);
      if (!itemKey) {
        return;
      }
      seenVersions[itemKey] = normalizeHelpVersion(version);
    });
    normalized[key] = {
      seenVersions,
      popupHidden: record.popupHidden === true || record.promptHidden === true || record.suppressed === true,
    };
  });
  return normalized;
}

function normalizeSecretaryEmployeeMessages(messagesLike) {
  if (!Array.isArray(messagesLike)) {
    return [];
  }
  const seenIds = new Set();
  return messagesLike
    .map((entry) => {
      const id = String(entry?.id || "").trim().slice(0, 180);
      const body = String(entry?.body || entry?.message || "").trim().slice(0, 800);
      const recipientUserIds = Array.from(
        new Set(
          (Array.isArray(entry?.recipientUserIds) ? entry.recipientUserIds : entry?.recipientUserId ? [entry.recipientUserId] : [])
            .map((userId) => normalizeUserId(userId || ""))
            .filter(Boolean)
        )
      );
      const sentAtRaw = String(entry?.sentAt || entry?.createdAt || "").trim();
      const sentAtMs = Date.parse(sentAtRaw);
      if (!id || !body || !recipientUserIds.length || !Number.isFinite(sentAtMs) || seenIds.has(id)) {
        return null;
      }
      seenIds.add(id);
      return {
        id,
        body,
        recipientUserIds,
        sentAt: new Date(sentAtMs).toISOString(),
        sentByUserId: normalizeUserId(entry?.sentByUserId || entry?.createdByUserId || ""),
        sentByName: String(entry?.sentByName || entry?.createdByName || "Superadmin").trim().slice(0, 180) || "Superadmin",
      };
    })
    .filter(Boolean)
    .sort((left, right) => Date.parse(right.sentAt) - Date.parse(left.sentAt))
    .slice(0, 500);
}

function normalizeSettings(settings) {
  const normalizedDepartments = normalizeDepartments(settings?.departments || []);
  return {
    platformCountryFilter: sanitizePlatformCountryFilter(
      settings?.platformCountryFilter || DASHBOARD_DEFAULT_COUNTRY
    ),
    dashboardStatusFilter: normalizeDashboardStatusFilter(settings?.dashboardStatusFilter),
    mapParameters: normalizeMapParameters(settings?.mapParameters || {}),
    userTerritoriesByEmail: normalizeUserTerritoriesByEmail(settings?.userTerritoriesByEmail || {}),
    userTerritoriesByUserId: normalizeUserTerritoriesByUserId(settings?.userTerritoriesByUserId || {}),
    employeeRatesByUserId: normalizeEmployeeRatesByUserId(settings?.employeeRatesByUserId || {}),
    employeeRatesByEmail: normalizeEmployeeRatesByEmail(settings?.employeeRatesByEmail || {}),
    employeeHonorariumEnabledByUserId: normalizeEmployeeHonorariumEnabledByUserId(
      settings?.employeeHonorariumEnabledByUserId || {}
    ),
    employeeHonorariumEnabledByEmail: normalizeEmployeeHonorariumEnabledByEmail(
      settings?.employeeHonorariumEnabledByEmail || {}
    ),
    provisionLedgerEntries: normalizeProvisionLedgerEntries(settings?.provisionLedgerEntries || []),
    employeeProfilesByUserId: normalizeEmployeeProfilesByUserId(
      settings?.employeeProfilesByUserId || {},
      normalizedDepartments
    ),
    employeeTasksByUserId: normalizeEmployeeTasksByUserId(settings?.employeeTasksByUserId || {}),
    inventoryItems: normalizeInventoryItems(settings?.inventoryItems || []),
    employeeLastLoginAtByUserId: normalizeEmployeeLastLoginAtByUserId(settings?.employeeLastLoginAtByUserId || {}),
    secretaryEmployeeMessages: normalizeSecretaryEmployeeMessages(settings?.secretaryEmployeeMessages || []),
    topicRequests: Array.isArray(settings?.topicRequests) ? settings.topicRequests.map((entry) => ({
      id: String(entry?.id || "").trim(), topic: String(entry?.topic || "").trim().slice(0, 120), note: String(entry?.note || "").trim().slice(0, 400), providerName: String(entry?.providerName || "").trim().slice(0, 180), requestedByName: String(entry?.requestedByName || "").trim().slice(0, 180), requestedByUserId: normalizeUserId(entry?.requestedByUserId || ""), createdAt: String(entry?.createdAt || "").trim(), status: String(entry?.status || "open").trim(), resolvedTopicName: String(entry?.resolvedTopicName || "").trim().slice(0, 180),
    })).filter((entry) => entry.id && entry.topic).slice(0, 500) : [],
    departments: normalizedDepartments,
    conversationThreads: normalizeConversationThreads(settings?.conversationThreads || []),
    conversationOrganizations: normalizeConversationOrganizations(settings?.conversationOrganizations || []),
    salesPhoneCalls: normalizeSalesPhoneCalls(settings?.salesPhoneCalls || []),
    incomingInvoices: normalizeIncomingInvoices(settings?.incomingInvoices || []),
    incomingInvoiceFiles: normalizeIncomingInvoiceFiles(settings?.incomingInvoiceFiles || []),
    incomingInvoiceEvents: normalizeIncomingInvoiceEvents(settings?.incomingInvoiceEvents || []),
    incomingInvoicePartialPaymentsByInvoiceId: normalizeIncomingInvoicePartialPaymentsByInvoiceId(
      settings?.incomingInvoicePartialPaymentsByInvoiceId || {}
    ),
    incomingOffers: normalizeIncomingOffers(settings?.incomingOffers || []),
    incomingOfferFiles: normalizeIncomingOfferFiles(settings?.incomingOfferFiles || []),
    contractManagerEntries: normalizeContractManagerEntries(settings?.contractManagerEntries || []),
    meetingProtocolMeetings: normalizeMeetingProtocolMeetings(settings?.meetingProtocolMeetings || []),
    meetingProtocolLocationOptions: normalizeMeetingProtocolLocationOptions(settings?.meetingProtocolLocationOptions || []),
    financeInvoiceCategories: normalizeFinanceInvoiceCategories(settings?.financeInvoiceCategories),
    financePaymentMethodOptions: normalizeFinancePaymentMethodOptions(settings?.financePaymentMethodOptions),
    providerTargetsByCountry: normalizeProviderTargetsByCountry(settings?.providerTargetsByCountry || {}),
    headerBranding: normalizeHeaderBrandingSettings(settings?.headerBranding || {}),
    adminNotificationDismissedById: normalizeAdminNotificationDismissedById(
      settings?.adminNotificationDismissedById || {}
    ),
    adminNotificationSeenById: normalizeAdminNotificationSeenById(settings?.adminNotificationSeenById || {}),
    completedOneTimeMaintenanceTaskIds: normalizeCompletedOneTimeMaintenanceTaskIds(
      settings?.completedOneTimeMaintenanceTaskIds || []
    ),
    salesDashboardCardOrderByUserId: normalizeSalesDashboardCardOrderByUserId(
      settings?.salesDashboardCardOrderByUserId || {}
    ),
    salesDashboardCardRowsByUserId: normalizeSalesDashboardCardRowsByUserId(
      settings?.salesDashboardCardRowsByUserId || {}
    ),
    salesDashboardCardWidthByUserId: normalizeSalesDashboardCardWidthByUserId(
      settings?.salesDashboardCardWidthByUserId || {}
    ),
    salesDashboardLayoutUpdatedAtByUserId: normalizeSalesDashboardLayoutUpdatedAtByUserId(
      settings?.salesDashboardLayoutUpdatedAtByUserId || {}
    ),
    salesLeadsBoardOrderByUserId: normalizeSalesLeadsBoardOrderByUserId(
      settings?.salesLeadsBoardOrderByUserId || {}
    ),
    salesLeadsBoardUpdatedAtByUserId: normalizeSalesLeadsBoardUpdatedAtByUserId(
      settings?.salesLeadsBoardUpdatedAtByUserId || {}
    ),
    providerExportHistoryByUserId: normalizeProviderExportHistoryByUserId(
      settings?.providerExportHistoryByUserId || {}
    ),
    providerNoteAuditLog: normalizeProviderNoteAuditLog(settings?.providerNoteAuditLog || []),
    helpCenter: normalizeHelpCenterSettings(settings?.helpCenter),
    onboardingProgressByUserId: normalizeOnboardingProgressByUserId(settings?.onboardingProgressByUserId || {}),
  };
}

function normalizeMeetingProtocolLocationOptions(optionsLike) {
  const defaults = ["Telefonkonferenz", "Online-Meeting"];
  const combined = defaults.concat(Array.isArray(optionsLike) ? optionsLike : []);
  const seen = new Set();
  const normalized = [];
  combined.forEach((value) => {
    const label = String(value || "").trim();
    if (!label) {
      return;
    }
    const key = normalizeText(label);
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    normalized.push(label);
  });
  return normalized;
}

function normalizeMeetingProtocolParticipant(entry, index = 0) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const id = String(entry.id || "").trim() || `mpart_${index + 1}`;
  const name = String(entry.name || "").trim();
  if (!name) {
    return null;
  }
  return {
    id,
    userId: normalizeUserId(entry.userId || ""),
    department: String(entry.department || "").trim(),
    name,
    initials: String(entry.initials || "").trim(),
  };
}

function normalizeMeetingProtocolItem(entry, index = 0) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const id = String(entry.id || "").trim() || `mitem_${index + 1}`;
  const status = normalizeText(entry.status || "") || "offen";
  const responsibleParticipants = normalizeMeetingProtocolInitialsList(
    Array.isArray(entry.responsibleParticipants)
      ? entry.responsibleParticipants
      : String(entry.responsibleParticipant || "")
          .split(",")
          .filter(Boolean)
  );
  return {
    id,
    title: String(entry.title || "").trim(),
    content: String(entry.content || "").trim(),
    tags: Array.isArray(entry.tags) ? entry.tags.map((tag) => String(tag || "").trim()).filter(Boolean) : [],
    affectedParticipants: Array.isArray(entry.affectedParticipants)
      ? entry.affectedParticipants.map((value) => String(value || "").trim()).filter(Boolean)
      : [],
    responsibleParticipants,
    status: ["offen", "in_arbeit", "erledigt"].includes(status) ? status : "offen",
    responsibleParticipant: String(entry.responsibleParticipant || "").trim() || responsibleParticipants[0] || "",
    dueDate: sanitizeEmployeeAdminDate(entry.dueDate || ""),
    type: String(entry.type || "").trim(),
    updatedByName: String(entry.updatedByName || "").trim(),
    updatedAt: String(entry.updatedAt || "").trim() || new Date().toISOString(),
  };
}

function normalizeMeetingProtocolMeeting(entry, index = 0) {
  if (!entry || typeof entry !== "object") {
    return null;
  }
  const id = String(entry.id || "").trim() || `meet_${index + 1}`;
  const date = sanitizeEmployeeAdminDate(entry.date || "");
  if (!id || !date) {
    return null;
  }
  const participants = Array.isArray(entry.participants)
    ? entry.participants.map((row, rowIndex) => normalizeMeetingProtocolParticipant(row, rowIndex)).filter(Boolean)
    : [];
  const items = Array.isArray(entry.items)
    ? entry.items.map((row, rowIndex) => normalizeMeetingProtocolItem(row, rowIndex)).filter(Boolean)
    : [];
  return {
    id,
    title: String(entry.title || "#meeting").trim() || "#meeting",
    teamId: String(entry.teamId || "default").trim(),
    date,
    startTime: String(entry.startTime || "").trim(),
    endTime: String(entry.endTime || "").trim(),
    location: String(entry.location || "").trim(),
    participants,
    items,
    collapsed: Boolean(entry.collapsed),
    createdBy: String(entry.createdBy || "").trim(),
    createdAt: String(entry.createdAt || "").trim() || new Date().toISOString(),
    updatedAt: String(entry.updatedAt || "").trim() || new Date().toISOString(),
  };
}

function normalizeMeetingProtocolMeetings(rows) {
  if (!Array.isArray(rows)) {
    return [];
  }
  const unique = new Set();
  const mapped = rows
    .map((entry, index) => normalizeMeetingProtocolMeeting(entry, index))
    .filter((entry) => {
      if (!entry || unique.has(entry.id)) {
        return false;
      }
      unique.add(entry.id);
      return true;
    });
  return mapped.sort((left, right) => {
    const byDate = String(right.date || "").localeCompare(String(left.date || ""));
    if (byDate !== 0) {
      return byDate;
    }
    const byCreated = String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
    if (byCreated !== 0) {
      return byCreated;
    }
    return String(right.id || "").localeCompare(String(left.id || ""));
  });
}

function normalizeMapParameters(mapParameters) {
  return {
    categoryRadiusKm: sanitizeRadiusValue(mapParameters?.categoryRadiusKm, DEFAULT_MAP_PARAMETERS.categoryRadiusKm),
    subcategoryRadiusKm: sanitizeRadiusValue(
      mapParameters?.subcategoryRadiusKm,
      DEFAULT_MAP_PARAMETERS.subcategoryRadiusKm
    ),
    topicRadiusKm: sanitizeRadiusValue(mapParameters?.topicRadiusKm, DEFAULT_MAP_PARAMETERS.topicRadiusKm),
    stateTopThreshold: sanitizeStateRankingThreshold(
      mapParameters?.stateTopThreshold,
      DEFAULT_MAP_PARAMETERS.stateTopThreshold
    ),
    stateFlopThreshold: sanitizeStateRankingThreshold(
      mapParameters?.stateFlopThreshold,
      DEFAULT_MAP_PARAMETERS.stateFlopThreshold
    ),
    defaultProvisionRateEur: sanitizeEmployeeRateValue(
      mapParameters?.defaultProvisionRateEur ?? DEFAULT_MAP_PARAMETERS.defaultProvisionRateEur
    ),
  };
}

function sanitizeRadiusValue(value, fallback) {
  const numeric = parseOptionalNumber(value);
  if (typeof numeric !== "number" || !Number.isFinite(numeric)) {
    return fallback;
  }
  return Math.max(1, Math.min(500, Math.round(numeric)));
}

function sanitizeStateRankingThreshold(value, fallback) {
  const numeric = parseOptionalNumber(value);
  if (typeof numeric !== "number" || !Number.isFinite(numeric)) {
    return fallback;
  }
  return Math.max(0, Math.min(1000000, Math.round(numeric)));
}

function parseOptionalNumber(value) {
  const raw = String(value ?? "").trim().replace(",", ".");
  if (!raw) {
    return null;
  }
  const numeric = Number(raw);
  if (!Number.isFinite(numeric)) {
    return null;
  }
  return numeric;
}

function formatDateTime(value) {
  if (!value) {
    return "–";
  }
  const parsedDate = new Date(value);
  if (Number.isNaN(parsedDate.getTime())) {
    return "–";
  }
  return new Intl.DateTimeFormat("de-AT", {
    dateStyle: "short",
    timeStyle: "short",
  }).format(parsedDate);
}

function normalizeEmployeeLastLoginAtByUserId(rawMap) {
  if (!rawMap || typeof rawMap !== "object" || Array.isArray(rawMap)) {
    return {};
  }
  const normalized = {};
  Object.entries(rawMap).forEach(([userId, value]) => {
    const normalizedUserId = normalizeUserId(userId || "");
    const timestamp = Date.parse(String(value || ""));
    if (!normalizedUserId || !Number.isFinite(timestamp)) {
      return;
    }
    normalized[normalizedUserId] = new Date(timestamp).toISOString();
  });
  return normalized;
}

function mergeEmployeeLastLoginAtByUserId(primaryLike = {}, secondaryLike = {}) {
  const primary = normalizeEmployeeLastLoginAtByUserId(primaryLike);
  const secondary = normalizeEmployeeLastLoginAtByUserId(secondaryLike);
  const merged = { ...primary };
  Object.entries(secondary).forEach(([userId, timestamp]) => {
    const existingTimestamp = Date.parse(String(merged[userId] || ""));
    const nextTimestamp = Date.parse(String(timestamp || ""));
    if (!Number.isFinite(existingTimestamp) || (Number.isFinite(nextTimestamp) && nextTimestamp >= existingTimestamp)) {
      merged[userId] = timestamp;
    }
  });
  return merged;
}

function getEmployeeLastLoginAtByUserId(userId) {
  const normalizedUserId = normalizeUserId(userId || "");
  if (!normalizedUserId) {
    return "";
  }
  return normalizeEmployeeLastLoginAtByUserId(state.settings?.employeeLastLoginAtByUserId || {})[normalizedUserId] || "";
}

async function recordCurrentUserLogin() {
  const currentUserId = normalizeUserId(authProfile?.user_id || "");
  if (!currentUserId || !isUserStatusActive(authProfile?.status)) {
    return;
  }
  const nextLoginMap = normalizeEmployeeLastLoginAtByUserId(state.settings?.employeeLastLoginAtByUserId || {});
  nextLoginMap[currentUserId] = new Date().toISOString();
  state.settings = normalizeSettings({
    ...state.settings,
    employeeLastLoginAtByUserId: nextLoginMap,
  });
  const persistence = await persistCriticalStateSnapshot({ retries: 2 });
  if (!persistence?.ok) {
    saveState({ showFeedback: false });
    console.warn("CRM-Anmeldung konnte noch nicht zentral protokolliert werden.", persistence?.reason || "unknown");
    return;
  }
  if (isSuperAdmin()) {
    renderEmployeeAdminSection();
  }
}

function formatAuditStamp(timestamp, role, name) {
  const dateLabel = formatDateTime(timestamp);
  if (dateLabel === "–") {
    return "–";
  }
  return `${dateLabel} · ${getRoleLabel(role)} (${(name || "Unbekannt").trim()})`;
}

function ensureSessionUser() {
  if (authProfile?.user_id) {
    const authUserEntry = state.users.find((entry) => entry.source === "profile" && entry.sourceId === authProfile.user_id);
    if (authUserEntry) {
      state.sessionUserId = authUserEntry.id;
      return;
    }
  }
  if (state.users.length) {
    state.sessionUserId = state.users[0].id;
  } else {
    state.sessionUserId = "";
  }
}

function ensureManagementSelection() {
  if (!state.categories.length) {
    selectedCategoryId = null;
    selectedSubcategoryId = null;
    return;
  }

  const categoryExists = state.categories.some((category) => category.id === selectedCategoryId);
  if (!categoryExists) {
    selectedCategoryId = state.categories[0].id;
  }

  const category = getSelectedCategory();
  if (!category || !category.subcategories.length) {
    selectedSubcategoryId = null;
    return;
  }

  const subcategoryExists = category.subcategories.some(
    (subcategory) => subcategory.id === selectedSubcategoryId
  );
  if (!subcategoryExists) {
    selectedSubcategoryId = category.subcategories[0].id;
  }
}

function getSelectedCategory() {
  if (!selectedCategoryId) {
    return null;
  }
  return state.categories.find((category) => category.id === selectedCategoryId) || null;
}

function getSelectedSubcategory() {
  const category = getSelectedCategory();
  if (!category || !selectedSubcategoryId) {
    return null;
  }
  return category.subcategories.find((subcategory) => subcategory.id === selectedSubcategoryId) || null;
}

function getTotalSubcategoryCount() {
  return state.categories.reduce((count, category) => count + category.subcategories.length, 0);
}

function setFormControlsDisabled(formElement, disabled) {
  formElement.querySelectorAll("input, select, textarea, button").forEach((control) => {
    control.disabled = disabled;
  });
}

function normalizeText(value) {
  return String(value)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

function getDefaultDashboardCountryFilter(countries = []) {
  const list = Array.isArray(countries) ? countries : [];
  const defaultCountry = list.find(
    (country) => normalizeText(country) === normalizeText(DASHBOARD_DEFAULT_COUNTRY)
  );
  return defaultCountry || "all";
}

function collectTopicIdsFromCategory(category) {
  return category.subcategories.flatMap((subcategory) => subcategory.topics.map((topic) => topic.id));
}

function getProvidersLinkedToTopicIds(topicIds) {
  const ids = new Set((Array.isArray(topicIds) ? topicIds : []).map((id) => String(id || "").trim()).filter(Boolean));
  if (!ids.size) {
    return [];
  }
  return state.providers.filter((provider) =>
    (Array.isArray(provider?.topicIds) ? provider.topicIds : []).some((topicId) => ids.has(String(topicId || "").trim()))
  );
}

function replaceTopicIdsForProviders(topicIds, targetTopicId) {
  const ids = new Set((Array.isArray(topicIds) ? topicIds : []).map((id) => String(id || "").trim()).filter(Boolean));
  const targetId = String(targetTopicId || "").trim();
  if (!ids.size || !targetId) {
    return 0;
  }
  let changedCount = 0;
  state.providers.forEach((provider) => {
    const currentIds = Array.isArray(provider?.topicIds) ? provider.topicIds : [];
    if (!currentIds.some((topicId) => ids.has(String(topicId || "").trim()))) {
      return;
    }
    provider.topicIds = Array.from(
      new Set(currentIds.map((topicId) => (ids.has(String(topicId || "").trim()) ? targetId : topicId)))
    );
    changedCount += 1;
  });
  return changedCount;
}

function removeTopicIdsFromProviders(topicIds) {
  if (!topicIds.length) {
    return;
  }

  const idsToRemove = new Set(topicIds);
  state.providers.forEach((provider) => {
    provider.topicIds = (provider.topicIds || []).filter((topicId) => !idsToRemove.has(topicId));
  });
}

function getAllTopics() {
  return state.categories.flatMap((category) =>
    category.subcategories.flatMap((subcategory) =>
      subcategory.topics.map((topic) => ({
        ...topic,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        categoryName: category.name,
        subcategoryName: subcategory.name,
      }))
    )
  );
}

function findTopicByNormalizedName(nameLike, excludedTopicId = "") {
  const normalizedName = normalizeText(nameLike || "");
  const excludedId = String(excludedTopicId || "").trim();
  if (!normalizedName) {
    return null;
  }
  return (
    getAllTopics().find(
      (topic) =>
        String(topic?.id || "").trim() !== excludedId &&
        normalizeText(topic?.name || "") === normalizedName
    ) || null
  );
}

function getTopicById(topicId) {
  return getAllTopics().find((topic) => topic.id === topicId) || null;
}

function normalizeProviderDedupPart(value) {
  return normalizeText(value || "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function getProviderRegistryTable() {
  return window.APP_CONFIG?.SUPABASE_PROVIDER_REGISTRY_TABLE || "provider_registry";
}

function buildProviderDedupSignatureFromPayload(providerPayload) {
  if (!providerPayload || typeof providerPayload !== "object") {
    return null;
  }
  const mode = normalizeProviderCoverageMode(providerPayload.coverageMode);
  const normalizedName = normalizeProviderDedupPart(providerPayload.name);
  if (!normalizedName) {
    return null;
  }
  if (mode === PROVIDER_COVERAGE_MODE_BIG_PLAYER) {
    const countryRaw = String(providerPayload.coverageCountry || providerPayload.country || "").trim();
    const country = normalizeProviderDedupPart(countryRaw);
    const strictCountry = country || "__all__";
    return {
      mode,
      normalizedName,
      country,
      key: `name|${normalizedName}|${strictCountry}`,
      locationKey: `big|${normalizedName}|${country}`,
      locationLabel: countryRaw || "ohne Land",
    };
  }

  const primaryLocation = Array.isArray(providerPayload.locations) && providerPayload.locations.length
    ? providerPayload.locations[0]
    : providerPayload;
  const countryRaw = String(primaryLocation?.country || providerPayload.country || "").trim();
  const stateRaw = String(primaryLocation?.state || providerPayload.state || "").trim();
  const cityRaw = String(primaryLocation?.city || providerPayload.city || "").trim();
  const postalRaw = String(primaryLocation?.postalCode || providerPayload.postalCode || "").trim();
  const addressRaw = String(primaryLocation?.address || providerPayload.address || "").trim();
  const country = normalizeProviderDedupPart(countryRaw);
  const state = normalizeProviderDedupPart(stateRaw);
  const city = normalizeProviderDedupPart(cityRaw);
  const postalCode = normalizeProviderDedupPart(postalRaw);
  const address = normalizeProviderDedupPart(addressRaw);
  const strictCountry = country || "__all__";
  return {
    mode,
    normalizedName,
    country,
    key: `name|${normalizedName}|${strictCountry}`,
    locationKey: `loc|${normalizedName}|${country}|${state}|${city}|${postalCode}|${address}`,
    locationLabel: [addressRaw, postalRaw, cityRaw, stateRaw, countryRaw].filter(Boolean).join(", "),
  };
}

function buildProviderDedupSignatureFromProvider(provider) {
  if (!provider || typeof provider !== "object") {
    return null;
  }
  const mode = getProviderCoverageMode(provider);
  const normalizedName = normalizeProviderDedupPart(provider.name);
  if (!normalizedName) {
    return null;
  }
  if (mode === PROVIDER_COVERAGE_MODE_BIG_PLAYER) {
    const countryRaw = String(getProviderCoverageCountry(provider) || "").trim();
    const country = normalizeProviderDedupPart(countryRaw);
    const strictCountry = country || "__all__";
    return {
      mode,
      normalizedName,
      country,
      key: `name|${normalizedName}|${strictCountry}`,
      locationKey: `big|${normalizedName}|${country}`,
      locationLabel: countryRaw || "ohne Land",
    };
  }

  const primaryLocation = getProviderLocations(provider)[0] || provider;
  const countryRaw = String(primaryLocation?.country || "").trim();
  const stateRaw = String(primaryLocation?.state || "").trim();
  const cityRaw = String(primaryLocation?.city || "").trim();
  const postalRaw = String(primaryLocation?.postalCode || "").trim();
  const addressRaw = String(primaryLocation?.address || "").trim();
  const country = normalizeProviderDedupPart(countryRaw);
  const state = normalizeProviderDedupPart(stateRaw);
  const city = normalizeProviderDedupPart(cityRaw);
  const postalCode = normalizeProviderDedupPart(postalRaw);
  const address = normalizeProviderDedupPart(addressRaw);
  const strictCountry = country || "__all__";
  return {
    mode,
    normalizedName,
    country,
    key: `name|${normalizedName}|${strictCountry}`,
    locationKey: `loc|${normalizedName}|${country}|${state}|${city}|${postalCode}|${address}`,
    locationLabel: [addressRaw, postalRaw, cityRaw, stateRaw, countryRaw].filter(Boolean).join(", "),
  };
}

