function getFriendlyAuthErrorMessage(error, mode = "signin") {
  const rawMessage = String(error?.message || "").trim();
  const normalizedMessage = normalizeText(rawMessage);

  if (normalizedMessage.includes("user already registered")) {
    return "Diese E-Mail ist bereits registriert. Bitte anmelden oder Passwort zurücksetzen.";
  }

  if (normalizedMessage.includes("invalid login credentials")) {
    return "E-Mail oder Passwort falsch oder Konto noch nicht registriert.";
  }

  if (
    normalizedMessage.includes("password should contain") ||
    normalizedMessage.includes("password should be at least")
  ) {
    return "Passwort erfüllt die Sicherheitsanforderungen nicht. Bitte alle Passwort-Kriterien erfüllen.";
  }

  if (
    normalizedMessage.includes("database error saving new user") ||
    normalizedMessage.includes("nur eingeladene mitarbeiter durfen sich registrieren")
  ) {
    return "Registrierung serverseitig blockiert. Bitte Supabase-Trigger/Funktionen für Signup prüfen und SQL-Patches erneut ausführen.";
  }

  if (normalizedMessage.includes("email not confirmed")) {
    return "E-Mail ist noch nicht bestätigt. Bitte Posteingang prüfen.";
  }

  if (!rawMessage) {
    return mode === "signup"
      ? "Konto konnte nicht erstellt werden. Bitte erneut versuchen."
      : "Anmeldung fehlgeschlagen. Bitte erneut versuchen.";
  }

  return rawMessage;
}

async function handleAuthFormSubmit(event) {
  event.preventDefault();
  if (authMode === "signup") {
    await handleSignUp();
    return;
  }
  await handleAuthSubmit();
}

async function handleAuthSubmit() {
  const client = getSupabaseClient();
  if (!client) {
    showAuthGate("Supabase ist nicht erreichbar. Konfiguration prüfen.");
    return;
  }

  const credentials = getAuthCredentials("signin");
  if (!credentials) {
    return;
  }
  const { email, password } = credentials;
  const flowId = beginAuthFlow();
  showAuthGate("Anmeldung wird geprüft...");

  try {
    const { data, error } = await signInWithPasswordViaAuthApi(client, email, password);
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }

    if (error) {
      cancelAuthFlow(flowId);
      showAuthGate(`Anmeldung fehlgeschlagen: ${getFriendlyAuthErrorMessage(error, "signin")}`);
      setAppLoadingState(false);
      return;
    }

    showAuthGate("Anmeldung erfolgreich. Dashboard wird geladen...");
    await withAsyncTimeout(
      activateSignedInSession(data?.session || null, flowId),
      APP_STARTUP_TIMEOUT_MS,
      "Anmeldung erfolgreich, aber der Dashboard-Start dauert zu lange. Bitte neu laden."
    );
  } catch (error) {
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    cancelAuthFlow(flowId);
    console.error("Anmeldung fehlgeschlagen:", error);
    showAuthGate(String(error?.message || "Anmeldung fehlgeschlagen. Bitte erneut versuchen."));
    setAppLoadingState(false);
  }
}

async function handleSignUp() {
  const client = getSupabaseClient();
  if (!client) {
    showAuthGate("Supabase ist nicht erreichbar. Konfiguration prüfen.");
    return;
  }

  const credentials = getAuthCredentials("signup");
  if (!credentials) {
    return;
  }
  const { fullName, email, password } = credentials;
  const flowId = beginAuthFlow();
  showAuthGate("Konto wird erstellt...");

  try {
    const { data, error } = await withAsyncTimeout(
      client.auth.signUp({
        email,
        password,
        options: {
          data: {
            full_name: fullName,
            name: fullName,
          },
        },
      }),
      AUTH_REQUEST_TIMEOUT_MS,
      "Registrierung hat zu lange gedauert. Bitte erneut versuchen."
    );
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }

    if (error) {
      cancelAuthFlow(flowId);
      showAuthGate(`Konto konnte nicht erstellt werden: ${getFriendlyAuthErrorMessage(error, "signup")}`);
      setAppLoadingState(false);
      return;
    }

    if (data.session) {
      await ensureAuthProfile(data.session.user || data.user);
      if (!isCurrentAuthFlow(flowId)) {
        return;
      }
      if (authProfile && isUserStatusPending(authProfile.status)) {
        suppressNextSignedOutAuthMessage = true;
        await client.auth.signOut();
        setAuthMode("signin", { preserveMessage: true });
        showAuthGate("Konto erstellt. Dein Zugang wird nach Prüfung durch Admin freigeschaltet.");
        setAppLoadingState(false);
        return;
      }
      if (authProfile && !isUserStatusActive(authProfile.status)) {
        suppressNextSignedOutAuthMessage = true;
        await client.auth.signOut();
        setAuthMode("signin", { preserveMessage: true });
        showAuthGate("Konto erstellt, aber noch nicht aktiv. Bitte Admin kontaktieren.");
        setAppLoadingState(false);
        return;
      }
      showAuthGate("Konto erstellt und angemeldet. Dashboard wird geladen...");
      await withAsyncTimeout(
        activateSignedInSession(data.session, flowId),
        APP_STARTUP_TIMEOUT_MS,
        "Konto wurde erstellt, aber der Dashboard-Start dauert zu lange. Bitte neu laden."
      );
      return;
    }

    cancelAuthFlow(flowId);
    setAuthMode("signin", { preserveMessage: true });
    showAuthGate("Konto erstellt. Dein Zugang wird nach Prüfung durch Admin freigeschaltet.");
    setAppLoadingState(false);
  } catch (error) {
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    cancelAuthFlow(flowId);
    console.error("Registrierung fehlgeschlagen:", error);
    showAuthGate(String(error?.message || "Registrierung fehlgeschlagen. Bitte erneut versuchen."));
    setAppLoadingState(false);
  }
}

function getAuthCredentials(mode = "signin") {
  const signInMode = mode !== "signup";
  const fullName = String(els.authSignUpFullName?.value || "").trim();
  const email = String(
    signInMode ? els.authSignInEmail?.value || "" : els.authSignUpEmail?.value || ""
  )
    .trim()
    .toLowerCase();
  const password = String(
    signInMode ? els.authSignInPassword?.value || "" : els.authSignUpPassword?.value || ""
  );
  const confirmPassword = String(mode === "signup" ? els.authSignUpPasswordConfirm?.value || "" : "");
  if (mode === "signup" && fullName.length < 2) {
    showAuthGate("Bitte Name eingeben.");
    return null;
  }
  if (!email || !email.includes("@")) {
    showAuthGate("Bitte eine gültige E-Mail eingeben.");
    return null;
  }
  if (mode === "signup") {
    const checks = getAuthSignUpPasswordValidation(password, confirmPassword);
    refreshAuthSignUpPasswordRules();
    if (!checks.validPassword) {
      showAuthGate("Bitte Passwort-Kriterien erfüllen.");
      return null;
    }
    if (!checks.match) {
      showAuthGate("Passwörter stimmen nicht überein.");
      return null;
    }
  } else if (password.length < 8) {
    showAuthGate("Bitte ein Passwort mit mindestens 8 Zeichen verwenden.");
    return null;
  }
  return { fullName, email, password };
}

async function handleSignOut() {
  const client = getSupabaseClient();
  if (!client) {
    return;
  }
  stopRemoteStateSync();
  stopPartnerRequestSync();
  setAppLoadingState(true);
  explicitSignOutInProgress = true;
  try {
    await client.auth.signOut();
  } finally {
    explicitSignOutInProgress = false;
  }
  authSession = null;
  authProfile = null;
  partnerRequests = [];
  partnerRequestsLoadedRemote = false;
  contentReadReceipts = [];
  contentReadReceiptsLoaded = false;
  contentReadReceiptsLoadInFlight = false;
  contentReadReceiptsUnavailable = false;
  resetMarketingRuntime();
  setAuthMode("signin", { preserveMessage: true });
  showAuthGate("Bitte melde dich an.");
}

async function activateSignedInSession(session, flowId = 0) {
  setAppLoadingState(true);
  authSession = session || authSession;
  const client = getSupabaseClient();
  if (!client) {
    showAuthGate("Supabase ist nicht erreichbar. Konfiguration prüfen.");
    return;
  }

  if (!authSession) {
    const restoredSession = await restoreStoredAuthSession(client);
    if (!isCurrentAuthFlow(flowId)) {
      return;
    }
    if (!restoredSession) {
      showAuthGate("Session konnte nicht geladen werden. Bitte erneut anmelden.");
      return;
    }
    authSession = restoredSession;
  }

  await ensureAuthProfile(authSession.user);
  if (!isCurrentAuthFlow(flowId)) {
    return;
  }
  if (!authProfile) {
    showAuthGate("Benutzerprofil fehlt oder konnte nicht geladen werden.");
    return;
  }

  if (isUserStatusPending(authProfile.status)) {
    suppressNextSignedOutAuthMessage = true;
    await client.auth.signOut();
    showAuthGate("Dein Konto wird gerade geprüft und nach Freigabe durch Admin aktiviert.");
    return;
  }

  if (!isUserStatusActive(authProfile.status)) {
    showAuthGate("Dein Zugang ist deaktiviert. Bitte Admin kontaktieren.");
    return;
  }

  await finishBootstrapAfterLogin(flowId);
}

async function syncUsersFromSupabase() {
  const client = getSupabaseClient();
  if (!client) {
    state.users = [];
    return;
  }

  const shouldLoadInvites = canUseAdminFeatures();
  const inviteQuery = shouldLoadInvites
    ? client
        .from("employee_invites")
        .select("id, email, full_name, role, phone, address, status, created_at")
        .eq("status", "pending")
        .order("created_at", { ascending: true })
    : Promise.resolve({ data: [], error: null });

  const [profilesResult, invitesResult] = await Promise.all([
    client
      .from("profiles")
      .select("user_id, email, full_name, role, phone, address, status, created_at")
      .order("created_at", { ascending: true }),
    inviteQuery,
  ]);

  if (profilesResult.error) {
    console.warn("Profiles konnten nicht geladen werden.", profilesResult.error);
  }
  if (invitesResult.error) {
    console.warn("Invites konnten nicht geladen werden.", invitesResult.error);
  }

  const profileRows = profilesResult.data || [];
  const inviteRows = invitesResult.data || [];
  const profileUserIds = new Set(
    profileRows.map((profile) => normalizeUserId(profile?.user_id || "")).filter(Boolean)
  );
  const profileUserIdByEmail = new Map();
  profileRows.forEach((profile) => {
    const profileUserId = normalizeUserId(profile?.user_id || "");
    const profileEmail = normalizeUserEmail(profile?.email || "");
    if (profileUserId && profileEmail && !profileUserIdByEmail.has(profileEmail)) {
      profileUserIdByEmail.set(profileEmail, profileUserId);
    }
  });
  if (profileRows.length && inviteRows.length) {
    const ratesByUserId = normalizeEmployeeRatesByUserId(state.settings?.employeeRatesByUserId || {});
    const enabledByUserId = normalizeEmployeeHonorariumEnabledByUserId(
      state.settings?.employeeHonorariumEnabledByUserId || {}
    );
    let migrated = false;
    profileRows.forEach((profile) => {
      const profileUserId = String(profile?.user_id || "").trim();
      const profileEmail = normalizeUserEmail(profile?.email || "");
      if (!profileUserId || !profileEmail) {
        return;
      }
      const matchedInvite = inviteRows.find((invite) => normalizeUserEmail(invite?.email || "") === profileEmail);
      const inviteId = String(matchedInvite?.id || "").trim();
      if (!inviteId || inviteId === profileUserId) {
        return;
      }
      if (!Object.prototype.hasOwnProperty.call(ratesByUserId, profileUserId) && Object.prototype.hasOwnProperty.call(ratesByUserId, inviteId)) {
        ratesByUserId[profileUserId] = sanitizeEmployeeRateValue(ratesByUserId[inviteId]);
        migrated = true;
      }
      if (!Object.prototype.hasOwnProperty.call(enabledByUserId, profileUserId) && enabledByUserId[inviteId] === true) {
        enabledByUserId[profileUserId] = true;
        migrated = true;
      }
    });
    if (migrated) {
      state.settings = normalizeSettings({
        ...state.settings,
        employeeRatesByUserId: ratesByUserId,
        employeeHonorariumEnabledByUserId: enabledByUserId,
      });
    }
  }
  let migratedLegacyEmployeeSettings = false;
  if (profileUserIdByEmail.size) {
    const departments = getDepartments();
    const profilesMap = normalizeEmployeeProfilesByUserId(state.settings?.employeeProfilesByUserId || {}, departments);
    Object.entries(profilesMap).forEach(([legacyUserId, legacyProfile]) => {
      if (profileUserIds.has(legacyUserId)) {
        return;
      }
      const profileEmail = normalizeUserEmail(legacyProfile?.email || "");
      const targetUserId = profileEmail ? profileUserIdByEmail.get(profileEmail) : "";
      if (!targetUserId || targetUserId === legacyUserId) {
        return;
      }
      profilesMap[targetUserId] = mergeEmployeeProfileRecords(profilesMap[targetUserId] || {}, legacyProfile, departments);
      delete profilesMap[legacyUserId];
      migratedLegacyEmployeeSettings = true;
    });
    if (migratedLegacyEmployeeSettings) {
      state.settings = normalizeSettings({
        ...state.settings,
        employeeProfilesByUserId: profilesMap,
      });
    }
  }
  if (authProfile?.user_id) {
    const freshAuthProfile = profileRows.find((entry) => entry.user_id === authProfile.user_id);
    if (freshAuthProfile) {
      authProfile = freshAuthProfile;
    }
  }

  const profileUsers = profileRows.map((profile) => ({
    id: `profile_${profile.user_id}`,
    source: "profile",
    sourceId: profile.user_id,
    name: profile.full_name || profile.email || "Benutzer",
    address: profile.address || "",
    email: profile.email || "",
    phone: profile.phone || "",
    role: normalizeUserRole(profile.role),
    status: normalizeUserStatus(profile.status),
    statusLabel: getUserStatusLabel(profile.status, "profile"),
    createdAt: String(profile.created_at || "").trim(),
    territories: getEffectiveUserTerritories(profile.user_id, profile.email),
    honorariumRate: getEmployeeRateByUserId(profile.user_id, profile.email),
  }));

  const visibleInviteRows = inviteRows.filter((invite) => {
    const inviteEmail = normalizeUserEmail(invite?.email || "");
    return !inviteEmail || !profileUserIdByEmail.has(inviteEmail);
  });

  const inviteUsers = visibleInviteRows.map((invite) => ({
    id: `invite_${invite.id}`,
    source: "invite",
    sourceId: invite.id,
    name: invite.full_name || invite.email || "Einladung",
    address: invite.address || "",
    email: invite.email || "",
    phone: invite.phone || "",
    role: normalizeUserRole(invite.role),
    status: invite.status || "pending",
    statusLabel: getUserStatusLabel(invite.status || "pending", "invite"),
    createdAt: String(invite.created_at || "").trim(),
    territories: getEffectiveUserTerritories("", invite.email),
    honorariumRate: getEmployeeRateByUserId(invite.id, invite.email),
  }));

  state.users = [...profileUsers, ...inviteUsers];
  if (migratedLegacyEmployeeSettings) {
    saveState({ showFeedback: false });
  }
}

function applyEmployeeHonorariumFromPayload(userId, userPayload, email = "") {
  const normalizedUserId = String(userId || "").trim();
  const normalizedEmail = normalizeUserEmail(email || userPayload?.email || "");
  if (!normalizedUserId && !normalizedEmail) {
    return;
  }
  if (typeof userPayload?.honorariumEnabled === "undefined") {
    return;
  }
  const enabled = !!userPayload?.honorariumEnabled;
  setEmployeeHonorariumEnabledByUserId(normalizedUserId, enabled, normalizedEmail);
  if (enabled) {
    setEmployeeRateByUserId(normalizedUserId, userPayload?.honorariumRate, normalizedEmail);
  }
}

async function saveEmployeeRecord(userPayload, selectedUser) {
  const client = getSupabaseClient();
  if (!client) {
    window.alert("Supabase Verbindung fehlt.");
    return false;
  }

  const getEmployeeSaveErrorMessage = (fallbackLabel, errorLike) => {
    const summary = getSupabaseErrorSummary(errorLike);
    const code = String(errorLike?.code || "").trim();
    const roleConstraintTriggered =
      code === "23514" &&
      /role_check|profiles_role_check|employee_invites_role_check/i.test(
        `${String(errorLike?.message || "")} ${String(errorLike?.details || "")} ${String(errorLike?.hint || "")}`
      );
    if (roleConstraintTriggered) {
      return `Rolle konnte nicht gespeichert werden. In Supabase fehlt vermutlich noch der Constraint für "vertriebsmitarbeiter". ${
        summary ? `(${summary})` : ""
      }`.trim();
    }
    return summary ? `${fallbackLabel} (${summary})` : fallbackLabel;
  };
  const getNoRowUpdatedMessage = (fallbackLabel) =>
    `${fallbackLabel} (keine Zeile geändert). Bitte Rechte/RLS oder Datensatz prüfen.`;

  const normalizedEmail = String(userPayload.email || "").trim().toLowerCase();
  const normalizedTerritories = normalizeTerritoryList(userPayload.territories || []);
  const previousEmail = normalizeUserEmail(selectedUser?.email || "");
  const selectedUserId =
    selectedUser?.source === "profile"
      ? String(selectedUser?.sourceId || "").trim()
      : "";
  const persistTerritories = (email, userIdOverride = "") => {
    const targetEmail = normalizeUserEmail(email);
    if (!targetEmail) {
      return;
    }
    setUserTerritoriesForEmail(targetEmail, normalizedTerritories);
    const targetUserId = String(userIdOverride || selectedUserId).trim();
    if (targetUserId) {
      setUserTerritoriesForUserId(targetUserId, normalizedTerritories);
    }
    if (previousEmail && previousEmail !== targetEmail) {
      clearUserTerritoriesForEmail(previousEmail);
    }
    saveState({ showFeedback: false });
  };
  const basePayload = {
    full_name: userPayload.name,
    address: userPayload.address,
    phone: userPayload.phone,
    role: normalizeUserRole(userPayload.role),
  };

  if (selectedUser?.source === "profile") {
    const { data: updatedProfile, error } = await client
      .from("profiles")
      .update(basePayload)
      .eq("user_id", selectedUser.sourceId)
      .select("user_id")
      .maybeSingle();
    if (error) {
      window.alert(getEmployeeSaveErrorMessage("Mitarbeiter konnte nicht aktualisiert werden.", error));
      return false;
    }
    if (!updatedProfile?.user_id) {
      window.alert(getNoRowUpdatedMessage("Mitarbeiter konnte nicht aktualisiert werden."));
      return false;
    }

    const { error: inviteSyncError } = await client
      .from("employee_invites")
      .update({ ...basePayload, email: normalizedEmail })
      .eq("email", normalizedEmail)
      .eq("status", "pending");
    if (inviteSyncError) {
      console.warn("Einladungsrolle konnte nicht mit Profilrolle synchronisiert werden.", inviteSyncError);
    }

    applyEmployeeHonorariumFromPayload(selectedUser.sourceId, userPayload, normalizedEmail);
    persistTerritories(normalizedEmail);
    return true;
  }

  if (selectedUser?.source === "invite") {
    const { data: updatedInvite, error } = await client
      .from("employee_invites")
      .update({ ...basePayload, email: normalizedEmail })
      .eq("id", selectedUser.sourceId)
      .select("id")
      .maybeSingle();
    if (error) {
      window.alert(getEmployeeSaveErrorMessage("Einladung konnte nicht aktualisiert werden.", error));
      return false;
    }
    if (!updatedInvite?.id) {
      window.alert(getNoRowUpdatedMessage("Einladung konnte nicht aktualisiert werden."));
      return false;
    }

    const { error: profileSyncError } = await client
      .from("profiles")
      .update(basePayload)
      .eq("email", normalizedEmail);
    if (profileSyncError) {
      console.warn("Profilrolle konnte nicht mit Einladungsrolle synchronisiert werden.", profileSyncError);
    }

    applyEmployeeHonorariumFromPayload(selectedUser.sourceId, userPayload, normalizedEmail);
    persistTerritories(normalizedEmail);
    return true;
  }

  const { data: existingProfile } = await client
    .from("profiles")
    .select("user_id")
    .eq("email", normalizedEmail)
    .maybeSingle();

  if (existingProfile?.user_id) {
    const { data: updatedProfile, error } = await client
      .from("profiles")
      .update(basePayload)
      .eq("user_id", existingProfile.user_id)
      .select("user_id")
      .maybeSingle();
    if (error) {
      window.alert(getEmployeeSaveErrorMessage("Bestehender Mitarbeiter konnte nicht aktualisiert werden.", error));
      return false;
    }
    if (!updatedProfile?.user_id) {
      window.alert(getNoRowUpdatedMessage("Bestehender Mitarbeiter konnte nicht aktualisiert werden."));
      return false;
    }
    applyEmployeeHonorariumFromPayload(existingProfile.user_id, userPayload, normalizedEmail);
    persistTerritories(normalizedEmail, existingProfile.user_id);
    return true;
  }

  const invitePayload = {
    email: normalizedEmail,
    ...basePayload,
    status: "pending",
    invited_by: authProfile?.user_id || null,
  };

  const { error: inviteError } = await client
    .from("employee_invites")
    .upsert(invitePayload, { onConflict: "email" });

  if (inviteError) {
    window.alert(getEmployeeSaveErrorMessage("Einladung konnte nicht gespeichert werden.", inviteError));
    return false;
  }
  applyEmployeeHonorariumFromPayload("", userPayload, normalizedEmail);
  persistTerritories(normalizedEmail);
  return true;
}

function cloneDefaultState() {
  return JSON.parse(JSON.stringify(defaultState));
}

