    contactPersonPhone: String(provider.contactPersonPhone || provider.contact_person_phone || "").trim(),
    contact_person_phone: String(provider.contactPersonPhone || provider.contact_person_phone || "").trim(),
    contactPersonEmail: String(provider.contactPersonEmail || provider.contact_person_email || "").trim(),
    contact_person_email: String(provider.contactPersonEmail || provider.contact_person_email || "").trim(),
