    coverage_mode: normalizeProviderCoverageMode(provider.coverageMode || provider.coverage_mode),
    coverageCountry: normalizeCountryLabel(provider.coverageCountry || provider.coverage_country || ""),
    coverage_country: normalizeCountryLabel(provider.coverageCountry || provider.coverage_country || ""),
    coverageStates: normalizeProviderCoverageStates(provider.coverageStates || provider.coverage_states || []),
    coverage_states: normalizeProviderCoverageStates(provider.coverageStates || provider.coverage_states || []),
    adminOnly: normalizedAdminOnly,
    admin_only: normalizedAdminOnly,
    dashboardCreated: normalizedDashboardCreated,
    dashboard_created: normalizedDashboardCreated,
    competitor: normalizedCompetitor,
    isCompetitor: normalizedCompetitor,
    competitorName: normalizedCompetitor ? normalizedCompetitorName : "",
    competitor_name: normalizedCompetitor ? normalizedCompetitorName : "",
    earlyPartner: normalizedEarlyPartner,
