    liveRequestedAt: provider.liveRequestedAt || provider.live_requested_at || "",
    liveRequestedByUserId: provider.liveRequestedByUserId || provider.live_requested_by_user_id || "",
    liveRequestedByName: provider.liveRequestedByName || provider.live_requested_by_name || "",
